BEGIN;

INSERT INTO public.academy_languages (code, name, native_name, is_active, sort_order)
VALUES ('it', 'Italian', 'Italiano', true, 5)
ON CONFLICT (code) DO UPDATE SET
  name = EXCLUDED.name,
  native_name = EXCLUDED.native_name,
  is_active = true,
  sort_order = EXCLUDED.sort_order,
  updated_at = now();

DO $guard$
DECLARE
  module_count integer;
  lesson_count integer;
BEGIN
  IF NOT EXISTS (
    SELECT 1
    FROM public.courses AS course
    JOIN public.course_versions AS version ON version.id = course.published_version_id
    WHERE course.slug = 'pielegnacja-i-sprzedaz-produktow-xzone' AND version.version_number = 9 AND version.status = 'published'
  ) THEN
    RAISE EXCEPTION 'The expected published Academy course version was not found';
  END IF;

  SELECT count(DISTINCT module.id), count(lesson.id)
  INTO module_count, lesson_count
  FROM public.courses AS course
  JOIN public.course_versions AS version ON version.id = course.published_version_id
  JOIN public.course_modules AS module ON module.course_version_id = version.id
  JOIN public.course_lessons AS lesson ON lesson.module_id = module.id
  WHERE course.slug = 'pielegnacja-i-sprzedaz-produktow-xzone' AND version.version_number = 9 AND version.status = 'published';
  IF module_count <> 7 OR lesson_count <> 36 THEN
    RAISE EXCEPTION 'The published Academy course structure changed (modules %, lessons %)', module_count, lesson_count;
  END IF;
END
$guard$;

-- en: course, module, and lesson text
INSERT INTO public.course_translations (course_version_id, language_code, title, description, image_path)
SELECT version.id,
       'en', translated.title, COALESCE(translated.description, ''), source.image_path
FROM public.courses AS course
JOIN public.course_versions AS version ON version.id = course.published_version_id
JOIN public.course_translations AS source ON source.course_version_id = version.id AND source.language_code = 'pl'
CROSS JOIN LATERAL jsonb_to_record($en_course${"course_id":3,"slug":"pielegnacja-i-sprzedaz-produktow-xzone","course_version_id":13,"language_code":"en","title":"Xzone product care and sales","description":"","image_path":null}$en_course$::jsonb) AS translated(title text, description text)
WHERE course.slug = 'pielegnacja-i-sprzedaz-produktow-xzone' AND version.version_number = 9 AND version.status = 'published'
  AND translated.title IS NOT NULL AND 'en' = 'en'
ON CONFLICT (course_version_id, language_code) DO UPDATE SET
  title = EXCLUDED.title,
  description = EXCLUDED.description,
  image_path = COALESCE(course_translations.image_path, EXCLUDED.image_path),
  updated_at = now();

INSERT INTO public.module_translations (module_id, language_code, title, summary, image_path)
SELECT module.id,
       'en', translated.title, COALESCE(translated.summary, ''), source.image_path
FROM public.courses AS course
JOIN public.course_versions AS version ON version.id = course.published_version_id
JOIN public.course_modules AS module ON module.course_version_id = version.id
JOIN public.module_translations AS source ON source.module_id = module.id AND source.language_code = 'pl'
CROSS JOIN LATERAL jsonb_to_recordset($en_modules$[{"module_id":61,"module_sort_order":0,"title":"Helmet care","summary":"","image_path":null},{"module_id":62,"module_sort_order":1,"title":"Leather garment care","summary":"","image_path":null},{"module_id":63,"module_sort_order":2,"title":"Textile garment care","summary":"","image_path":null},{"module_id":64,"module_sort_order":3,"title":"Gloves and accessories","summary":"","image_path":null},{"module_id":65,"module_sort_order":4,"title":"Motorcycle detailing","summary":"","image_path":null},{"module_id":66,"module_sort_order":5,"title":"Off-road motorcycle care","summary":"","image_path":null},{"module_id":67,"module_sort_order":6,"title":"Selling Xzone products effectively","summary":"","image_path":null}]$en_modules$::jsonb) AS translated(module_sort_order integer, title text, summary text)
WHERE course.slug = 'pielegnacja-i-sprzedaz-produktow-xzone' AND version.version_number = 9 AND version.status = 'published'
  AND module.sort_order = translated.module_sort_order
  AND 'en' = 'en'
ON CONFLICT (module_id, language_code) DO UPDATE SET
  title = EXCLUDED.title,
  summary = EXCLUDED.summary,
  image_path = COALESCE(module_translations.image_path, EXCLUDED.image_path),
  updated_at = now();

INSERT INTO public.lesson_translations (
  lesson_id, language_code, title, summary, youtube_video_id, content, product_bullets,
  key_points_title, conversation_title, conversation, youtube_video_ids, image_path
)
SELECT lesson.id,
       'en', translated.title, COALESCE(translated.summary, ''), source.youtube_video_id,
       translated.content, COALESCE(translated.product_bullets, '[]'::jsonb),
       translated.key_points_title, translated.conversation_title,
       COALESCE(translated.conversation, '[]'::jsonb), source.youtube_video_ids, source.image_path
FROM public.courses AS course
JOIN public.course_versions AS version ON version.id = course.published_version_id
JOIN public.course_modules AS module ON module.course_version_id = version.id
JOIN public.course_lessons AS lesson ON lesson.module_id = module.id
JOIN public.lesson_translations AS source ON source.lesson_id = lesson.id AND source.language_code = 'pl'
CROSS JOIN LATERAL jsonb_to_recordset($en_lessons$[{"lesson_id":294,"module_sort_order":0,"sort_order":0,"title":"Why does a helmet need proper care?","summary":"Identify the helmet’s three areas and choose the right care method for each.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Why a helmet needs careful attention","type":"text"}]},{"type":"paragraph","content":[{"text":"While riding, insects, road dust and rain collect on the helmet, while its interior is exposed to sweat and moisture. Dirt on the outside of the visor can reduce visibility, and neglected padding can make the helmet less comfortable. When speaking with a customer, first find out which part of the helmet needs attention.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Three areas, three care methods","type":"text"}]},{"type":"heading","attrs":{"level":3},"content":[{"text":"Shell and outer visor","type":"text"}]},{"type":"paragraph","content":[{"text":"For dried-on insects, do not start by rubbing the surface dry. Helmet Gel softens the dirt so it can be gently wiped away. Helmet Detailer is used afterwards to finish the already-clean surface.","type":"text"}]},{"type":"heading","attrs":{"level":3},"content":[{"text":"Lining","type":"text"}]},{"type":"paragraph","content":[{"text":"A freshener helps keep the lining fresh between washes, but it does not remove dirt like washing does. Before washing, check whether the lining can be removed and follow the helmet’s care instructions.","type":"text"}]},{"type":"heading","attrs":{"level":3},"content":[{"text":"Pinlock","type":"text"}]},{"type":"paragraph","content":[{"text":"The Pinlock insert is delicate and must be treated separately. Do not apply gel or detailer to it, and do not rub it. Rinse it with distilled water and leave it to air-dry, following the helmet manufacturer’s recommendations.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"How to start the conversation","type":"text"}]},{"type":"paragraph","content":[{"text":"Ask whether the customer wants to care for the visor and shell, the interior, or both. Then recommend a product. Do not assume that everyone needs a complete kit or daily care.","type":"text"}]}]},"product_bullets":["Treat the shell, outer visor and lining separately—each area requires a different approach.","First soften dried-on insects with Helmet Gel; do not rub them off dry.","Use Helmet Detailer to finish a clean surface.","An interior freshener does not replace washing a dirty lining.","Treat the Pinlock insert separately and follow the helmet manufacturer’s instructions."],"key_points_title":"Key points","conversation_title":"Customer conversation","conversation":[{"text":"I have a new helmet. Do I need to buy the complete care kit straight away?","speaker":"client"},{"text":"No. If you want to care for the visor and shell now, choose products for the outer surfaces. An interior product is only useful when the lining needs freshening up or washing.","speaker":"seller"},{"text":"Can I use one liquid to clean both the visor and the interior?","speaker":"client"},{"text":"It is better to treat these as separate steps. Use products intended for visors on the outside, and clean the lining with a separate product according to the helmet instructions.","speaker":"seller"},{"text":"For now, the only problem is insects on the visor.","speaker":"client"},{"text":"In that case, start with Helmet Gel and a clean microfibre cloth. You can add the Detailer if you also want to finish the clean visor.","speaker":"seller"}],"youtube_video_id":null,"youtube_video_ids":[],"image_path":null},{"lesson_id":295,"module_sort_order":0,"sort_order":1,"title":"Helmet Gel and Helmet Detailer: the difference and how to use them","summary":"Learn the correct order for using Helmet Gel and Helmet Detailer, and choose the cloth and product size to suit the customer’s needs.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Two products, two different functions","type":"text"}]},{"type":"paragraph","content":[{"text":"Helmet Gel and Helmet Detailer work together, but neither replaces the other. The gel prepares a dirty surface, while the Detailer is used after it has been cleaned.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Step 1: Soften the dirt","type":"text"}]},{"type":"paragraph","content":[{"text":"Apply Helmet Gel to the dirty area and leave it for the time stated on the label. The travel size specifies about five minutes; shorten the time in strong sunlight. Do not let the product dry. Once the dirt has softened, wipe it away with a clean microfibre cloth without pressing hard.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Step 2: Finish the clean surface","type":"text"}]},{"type":"paragraph","content":[{"text":"Use Helmet Detailer only after removing the dirt. A thicker microfibre cloth works well for wiping away loosened dirt; use an Evolon cloth for the final finish. Always start with clean accessories.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Choose the size to suit how it will be used","type":"text"}]},{"type":"paragraph","content":[{"text":"The 30 ml size is easy to take on a trip. The 250 ml bottle is practical for regular helmet cleaning. Ask the customer where and how often they plan to use the products.","type":"text"}]}]},"product_bullets":["Helmet Gel is step 1: it softens dried-on insects and dirt so you can remove them gently.","After applying, wait as directed; the travel size specifies about 5 minutes. Shorten the wait in direct sunlight.","Helmet Detailer is step 2: use it on a clean surface for an even finish and to help prevent streaks.","Wipe away loosened dirt with a clean, thicker microfibre cloth; use Evolon for the final finish.","The products are available in a 30 ml travel size and a larger 250 ml size. Choose according to how often they will be used."],"key_points_title":"Key points","conversation_title":"Customer conversation","conversation":[{"text":"Is the Detailer alone enough for dried-on insects?","speaker":"client"},{"text":"For dried-on insects, start with Helmet Gel: soften the dirt, gently wipe it away with a microfibre cloth, then finish the clean visor with the Detailer.","speaker":"seller"},{"text":"I have a matte helmet. Will the Detailer make the surface shiny?","speaker":"client"},{"text":"Yes, it can be used on a matte helmet—the finish remains matte. Apply the product to a clean microfibre cloth and follow the helmet instructions.","speaker":"seller"},{"text":"How long should I wait after applying the gel?","speaker":"client"},{"text":"Follow the time stated on the label; the travel size specifies about 5 minutes. Do not let the product dry, and shorten the wait in direct sunlight.","speaker":"seller"},{"text":"Can I use a paper towel?","speaker":"client"},{"text":"Use a clean, soft microfibre cloth. Paper can be rough and may scratch a delicate surface.","speaker":"seller"}],"youtube_video_id":"rRsVUfSr9Sk","youtube_video_ids":["rRsVUfSr9Sk"],"image_path":null},{"lesson_id":296,"module_sort_order":0,"sort_order":2,"title":"How to clean the visor and Pinlock correctly","summary":"Learn how to clean the outside of a visor safely and distinguish it from the delicate Pinlock insert.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"First identify which surface you are cleaning","type":"text"}]},{"type":"paragraph","content":[{"text":"The outer visor and Pinlock insert require different care. Before using any product, check the instructions for the specific helmet, visor and its coating.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Outer visor: gentle cleaning step by step","type":"text"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Remove loose sand and other particles without rubbing. Do not polish dirt while the surface is dry.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Apply Helmet Gel to dried-on insects and let it work as directed on the label. Do not let it dry.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Wipe away softened dirt with a clean cloth without pressing hard.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"If the visor instructions allow it, use Helmet Detailer and a clean Evolon cloth for the final finish.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Pinlock: a separate, delicate insert","type":"text"}]},{"type":"paragraph","content":[{"text":"Do not use Helmet Gel or Helmet Detailer on the insert. Do not polish it with a cloth. Rinse it with distilled water without rubbing and leave it to air-dry.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"What these products do not do","type":"text"}]},{"type":"paragraph","content":[{"text":"These products are for cleaning and finishing. They do not remove scratches or repair a damaged visor.","type":"text"}]}]},"product_bullets":["Remove loose sand without rubbing before you start cleaning the visor.","Apply gel to dried-on insects on the outside of the visor and wipe the dirt away without pressure.","Finish a clean outer visor with the Detailer and an Evolon cloth.","Do not apply gel or Detailer to the Pinlock, and do not polish it with a microfibre cloth.","Rinse the Pinlock with distilled water and leave it to air-dry."],"key_points_title":"Key points","conversation_title":"Customer conversation","conversation":[{"text":"Can I clean the Pinlock with the same product as the outer visor?","speaker":"client"},{"text":"No. Use Helmet Gel and Detailer on the outside of the visor. Clean the Pinlock gently with distilled water, without rubbing, and follow the helmet instructions.","speaker":"seller"},{"text":"There is sand on the visor. Can I wipe it with a microfibre cloth straight away?","speaker":"client"},{"text":"First rinse it or gently remove the loose particles. Do not rub sand across the visor, as it may scratch it.","speaker":"seller"},{"text":"Will these products remove scratches?","speaker":"client"},{"text":"No. They are for cleaning and finishing, and will not repair scratches.","speaker":"seller"}],"youtube_video_id":"rRsVUfSr9Sk","youtube_video_ids":["rRsVUfSr9Sk","8z1Me4HeZAA"],"image_path":null},{"lesson_id":297,"module_sort_order":0,"sort_order":3,"title":"How to care for the helmet interior","summary":"Distinguish between freshening up the helmet interior and washing a dirty lining.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"First identify the need","type":"text"}]},{"type":"paragraph","content":[{"text":"Ask whether the customer wants to freshen the interior after a ride or whether the lining is visibly dirty. A freshener and washing solve different problems: the product helps maintain freshness, while a dirty lining needs proper cleaning.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Freshen between washes","type":"text"}]},{"type":"paragraph","content":[{"text":"Mint freshener is designed for the inside of a helmet. Spray it from about 15–20 cm away and let the helmet dry completely before wearing it. The product is not intended for use on skin or the body.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Washing the lining","type":"text"}]},{"type":"paragraph","content":[{"text":"First check whether the lining can be removed and review the helmet manufacturer’s recommendations. For hand-washing, use a dedicated detergent according to its label. Wash gently, rinse thoroughly and leave it to air-dry. Do not wring the material or dry it near a heat source.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"When to revisit the issue","type":"text"}]},{"type":"paragraph","content":[{"text":"If the smell persists after freshening, check the condition of the lining and consider washing it. Present the freshener as a complement to care between washes.","type":"text"}]}]},"product_bullets":["Ask whether the customer is concerned about odour or whether the dirty lining needs washing.","Mint freshener helps keep the helmet fresh between washes, but does not replace washing.","Spray the inside from about 15–20 cm away and wait until it is completely dry.","Hand-wash removable lining according to the helmet instructions.","Rinse thoroughly and air-dry; do not wring it or use a heat source."],"key_points_title":"Key points","conversation_title":"Customer conversation","conversation":[{"text":"The inside of the helmet smells of sweat. What should I choose?","speaker":"client"},{"text":"Choose Mint to quickly freshen the helmet between washes. If the lining is dirty, wash it with a separate product according to the helmet instructions.","speaker":"seller"},{"text":"Can I spray the product on my head?","speaker":"client"},{"text":"No. Use it on the inside of the helmet as directed on the label, not on your skin.","speaker":"seller"},{"text":"Can I put the helmet on straight after using it?","speaker":"client"},{"text":"Wait until the inside is completely dry. If the smell returns, the lining may need washing.","speaker":"seller"}],"youtube_video_id":null,"youtube_video_ids":[],"image_path":null},{"lesson_id":298,"module_sort_order":0,"sort_order":4,"title":"Which kit should you recommend: GIGA or Trip Kit?","summary":"Choose Trip Kit or GIGA based on where and how often the customer cleans their helmet.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Choose the kit to suit how it will be used","type":"text"}]},{"type":"paragraph","content":[{"text":"Trip Kit and GIGA cover the steps for cleaning the outside of a helmet: softening dirt with gel, then finishing with the Detailer. They mainly differ in bottle size and ease of storage.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Trip Kit: for travelling","type":"text"}]},{"type":"paragraph","content":[{"text":"Compact bottles and a travel pouch make it easy to take the kit on a trip, store it in a case or compartment, and use it quickly during a stop.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"GIGA: for regular care","type":"text"}]},{"type":"paragraph","content":[{"text":"The larger 250 ml bottles of gel and Detailer are suitable for frequent cleaning at home or in the garage, for example when caring for several helmets.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Questions that make choosing easier","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Where will the helmet usually be cleaned—in the middle of a trip or at home?","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"How often will the customer clean it?","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"One helmet or several?","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Is only the insect-removal step needed, or a final finish as well?","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"If the customer is concerned about an odour inside the helmet, discuss a separate interior product. A kit for cleaning the outside does not replace washing the lining.","type":"text"}]}]},"product_bullets":["Trip Kit and GIGA are for two-step cleaning of the outside of a helmet.","Trip Kit has compact bottles and a pouch, making it suitable for travel.","GIGA includes 250 ml bottles and accessories for regular use at home or in the garage.","Choose a separate product to freshen the interior—the outer-surface kits do not replace it.","Ask where and how often the customer will clean the helmet; do not assume the larger kit is better."],"key_points_title":"Key points","conversation_title":"Customer conversation","conversation":[{"text":"I want something to clean my helmet while travelling. Which kit should I choose?","speaker":"client"},{"text":"Trip Kit is compact and designed for travel. It contains products for the outside of the helmet as well as accessories.","speaker":"seller"},{"text":"Would Trip Kit be better for regularly cleaning two helmets at home?","speaker":"client"},{"text":"For frequent use, GIGA with its larger bottles may be more convenient. Choose a size based on how often and how many helmets will be cleaned.","speaker":"seller"},{"text":"Will the kit clean the lining too?","speaker":"client"},{"text":"No. This kit is for caring for the outside of the helmet. Choose a separate product for the interior if needed.","speaker":"seller"},{"text":"I have run out of the gel. Do I need to buy the whole kit again?","speaker":"client"},{"text":"No. You can replace just that product if it is available separately.","speaker":"seller"}],"youtube_video_id":null,"youtube_video_ids":[],"image_path":null},{"lesson_id":299,"module_sort_order":0,"sort_order":5,"title":"Sales role-play: a customer is buying a new helmet","summary":"Practise identifying needs and recommending care for a customer buying a helmet.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Exercise objective","type":"text"}]},{"type":"paragraph","content":[{"text":"Practise a conversation that helps someone buying a new helmet choose care products that suit their riding habits. Do not start with a list of products. Find out where and how often they will clean the helmet and what problem they want to solve.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"What to focus on","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Ask at least one question to help choose the right size.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Explain what the gel and Detailer do in two short sentences.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Do not recommend an add-on the customer does not need.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Do not promise a specific yield without verified data.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Individual practice","type":"text"}]},{"type":"paragraph","content":[{"text":"After acting out the scenarios, put the suggested answer into your own words. Finish by asking one question: “Do you clean your helmet more often on the road or at home?”, “One helmet or several?”, or “Are you mainly dealing with insects, or would you also like to freshen the interior?” Explain your recommendation in one sentence.","type":"text"}]}]},"product_bullets":["Start by asking where and how often the helmet will be cleaned, and how many helmets need care.","Choose Trip Kit for care on the road and GIGA for regular use at home.","Briefly explain the order: the gel softens dirt, and the Detailer finishes the clean surface.","Do not recommend an interior freshener if the customer does not need one.","Respect a refusal and do not promise a yield that has not been verified."],"key_points_title":"Key points","conversation_title":"Customer conversation","conversation":[{"text":"I’m going on a week-long trip and don’t want insects on my visor. What should I take?","speaker":"client"},{"text":"For cleaning on the road, I recommend Trip Kit. The gel softens insects, and after you gently remove them, the Detailer helps finish the clean visor.","speaker":"seller"},{"text":"Can I clean the Pinlock with the same kit?","speaker":"client"},{"text":"Do not use products for the outer visor on the insert. Clean the Pinlock gently according to the manufacturer’s instructions.","speaker":"seller"},{"text":"I don’t need anything for the interior; the helmet is new.","speaker":"client"},{"text":"That’s fine—you do not need to buy a freshener just in case. You can come back to it if an odour or dirt becomes an issue.","speaker":"seller"}],"youtube_video_id":null,"youtube_video_ids":[],"image_path":null},{"lesson_id":300,"module_sort_order":1,"sort_order":0,"title":"Why does motorcycle leather need care?","summary":"Identify the type of leather and the dirt, then choose separate products for cleaning and conditioning.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"First identify what you are dealing with","type":"text"}]},{"type":"paragraph","content":[{"text":"A leather suit may include different types of leather, colours, finishes and textile panels. Ask what exactly needs care, how heavy the dirt is, and whether the customer knows the manufacturer’s recommendations. Light-coloured or fluorescent leather requires extra care.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Separate cleaning from conditioning","type":"text"}]},{"type":"paragraph","content":[{"text":"Leather Cleaner removes dirt. Leather Milk is applied only to clean, dry leather to condition it. One product does not automatically replace the other, and care products do not repair physical damage.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Demonstrate the safe order","type":"text"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Remove loose dust without rubbing hard.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Test the product on a hidden area and check the result.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Clean gently with the appropriate cleaner and a soft brush.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Wipe away any residue with a clean, slightly damp cloth and leave it to air-dry.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"If the leather needs conditioning, apply a thin layer of Leather Milk as directed on the label.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Set realistic expectations","type":"text"}]},{"type":"paragraph","content":[{"text":"A care product can clean and support routine maintenance, but it will not restore a worn finish or repair cracks. For this kind of damage, recommend having the garment assessed by a repair service or the manufacturer.","type":"text"}]}]},"product_bullets":["First identify the leather type and colour, and check the garment manufacturer’s recommendations.","Leather Cleaner removes dirt; Leather Milk conditions leather after it has dried.","Test the product on an inconspicuous area before use, especially on light-coloured leather.","Use a soft brush and light pressure for cleaning.","Care products cannot repair cracks, scuffs or damage to the finish."],"key_points_title":"Key points","conversation_title":"Customer conversation","conversation":[{"text":"I have a leather suit with bright-coloured panels. How should I start cleaning it?","speaker":"client"},{"text":"For everyday dirt, choose Leather Cleaner Normal. For fluorescent colours, first test it on an inconspicuous area and clean with a soft brush.","speaker":"seller"},{"text":"Is the leather conditioned after using the cleaner?","speaker":"client"},{"text":"The cleaner removes dirt. Once the leather has dried completely, you can apply Leather Milk as a separate conditioning step.","speaker":"seller"},{"text":"There is a crack near the seam. Will the milk repair it?","speaker":"client"},{"text":"No. Care products condition leather but do not repair cracks or damaged seams. Take the garment to a repair service for this.","speaker":"seller"}],"youtube_video_id":null,"youtube_video_ids":[],"image_path":null},{"lesson_id":301,"module_sort_order":1,"sort_order":1,"title":"How to clean leather: Leather Cleaner and a brush","summary":"Choose the Leather Cleaner variant to suit the dirt and leather colour, then demonstrate a gentle cleaning technique.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Choose the variant to suit the leather and dirt","type":"text"}]},{"type":"paragraph","content":[{"text":"Do not automatically choose the strongest cleaner. Normal is suitable for everyday dirt and more delicate colours. Strong may be considered for heavier dirt on traditional leather, if the garment manufacturer’s instructions allow it.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Demonstration step by step","type":"text"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Shake the bottle and test the product on an inconspicuous area.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Apply the foam to a soft, slightly damp brush, not directly to the whole garment.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Clean a small area using calm, gentle strokes.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Wipe away the dirt with a clean, slightly damp cloth.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Leave the garment to air-dry before continuing with care.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"When to change the approach","type":"text"}]},{"type":"paragraph","content":[{"text":"If the material has an unusual finish, a vivid colour or signs of damage, pause the demonstration and check the garment instructions. The cleaner removes dirt but does not repair scuffs or cracks.","type":"text"}]}]},"product_bullets":["Normal is the choice for everyday dirt and more delicate colours.","Consider Strong for heavier dirt on traditional leather after testing it first.","Shake the bottle and test the product on a hidden area.","Apply the foam to a soft, slightly damp brush; do not scrub hard.","Wipe away any residue and leave the leather to air-dry."],"key_points_title":"Key points","conversation_title":"Customer conversation","conversation":[{"text":"I have a white suit with fluorescent panels. Should I choose Strong?","speaker":"client"},{"text":"For fluorescent colours, choose Normal and test it on a hidden area first. Reserve Strong for heavy dirt and use it only as intended.","speaker":"seller"},{"text":"Can I use a hard shoe brush?","speaker":"client"},{"text":"It is better to use a soft brush. Apply the foam to slightly damp bristles and gently clean a small area using circular motions.","speaker":"seller"},{"text":"When should I apply Leather Milk?","speaker":"client"},{"text":"After cleaning, wipe away the dirt with a clean cloth and let the leather air-dry. Apply the milk only to the dry surface, if it needs conditioning.","speaker":"seller"}],"youtube_video_id":"iyz1GD-lV2Y","youtube_video_ids":["iyz1GD-lV2Y","s4I4GwvoHuc"],"image_path":null},{"lesson_id":302,"module_sort_order":1,"sort_order":2,"title":"How to condition leather: Leather Milk","summary":"Explain Leather Milk as a conditioning step after the leather has been cleaned and dried.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Why condition leather","type":"text"}]},{"type":"paragraph","content":[{"text":"After cleaning and drying, leather may need separate conditioning. Leather Milk comes after the cleaner; it is not a detergent for dirty clothing. Explain this order to the customer before demonstrating how to apply it.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Apply without overdoing it","type":"text"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Make sure the leather is clean and completely dry.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Test it on an inconspicuous area, especially if the finish is unusual.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Apply a small amount of product with a soft cloth.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Spread it thinly and evenly, as directed on the label.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Leave it to dry and check the result before applying more.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"What it can and cannot do","type":"text"}]},{"type":"paragraph","content":[{"text":"The milk supports routine care but does not repair cracks, scuffs or a damaged finish. Do not promise waterproofing unless the product manufacturer states that it provides it. If in doubt, refer to the garment instructions.","type":"text"}]}]},"product_bullets":["Apply Leather Milk to clean, dry leather.","Apply a thin, even layer as directed.","Test it on a hidden area before applying it to the whole garment.","Do not use the milk to remove dirt.","Do not promise that it will repair cracks or restore the original protective finish."],"key_points_title":"Key points","conversation_title":"Customer conversation","conversation":[{"text":"Why do I need Leather Milk if I already have Leather Cleaner?","speaker":"client"},{"text":"The cleaner removes dirt, while Leather Milk conditions the leather after it has been cleaned and dried. If the leather does not need conditioning right now, you do not need to add the milk.","speaker":"seller"},{"text":"Can I apply the milk to a dirty jacket?","speaker":"client"},{"text":"Clean and dry it first. The milk does not replace the cleaner.","speaker":"seller"},{"text":"I have matte leather. How can I check whether the milk is suitable?","speaker":"client"},{"text":"Test it on an inconspicuous area and check the garment manufacturer’s recommendations. Only then apply a thin layer as directed on the label.","speaker":"seller"},{"text":"Will the milk repair cracks?","speaker":"client"},{"text":"No. Cracks and scuffs need repair, not a care product.","speaker":"seller"}],"youtube_video_id":null,"youtube_video_ids":[],"image_path":null},{"lesson_id":303,"module_sort_order":1,"sort_order":3,"title":"How to use the Leather Care Kit","summary":"Guide the customer through the leather-care routine and check that each item meets a real need.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"The kit as a step-by-step routine","type":"text"}]},{"type":"paragraph","content":[{"text":"Leather Care Kit can be convenient for someone who wants to care for the outside of leather garments and freshen their interior. The kit includes a cleaner, Leather Milk, an interior freshener, a brush and a cloth. Show the order of use instead of simply listing the items.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Order of use","type":"text"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Choose the cleaner variant to suit the dirt and colour, then test it.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Clean the leather with a soft brush and wipe away any residue.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Leave the leather to air-dry.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Apply a thin layer of Leather Milk as directed on the label.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Freshen the interior separately, following the instructions for that product.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Recommend the kit only when it fits","type":"text"}]},{"type":"paragraph","content":[{"text":"Ask what the customer already owns and whether they also need to care for the interior. If they have a cleaner and only need a conditioner, recommend just the missing step. Do not present the kit as essential for everyone.","type":"text"}]}]},"product_bullets":["Leather Care Kit combines a cleaner, conditioning milk, an interior freshener and accessories.","Clean the leather first, let it dry, then apply Leather Milk.","An interior freshener addresses a different need from care for the outside.","Choose Normal or Strong according to the colour, dirt and garment instructions.","If the customer already owns some of the products, recommend only what is missing."],"key_points_title":"Key points","conversation_title":"Customer conversation","conversation":[{"text":"My suit is dirty on the outside and smells inside. Will the kit solve both problems?","speaker":"client"},{"text":"Leather Care Kit combines a cleaner, conditioning milk, an interior freshener and accessories. First clean the leather; once it dries, condition it with the milk, and freshen the interior separately.","speaker":"seller"},{"text":"I already have a cleaner. Is it still worth getting the whole kit?","speaker":"client"},{"text":"There is no need if you already have the other items. Choose only the missing milk or interior product.","speaker":"seller"},{"text":"The leather is cracked. Will the kit restore it?","speaker":"client"},{"text":"It will not repair the damage. If the leather is cracked, consult a repair service first.","speaker":"seller"}],"youtube_video_id":null,"youtube_video_ids":[],"image_path":null},{"lesson_id":304,"module_sort_order":1,"sort_order":4,"title":"Sales role-play: a customer is buying leather clothing","summary":"Practise identifying the type of leather, choosing the simplest suitable solution and responding to the customer’s needs.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Start the conversation with a needs assessment","type":"text"}]},{"type":"paragraph","content":[{"text":"The aim of the role-play is to choose a solution for a specific suit, not to sell every product on the shelf. Find out the colour and type of leather, how dirty it is, its condition and what the customer already owns. Only then explain which steps are needed.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Three scenarios to practise","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"A light-coloured suit with fluorescent panels: choose the cleaner carefully and test it in a hidden area.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"A heavily soiled black suit: choose a cleaner to suit the leather type, clean gently and let it dry.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"A clean jacket that needs routine care: consider Leather Milk without adding an unnecessary cleaner.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Review together","type":"text"}]},{"type":"paragraph","content":[{"text":"After each conversation, the salesperson should be able to explain what is being purchased, in what order the products will be used and what they cannot repair. If the customer already owns some accessories, the recommendation may be limited to one missing product.","type":"text"}]}]},"product_bullets":["Ask about the type, colour and condition of the leather, as well as the garment manufacturer’s recommendations.","Separate cleaning the outer surface, conditioning it and freshening the interior.","Choose a cleaner to suit the colour and dirt; test it first on delicate leather.","Recommend Leather Milk after the leather has dried, if the customer needs conditioning.","Refer physical damage to a repair service; do not promise that a care product will repair it."],"key_points_title":"Key points","conversation_title":"Customer conversation","conversation":[{"text":"I have a suit with fluorescent panels and I’m worried about discolouration.","speaker":"client"},{"text":"For fluorescent colours, choose Normal. Test it on an inconspicuous area, then clean a small section with a soft brush.","speaker":"seller"},{"text":"I already have the cleaner. What do I need for care after cleaning?","speaker":"client"},{"text":"If the leather needs it, choose Leather Milk on its own. Apply it only after the leather has dried following cleaning.","speaker":"seller"},{"text":"There is a scuff on the sleeve. Will a care product hide it?","speaker":"client"},{"text":"No, a care product will not repair a scuff. Have the suit checked to see whether it needs professional repair.","speaker":"seller"},{"text":"It smells of sweat inside. Should I wash the whole leather suit?","speaker":"client"},{"text":"Do not start by soaking the suit. Choose a separate product for the interior and use it according to the garment instructions.","speaker":"seller"}],"youtube_video_id":null,"youtube_video_ids":[],"image_path":null},{"lesson_id":305,"module_sort_order":2,"sort_order":0,"title":"How to care for textile garments","summary":"Identify the garment material and washing instructions, then choose the right product for the specific fibre.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Before choosing a detergent","type":"text"}]},{"type":"paragraph","content":[{"text":"Motorcycle clothing may combine a membrane, lining, armour and different fibres. Find out what the customer wants to wash, check the care label, and only then recommend a product. The garment instructions determine the temperature, programme, dosage and drying method.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Choose a product to suit the material","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Textile Care: standard technical and membrane garments.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Active Care: synthetic sportswear, thermal base layers and microfibre.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Merino Care: merino wool and delicate natural fibres.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Jeans Care: denim, including motorcycle clothing when its care label allows it.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Fabric Protect: a laundry additive that helps maintain freshness, not a waterproofing treatment.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Do not wash everything the same way","type":"text"}]},{"type":"paragraph","content":[{"text":"A membrane jacket, thermal shirt and merino layer may require different detergents and wash programmes. Do not recommend fabric softener as a substitute for specialist care. If the customer wants to restore water repellency, choose a separate product for that purpose that is compatible with the garment instructions.","type":"text"}]}]},"product_bullets":["Start with the care label: material, temperature, programme, detergent and drying.","Choose Textile Care for technical clothing and Active Care for sportswear.","Merino Care is for delicate wool, while Jeans Care is for denim.","Fabric Protect helps maintain freshness during washing and is not a water-repellent treatment.","Wash different materials separately if they require different programmes and products."],"key_points_title":"Key points","conversation_title":"Customer conversation","conversation":[{"text":"I have a membrane jacket, a thermal shirt and a merino top. Can I wash them all together?","speaker":"client"},{"text":"It is better to separate them according to their care labels: they are different materials and may need different detergents and programmes. Choose Textile Care for the jacket and a separate product for the merino.","speaker":"seller"},{"text":"Will Fabric Protect waterproof my jacket?","speaker":"client"},{"text":"No. Fabric Protect is a laundry additive that helps maintain freshness. For water protection, choose a separate waterproofing treatment for that garment.","speaker":"seller"},{"text":"I’m not sure which programme to use.","speaker":"client"},{"text":"Use the programme and temperature shown on the garment label, and check the detergent label for the dosage.","speaker":"seller"}],"youtube_video_id":null,"youtube_video_ids":[],"image_path":null},{"lesson_id":306,"module_sort_order":2,"sort_order":1,"title":"Textile Care: cleaning garments","summary":"Explain what Textile Care is for and demonstrate how to choose it safely for technical garments.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"What Textile Care is for","type":"text"}]},{"type":"paragraph","content":[{"text":"Textile Care is intended for technical motorcycle clothing, including garments with membranes. Do not promise that the detergent can repair a worn membrane or restore its properties after damage. The goal is to wash the garment correctly in line with its manufacturer’s instructions.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"How to prepare for washing","type":"text"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Check the garment label and remove any items that need to be washed separately.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Select an approved programme and temperature.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Measure the detergent according to its label.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Do not add regular fabric softener unless the manufacturer explicitly recommends it.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Dry the garment as directed on the label, away from excessive heat if specified.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Extra freshness","type":"text"}]},{"type":"paragraph","content":[{"text":"Fabric Protect can be added to the wash as a separate additive. Explain its role clearly: it helps keep garments fresh but does not replace a water-repellent treatment.","type":"text"}]}]},"product_bullets":["Textile Care is designed for washing technical and membrane motorcycle clothing.","The garment label determines the programme, temperature and drying method.","Do not automatically substitute regular fabric softener.","Measure it according to the product label and washing instructions.","Fabric Protect can be considered as a separate additive to help maintain freshness."],"key_points_title":"Key points","conversation_title":"Customer conversation","conversation":[{"text":"Is Textile Care suitable for a membrane jacket?","speaker":"client"},{"text":"Yes. It is a detergent for technical and membrane garments. Choose the programme and temperature according to the jacket’s care label.","speaker":"seller"},{"text":"I always add fabric softener. Should I keep using it?","speaker":"client"},{"text":"Do not automatically use it with technical clothing. Check the care label and use Textile Care as directed.","speaker":"seller"},{"text":"What can I add if I want my clothes to smell fresh after washing?","speaker":"client"},{"text":"You can add Fabric Protect to the fabric-softener compartment instead of regular softener, as directed on its label.","speaker":"seller"}],"youtube_video_id":"UUXCozkqAZk","youtube_video_ids":["UUXCozkqAZk"],"image_path":null},{"lesson_id":307,"module_sort_order":2,"sort_order":2,"title":"Fabric Protect: care and freshness after washing","summary":"Show how to add Fabric Protect to the wash and distinguish it from a waterproofing treatment.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"A laundry additive, not a waterproofing treatment","type":"text"}]},{"type":"paragraph","content":[{"text":"The name may suggest water protection, so explain the product’s role clearly. Fabric Protect is an additive that helps maintain garment freshness during washing. It is not a water-repellent treatment and does not restore the DWR coating on its own.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"How to use it","type":"text"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Choose a detergent that suits the material and check the garment label.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Pour Fabric Protect into the fabric-softener compartment if the instructions specify this.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Use the dosage stated on the label.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Select a programme that follows the garment instructions.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Use a separate product specifically intended for waterproofing.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"How to explain the added value","type":"text"}]},{"type":"paragraph","content":[{"text":"If the customer washes technical clothing and wants it to stay fresh after washing, you can recommend Fabric Protect alongside Textile Care. If they ask about rain protection, explain clearly that they need a separate waterproofing treatment.","type":"text"}]}]},"product_bullets":["Fabric Protect is a laundry additive that helps maintain garment freshness.","It can replace regular fabric softener if the label says so.","Pour it into the fabric-softener compartment as directed.","Choose it alongside the right detergent for the material.","Do not promise that it will restore waterproofing or the DWR finish."],"key_points_title":"Key points","conversation_title":"Customer conversation","conversation":[{"text":"Will Fabric Protect make my jacket repel water again?","speaker":"client"},{"text":"No—it is a laundry additive that helps keep garments fresh, not a water-repellent treatment. Choose a separate waterproofing treatment for the jacket.","speaker":"seller"},{"text":"Where should I pour Fabric Protect?","speaker":"client"},{"text":"Pour it into the fabric-softener compartment instead of regular softener and wash the garment according to its care label.","speaker":"seller"},{"text":"Can I use it with Textile Care?","speaker":"client"},{"text":"Yes. Textile Care washes technical garments, and Fabric Protect is added to the rinse compartment as a separate step.","speaker":"seller"}],"youtube_video_id":null,"youtube_video_ids":[],"image_path":null},{"lesson_id":308,"module_sort_order":2,"sort_order":3,"title":"Active Care: caring for sportswear","summary":"Choose Active Care for synthetic sportswear and thermal base layers according to how they are used.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"When to consider Active Care","type":"text"}]},{"type":"paragraph","content":[{"text":"Active Care is suitable for synthetic sportswear, thermal base layers and microfibre. Start by asking about the customer’s activity and the issue they are trying to solve, such as odour after a workout or frequent washing of a base layer.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Match it to the material","type":"text"}]},{"type":"paragraph","content":[{"text":"If the customer asks about a membrane jacket, check its label and consider Textile Care. For merino wool, choose a product intended for delicate natural fibres. Do not choose Active Care just because the garment is sportswear.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Use and size","type":"text"}]},{"type":"paragraph","content":[{"text":"Always check the garment label for programme, temperature and drying instructions. Follow the product label for dosage. The 40 ml sachet can be a convenient option for trying the product or taking it on a trip.","type":"text"}]}]},"product_bullets":["Choose Active Care for synthetic sportswear and thermal base layers.","Ask about the material, odour after exercise and care-label instructions.","Do not assume that it is a detergent for every type of garment.","Follow the dosage and programme shown on the product and garment labels.","The 40 ml sachet lets the customer try the product before buying a larger size."],"key_points_title":"Key points","conversation_title":"Customer conversation","conversation":[{"text":"My thermal shirt keeps smelling of sweat. What should I choose?","speaker":"client"},{"text":"If it is synthetic sportswear or a thermal base layer, choose Active Care. Wash it according to the care label and follow the product label for dosage.","speaker":"seller"},{"text":"Should I use Active Care for a membrane jacket?","speaker":"client"},{"text":"Choose Textile Care for a membrane jacket. Active Care is for synthetic sportswear and base layers.","speaker":"seller"},{"text":"Can I take a smaller pack for a trip?","speaker":"client"},{"text":"Yes, a 40 ml sachet is available. It is a handy size for trying the product or taking it on a trip.","speaker":"seller"}],"youtube_video_id":null,"youtube_video_ids":[],"image_path":null},{"lesson_id":309,"module_sort_order":2,"sort_order":4,"title":"Merino Care","summary":"Learn how to wash merino and delicate fibres, and avoid making overly broad recommendations.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Delicate fibres need special care","type":"text"}]},{"type":"paragraph","content":[{"text":"Merino layers help regulate comfort while riding and need to be cared for according to their labels. Merino Care is intended for merino wool and other delicate fibres specified by the manufacturer. Do not assume that a programme suitable for synthetic base layers is safe for wool.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Washing and drying","type":"text"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Check the fabric composition and care symbols on the label.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Choose a wool programme or hand-wash if specified.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Measure the detergent according to its label; for a small load, the label may specify 15–30 ml.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Avoid regular fabric softener unless the manufacturer recommends otherwise.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Air-dry the garment and do not place it on a hot radiator.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Sales conversation","type":"text"}]},{"type":"paragraph","content":[{"text":"Ask whether the customer is washing a merino layer on its own or a mixed-material garment. With mixed fabrics, separate washes may be better than using one detergent for everything.","type":"text"}]}]},"product_bullets":["Merino Care is intended for merino wool and delicate natural fibres.","Choose the temperature and programme primarily according to the garment label.","Use the detergent dosage stated on its label.","Do not add regular fabric softener unless it is explicitly recommended.","Air-dry as directed, away from excessive heat."],"key_points_title":"Key points","conversation_title":"Customer conversation","conversation":[{"text":"Can I wash a merino shirt with regular detergent?","speaker":"client"},{"text":"Choose Merino Care for merino, and check the care label first. Regular detergent may not be suitable for delicate wool.","speaker":"seller"},{"text":"Which programme and temperature should I use?","speaker":"client"},{"text":"Use a wool programme or hand-wash only if the care label allows it, and follow the stated temperature.","speaker":"seller"},{"text":"Can I dry the shirt on a radiator?","speaker":"client"},{"text":"Do not put it on a hot radiator. Air-dry it according to the care label.","speaker":"seller"}],"youtube_video_id":"Hs9QuFjKbRA","youtube_video_ids":["Hs9QuFjKbRA"],"image_path":null},{"lesson_id":310,"module_sort_order":2,"sort_order":5,"title":"Jeans Care","summary":"Choose Jeans Care for denim and take the construction of motorcycle clothing into account.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Motorcycle denim is not always ordinary jeans","type":"text"}]},{"type":"paragraph","content":[{"text":"Motorcycle clothing may contain stretch fibres, linings, armour and reinforced panels. Before recommending a detergent, check the material composition and which components can be removed. The garment label specifies the wash programme and drying method.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Care step by step","type":"text"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Check the care label and material composition.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Remove the armour if the manufacturer allows it.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Choose Jeans Care for denim and follow the label for dosage.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Select the programme stated on the care label.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Dry the garment as directed, without excessive heat.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Choose a product that suits the garment","type":"text"}]},{"type":"paragraph","content":[{"text":"Jeans Care is not a universal product for every type of clothing. If the customer has trousers with a membrane or a high proportion of technical fibres, follow their material composition and care instructions. The 40 ml sachet is a compact option.","type":"text"}]}]},"product_bullets":["Choose Jeans Care for denim, including motorcycle clothing when its care label allows it.","Check the material composition, blends, and whether the garment has armour or a lining.","Set the programme and temperature according to the manufacturer’s care symbols.","Do not automatically use a denim detergent on wool or membrane garments.","The 40 ml sachet can be a practical sample or travel size."],"key_points_title":"Key points","conversation_title":"Customer conversation","conversation":[{"text":"I have reinforced motorcycle jeans. Can I wash them?","speaker":"client"},{"text":"Yes—Jeans Care is intended for denim and garments with aramid fibres. Check the label, turn the trousers inside out, and choose a gentle wash, usually up to 30°C with a low spin; air-dry them.","speaker":"seller"},{"text":"Can I tumble-dry them?","speaker":"client"},{"text":"Air-dry them and do not use a tumble dryer. Check the trousers’ care label too.","speaker":"seller"},{"text":"Is Jeans Care suitable for a membrane jacket?","speaker":"client"},{"text":"Do not choose it for a membrane jacket. For technical clothing, choose Textile Care according to the care label.","speaker":"seller"}],"youtube_video_id":null,"youtube_video_ids":[],"image_path":null},{"lesson_id":311,"module_sort_order":2,"sort_order":6,"title":"Sales role-play: choosing care for different garment types","summary":"Practise choosing a detergent for several types of clothing and responding to a request for waterproofing.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Three scenarios to practise","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"A membrane jacket, thermal shirt and jeans: separate the garments and choose a product for each material.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"The customer wants to “waterproof” a jacket with Fabric Protect: explain the difference and check whether they need a separate waterproofing product.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"The customer is washing only a merino top: show Merino Care and the relevant care-label instructions.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Recommendation approach","type":"text"}]},{"type":"paragraph","content":[{"text":"Restate the customer’s need in your own words, ask about the material composition and washing method, then recommend one product. Explain what it is for and what it cannot do. Recommend an additional product only if it addresses a separate need.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Exercise objective","type":"text"}]},{"type":"paragraph","content":[{"text":"After each scenario, the salesperson should be able to explain the recommendation based on the material and its care instructions, instead of offering every customer the same detergent.","type":"text"}]}]},"product_bullets":["Choose a product according to the material, fabric composition and garment manufacturer’s instructions.","Textile Care is suitable for technical garments; Active Care is for synthetic sportswear and base layers.","Merino Care and Jeans Care are for different types of fibres.","Fabric Protect helps maintain freshness during washing, but is not a waterproofing treatment.","Do not sell a complete kit if the customer needs only one product."],"key_points_title":"Key points","conversation_title":"Customer conversation","conversation":[{"text":"I have a membrane jacket, a thermal shirt and jeans. I want one detergent for everything.","speaker":"client"},{"text":"I understand. Choose separate detergents for these three materials: Textile Care for the jacket, Active Care for the synthetic base layer and Jeans Care for denim—following each care label.","speaker":"seller"},{"text":"Will Fabric Protect waterproof the jacket?","speaker":"client"},{"text":"No, the additive helps maintain freshness after washing. If you want the jacket to repel water, it needs a separate waterproofing treatment.","speaker":"seller"},{"text":"I’m washing only a merino top. Do I need to buy a kit?","speaker":"client"},{"text":"No. Merino Care is enough if the care label allows washing; follow the programme specified by the manufacturer.","speaker":"seller"}],"youtube_video_id":null,"youtube_video_ids":[],"image_path":null},{"lesson_id":312,"module_sort_order":3,"sort_order":0,"title":"How to care for motorcycle gloves","summary":"Identify whether the issue is on the inside or outside of the glove and choose the right care method.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"First identify the problem","type":"text"}]},{"type":"paragraph","content":[{"text":"Gloves combine leather, textiles, armour, seams and hard-to-reach fingers. Ask whether the customer wants to remove dirt from the outside, freshen the inside or condition dry leather. These needs call for different solutions.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Check the glove instructions","type":"text"}]},{"type":"paragraph","content":[{"text":"Not every pair can be machine-washed or turned inside out. It is especially important to check the manufacturer’s recommendations for leather gloves. Do not soak or stretch them unless the instructions say to.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Choose the right care","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Odour inside that is difficult to remove: consider Magiczne Rękawiczki and follow their instructions.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Dirt on the outside: choose a product to suit the glove material and manufacturer’s recommendations.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"A zip is stiff but not damaged: consider Zip Service.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Scuffs, delamination and broken seams: a care product cannot replace a repair.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"A concise recommendation","type":"text"}]},{"type":"paragraph","content":[{"text":"When recommending a product, explain what it is for and what it cannot do. Magiczne Rękawiczki freshen the inside; they do not fully wash or repair the glove.","type":"text"}]}]},"product_bullets":["Gloves have seams, armour and different materials, so check the care label.","Distinguish dirt on the outside from odour or moisture inside.","Do not assume that gloves can be machine-washed or turned inside out.","Magiczne Rękawiczki help freshen hard-to-reach areas inside.","Damaged or delaminated seams and scuffed leather need professional repair."],"key_points_title":"Key points","conversation_title":"Customer conversation","conversation":[{"text":"My gloves smell, but I can’t turn them inside out.","speaker":"client"},{"text":"Use Magiczne Rękawiczki to freshen hard-to-reach areas inside. Put the impregnated pair on your hands and clean the inside, following the instructions.","speaker":"seller"},{"text":"Can I just put them in the washing machine?","speaker":"client"},{"text":"Only if the glove manufacturer allows machine-washing. Check the label—gloves may include leather, armour and bonded parts.","speaker":"seller"},{"text":"The material is scuffed. Will the product repair it?","speaker":"client"},{"text":"No. A care product will not repair a scuff or seam; take the gloves to a repair service.","speaker":"seller"}],"youtube_video_id":null,"youtube_video_ids":[],"image_path":null},{"lesson_id":313,"module_sort_order":3,"sort_order":1,"title":"Magiczne Rękawiczki: use and demonstration","summary":"Show the customer how to use Magiczne Rękawiczki to freshen the inside of their gloves.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Why use Magiczne Rękawiczki","type":"text"}]},{"type":"paragraph","content":[{"text":"The impregnated pair makes it easier to clean hard-to-reach areas inside gloves that cannot easily be turned inside out. This can be especially useful for leather gloves if their instructions allow this method of freshening.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Demonstration","type":"text"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Open the sachet and put the single-use pair on your hands.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Put your hands inside the motorcycle gloves.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Move your fingers and apply gentle pressure so the product reaches the inside.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Do not pull at the lining or force the glove inside out.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"When finished, remove the impregnated pair and wash your hands as directed.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"What not to promise","type":"text"}]},{"type":"paragraph","content":[{"text":"This is a practical way to freshen the inside, not a substitute for washing the whole glove, repairing seams or removing every type of dirt. The customer should use the product as directed on the packaging.","type":"text"}]}]},"product_bullets":["The sachet contains one pair of impregnated, single-use gloves.","Put them on your hands, place your hands inside the motorcycle gloves and move your fingers.","Work gently to reach the inside without turning the glove inside out.","This is a way to freshen the inside, not to fully wash or repair the gloves.","After use, remove the product and wash your hands as directed."],"key_points_title":"Key points","conversation_title":"Customer conversation","conversation":[{"text":"How do I use Magiczne Rękawiczki?","speaker":"client"},{"text":"Put the impregnated, single-use pair on your hands, place them inside the motorcycle gloves and move your fingers to clean the inside.","speaker":"seller"},{"text":"Do I need to turn the gloves inside out?","speaker":"client"},{"text":"No. That is why you put your hands, wearing the impregnated gloves, inside them. Do not pull at the lining.","speaker":"seller"},{"text":"Does this replace washing the whole glove?","speaker":"client"},{"text":"No, it is a way to freshen the inside. After use, remove the single-use pair and follow the product instructions.","speaker":"seller"},{"text":"Can I use them with leather gloves?","speaker":"client"},{"text":"First check the glove manufacturer’s recommendations and the product instructions, then use them accordingly.","speaker":"seller"}],"youtube_video_id":null,"youtube_video_ids":[],"image_path":null},{"lesson_id":314,"module_sort_order":3,"sort_order":2,"title":"Zip Service: zip care and add-on sales","summary":"Explain what Zip Service does for zips and distinguish maintenance from repairing damage.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"For a working zip that sticks","type":"text"}]},{"type":"paragraph","content":[{"text":"Zip Service is a care product for zips that are stiff but not mechanically damaged. Ask whether the problem is friction and resistance, or whether teeth are missing or the slider is bent.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"How to demonstrate use","type":"text"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Clean any visible dirt from the zip.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Apply a small amount of Zip Service to the teeth, as directed on the label.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Move the slider back and forth several times to distribute the product.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Wipe away any excess with a clean, dry cloth.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Check the zip’s movement without using excessive force.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"An add-on product","type":"text"}]},{"type":"paragraph","content":[{"text":"You can recommend it as a practical add-on for clothing, footwear or a bag if the customer mentions a zip problem. Do not promise that it will repair broken teeth, torn fabric or a damaged slider.","type":"text"}]}]},"product_bullets":["Zip Service helps working metal and plastic zips slide more smoothly.","Apply a small amount to the teeth and move the slider back and forth several times.","Wipe away excess with a clean, dry cloth.","It can be useful for zips on clothing, footwear and bags.","It will not repair broken teeth or a damaged slider."],"key_points_title":"Key points","conversation_title":"Customer conversation","conversation":[{"text":"The zip on my jacket is stiff. Will Zip Service help?","speaker":"client"},{"text":"If the slider and teeth are intact, Zip Service can help maintain the zip. Apply a small amount to the teeth, move the slider back and forth a few times, and wipe away any excess.","speaker":"seller"},{"text":"How much should I apply?","speaker":"client"},{"text":"A small amount, as directed on the label. After distributing it, wipe away any residue with a clean, dry cloth.","speaker":"seller"},{"text":"One of the teeth is broken. Will it repair it?","speaker":"client"},{"text":"No. Zip Service maintains working zips but does not repair damaged teeth or sliders.","speaker":"seller"}],"youtube_video_id":null,"youtube_video_ids":[],"image_path":null},{"lesson_id":315,"module_sort_order":4,"sort_order":0,"title":"Where to start with motorcycle care","summary":"Identify the type of dirt and choose a simple motorcycle-care routine.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Start with an assessment","type":"text"}]},{"type":"paragraph","content":[{"text":"A motorcycle after a dry ride needs a different approach from one ridden in the rain or through mud. Ask what kind of dirt is present, how heavy it is, and whether the customer has access to water, a pressure washer and a garage. This helps you recommend a simple sequence instead of a random collection of products.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Quick refresh","type":"text"}]},{"type":"paragraph","content":[{"text":"For light dust between full washes, Wash & Ride and a clean, soft microfibre cloth may be enough. Do not use this method to rub off coarse sand, which can scratch the paint.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Full wash","type":"text"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Consider Bug Killer as a pre-wash step for dried-on insects.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Use Moto Wash or a prepared Power Powder solution for the main wash.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"For deposits on the wheels, choose Wheelixir and the right accessory.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Rinse and dry the motorcycle according to the product instructions.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"You can apply Ceramic Detailer as a finishing step to a clean, cool surface.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Explain the limitations","type":"text"}]},{"type":"paragraph","content":[{"text":"Do not apply products to hot components or let them dry on the surface if the instructions warn against this. Ceramic Detailer does not replace washing or a professional, long-lasting coating.","type":"text"}]}]},"product_bullets":["Identify dust, insects, brake dust, grease or heavy mud.","Ask about access to water and the cleaning conditions.","Wash & Ride is suitable for light dust between full washes.","Bug Killer, Moto Wash and Wheelixir are for different steps and types of dirt.","Use Ceramic Detailer after washing, on a clean, cool surface."],"key_points_title":"Key points","conversation_title":"Customer conversation","conversation":[{"text":"My motorcycle is only dusty, and I have five minutes. What do you recommend?","speaker":"client"},{"text":"For light dust between full washes, use Wash & Ride and a clean microfibre cloth. If there is a lot of sand or mud, rinse and wash the motorcycle first.","speaker":"seller"},{"text":"Can I use one product to clean insects and the wheels?","speaker":"client"},{"text":"Choose Bug Killer for insects, Wheelixir for deposits on the wheels, and Moto Wash for washing the whole motorcycle.","speaker":"seller"},{"text":"Can I start while the engine is hot?","speaker":"client"},{"text":"Wait for the motorcycle to cool down. Do not apply products to hot components.","speaker":"seller"}],"youtube_video_id":null,"youtube_video_ids":[],"image_path":null},{"lesson_id":316,"module_sort_order":4,"sort_order":1,"title":"Wash & Ride: motorcycle cleaning","summary":"Show when Wash & Ride is a convenient choice and how to use it safely on light dirt.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Quick cleaning without a hose","type":"text"}]},{"type":"paragraph","content":[{"text":"Wash & Ride is convenient when a motorcycle needs a light refresh and the customer has no access to a hose or bucket. It complements regular washing; it is not a substitute when there is a thick layer of mud, sand or heavy deposits.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"How to use it","type":"text"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Make sure the surface is cool.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Spray the product onto a small area as directed on the label.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Gently wipe away the dirt with a clean, soft microfibre cloth; do not press hard.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Turn the cloth to a clean side or replace it when it picks up dirt.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"For heavy dirt, stop and plan a full wash.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Who it is for","type":"text"}]},{"type":"paragraph","content":[{"text":"The product is useful between washes in the garage, in a car park or on the road. It helps refresh the appearance and leaves a light protective layer as stated by the product manufacturer.","type":"text"}]}]},"product_bullets":["Wash & Ride is for dust and light dirt between full washes.","Use it on a cool surface and gently wipe away dirt with a clean microfibre cloth.","It can be useful in a garage, car park or while travelling.","Do not use it to rub off a thick layer of sand or mud.","For heavy dirt, rinse the motorcycle and carry out a full wash."],"key_points_title":"Key points","conversation_title":"Customer conversation","conversation":[{"text":"I don’t have a hose or bucket. How can I refresh my motorcycle?","speaker":"client"},{"text":"If the dirt is light, use Wash & Ride and a clean, soft microfibre cloth. Work on a cool surface and wipe away the dirt without pressing hard.","speaker":"seller"},{"text":"Will it work after a muddy ride?","speaker":"client"},{"text":"Do not use it on a thick layer of mud or sand. Rinse the dirt off first and do a full wash.","speaker":"seller"},{"text":"Can I use it on a hot engine?","speaker":"client"},{"text":"No. Wait for the components to cool down and use the product as directed on the label.","speaker":"seller"}],"youtube_video_id":"aqzUkc7BheU","youtube_video_ids":["aqzUkc7BheU"],"image_path":null},{"lesson_id":317,"module_sort_order":4,"sort_order":2,"title":"Power Powder: preparation and use","summary":"Explain how to prepare a Power Powder solution and choose the right variant for the job.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Prepare the concentrate before use","type":"text"}]},{"type":"paragraph","content":[{"text":"Power Powder is a powder that must be dissolved in water according to the instructions for the specific variant. Do not sprinkle it directly onto the motorcycle, and do not assume that all sachets work the same way.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Choose a product for the task","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Moto Wash is for the main wash.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Bug Killer helps remove insects and organic dirt as a pre-wash step.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Wheelixir is intended for wheels and deposits around them.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Preparing a solution","type":"text"}]},{"type":"paragraph","content":[{"text":"The 500 ml Shaker can help measure the water and prepare a portion. Read the dosage on the packaging, dissolve the powder in the correct amount of water, and use the solution as directed by the manufacturer. Do not treat the products as interchangeable.","type":"text"}]}]},"product_bullets":["Once dissolved, Power Powder Moto Wash is used for the main motorcycle wash.","The Moto Wash package contains three sachets; follow the instructions for use.","Bug Killer and Wheelixir are separate concentrates for different purposes.","The 500 ml Shaker bottle can be used to prepare a solution.","Do not give one dilution ratio for all powders."],"key_points_title":"Key points","conversation_title":"Customer conversation","conversation":[{"text":"Can I sprinkle the powder directly onto the fairing?","speaker":"client"},{"text":"No. First dissolve Power Powder in water according to the packaging instructions, then use the prepared solution.","speaker":"seller"},{"text":"Are all sachets diluted in the same way?","speaker":"client"},{"text":"No. Moto Wash, Bug Killer and Wheelixir have different uses; check the dosage for each one separately.","speaker":"seller"},{"text":"What do I need a Shaker bottle for?","speaker":"client"},{"text":"It makes it easier to measure the water and prepare a portion of solution, if this method is allowed by the instructions.","speaker":"seller"}],"youtube_video_id":null,"youtube_video_ids":[],"image_path":null},{"lesson_id":318,"module_sort_order":4,"sort_order":3,"title":"Bug Killer and Wheelixir: removing dirt","summary":"Choose Bug Killer for organic dirt and Wheelixir for deposits on wheels.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Two different problems, two products","type":"text"}]},{"type":"paragraph","content":[{"text":"Bug Killer is for pre-treating insects, bird droppings and other organic dirt. Wheelixir is for deposits on wheels and around the brake calipers. Neither replaces washing the entire motorcycle.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"How to use them","type":"text"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Prepare the Power Powder concentrate as directed on its label.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Apply Bug Killer to the dirt before the main wash.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Wait for the time stated in the instructions, then rinse or proceed with washing.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Apply Wheelixir to the wheel and use an appropriate brush if needed.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Rinse the wheel and loosened dirt thoroughly.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Address the customer’s problem","type":"text"}]},{"type":"paragraph","content":[{"text":"If there are insects on the fairing, recommend a product for organic dirt. If dark deposits are on the wheel, choose a wheel cleaner. Check compatibility and work on a cool surface.","type":"text"}]}]},"product_bullets":["Use Bug Killer as a pre-wash step for insects and organic dirt.","Choose Wheelixir for wheels and brake deposits.","Dissolve Power Powder variants beforehand as directed on the label.","Leave Bug Killer on for the time stated in the instructions and do not let it dry.","Rinse wheels thoroughly after using Wheelixir; choose a brush that suits the surface."],"key_points_title":"Key points","conversation_title":"Customer conversation","conversation":[{"text":"There are dried-on insects on my fairing. What should I use?","speaker":"client"},{"text":"Apply Bug Killer to the dirt before washing and leave it for the time stated on the label. Then rinse it off and wash the motorcycle.","speaker":"seller"},{"text":"And what should I use to remove dark deposits from the wheel?","speaker":"client"},{"text":"Use Wheelixir for deposits on the wheels. If needed, choose a suitable wheel brush and rinse thoroughly after cleaning.","speaker":"seller"},{"text":"Can I pour out Power Powder without diluting it?","speaker":"client"},{"text":"No. First dissolve the powder in water using the ratio stated on the packaging.","speaker":"seller"}],"youtube_video_id":"WsgHV1M274Y","youtube_video_ids":["WsgHV1M274Y"],"image_path":null},{"lesson_id":319,"module_sort_order":4,"sort_order":4,"title":"Ceramic Detailer: finishing and protection","summary":"Present Ceramic Detailer as the final finish for a clean motorcycle.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"The finishing step after washing","type":"text"}]},{"type":"paragraph","content":[{"text":"Ceramic Detailer is for finishing a clean motorcycle. It can enhance gloss and colour and provide a water-repellent effect. It is not a heavy-duty dirt remover or a professional ceramic coating that lasts for years.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Demonstration","type":"text"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Work on a cool surface, out of direct sunlight.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Spray a small amount onto a microfibre cloth or follow the label instructions.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Apply the product in small sections rather than soaking a large area.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Buff it with a clean, dry side of the cloth or with a second microfibre cloth.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Check for streaks and repeat only as directed.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Set clear expectations","type":"text"}]},{"type":"paragraph","content":[{"text":"The Detailer can support routine care and help reduce dirt adhesion. The motorcycle still needs washing, and the product does not replace a durable coating or paint restoration.","type":"text"}]}]},"product_bullets":["Use Ceramic Detailer on a clean surface after washing or a light refresh.","It helps add gloss and a water-repellent effect when used as intended.","This is a quick detailer, not a professional ceramic coating that lasts for years.","Work on a cool surface, out of direct sunlight.","Apply it with a microfibre cloth in small sections and buff with a dry side."],"key_points_title":"Key points","conversation_title":"Customer conversation","conversation":[{"text":"Is Ceramic Detailer a coating that lasts for several years?","speaker":"client"},{"text":"No. It is a quick detailer for finishing and routine care, not a durable professional ceramic coating.","speaker":"seller"},{"text":"Can I apply it to a dirty motorcycle?","speaker":"client"},{"text":"Wash and dry the motorcycle first. Apply the Detailer to a clean, cool surface, working in small sections.","speaker":"seller"},{"text":"Will I no longer need to wash the motorcycle after using it?","speaker":"client"},{"text":"You will still need to wash it. The Detailer helps finish the surface but does not replace washing.","speaker":"seller"}],"youtube_video_id":"mofx3RgqndY","youtube_video_ids":["mofx3RgqndY"],"image_path":null},{"lesson_id":320,"module_sort_order":4,"sort_order":5,"title":"Brushes and microfibre cloths: choosing accessories","summary":"Choose a microfibre cloth and brush for each step, and avoid transferring dirt between surfaces.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Choose accessories for the surface","type":"text"}]},{"type":"paragraph","content":[{"text":"Even a good product cannot replace the right tool. A soft microfibre cloth removes light dirt and is used for finishing. Choose separate brushes for wheels, the chain and hard-to-reach details.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Keep clean and dirty areas separate","type":"text"}]},{"type":"paragraph","content":[{"text":"Do not transfer grease from the chain to the paintwork, fairings or visor. Deposits from a wheel can also scratch delicate surfaces. When the cloth picks up dirt, switch to a clean side or use a clean cloth.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Choosing accessories on a limited budget","type":"text"}]},{"type":"paragraph","content":[{"text":"If the customer is starting from scratch, ask about their main concern. A clean, soft microfibre cloth is versatile for many light tasks. Recommend an additional brush only for a specific area.","type":"text"}]}]},"product_bullets":["Use clean, soft microfibre cloths for light cleaning and finishing.","Use separate cloths for different steps and surfaces.","Do not use a chain brush on paintwork or a visor.","A detailing brush helps reach hard-to-access areas.","Choose a wheel brush that suits the surface to avoid scratching the paintwork."],"key_points_title":"Key points","conversation_title":"Customer conversation","conversation":[{"text":"Is one microfibre cloth enough for the whole motorcycle?","speaker":"client"},{"text":"Use separate, clean microfibre cloths for each step so that dirt from the wheels and drivetrain is not transferred to the paintwork.","speaker":"seller"},{"text":"Can I use a detailing brush and chain brush interchangeably?","speaker":"client"},{"text":"No. A chain brush is for the drivetrain; a detailing brush is for hard-to-reach details. Do not use the chain brush on paintwork.","speaker":"seller"},{"text":"Where should I start if I have a limited budget?","speaker":"client"},{"text":"Start with a clean, soft microfibre cloth. Add a brush only for a specific area that is hard to clean.","speaker":"seller"}],"youtube_video_id":"xYSzhwsyZjs","youtube_video_ids":["xYSzhwsyZjs","sqLlcgn_lQA","FvYwpb_PqlA"],"image_path":null},{"lesson_id":321,"module_sort_order":5,"sort_order":0,"title":"What kinds of dirt build up during off-road riding?","summary":"Identify off-road dirt and choose Mud Breaker or Dirt Finisher to match its severity.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Why off-road riding needs a different approach","type":"text"}]},{"type":"paragraph","content":[{"text":"After an off-road ride, a motorcycle may be covered in mud, sand, dust and residue from puddles. Dry particles are abrasive, so do not start by wiping the whole bike with a microfibre cloth. First assess the amount of dirt and prepare for safe cleaning.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Choose one of two approaches","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Thick, dried mud: use Mud Breaker as directed, then rinse thoroughly.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Light dust after a dry ride: Dirt Finisher and a clean microfibre cloth may be enough.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"A lot of sand: remove it safely before wiping the surface.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Questions to ask before recommending","type":"text"}]},{"type":"paragraph","content":[{"text":"Ask what kind of terrain the customer rides on and whether they have access to water. Mud Breaker needs to be rinsed off. Do not promise that it will prevent future mud from sticking or make the motorcycle self-cleaning.","type":"text"}]}]},"product_bullets":["Mud, sand and dust need a different approach from light road dirt.","Do not wipe a thick layer of dry sand, as the particles can cause scratches.","Mud Breaker softens heavy dirt and must be rinsed off thoroughly.","Dirt Finisher helps with light dust and final finishing.","Ask whether water is available and work on a cool surface."],"key_points_title":"Key points","conversation_title":"Customer conversation","conversation":[{"text":"I’m back from motocross with a thick layer of mud. Can I wipe the bike straight away?","speaker":"client"},{"text":"Do not wipe thick, dry mud or sand. Soften the dirt with Mud Breaker and rinse it thoroughly.","speaker":"seller"},{"text":"After a dry ride, there is only dust. Do I need a full wash?","speaker":"client"},{"text":"Dirt Finisher and a clean microfibre cloth may be enough for light dust. If there is a lot of sand, remove it safely first.","speaker":"seller"},{"text":"I don’t have access to water after a ride.","speaker":"client"},{"text":"Mud Breaker needs to be rinsed off, so use it where water is available. Choose a method that suits the dirt and the conditions.","speaker":"seller"}],"youtube_video_id":null,"youtube_video_ids":[],"image_path":null},{"lesson_id":322,"module_sort_order":5,"sort_order":1,"title":"Mud Breaker: removing mud","summary":"Learn how to use Mud Breaker safely on heavy mud and rinse away dirt properly.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"A product for heavy dirt","type":"text"}]},{"type":"paragraph","content":[{"text":"Mud Breaker helps soften mud, sand and mineral dirt after off-road riding. Explain that it prepares dirt for rinsing; it is not a waterless cleaning method.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"How to use it","type":"text"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Wait for the motorcycle to cool down.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Assess how much mud there is and make sure water is available.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Apply the product to dirty components as directed on the label.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Leave it to work for the stated time, without letting it dry.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Rinse away the dirt and product thoroughly with water.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Brushes and follow-up care","type":"text"}]},{"type":"paragraph","content":[{"text":"A suitable brush can help reach difficult areas, but use it gently and do not scrub dry. After rinsing, the customer can decide whether they need Dirt Finisher for the final finish.","type":"text"}]}]},"product_bullets":["Mud Breaker is designed for heavy mud and mineral dirt.","Make sure the motorcycle has cooled down and have water ready for rinsing.","Use it on a dirty surface as directed on the label.","Do not let the product dry; brush gently only if needed.","Rinse the vehicle thoroughly after the product has worked."],"key_points_title":"Key points","conversation_title":"Customer conversation","conversation":[{"text":"Will Mud Breaker remove dried mud from the swingarm?","speaker":"client"},{"text":"Yes, it softens the mud so it is easier to rinse away. Spray the dirty surface, wait briefly and rinse thoroughly; for heavy deposits, gently use a brush if needed.","speaker":"seller"},{"text":"I don’t have a hose. Should I use it in the car park?","speaker":"client"},{"text":"Not unless you can rinse it off. Use Mud Breaker where water is available, because the vehicle must be rinsed thoroughly after it has worked.","speaker":"seller"},{"text":"Can I leave the product to dry?","speaker":"client"},{"text":"No. Rinse it off before it dries and do not apply it to hot components.","speaker":"seller"}],"youtube_video_id":null,"youtube_video_ids":[],"image_path":null},{"lesson_id":323,"module_sort_order":5,"sort_order":2,"title":"Dirt Finisher: finishing and care","summary":"Explain how Dirt Finisher is used for light dirt and as a step after a heavier wash.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Lighter care for off-road motorcycles","type":"text"}]},{"type":"paragraph","content":[{"text":"Dirt Finisher is not another version of Mud Breaker. It helps with light dirt and finishing a cleaner surface. For heavy mud, it is a follow-up step only after the dirt has been softened and rinsed away.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"How to use it","type":"text"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Check that the surface is cool and free of thick sand.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Shake the bottle as directed.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Spray a small amount onto the chosen area.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Gently wipe away light dirt with a clean microfibre cloth.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Change the cloth when it picks up sand or mud.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Match it to the amount of dirt","type":"text"}]},{"type":"paragraph","content":[{"text":"Dirt Finisher may be enough on its own for light dust after riding on gravel. For a thick layer of clay, use Mud Breaker and rinse first. The finishing step can make later care easier, but it does not eliminate dirt.","type":"text"}]}]},"product_bullets":["Dirt Finisher is intended for light cleaning and finishing.","For heavy mud, use Mud Breaker first and rinse thoroughly.","Before use, remove coarse sand and check that the surface is cool.","Shake the bottle and work in small sections.","Wipe away dirt with a clean microfibre cloth and replace it when it becomes heavily soiled."],"key_points_title":"Key points","conversation_title":"Customer conversation","conversation":[{"text":"Do I need to buy Mud Breaker and Dirt Finisher together?","speaker":"client"},{"text":"No. Dirt Finisher is enough for light dust. For heavy mud, use Mud Breaker first and rinse; add the finishing product only if you need it.","speaker":"seller"},{"text":"Will Dirt Finisher handle a thick layer of clay?","speaker":"client"},{"text":"No. First soften the mud with Mud Breaker and rinse it off. Dirt Finisher is for lighter cleaning and finishing.","speaker":"seller"},{"text":"Can I wipe away a lot of sand with it?","speaker":"client"},{"text":"Remove coarse sand first. Do not rub particles into the surface with a microfibre cloth, as they can scratch it.","speaker":"seller"}],"youtube_video_id":null,"youtube_video_ids":[],"image_path":null},{"lesson_id":324,"module_sort_order":5,"sort_order":3,"title":"How to choose an Off-Road Kit","summary":"Choose an off-road care kit to suit the riding style, amount of dirt and access to water.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Ask what the customer means by a “kit”","type":"text"}]},{"type":"paragraph","content":[{"text":"The customer may mean a ready-made package or a set of care products. Ask what they ride, what kind of dirt they encounter most often and whether they have access to water after a ride. Until you confirm a specific product, present the solution as a two-step system.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Tailor the recommendation to the rider","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Motocross on a muddy track: Mud Breaker, rinsing and Dirt Finisher if needed.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Enduro on dry gravel: Dirt Finisher for light dust.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Quad or mountain bike in heavy mud: choose a product and check the vehicle’s care instructions.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"No access to water: plan to clean where you can rinse the vehicle properly.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Accessories and choosing the essentials","type":"text"}]},{"type":"paragraph","content":[{"text":"A clean, soft microfibre cloth is useful for finishing, and a suitable brush can reach tight areas. Do not add products unnecessarily. First recommend the essentials that solve the problem, then present a second step as an option.","type":"text"}]}]},"product_bullets":["Find out whether the customer rides motocross, enduro, a quad or a mountain bike.","For heavy mud, recommend Mud Breaker and access to water for rinsing.","For light dust, the customer can start with Dirt Finisher.","Recommend an extra microfibre cloth or brush only if there is a real need.","Do not present Off-Road Kit as a specific ready-made package unless you have confirmed the product."],"key_points_title":"Key points","conversation_title":"Customer conversation","conversation":[{"text":"I want one enduro kit and don’t want five different liquids. What are the essentials?","speaker":"client"},{"text":"If you most often deal with heavy mud and have water for rinsing, start with Mud Breaker. Add Dirt Finisher only if you also want to finish the clean surface.","speaker":"seller"},{"text":"I mostly ride on dry gravel. Do I need both products?","speaker":"client"},{"text":"No. For light dust, start with Dirt Finisher and a clean microfibre cloth.","speaker":"seller"},{"text":"Is Off-Road Kit a ready-made box?","speaker":"client"},{"text":"Let’s check which retail option is currently available. If you mean a care kit, I can recommend Mud Breaker and Dirt Finisher as two separate steps.","speaker":"seller"}],"youtube_video_id":null,"youtube_video_ids":[],"image_path":null},{"lesson_id":325,"module_sort_order":6,"sort_order":0,"title":"How to identify a customer’s needs","summary":"Ask questions that uncover the customer’s needs and lead to a simple recommendation.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Sales starts with listening","type":"text"}]},{"type":"paragraph","content":[{"text":"A customer may describe a problem without knowing product names: “I’m looking for something for my helmet” or “my jacket smells unpleasant.” Your task is to clarify what they need, not immediately list the available products.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Five helpful questions","type":"text"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"What would you like to clean or protect?","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"What is the main issue: insects, dust, mud, sweat or conditioning?","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"What material is the garment or surface made from?","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Where will you use the product, and will you have access to water?","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Is this a one-off need or for regular care?","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"From answers to a recommendation","type":"text"}]},{"type":"paragraph","content":[{"text":"You do not need to ask every question. Choose the ones that affect which product is suitable. Restate the problem in your own words, recommend one solution, explain how to use it and mention an important limitation. Suggest an add-on only when it fills a specific gap in the process.","type":"text"}]}]},"product_bullets":["Ask what the customer wants to clean or protect.","Identify the specific issue: insects, dust, mud, odour or conditioning.","Check the material, conditions of use and how often it needs care.","Summarise the problem in your own words before recommending a product.","Present one or two suitable solutions and explain how to use them."],"key_points_title":"Key points","conversation_title":"Customer conversation","conversation":[{"text":"I need a good cleaning product. What do you recommend?","speaker":"client"},{"text":"First, let’s find out what you want to clean: a helmet, clothing or a motorcycle. What problem are you trying to solve—insects, dirt, odour or material care?","speaker":"seller"},{"text":"It’s the helmet visor and dried-on insects.","speaker":"client"},{"text":"In that case, start with Helmet Gel to soften the insects. Then you can finish the clean visor with Helmet Detailer.","speaker":"seller"},{"text":"The customer asks only about the price straight away. What should I say?","speaker":"client"},{"text":"Give the price if you know it, then briefly ask what they need it for. This helps you identify the right option without pushing an unnecessary product.","speaker":"seller"}],"youtube_video_id":null,"youtube_video_ids":[],"image_path":null},{"lesson_id":326,"module_sort_order":6,"sort_order":1,"title":"How to recommend kits instead of individual products","summary":"Show the value of a kit by explaining its care steps, and choose a size that suits how it will be used.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Explain the process, not just the price","type":"text"}]},{"type":"paragraph","content":[{"text":"A kit makes sense when the customer understands the steps it covers. For leather garments, these may include cleaning, conditioning and freshening the inside. For helmets, consider cleaning the outer surfaces and choosing a size that is convenient at home or on the road.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Choose a kit to suit the situation","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Consider Leather Care Kit for someone who needs several steps for leather care.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Trip Kit is handy for travel.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"GIGA can be convenient for regular care at home or for several helmets.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"If the customer already has accessories, recommend only the missing product.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Check what the customer needs","type":"text"}]},{"type":"paragraph","content":[{"text":"A kit is not always the best choice. Ask what the customer already owns, how often they care for their gear and where they will use it. A kit’s value comes from convenience and suitability, not simply from the number of items.","type":"text"}]}]},"product_bullets":["Explain the process: cleaning, conditioning or finishing, and then the interior if relevant.","Leather Care Kit can combine care for outer leather with freshening the interior.","Trip Kit is suitable for travel; GIGA is for regular helmet care.","A customer who already owns some products can buy only what is missing.","Finish by asking how and how often the products will be used."],"key_points_title":"Key points","conversation_title":"Customer conversation","conversation":[{"text":"Why do I need a kit if I only need one product?","speaker":"client"},{"text":"If you already have the other products and accessories, buy only the product you are missing. A kit makes sense when you want to complete every step of the care routine.","speaker":"seller"},{"text":"I need something for my helmet while travelling. What should I choose?","speaker":"client"},{"text":"Choose Trip Kit—it has compact bottles that are easy to take on the road. For regular cleaning at home, compare it with GIGA.","speaker":"seller"},{"text":"Does the larger kit work better?","speaker":"client"},{"text":"No, the kits differ in size and contents. Choose according to how often you clean and how many helmets you have.","speaker":"seller"}],"youtube_video_id":null,"youtube_video_ids":[],"image_path":null},{"lesson_id":327,"module_sort_order":6,"sort_order":2,"title":"How to increase sales with complementary products","summary":"Recommend at most one relevant complementary product to support the care process the customer is already starting.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Good complementary selling","type":"text"}]},{"type":"paragraph","content":[{"text":"An add-on is valuable when it completes another step in the process. A customer buying a cleaner may also need a product for follow-up conditioning or a suitable cloth. If they already own that item, there is no reason to recommend it again.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Natural product pairings","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Helmet Gel → Helmet Detailer and a suitable cloth.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Leather Cleaner → Leather Milk after the leather has been cleaned and dried.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Textile Care → Fabric Protect as an additive for freshness, not waterproofing.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Moto Wash or Bug Killer → Ceramic Detailer after washing and rinsing.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Mud Breaker → Dirt Finisher after a heavy wash if the customer wants a finishing step.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Recommend without pressure","type":"text"}]},{"type":"paragraph","content":[{"text":"Ask what step is missing and offer no more than one relevant add-on. For example: “The cleaner will remove dirt from the leather. If you do not have a product for conditioning it after cleaning, I can show you Leather Milk.” If the customer declines, respect their decision.","type":"text"}]}]},"product_bullets":["An add-on should support the next care step, not simply increase the basket.","Helmet Gel can be paired with the Detailer and a suitable cloth.","Leather Milk complements Leather Cleaner once the leather has dried.","Textile Care can be paired with Fabric Protect as a laundry additive.","Respect a refusal and do not recommend a product that duplicates what the customer already owns."],"key_points_title":"Key points","conversation_title":"Customer conversation","conversation":[{"text":"Why are you recommending a second product?","speaker":"client"},{"text":"An add-on makes sense when it completes a needed step: for example, Leather Milk conditions leather after cleaning. If you already have it, you do not need to buy another.","speaker":"seller"},{"text":"No, thank you. I already have that product.","speaker":"client"},{"text":"Of course. Let’s stick to what you actually need.","speaker":"seller"},{"text":"What should I add to Leather Cleaner if I don’t have a leather conditioner?","speaker":"client"},{"text":"After cleaning and drying the leather, you can use Leather Milk as a separate step.","speaker":"seller"}],"youtube_video_id":null,"youtube_video_ids":[],"image_path":null},{"lesson_id":328,"module_sort_order":6,"sort_order":3,"title":"How to respond to common customer objections","summary":"Respond to objections by understanding the concern, sharing a relevant fact and leaving the decision to the customer.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"An objection provides information","type":"text"}]},{"type":"paragraph","content":[{"text":"“It’s too expensive,” “I already have something similar” or “Is it safe?” are signs that the customer needs clarification. First acknowledge their concern, then ask a brief question, give a factual answer and leave the choice to them.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Four common situations","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Price: ask whether the product will be used occasionally or regularly, then choose the right size.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Regular detergent: compare its intended use with the material and garment label.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Safety: check the surface, finish and instructions; test the product first on leather.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Effectiveness: explain the product’s specific function and limitations.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Answer in three sentences","type":"text"}]},{"type":"paragraph","content":[{"text":"A brief response can acknowledge the concern, share a specific fact and suggest a next step. Do not scare the customer with potential damage, promise that a product works “for everything” or invent a returns policy. If you do not know the answer, check it before making a recommendation.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Practice","type":"text"}]},{"type":"paragraph","content":[{"text":"In pairs, practise responding to these objections: “It’s too expensive,” “I already have regular detergent,” “Is it safe?” and “Will it work?” Swap roles and check that your answer stays within the product’s intended use.","type":"text"}]}]},"product_bullets":["First acknowledge the concern and ask a clarifying question.","When discussing price, choose a size and contents to suit how often it will be used.","For safety, check the surface, care label and manufacturer’s recommendations.","Explain what the product is for instead of making broad promises.","Do not make claims about returns, repairs or results that you cannot verify."],"key_points_title":"Key points","conversation_title":"Customer conversation","conversation":[{"text":"That is too expensive for me.","speaker":"client"},{"text":"I understand. If you will use it occasionally, let’s look at a smaller size or buy only the product you need for this step.","speaker":"seller"},{"text":"Is this product safe for every material?","speaker":"client"},{"text":"There is no single product for everything. Tell me what material you need it for, and I’ll choose a product and method that follow its care label.","speaker":"seller"},{"text":"I saw it for less online.","speaker":"client"},{"text":"Let’s compare the size, variant and kit contents. If it is the same product, you can choose whichever offer suits you better.","speaker":"seller"}],"youtube_video_id":null,"youtube_video_ids":[],"image_path":null},{"lesson_id":329,"module_sort_order":6,"sort_order":4,"title":"Sales conversation role-plays","summary":"Practise complete sales conversations, from identifying a need to choosing one suitable solution.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Scenario: a helmet after a ride","type":"text"}]},{"type":"paragraph","content":[{"text":"The customer has bought their first helmet and has dried-on insects on the visor. Ask whether they clean it at home or on the road. Explain how to soften the dirt and then finish the clean surface. If they ask about Pinlock, distinguish the insert from the outer visor and follow the manufacturer’s instructions.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Scenario: a suit after the season","type":"text"}]},{"type":"paragraph","content":[{"text":"The customer has dirty leather and an odour inside the suit. Separate cleaning the exterior, conditioning after it dries and freshening the interior. If they already own a cleaner, recommend only the missing step. Refer a scuff in the material to a repair service.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Scenario: an enduro bike after riding in mud","type":"text"}]},{"type":"paragraph","content":[{"text":"The customer returns from a demanding off-road ride and has access to water. Recommend Mud Breaker and thorough rinsing; present Dirt Finisher as an optional finishing step. Do not recommend wiping dry sand or applying products to hot components.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Conversation recap","type":"text"}]},{"type":"paragraph","content":[{"text":"In every scenario, identify the need, recommend a suitable product, and explain how to use it and its limitations. Leave the decision to the customer, and if no add-on is needed, finish with the basic solution.","type":"text"}]}]},"product_bullets":["Ask how the product will be used before presenting it.","Choose a product for the specific problem and material.","Explain the order of use and one important safety condition.","Recommend an add-on only if it fills a needed step.","If there is damage or you are unsure, check the instructions or refer the customer to a repair service."],"key_points_title":"Key points","conversation_title":"Customer conversation","conversation":[{"text":"I bought an expensive helmet. I have dried-on insects on the visor and want one product.","speaker":"client"},{"text":"Start with Helmet Gel to soften the insects, then gently wipe them away with a microfibre cloth. If you like, finish the clean visor with Helmet Detailer.","speaker":"seller"},{"text":"Can I clean the Pinlock with the same product?","speaker":"client"},{"text":"No. Use products for the outer visor only on the outside; clean the insert gently according to the helmet manufacturer’s instructions.","speaker":"seller"},{"text":"I have a membrane jacket. Will Fabric Protect waterproof it?","speaker":"client"},{"text":"No. Fabric Protect is added to the wash to help maintain freshness. Choose a separate waterproofing treatment that is suitable for the jacket.","speaker":"seller"},{"text":"I’m back from an enduro ride in heavy mud, but I only want one product.","speaker":"client"},{"text":"In that case, start with Mud Breaker and rinse thoroughly. You can add Dirt Finisher later if you want to finish the clean surface.","speaker":"seller"}],"youtube_video_id":null,"youtube_video_ids":[],"image_path":null}]$en_lessons$::jsonb) AS translated(
  module_sort_order integer, sort_order integer, title text, summary text, content jsonb,
  product_bullets jsonb, key_points_title text, conversation_title text, conversation jsonb
)
WHERE course.slug = 'pielegnacja-i-sprzedaz-produktow-xzone' AND version.version_number = 9 AND version.status = 'published'
  AND module.sort_order = translated.module_sort_order
  AND lesson.sort_order = translated.sort_order
  AND 'en' = 'en'
ON CONFLICT (lesson_id, language_code) DO UPDATE SET
  title = EXCLUDED.title,
  summary = EXCLUDED.summary,
  content = EXCLUDED.content,
  product_bullets = EXCLUDED.product_bullets,
  key_points_title = EXCLUDED.key_points_title,
  conversation_title = EXCLUDED.conversation_title,
  conversation = EXCLUDED.conversation,
  youtube_video_id = COALESCE(lesson_translations.youtube_video_id, EXCLUDED.youtube_video_id),
  youtube_video_ids = CASE WHEN cardinality(lesson_translations.youtube_video_ids) > 0 THEN lesson_translations.youtube_video_ids ELSE EXCLUDED.youtube_video_ids END,
  image_path = COALESCE(lesson_translations.image_path, EXCLUDED.image_path),
  updated_at = now();

-- de: course, module, and lesson text
INSERT INTO public.course_translations (course_version_id, language_code, title, description, image_path)
SELECT version.id,
       'de', translated.title, COALESCE(translated.description, ''), source.image_path
FROM public.courses AS course
JOIN public.course_versions AS version ON version.id = course.published_version_id
JOIN public.course_translations AS source ON source.course_version_id = version.id AND source.language_code = 'pl'
CROSS JOIN LATERAL jsonb_to_record($de_course${"title":"Pflege und Verkauf von Xzone-Produkten","description":"","language_code":"de","course_version_id":13,"course_slug":"pielegnacja-i-sprzedaz-produktow-xzone"}$de_course$::jsonb) AS translated(title text, description text)
WHERE course.slug = 'pielegnacja-i-sprzedaz-produktow-xzone' AND version.version_number = 9 AND version.status = 'published'
  AND translated.title IS NOT NULL AND 'de' = 'de'
ON CONFLICT (course_version_id, language_code) DO UPDATE SET
  title = EXCLUDED.title,
  description = EXCLUDED.description,
  image_path = COALESCE(course_translations.image_path, EXCLUDED.image_path),
  updated_at = now();

INSERT INTO public.module_translations (module_id, language_code, title, summary, image_path)
SELECT module.id,
       'de', translated.title, COALESCE(translated.summary, ''), source.image_path
FROM public.courses AS course
JOIN public.course_versions AS version ON version.id = course.published_version_id
JOIN public.course_modules AS module ON module.course_version_id = version.id
JOIN public.module_translations AS source ON source.module_id = module.id AND source.language_code = 'pl'
CROSS JOIN LATERAL jsonb_to_recordset($de_modules$[{"module_id":61,"module_sort_order":0,"title":"Helmpflege","summary":""},{"module_id":62,"module_sort_order":1,"title":"Lederbekleidung pflegen","summary":""},{"module_id":63,"module_sort_order":2,"title":"Pflege von Textilbekleidung","summary":""},{"module_id":64,"module_sort_order":3,"title":"Handschuhe und Zubehör","summary":""},{"module_id":65,"module_sort_order":4,"title":"Motorrad-Detailing","summary":""},{"module_id":66,"module_sort_order":5,"title":"Pflege von Offroad-Motorrädern","summary":""},{"module_id":67,"module_sort_order":6,"title":"Erfolgreich Xzone-Produkte verkaufen","summary":""}]$de_modules$::jsonb) AS translated(module_sort_order integer, title text, summary text)
WHERE course.slug = 'pielegnacja-i-sprzedaz-produktow-xzone' AND version.version_number = 9 AND version.status = 'published'
  AND module.sort_order = translated.module_sort_order
  AND 'de' = 'de'
ON CONFLICT (module_id, language_code) DO UPDATE SET
  title = EXCLUDED.title,
  summary = EXCLUDED.summary,
  image_path = COALESCE(module_translations.image_path, EXCLUDED.image_path),
  updated_at = now();

INSERT INTO public.lesson_translations (
  lesson_id, language_code, title, summary, youtube_video_id, content, product_bullets,
  key_points_title, conversation_title, conversation, youtube_video_ids, image_path
)
SELECT lesson.id,
       'de', translated.title, COALESCE(translated.summary, ''), source.youtube_video_id,
       translated.content, COALESCE(translated.product_bullets, '[]'::jsonb),
       translated.key_points_title, translated.conversation_title,
       COALESCE(translated.conversation, '[]'::jsonb), source.youtube_video_ids, source.image_path
FROM public.courses AS course
JOIN public.course_versions AS version ON version.id = course.published_version_id
JOIN public.course_modules AS module ON module.course_version_id = version.id
JOIN public.course_lessons AS lesson ON lesson.module_id = module.id
JOIN public.lesson_translations AS source ON source.lesson_id = lesson.id AND source.language_code = 'pl'
CROSS JOIN LATERAL jsonb_to_recordset($de_lessons$[{"lesson_id":294,"module_id":61,"module_sort_order":0,"sort_order":0,"title":"Warum braucht ein Helm die richtige Pflege?","summary":"Unterscheiden Sie die drei Bereiche eines Helms und wählen Sie für jeden die passende Pflege.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Warum ein Helm sorgfältige Pflege braucht","type":"text"}]},{"type":"paragraph","content":[{"text":"Beim Fahren gelangen Insekten, Straßenstaub und Regen auf den Helm; sein Innenfutter kommt mit Schweiß und Feuchtigkeit in Kontakt. Schmutz auf der Außenseite des Visiers kann die Sicht einschränken, und ein vernachlässigtes Innenfutter mindert den Komfort. Fragen Sie im Kundengespräch zuerst, welcher Bereich des Helms Pflege braucht.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Drei Bereiche, drei Pflegemethoden","type":"text"}]},{"type":"heading","attrs":{"level":3},"content":[{"text":"Helmschale und äußere Visierseite","type":"text"}]},{"type":"paragraph","content":[{"text":"Bei eingetrockneten Insekten nicht trocken reiben. Helmet Gel weicht den Schmutz auf, sodass er sich vorsichtig abnehmen lässt. Helmet Detailer dient anschließend zur Pflege der bereits gereinigten Oberfläche.","type":"text"}]},{"type":"heading","attrs":{"level":3},"content":[{"text":"Innenfutter","type":"text"}]},{"type":"paragraph","content":[{"text":"Ein Erfrischer hilft, den Helm zwischen den Reinigungen frisch zu halten, entfernt Schmutz jedoch nicht wie eine Wäsche. Prüfen Sie vor dem Waschen, ob sich das Innenfutter herausnehmen lässt und wie es laut Helmanleitung zu reinigen ist.","type":"text"}]},{"type":"heading","attrs":{"level":3},"content":[{"text":"Pinlock","type":"text"}]},{"type":"paragraph","content":[{"text":"Die Pinlock-Innenscheibe ist empfindlich und muss separat behandelt werden. Tragen Sie weder Gel noch Detailer darauf auf und reiben Sie sie nicht ab. Spülen Sie sie mit destilliertem Wasser ab und lassen Sie sie an der Luft trocknen. Beachten Sie dabei die Empfehlungen des Helmherstellers.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"So beginnen Sie das Gespräch","type":"text"}]},{"type":"paragraph","content":[{"text":"Fragen Sie, ob der Kunde das Visier und die Helmschale, das Innenfutter oder beide Bereiche pflegen möchte. Wählen Sie erst danach ein Produkt aus. Gehen Sie nicht davon aus, dass jeder ein komplettes Set oder tägliche Pflege benötigt.","type":"text"}]}]},"product_bullets":["Behandeln Sie Helmschale, äußere Visierseite und Innenfutter getrennt – jeder Bereich erfordert eine andere Pflege.","Weichen Sie eingetrocknete Insekten zuerst mit Helmet Gel auf; reiben Sie sie nicht trocken ab.","Verwenden Sie Helmet Detailer zur Pflege der gereinigten Oberfläche.","Ein Innenraumerfrischer ersetzt nicht das Waschen eines verschmutzten Innenfutters.","Behandeln Sie Pinlock separat und beachten Sie die Anleitung des Helmherstellers."],"key_points_title":"Das Wichtigste","conversation_title":"Kundengespräch","conversation":[{"text":"Ich habe einen neuen Helm. Muss ich gleich das komplette Pflegeset kaufen?","speaker":"client"},{"text":"Nein. Wenn Sie Visier und Helmschale gleich pflegen möchten, wählen Sie Produkte für die Außenflächen. Ein Produkt für den Innenbereich wird erst nötig, wenn das Innenfutter aufgefrischt oder gewaschen werden muss.","speaker":"seller"},{"text":"Kann ich Visier und Innenfutter mit demselben Mittel reinigen?","speaker":"client"},{"text":"Am besten trennen Sie diese Schritte. Verwenden Sie für die Außenseite des Visiers ein dafür vorgesehenes Produkt und reinigen Sie das Innenfutter mit einem separaten Mittel gemäß der Helmanleitung.","speaker":"seller"},{"text":"Mich stören im Moment nur die Insekten auf dem Visier.","speaker":"client"},{"text":"Dann beginnen Sie mit Helmet Gel und einem sauberen Mikrofasertuch. Den Detailer können Sie ergänzen, wenn Sie das gereinigte Visier anschließend pflegen möchten.","speaker":"seller"}]},{"lesson_id":295,"module_id":61,"module_sort_order":0,"sort_order":1,"title":"Helmet Gel und Helmet Detailer – Unterschiede und Anwendung","summary":"Lernen Sie die richtige Reihenfolge für Helmet Gel und Helmet Detailer kennen und wählen Sie Tuch und Produktgröße passend zum Bedarf des Kunden.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Zwei Produkte mit unterschiedlichen Aufgaben","type":"text"}]},{"type":"paragraph","content":[{"text":"Helmet Gel und Helmet Detailer ergänzen sich, ersetzen einander aber nicht. Das Gel bereitet eine verschmutzte Oberfläche vor, der Detailer wird nach der Reinigung verwendet.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Schritt 1: Schmutz aufweichen","type":"text"}]},{"type":"paragraph","content":[{"text":"Tragen Sie Helmet Gel auf die verschmutzte Stelle auf und lassen Sie es gemäß Etikett einwirken. Für die Reisegröße werden etwa fünf Minuten angegeben; bei starker Sonneneinstrahlung verkürzen Sie die Einwirkzeit. Lassen Sie das Mittel nicht antrocknen. Sobald der Schmutz aufgeweicht ist, nehmen Sie ihn ohne starken Druck mit einem sauberen Mikrofasertuch ab.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Schritt 2: saubere Oberfläche nachbehandeln","type":"text"}]},{"type":"paragraph","content":[{"text":"Verwenden Sie Helmet Detailer erst, nachdem der Schmutz entfernt wurde. Zum Aufnehmen gelösten Schmutzes eignet sich ein dickeres Mikrofasertuch; für das abschließende Finish verwenden Sie ein Evolon-Tuch. Beginnen Sie immer mit sauberen Hilfsmitteln.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Wählen Sie die Größe passend zur Nutzung","type":"text"}]},{"type":"paragraph","content":[{"text":"Die 30-ml-Größe lässt sich leicht auf Reisen mitnehmen. Die 250-ml-Flasche ist praktisch, wenn der Helm regelmäßig gereinigt wird. Fragen Sie den Kunden, wo und wie oft er die Produkte verwenden möchte.","type":"text"}]}]},"product_bullets":["Helmet Gel ist Schritt 1: Es weicht eingetrocknete Insekten und Schmutz auf, bevor Sie sie vorsichtig entfernen.","Lassen Sie das Mittel gemäß Anleitung einwirken; für die Reisegröße werden etwa fünf Minuten angegeben. Verkürzen Sie die Einwirkzeit in der Sonne.","Helmet Detailer ist Schritt 2: Verwenden Sie ihn auf einer sauberen Oberfläche, um das Finish zu vereinheitlichen und Streifen zu vermeiden.","Nehmen Sie gelösten Schmutz mit einem dickeren, sauberen Mikrofasertuch auf; verwenden Sie Evolon für das Finish.","Die Produkte sind in Reisegrößen mit 30 ml und größeren 250-ml-Flaschen erhältlich. Wählen Sie die Größe passend zur Nutzungshäufigkeit."],"key_points_title":"Das Wichtigste","conversation_title":"Kundengespräch","conversation":[{"text":"Reicht der Detailer allein bei eingetrockneten Insekten?","speaker":"client"},{"text":"Bei eingetrockneten Insekten beginnen Sie mit Helmet Gel: Weichen Sie den Schmutz auf und nehmen Sie ihn vorsichtig mit einem Mikrofasertuch ab. Pflegen Sie das saubere Visier anschließend mit dem Detailer.","speaker":"seller"},{"text":"Ich habe einen matten Helm. Bringt der Detailer die Oberfläche zum Glänzen?","speaker":"client"},{"text":"Ja, Sie können ihn auf einem matten Helm verwenden – das Finish bleibt matt. Tragen Sie das Mittel auf ein sauberes Mikrofasertuch auf und beachten Sie die Helmanleitung.","speaker":"seller"},{"text":"Wie lange muss das Gel einwirken?","speaker":"client"},{"text":"Halten Sie sich an die Einwirkzeit auf dem Etikett; für die Reisegröße werden etwa fünf Minuten angegeben. Lassen Sie das Mittel nicht antrocknen und verkürzen Sie die Einwirkzeit in der Sonne.","speaker":"seller"},{"text":"Kann ich ein Papiertuch verwenden?","speaker":"client"},{"text":"Verwenden Sie ein sauberes, weiches Mikrofasertuch. Papier kann rau sein und empfindliche Oberflächen zerkratzen.","speaker":"seller"}]},{"lesson_id":296,"module_id":61,"module_sort_order":0,"sort_order":2,"title":"Wie reinigt man Visier und Pinlock richtig?","summary":"Lernen Sie, die Außenseite des Visiers sicher zu reinigen und sie von der empfindlichen Pinlock-Innenscheibe zu unterscheiden.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Stellen Sie zuerst fest, welche Oberfläche Sie reinigen","type":"text"}]},{"type":"paragraph","content":[{"text":"Die Außenseite des Visiers und die Pinlock-Innenscheibe erfordern unterschiedliche Pflege. Prüfen Sie vor der Verwendung eines Mittels die Anleitungen des jeweiligen Helm- und Visierherstellers sowie die Hinweise zur Beschichtung.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Außenseite des Visiers – schonende Reinigung Schritt für Schritt","type":"text"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Entfernen Sie losen Sand und andere Körner, ohne zu reiben. Polieren Sie Schmutz nicht trocken weg.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Tragen Sie bei eingetrockneten Insekten Helmet Gel auf und lassen Sie es gemäß Etikett einwirken. Lassen Sie das Mittel nicht antrocknen.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Nehmen Sie den aufgeweichten Schmutz ohne starken Druck mit einem sauberen Tuch ab.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Wenn es die Visieranleitung erlaubt, verwenden Sie Helmet Detailer und ein sauberes Evolon-Tuch für das Finish.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Pinlock – eine separate, empfindliche Innenscheibe","type":"text"}]},{"type":"paragraph","content":[{"text":"Verwenden Sie auf der Innenscheibe weder Helmet Gel noch Helmet Detailer. Polieren Sie sie nicht mit einem Tuch. Spülen Sie sie ohne Reiben mit destilliertem Wasser ab und lassen Sie sie an der Luft trocknen.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Was diese Produkte nicht leisten","type":"text"}]},{"type":"paragraph","content":[{"text":"Die Mittel dienen der Reinigung und Pflege. Sie entfernen keine Kratzer und reparieren kein beschädigtes Visier.","type":"text"}]}]},"product_bullets":["Entfernen Sie losen Sand ohne Reiben, bevor Sie das Visier reinigen.","Tragen Sie bei eingetrockneten Insekten auf der Außenseite des Visiers das Gel auf und nehmen Sie den Schmutz ohne Druck ab.","Pflegen Sie das saubere Visier außen mit dem Detailer und einem Evolon-Tuch.","Tragen Sie auf Pinlock weder Gel noch Detailer auf und polieren Sie es nicht mit einem Mikrofasertuch.","Spülen Sie Pinlock mit destilliertem Wasser ab und lassen Sie es an der Luft trocknen."],"key_points_title":"Das Wichtigste","conversation_title":"Kundengespräch","conversation":[{"text":"Kann ich Pinlock mit demselben Mittel wie die Visieraußenseite reinigen?","speaker":"client"},{"text":"Nein. Verwenden Sie Helmet Gel und Detailer auf der Außenseite des Visiers. Reinigen Sie Pinlock vorsichtig mit destilliertem Wasser und ohne Reiben. Beachten Sie die Helmanleitung.","speaker":"seller"},{"text":"Auf dem Visier ist Sand. Kann ich es gleich mit einem Mikrofasertuch abwischen?","speaker":"client"},{"text":"Spülen Sie zuerst lose Partikel ab oder entfernen Sie sie vorsichtig. Reiben Sie den Sand nicht über das Visier, denn er kann es zerkratzen.","speaker":"seller"},{"text":"Entfernen diese Mittel Kratzer?","speaker":"client"},{"text":"Nein. Sie dienen der Reinigung und Pflege, reparieren aber keine Kratzer.","speaker":"seller"}]},{"lesson_id":297,"module_id":61,"module_sort_order":0,"sort_order":3,"title":"Wie pflegt man das Helminnere?","summary":"Unterscheiden Sie zwischen dem Auffrischen des Helminneren und dem Waschen eines verschmutzten Innenfutters.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Ermitteln Sie zuerst den Bedarf","type":"text"}]},{"type":"paragraph","content":[{"text":"Fragen Sie, ob der Kunde das Helminnere nach der Fahrt auffrischen möchte oder ob das Innenfutter sichtbar verschmutzt ist. Ein Erfrischer und eine Wäsche lösen unterschiedliche Probleme: Das Mittel hilft, die Frische zu erhalten; ein verschmutztes Innenfutter muss richtig gereinigt werden.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Auffrischen zwischen den Wäschen","type":"text"}]},{"type":"paragraph","content":[{"text":"Mint-Erfrischer ist für das Helminnere vorgesehen. Sprühen Sie ihn aus etwa 15–20 cm Entfernung auf und lassen Sie den Helm vor dem Aufsetzen vollständig trocknen. Das Mittel ist nicht für die Anwendung auf Haut oder Körper bestimmt.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Innenfutter waschen","type":"text"}]},{"type":"paragraph","content":[{"text":"Prüfen Sie zuerst, ob sich das Innenfutter herausnehmen lässt und welche Empfehlungen der Helmhersteller gibt. Verwenden Sie zum Waschen von Hand ein dafür vorgesehenes Waschmittel gemäß Etikett. Waschen Sie es vorsichtig, spülen Sie es gründlich aus und lassen Sie es an der Luft trocknen. Wringen Sie den Stoff nicht aus und trocknen Sie ihn nicht an einer Wärmequelle.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Wann das Thema wieder aufgreifen","type":"text"}]},{"type":"paragraph","content":[{"text":"Wenn der Geruch trotz Auffrischung anhält, prüfen Sie den Zustand des Innenfutters und erwägen Sie eine Wäsche. Stellen Sie den Erfrischer am besten als Ergänzung zur Pflege zwischen den Wäschen vor.","type":"text"}]}]},"product_bullets":["Fragen Sie, ob den Kunden der Geruch stört oder ob das verschmutzte Innenfutter gewaschen werden muss.","Mint-Erfrischer trägt dazu bei, den Helm zwischen den Reinigungen frisch zu halten, ersetzt aber keine Wäsche.","Sprühen Sie das Helminnere aus etwa 15–20 cm Entfernung ein und warten Sie, bis es vollständig getrocknet ist.","Waschen Sie ein herausnehmbares Innenfutter von Hand gemäß der Helmanleitung.","Spülen Sie es gründlich aus und lassen Sie es an der Luft trocknen; wringen Sie es nicht aus und verwenden Sie keine Wärmequelle."],"key_points_title":"Das Wichtigste","conversation_title":"Kundengespräch","conversation":[{"text":"Das Helminnere riecht nach Schweiß. Was empfehlen Sie?","speaker":"client"},{"text":"Wählen Sie Mint zum schnellen Auffrischen zwischen den Wäschen. Wenn das Innenfutter verschmutzt ist, waschen Sie es mit einem separaten Mittel gemäß der Helmanleitung.","speaker":"seller"},{"text":"Kann ich das Mittel auf meinen Kopf sprühen?","speaker":"client"},{"text":"Nein. Verwenden Sie es gemäß Etikett im Helminneren, nicht auf der Haut.","speaker":"seller"},{"text":"Kann ich den Helm gleich nach der Anwendung aufsetzen?","speaker":"client"},{"text":"Warten Sie, bis das Helminnere vollständig getrocknet ist. Wenn der Geruch zurückkehrt, muss das Innenfutter möglicherweise gewaschen werden.","speaker":"seller"}]},{"lesson_id":298,"module_id":61,"module_sort_order":0,"sort_order":4,"title":"Welches Set sollte man dem Kunden empfehlen – GIGA oder Trip Kit?","summary":"Wählen Sie Trip Kit oder GIGA passend dazu aus, wo und wie oft der Kunde seinen Helm reinigt.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Wählen Sie das Set passend zur Nutzung","type":"text"}]},{"type":"paragraph","content":[{"text":"Trip Kit und GIGA umfassen die Reinigungsschritte für die Helmaußenseite: Schmutz mit Gel aufweichen und anschließend mit dem Detailer nachbehandeln. Sie unterscheiden sich vor allem in der Gebindegröße und der Aufbewahrung.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Trip Kit – für unterwegs","type":"text"}]},{"type":"paragraph","content":[{"text":"Kompakte Verpackungen und ein Reisebeutel erleichtern es, das Set auf Tour mitzunehmen, im Koffer oder Staufach zu verstauen und bei einem Halt schnell zu verwenden.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"GIGA – für die regelmäßige Pflege","type":"text"}]},{"type":"paragraph","content":[{"text":"Die größeren 250-ml-Flaschen mit Gel und Detailer eignen sich für häufige Reinigung zu Hause oder in der Garage, etwa wenn mehrere Helme gepflegt werden.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Fragen, die bei der Auswahl helfen","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Wo wird der Helm meistens gereinigt – unterwegs oder zu Hause?","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Wie oft wird der Kunde den Helm reinigen?","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Ein Helm oder mehrere?","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Wird nur der Schritt zum Entfernen von Insekten benötigt oder auch das abschließende Finish?","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"Wenn den Kunden ein Geruch im Helminneren stört, sprechen Sie über ein separates Innenraumpflegemittel. Ein Set für die Helmaußenseite ersetzt nicht das Waschen des Innenfutters.","type":"text"}]}]},"product_bullets":["Trip Kit und GIGA dienen der zweistufigen Reinigung der Helmaußenseite.","Trip Kit hat kompakte Verpackungen und einen Beutel und eignet sich daher für unterwegs.","GIGA enthält 250-ml-Flaschen und Zubehör für die regelmäßige Anwendung zu Hause oder in der Garage.","Wählen Sie zum Auffrischen des Helminneren ein separates Produkt – die Sets für die Außenpflege ersetzen es nicht.","Fragen Sie, wo und wie oft der Kunde den Helm reinigen wird; gehen Sie nicht davon aus, dass ein größeres Set besser ist."],"key_points_title":"Das Wichtigste","conversation_title":"Kundengespräch","conversation":[{"text":"Ich möchte etwas zur Helmpflege auf Tour. Welches Set soll ich nehmen?","speaker":"client"},{"text":"Trip Kit ist kompakt und für unterwegs gedacht. Es enthält Produkte für die Außenpflege des Helms sowie Zubehör.","speaker":"seller"},{"text":"Eignet sich Trip Kit besser für die regelmäßige Reinigung von zwei Helmen zu Hause?","speaker":"client"},{"text":"Für die häufige Anwendung kann GIGA mit den größeren Gebinden praktischer sein. Wählen Sie die Größe passend zur Nutzungshäufigkeit und Anzahl der Helme.","speaker":"seller"},{"text":"Reinigt das Set auch das Innenfutter?","speaker":"client"},{"text":"Nein. Das Set ist für die Pflege der Helmaußenseite gedacht. Wählen Sie bei Bedarf ein separates Produkt für das Helminnere.","speaker":"seller"},{"text":"Mein Gel ist aufgebraucht. Muss ich das Set erneut kaufen?","speaker":"client"},{"text":"Nein. Sie können nur das einzelne Produkt nachkaufen, sofern es separat erhältlich ist.","speaker":"seller"}]},{"lesson_id":299,"module_id":61,"module_sort_order":0,"sort_order":5,"title":"Verkaufssimulation – der Kunde kauft einen neuen Helm","summary":"Üben Sie, den Bedarf eines Helmkäufers zu ermitteln und die Pflege passend zu seiner Situation auszuwählen.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Ziel der Übung","type":"text"}]},{"type":"paragraph","content":[{"text":"Üben Sie ein Gespräch, das einem Käufer eines neuen Helms hilft, eine zu seinem Fahrstil passende Pflege auszuwählen. Beginnen Sie nicht mit einer Produktliste. Finden Sie heraus, wo und wie oft der Kunde den Helm reinigen möchte und welches Problem er lösen will.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Worauf Sie achten sollten","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Stellen Sie mindestens eine Frage, die bei der Wahl der Gebindegröße hilft.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Erklären Sie die Wirkung von Gel und Detailer in zwei kurzen Sätzen.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Bieten Sie keine Ergänzung an, wenn der Kunde sie nicht benötigt.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Versprechen Sie keine konkrete Ergiebigkeit ohne bestätigte Angaben.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Übung zur eigenen Vorbereitung","type":"text"}]},{"type":"paragraph","content":[{"text":"Formulieren Sie die vorbereitete Antwort nach dem Rollenspiel mit eigenen Worten. Stellen Sie zum Schluss eine Frage: „Reinigen Sie Ihren Helm häufiger unterwegs oder zu Hause?“, „Ein Helm oder mehrere?“ oder „Geht es vor allem um Insekten oder auch um das Auffrischen des Helminneren?“ Begründen Sie Ihre Empfehlung in einem Satz.","type":"text"}]}]},"product_bullets":["Fragen Sie zuerst, wo und wie oft der Helm gereinigt wird und wie viele Helme gepflegt werden sollen.","Wählen Sie Trip Kit für die Pflege unterwegs und GIGA für die regelmäßige Anwendung zu Hause.","Erklären Sie kurz die Reihenfolge: Das Gel weicht Schmutz auf, der Detailer pflegt die saubere Oberfläche.","Bieten Sie keinen Innenraumerfrischer an, wenn der Kunde ihn nicht benötigt.","Akzeptieren Sie ein Nein und versprechen Sie keine Ergiebigkeit, die nicht belegt ist."],"key_points_title":"Das Wichtigste","conversation_title":"Kundengespräch","conversation":[{"text":"Ich mache eine einwöchige Tour und möchte keine Insekten auf dem Visier haben. Was soll ich mitnehmen?","speaker":"client"},{"text":"Für die Reinigung unterwegs empfehle ich Trip Kit. Das Gel weicht die Insekten auf; nachdem sie vorsichtig entfernt wurden, pflegt der Detailer das saubere Visier.","speaker":"seller"},{"text":"Kann ich Pinlock mit demselben Set reinigen?","speaker":"client"},{"text":"Verwenden Sie Produkte für die Visieraußenseite nicht auf der Innenscheibe. Reinigen Sie Pinlock vorsichtig gemäß Herstelleranleitung.","speaker":"seller"},{"text":"Ich brauche nichts für das Helminnere; der Helm ist neu.","speaker":"client"},{"text":"In Ordnung – Sie müssen keinen Erfrischer auf Vorrat kaufen. Sie können später darauf zurückkommen, falls Geruch oder Verschmutzungen zum Problem werden.","speaker":"seller"}]},{"lesson_id":300,"module_id":62,"module_sort_order":1,"sort_order":0,"title":"Warum muss Motorradbekleidung aus Leder gepflegt werden?","summary":"Ermitteln Sie Lederart und Verschmutzung und wählen Sie anschließend Reinigung und Pflege getrennt aus.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Stellen Sie zuerst fest, womit Sie es zu tun haben","type":"text"}]},{"type":"paragraph","content":[{"text":"Motorradkombis aus Leder können aus unterschiedlichen Lederarten und Farben bestehen, verschiedene Oberflächen und Textileinsätze haben. Fragen Sie, welcher Bereich gepflegt werden soll, wie stark die Verschmutzung ist und ob der Kunde die Pflegehinweise des Herstellers kennt. Helles oder fluoreszierendes Leder erfordert besondere Vorsicht.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Reinigung und Pflege getrennt behandeln","type":"text"}]},{"type":"paragraph","content":[{"text":"Leather Cleaner entfernt Verschmutzungen. Leather Milk wird erst auf das gereinigte und getrocknete Leder aufgetragen, um es zu pflegen. Das eine Produkt ersetzt nicht automatisch das andere, und Pflegeprodukte reparieren keine mechanischen Schäden.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Zeigen Sie die sichere Reihenfolge","type":"text"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Entfernen Sie losen Staub ohne starkes Reiben.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Testen Sie das Mittel an einer unauffälligen Stelle und warten Sie das Ergebnis ab.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Reinigen Sie die Stelle vorsichtig mit einem geeigneten Cleaner und einer weichen Bürste.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Nehmen Sie Rückstände mit einem sauberen, leicht feuchten Tuch auf und lassen Sie das Leder an der Luft trocknen.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Tragen Sie bei Bedarf gemäß Etikett eine dünne Schicht Leather Milk auf.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Wecken Sie realistische Erwartungen","type":"text"}]},{"type":"paragraph","content":[{"text":"Ein Pflegeprodukt kann reinigen und die laufende Pflege unterstützen, aber weder eine abgenutzte Beschichtung wiederherstellen noch Risse reparieren. Lassen Sie solche Schäden gegebenenfalls von einem Servicebetrieb oder vom Bekleidungshersteller beurteilen.","type":"text"}]}]},"product_bullets":["Ermitteln Sie zuerst Lederart, Farbe und Pflegehinweise des Bekleidungsherstellers.","Leather Cleaner entfernt Verschmutzungen; Leather Milk pflegt das Leder nach dem Trocknen.","Testen Sie das Mittel vor der Anwendung an einer unauffälligen Stelle, besonders bei hellem Leder.","Verwenden Sie zum Reinigen eine weiche Bürste und wenig Druck.","Pflegeprodukte reparieren weder Risse und Abrieb noch beschädigte Beschichtungen."],"key_points_title":"Das Wichtigste","conversation_title":"Kundengespräch","conversation":[{"text":"Ich habe einen Lederkombi mit leuchtenden Einsätzen. Wie beginne ich mit der Reinigung?","speaker":"client"},{"text":"Bei normalen Verschmutzungen wählen Sie Leather Cleaner Normal. Testen Sie bei fluoreszierenden Farben zuerst an einer unauffälligen Stelle und reinigen Sie mit einer weichen Bürste.","speaker":"seller"},{"text":"Ist das Leder nach dem Cleaner bereits gepflegt?","speaker":"client"},{"text":"Der Cleaner entfernt Schmutz. Sobald das Leder vollständig getrocknet ist, können Sie Leather Milk als separaten Pflegeschritt auftragen.","speaker":"seller"},{"text":"Ich habe einen Riss an der Naht. Repariert die Milch das?","speaker":"client"},{"text":"Nein. Pflegeprodukte pflegen das Leder, reparieren aber weder Risse noch beschädigte Nähte. Lassen Sie den Schaden von einem Servicebetrieb begutachten.","speaker":"seller"}]},{"lesson_id":301,"module_id":62,"module_sort_order":1,"sort_order":1,"title":"Leder reinigen – Leather Cleaner und Bürste","summary":"Wählen Sie die Leather-Cleaner-Variante passend zu Verschmutzung und Lederfarbe und zeigen Sie anschließend eine schonende Reinigungstechnik.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Wählen Sie die Variante passend zu Leder und Verschmutzung","type":"text"}]},{"type":"paragraph","content":[{"text":"Wählen Sie nicht automatisch das stärkste Mittel. Normal eignet sich für typische Verschmutzungen und empfindlichere Farben. Strong kommt bei stärkeren Verschmutzungen auf klassischem Leder infrage, sofern die Pflegehinweise des Bekleidungsherstellers dies zulassen.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Anwendung Schritt für Schritt","type":"text"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Schütteln Sie die Flasche und testen Sie das Mittel an einer unauffälligen Stelle.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Geben Sie den Schaum auf eine weiche, leicht angefeuchtete Bürste und nicht direkt auf das gesamte Kleidungsstück.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Reinigen Sie eine kleine Stelle mit ruhigen, sanften Bewegungen.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Nehmen Sie die Verschmutzung mit einem sauberen, leicht feuchten Tuch auf.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Lassen Sie die Bekleidung vor der weiteren Pflege an der Luft trocknen.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Wann Sie anders vorgehen sollten","type":"text"}]},{"type":"paragraph","content":[{"text":"Wenn das Material eine ungewöhnliche Beschichtung, eine kräftige Farbe oder sichtbare Schäden aufweist, unterbrechen Sie die Vorführung und prüfen Sie die Pflegehinweise. Der Cleaner entfernt Schmutz, repariert aber weder Abrieb noch Risse.","type":"text"}]}]},"product_bullets":["Normal eignet sich für typische Verschmutzungen und empfindlichere Farben.","Strong kommt nach einem Test bei stärkeren Verschmutzungen auf klassischem Leder infrage.","Schütteln Sie die Flasche und testen Sie das Mittel an einer verdeckten Stelle.","Geben Sie den Schaum auf eine weiche, leicht feuchte Bürste; schrubben Sie nicht kräftig.","Nehmen Sie Rückstände auf und lassen Sie das Leder an der Luft trocknen."],"key_points_title":"Das Wichtigste","conversation_title":"Kundengespräch","conversation":[{"text":"Ich habe einen weißen Kombi mit fluoreszierenden Einsätzen. Soll ich Strong wählen?","speaker":"client"},{"text":"Wählen Sie bei fluoreszierenden Farben Normal und testen Sie es zuerst an einer verdeckten Stelle. Verwenden Sie Strong nur bei starken Verschmutzungen und entsprechend dem Verwendungszweck.","speaker":"seller"},{"text":"Kann ich eine harte Schuhbürste verwenden?","speaker":"client"},{"text":"Verwenden Sie besser eine weiche Bürste. Geben Sie den Schaum auf die leicht angefeuchteten Borsten und reinigen Sie eine kleine Stelle mit sanften, kreisenden Bewegungen.","speaker":"seller"},{"text":"Wann trage ich Leather Milk auf?","speaker":"client"},{"text":"Nehmen Sie nach der Reinigung den Schmutz mit einem sauberen Tuch auf und lassen Sie das Leder an der Luft trocknen. Tragen Sie die Milch erst auf die trockene Oberfläche auf, wenn diese Pflege benötigt.","speaker":"seller"}]},{"lesson_id":302,"module_id":62,"module_sort_order":1,"sort_order":2,"title":"Leder pflegen – Leather Milk","summary":"Erklären Sie Leather Milk als Pflegeschritt nach der Reinigung und dem Trocknen des Leders.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Warum Lederpflege wichtig ist","type":"text"}]},{"type":"paragraph","content":[{"text":"Nach der Reinigung und dem Trocknen kann das Leder eine separate Pflege benötigen. Leather Milk ist der Schritt nach dem Cleaner und kein Waschmittel für verschmutzte Kleidung. Erklären Sie dem Kunden diese Reihenfolge, bevor Sie die Anwendung zeigen.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Sparsame Anwendung","type":"text"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Vergewissern Sie sich, dass das Leder sauber und vollständig trocken ist.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Testen Sie das Mittel an einer unauffälligen Stelle, besonders bei einer ungewöhnlichen Oberflächenbehandlung.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Geben Sie eine kleine Menge des Produkts auf ein weiches Tuch.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Tragen Sie das Mittel gemäß Etikett dünn und gleichmäßig auf.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Lassen Sie das Mittel trocknen und prüfen Sie das Ergebnis vor einer weiteren Anwendung.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Grenzen der Wirkung","type":"text"}]},{"type":"paragraph","content":[{"text":"Die Milch unterstützt die laufende Pflege, repariert aber weder Risse und Abrieb noch beschädigte Beschichtungen. Versprechen Sie keine Wasserfestigkeit, wenn der Produkthersteller sie nicht angibt. Wenden Sie sich bei Fragen an die Pflegehinweise des Kleidungsstücks.","type":"text"}]}]},"product_bullets":["Leather Milk wird auf sauberem, trockenem Leder verwendet.","Tragen Sie das Mittel gemäß Anleitung dünn und gleichmäßig auf.","Testen Sie das Mittel vor dem großflächigen Auftragen an einer verdeckten Stelle.","Verwenden Sie die Milch nicht zum Entfernen von Schmutz.","Versprechen Sie weder die Reparatur von Rissen noch die Wiederherstellung des ursprünglichen Schutzes."],"key_points_title":"Das Wichtigste","conversation_title":"Kundengespräch","conversation":[{"text":"Wozu brauche ich Leather Milk, wenn ich bereits Leather Cleaner habe?","speaker":"client"},{"text":"Der Cleaner entfernt Schmutz, Leather Milk pflegt das Leder nach der Reinigung und dem Trocknen. Wenn das Leder gerade keine Pflege benötigt, müssen Sie die Milch nicht dazukaufen.","speaker":"seller"},{"text":"Kann ich die Milch auf eine schmutzige Jacke auftragen?","speaker":"client"},{"text":"Reinigen und trocknen Sie die Jacke zuerst. Die Milch ersetzt keinen Cleaner.","speaker":"seller"},{"text":"Ich habe mattes Leder. Wie kann ich prüfen, ob die Milch dafür geeignet ist?","speaker":"client"},{"text":"Testen Sie das Mittel an einer unauffälligen Stelle und prüfen Sie die Pflegehinweise des Bekleidungsherstellers. Tragen Sie erst danach gemäß Etikett eine dünne Schicht auf.","speaker":"seller"},{"text":"Repariert die Milch Risse?","speaker":"client"},{"text":"Nein. Risse und Abrieb müssen repariert werden; ein Pflegeprodukt reicht dafür nicht aus.","speaker":"seller"}]},{"lesson_id":303,"module_id":62,"module_sort_order":1,"sort_order":3,"title":"Wie verwendet man das Leather Care Kit?","summary":"Führen Sie den Kunden durch die Pflege mit dem Set und prüfen Sie, ob jedes Produkt seinem Bedarf entspricht.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Das Set als klarer Pflegeablauf","type":"text"}]},{"type":"paragraph","content":[{"text":"Das Leather Care Kit ist praktisch für alle, die das Leder außen pflegen und das Innenfutter der Bekleidung auffrischen möchten. Das Set enthält einen Cleaner, Leather Milk, einen Innenraumerfrischer, eine Bürste und ein Tuch. Zeigen Sie die Reihenfolge, statt nur die einzelnen Bestandteile aufzuzählen.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Reihenfolge der Anwendung","type":"text"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Wählen Sie den Cleaner passend zu Verschmutzung und Farbe und testen Sie ihn anschließend.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Reinigen Sie das Leder mit einer weichen Bürste und nehmen Sie Rückstände auf.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Lassen Sie das Leder an der Luft trocknen.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Tragen Sie gemäß Etikett eine dünne Schicht Leather Milk auf.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Frischen Sie das Innenfutter separat auf und beachten Sie die Anleitung des jeweiligen Produkts.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Das Set nur empfehlen, wenn es passt","type":"text"}]},{"type":"paragraph","content":[{"text":"Fragen Sie, welche Produkte der Kunde bereits besitzt und ob auch das Innenfutter gepflegt werden soll. Wenn er bereits einen Cleaner hat und nur ein Pflegemittel fehlt, bieten Sie nur diesen fehlenden Schritt an. Stellen Sie das Set nicht als Pflichtkauf für jeden dar.","type":"text"}]}]},"product_bullets":["Das Leather Care Kit kombiniert Cleaner, Pflegemilch, Innenraumerfrischer und Zubehör.","Reinigen Sie zuerst das Leder, lassen Sie es trocknen und verwenden Sie anschließend Leather Milk.","Ein Innenraumerfrischer erfüllt einen anderen Zweck als die Pflege der Außenseite.","Wählen Sie Normal oder Strong passend zu Farbe, Verschmutzung und Pflegehinweisen des Kleidungsstücks.","Wenn der Kunde bereits einige Produkte besitzt, bieten Sie nur die noch fehlenden an."],"key_points_title":"Das Wichtigste","conversation_title":"Kundengespräch","conversation":[{"text":"Mein Kombi ist außen schmutzig und riecht innen. Löst das Set beide Probleme?","speaker":"client"},{"text":"Das Leather Care Kit kombiniert Cleaner, Pflegemilch, Innenraumerfrischer und Zubehör. Reinigen Sie zuerst das Leder und pflegen Sie es nach dem Trocknen mit der Milch. Das Innenfutter frischen Sie separat auf.","speaker":"seller"},{"text":"Ich habe bereits einen Cleaner. Lohnt sich trotzdem das ganze Set?","speaker":"client"},{"text":"Das ist nicht nötig, wenn Sie die übrigen Produkte bereits haben. Ergänzen Sie nur die fehlende Pflegemilch oder das Produkt für das Innenfutter.","speaker":"seller"},{"text":"Das Leder ist rissig. Kann das Set es wiederherstellen?","speaker":"client"},{"text":"Es repariert keine Schäden. Lassen Sie einen Lederkombi mit Rissen zuerst von einem Servicebetrieb begutachten.","speaker":"seller"}]},{"lesson_id":304,"module_id":62,"module_sort_order":1,"sort_order":4,"title":"Verkaufssimulation – der Kunde kauft Lederbekleidung","summary":"Üben Sie, die Lederart zu erkennen, eine passende Mindestlösung auszuwählen und auf den Bedarf des Kunden einzugehen.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Das Gespräch beginnt mit der Bedarfsermittlung","type":"text"}]},{"type":"paragraph","content":[{"text":"Ziel des Rollenspiels ist es, eine Lösung für den jeweiligen Kombi zu finden und nicht das ganze Regal zu verkaufen. Fragen Sie nach Farbe, Lederart, Verschmutzungsgrad, Zustand der Bekleidung und bereits vorhandenen Produkten. Erklären Sie erst dann, welche Pflegeschritte nötig sind.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Drei Situationen zum Üben","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Heller Kombi mit fluoreszierenden Einsätzen: Cleaner vorsichtig auswählen und an einer verdeckten Stelle testen.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Schwarze, stark verschmutzte Bekleidung: Cleaner passend zur Lederart wählen, vorsichtig reinigen und trocknen lassen.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Saubere Jacke, die laufende Pflege benötigt: Leather Milk empfehlen, ohne unnötig einen Cleaner dazuzunehmen.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Gemeinsame Zusammenfassung","type":"text"}]},{"type":"paragraph","content":[{"text":"Nach jedem Gespräch sollte der Verkäufer erklären können, was gekauft wird, in welcher Reihenfolge die Produkte verwendet werden und welche Schäden sie nicht beheben. Wenn der Kunde bereits einen Teil des Zubehörs besitzt, kann die Empfehlung auf ein einziges fehlendes Produkt beschränkt sein.","type":"text"}]}]},"product_bullets":["Fragen Sie nach Lederart, Farbe und Zustand sowie nach den Pflegehinweisen des Bekleidungsherstellers.","Trennen Sie die Reinigung der Außenseite, deren Pflege und das Auffrischen des Innenfutters.","Wählen Sie den Cleaner passend zu Farbe und Verschmutzung; testen Sie ihn bei empfindlichem Leder zuerst.","Empfehlen Sie Leather Milk nach dem Trocknen des Leders, wenn der Kunde eine Pflege benötigt.","Verweisen Sie bei mechanischen Schäden an einen Servicebetrieb und versprechen Sie nicht, dass ein Pflegeprodukt sie repariert."],"key_points_title":"Das Wichtigste","conversation_title":"Kundengespräch","conversation":[{"text":"Ich habe einen Kombi mit fluoreszierenden Einsätzen und habe Angst vor Verfärbungen.","speaker":"client"},{"text":"Wählen Sie für fluoreszierende Farben Normal. Testen Sie das Mittel an einer unauffälligen Stelle und reinigen Sie anschließend einen kleinen Bereich mit einer weichen Bürste.","speaker":"seller"},{"text":"Ich habe bereits einen Cleaner. Was fehlt für die Pflege nach der Reinigung?","speaker":"client"},{"text":"Wenn das Leder es benötigt, wählen Sie nur Leather Milk. Tragen Sie es erst auf, wenn das Leder nach der Reinigung getrocknet ist.","speaker":"seller"},{"text":"Der Ärmel ist abgerieben. Kann das Pflegeprodukt die Stelle kaschieren?","speaker":"client"},{"text":"Nein, ein Pflegeprodukt repariert keinen Abrieb. Lassen Sie prüfen, ob der Kombi fachgerecht repariert werden muss.","speaker":"seller"},{"text":"Innen riecht es nach Schweiß. Soll ich das ganze Leder waschen?","speaker":"client"},{"text":"Weichen Sie den Kombi nicht einfach ein. Wählen Sie ein separates Produkt für das Innenfutter und beachten Sie die Pflegehinweise der Bekleidung.","speaker":"seller"}]},{"lesson_id":305,"module_id":63,"module_sort_order":2,"sort_order":0,"title":"Wie pflegt man Textilbekleidung?","summary":"Ermitteln Sie das Bekleidungsmaterial und die Waschanleitung und wählen Sie ein passendes Produkt für die jeweiligen Fasern.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Bevor Sie ein Waschmittel auswählen","type":"text"}]},{"type":"paragraph","content":[{"text":"Motorradbekleidung kann Membran, Futter, Protektoren und unterschiedliche Fasern kombinieren. Fragen Sie, was der Kunde waschen möchte, prüfen Sie das Pflegeetikett und empfehlen Sie erst dann ein Produkt. Temperatur, Waschprogramm, Dosierung und Trocknung richten sich in erster Linie nach der Bekleidungsanleitung.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Wählen Sie das Mittel passend zum Material","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Textile Care: klassische technische Bekleidung und Bekleidung mit Membran.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Active Care: synthetische Sport- und Funktionsbekleidung sowie Mikrofaser.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Merino Care: Merinowolle und empfindliche Naturfasern.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Jeans Care: Denim, auch Motorradbekleidung gemäß Pflegeetikett.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Fabric Protect: Waschzusatz für mehr Frische, kein Imprägniermittel gegen Regen.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Nicht alles nach demselben Schema waschen","type":"text"}]},{"type":"paragraph","content":[{"text":"Eine Jacke mit Membran, ein Funktionsshirt und eine Merinoschicht können unterschiedliche Waschmittel und Programme erfordern. Empfehlen Sie Weichspüler nicht als Ersatz für die Spezialpflege. Wenn der Kunde die wasserabweisende Wirkung erneuern möchte, wählen Sie dafür ein separates Produkt gemäß den Bekleidungshinweisen.","type":"text"}]}]},"product_bullets":["Beginnen Sie mit dem Pflegeetikett: Material, Temperatur, Programm, Waschmittel und Trocknung.","Wählen Sie Textile Care für technische Bekleidung und Active Care für Sportbekleidung.","Merino Care ist für empfindliche Wolle und Jeans Care für Denim vorgesehen.","Fabric Protect sorgt während des Waschens für mehr Frische und ist kein wasserabweisendes Imprägniermittel.","Waschen Sie unterschiedliche Materialien getrennt, wenn sie verschiedene Programme und Waschmittel erfordern."],"key_points_title":"Das Wichtigste","conversation_title":"Kundengespräch","conversation":[{"text":"Ich habe eine Jacke mit Membran, ein Funktionsshirt und einen Merinopullover. Kann ich alles zusammen waschen?","speaker":"client"},{"text":"Waschen Sie die Teile am besten entsprechend ihren Pflegeetiketten getrennt: Es handelt sich um unterschiedliche Materialien, die verschiedene Waschmittel und Programme benötigen können. Wählen Sie Textile Care für die Jacke und ein separates Mittel für Merinowolle.","speaker":"seller"},{"text":"Imprägniert Fabric Protect meine Jacke?","speaker":"client"},{"text":"Nein, Fabric Protect ist ein Waschzusatz, der die Frische unterstützt. Wählen Sie für den Nässeschutz ein separates Imprägniermittel, das für diese Bekleidung geeignet ist.","speaker":"seller"},{"text":"Ich weiß nicht, welches Waschprogramm ich wählen soll.","speaker":"client"},{"text":"Richten Sie Programm und Temperatur nach dem Pflegeetikett aus und prüfen Sie die Waschmitteldosierung auf dem Etikett.","speaker":"seller"}]},{"lesson_id":306,"module_id":63,"module_sort_order":2,"sort_order":1,"title":"Textile Care – Bekleidung waschen","summary":"Erklären Sie den Einsatz von Textile Care und zeigen Sie, wie das Waschmittel sicher für technische Bekleidung ausgewählt wird.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Die Aufgabe von Textile Care","type":"text"}]},{"type":"paragraph","content":[{"text":"Textile Care ist für technische Motorradbekleidung vorgesehen, auch für Kleidung mit Membran. Versprechen Sie im Gespräch nicht, dass das Waschmittel eine abgenutzte Membran repariert oder ihre Eigenschaften nach einer Beschädigung wiederherstellt. Ziel ist eine richtige Wäsche gemäß den Herstellerhinweisen.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Die Wäsche vorbereiten","type":"text"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Prüfen Sie das Pflegeetikett und nehmen Sie Teile heraus, die separat gewaschen werden müssen.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Wählen Sie das zugelassene Waschprogramm und die passende Temperatur.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Dosieren Sie das Waschmittel gemäß Etikett.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Geben Sie keinen herkömmlichen Weichspüler hinzu, es sei denn, der Hersteller empfiehlt es ausdrücklich.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Trocknen Sie die Bekleidung gemäß Pflegeetikett und halten Sie sie von starker Hitze fern, falls dies dort angegeben ist.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Mehr Frische","type":"text"}]},{"type":"paragraph","content":[{"text":"Fabric Protect kann als separater Zusatz die Wäsche ergänzen. Erklären Sie genau seine Aufgabe: Er unterstützt die Frische der Bekleidung, ersetzt aber keine wasserabweisende Imprägnierung.","type":"text"}]}]},"product_bullets":["Textile Care ist zum Waschen technischer Motorradbekleidung und von Kleidung mit Membran vorgesehen.","Waschprogramm, Temperatur und Trocknung richten sich nach dem Pflegeetikett des Kleidungsstücks.","Verwenden Sie herkömmlichen Weichspüler nicht automatisch als Ersatz.","Dosieren Sie das Waschmittel gemäß Produktetikett und Waschanleitung.","Fabric Protect kommt als separater Zusatz für mehr Frische infrage."],"key_points_title":"Das Wichtigste","conversation_title":"Kundengespräch","conversation":[{"text":"Eignet sich Textile Care für eine Jacke mit Membran?","speaker":"client"},{"text":"Ja. Es ist ein Waschmittel für technische Bekleidung und Membranbekleidung. Wählen Sie Programm und Temperatur gemäß dem Pflegeetikett der Jacke.","speaker":"seller"},{"text":"Ich verwende immer Weichspüler. Soll ich das beibehalten?","speaker":"client"},{"text":"Geben Sie bei technischer Bekleidung nicht automatisch Weichspüler hinzu. Prüfen Sie das Pflegeetikett und verwenden Sie Textile Care gemäß Anleitung.","speaker":"seller"},{"text":"Was kann ich hinzufügen, wenn mir Frische nach dem Waschen wichtig ist?","speaker":"client"},{"text":"Sie können Fabric Protect gemäß Etikett in das Weichspülerfach geben, anstelle des herkömmlichen Weichspülers.","speaker":"seller"}]},{"lesson_id":307,"module_id":63,"module_sort_order":2,"sort_order":2,"title":"Fabric Protect – Pflege und Frische nach dem Waschen","summary":"Zeigen Sie, wie Fabric Protect der Wäsche hinzugefügt wird und wie es sich von einem wasserabweisenden Imprägniermittel unterscheidet.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Waschzusatz, kein Imprägniermittel","type":"text"}]},{"type":"paragraph","content":[{"text":"Der Name könnte einen Nässeschutz vermuten lassen, deshalb sollten Sie die Funktion klar erklären. Fabric Protect ist ein Waschzusatz, der die Frische der Bekleidung unterstützt. Er ist kein wasserabweisendes Imprägniermittel und erneuert die DWR-Beschichtung nicht selbstständig.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"So wird es angewendet","type":"text"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Wählen Sie das Waschmittel passend zum Material und prüfen Sie das Pflegeetikett.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Geben Sie Fabric Protect gemäß Anleitung in das Weichspülerfach.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Verwenden Sie die auf dem Etikett angegebene Dosierung.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Starten Sie ein Waschprogramm gemäß den Pflegehinweisen des Kleidungsstücks.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Verwenden Sie zum Imprägnieren ein separates, dafür vorgesehenes Mittel.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"So erklären Sie den Zusatznutzen","type":"text"}]},{"type":"paragraph","content":[{"text":"Wenn der Kunde technische Bekleidung wäscht und sich mehr Frische wünscht, können Sie Fabric Protect als Ergänzung zu Textile Care anbieten. Fragt er nach Regenschutz, erklären Sie offen, dass dafür ein separates Imprägniermittel erforderlich ist.","type":"text"}]}]},"product_bullets":["Fabric Protect ist ein Waschzusatz, der die Frische der Bekleidung unterstützt.","Es kann herkömmlichen Weichspüler ersetzen, wenn das Etikett dies vorsieht.","Geben Sie es gemäß Anleitung in das Weichspülerfach.","Wählen Sie es am besten zusammen mit einem für das Material geeigneten Waschmittel.","Versprechen Sie weder die Wiederherstellung der Wasserdichtigkeit noch einen DWR-Effekt."],"key_points_title":"Das Wichtigste","conversation_title":"Kundengespräch","conversation":[{"text":"Sorgt Fabric Protect dafür, dass die Jacke wieder wasserabweisend ist?","speaker":"client"},{"text":"Nein – es ist ein Waschzusatz für mehr Frische und kein wasserabweisendes Imprägniermittel. Wählen Sie für den Nässeschutz ein separates Imprägniermittel für die Jacke.","speaker":"seller"},{"text":"Wohin gebe ich Fabric Protect?","speaker":"client"},{"text":"Geben Sie es anstelle des herkömmlichen Weichspülers in das Weichspülerfach und wählen Sie ein Waschprogramm gemäß Pflegeetikett.","speaker":"seller"},{"text":"Kann ich es zusammen mit Textile Care verwenden?","speaker":"client"},{"text":"Ja. Textile Care wäscht technische Bekleidung; Fabric Protect wird als separater Schritt in das Weichspülerfach gegeben.","speaker":"seller"}]},{"lesson_id":308,"module_id":63,"module_sort_order":2,"sort_order":3,"title":"Active Care – Pflege von Sportbekleidung","summary":"Wählen Sie Active Care passend zu synthetischer Sport- und Funktionsbekleidung sowie deren Nutzung.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Wann Active Care infrage kommt","type":"text"}]},{"type":"paragraph","content":[{"text":"Active Care eignet sich für synthetische Sportbekleidung, Funktionswäsche und Mikrofaser. Fragen Sie im Gespräch zuerst nach der Aktivität und dem Problem des Kunden, etwa Geruch nach dem Training oder häufigem Waschen der Basisschicht.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Passend zum Material auswählen","type":"text"}]},{"type":"paragraph","content":[{"text":"Fragt der Kunde nach einer Jacke mit Membran, prüfen Sie das Pflegeetikett und ziehen Sie Textile Care in Betracht. Wählen Sie für Merinowolle ein Mittel für empfindliche Naturfasern. Entscheiden Sie sich nicht allein deshalb für Active Care, weil es sich um Sportbekleidung handelt.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Anwendung und Gebindegröße","type":"text"}]},{"type":"paragraph","content":[{"text":"Prüfen Sie Programm, Temperatur und Trocknung immer anhand des Pflegeetiketts. Die Dosierung entnehmen Sie dem Produktetikett. Der 40-ml-Beutel eignet sich zum Ausprobieren oder für unterwegs.","type":"text"}]}]},"product_bullets":["Wählen Sie Active Care für synthetische Sport- und Funktionsbekleidung.","Fragen Sie nach dem Material, Geruch nach dem Training und den Pflegehinweisen auf dem Etikett.","Gehen Sie nicht davon aus, dass es ein Waschmittel für jede Art von Bekleidung ist.","Beachten Sie die Dosierung auf der Verpackung und das Programm auf dem Pflegeetikett.","Der 40-ml-Beutel eignet sich, um das Produkt vor dem Kauf einer größeren Größe auszuprobieren."],"key_points_title":"Das Wichtigste","conversation_title":"Kundengespräch","conversation":[{"text":"Mein Funktionsshirt riecht lange nach Schweiß. Was soll ich nehmen?","speaker":"client"},{"text":"Wenn es sich um synthetische Sport- oder Funktionsbekleidung handelt, wählen Sie Active Care. Waschen Sie das Kleidungsstück gemäß Pflegeetikett und dosieren Sie das Waschmittel nach Packungsangabe.","speaker":"seller"},{"text":"Kann ich Active Care für eine Jacke mit Membran verwenden?","speaker":"client"},{"text":"Wählen Sie für eine Jacke mit Membran Textile Care. Active Care ist für synthetische Sportbekleidung vorgesehen.","speaker":"seller"},{"text":"Kann ich für die Reise eine kleinere Packung nehmen?","speaker":"client"},{"text":"Ja, es gibt einen 40-ml-Beutel. Er ist praktisch zum Ausprobieren oder für unterwegs.","speaker":"seller"}]},{"lesson_id":309,"module_id":63,"module_sort_order":2,"sort_order":4,"title":"Merino Care","summary":"Lernen Sie die Pflege von Merinowolle und empfindlichen Fasern kennen und vermeiden Sie zu allgemeine Empfehlungen.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Empfindliche Fasern brauchen besondere Pflege","type":"text"}]},{"type":"paragraph","content":[{"text":"Merinoschichten tragen zum Komfort beim Fahren bei und müssen gemäß Pflegeetikett behandelt werden. Merino Care ist für Merinowolle und andere vom Hersteller angegebene empfindliche Fasern vorgesehen. Gehen Sie nicht davon aus, dass ein Programm für synthetische Unterwäsche auch für Wolle geeignet ist.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Waschen und trocknen","type":"text"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Prüfen Sie Materialzusammensetzung und Pflegehinweise auf dem Etikett.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Wählen Sie das Wollprogramm oder Handwäsche, sofern dies empfohlen wird.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Dosieren Sie das Waschmittel gemäß Etikett; für eine kleine Ladung können 15–30 ml angegeben sein.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Vermeiden Sie herkömmlichen Weichspüler, sofern der Hersteller nichts anderes empfiehlt.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Lassen Sie die Bekleidung an der Luft trocknen und legen Sie sie nicht auf einen heißen Heizkörper.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Verkaufsgespräch","type":"text"}]},{"type":"paragraph","content":[{"text":"Fragen Sie, ob der Kunde nur die Merinoschicht oder Kleidung aus Materialmix wäscht. Bei Mischgeweben kann getrenntes Waschen sinnvoller sein, als ein Waschmittel für alles zu verwenden.","type":"text"}]}]},"product_bullets":["Merino Care ist für Merinowolle und empfindliche Naturfasern vorgesehen.","Wählen Sie Temperatur und Waschprogramm in erster Linie nach dem Pflegeetikett.","Dosieren Sie das Waschmittel gemäß der Angabe auf dem Etikett.","Geben Sie keinen herkömmlichen Weichspüler hinzu, sofern dies nicht ausdrücklich empfohlen wird.","Trocknen Sie die Bekleidung gemäß Anleitung an der Luft und fern von übermäßiger Wärme."],"key_points_title":"Das Wichtigste","conversation_title":"Kundengespräch","conversation":[{"text":"Kann ich ein Merinoshirt mit normalem Waschmittel waschen?","speaker":"client"},{"text":"Wählen Sie für Merino Merino Care und prüfen Sie zuerst das Pflegeetikett. Normales Waschmittel ist möglicherweise nicht für empfindliche Wolle geeignet.","speaker":"seller"},{"text":"Welches Programm und welche Temperatur soll ich wählen?","speaker":"client"},{"text":"Wählen Sie das Wollprogramm oder Handwäsche nur, wenn das Pflegeetikett es zulässt, und halten Sie die angegebene Temperatur ein.","speaker":"seller"},{"text":"Soll ich das Shirt auf dem Heizkörper trocknen?","speaker":"client"},{"text":"Legen Sie es nicht auf einen heißen Heizkörper. Trocknen Sie es gemäß Pflegeetikett an der Luft.","speaker":"seller"}]},{"lesson_id":310,"module_id":63,"module_sort_order":2,"sort_order":5,"title":"Jeans Care","summary":"Wählen Sie Jeans Care für Denim und berücksichtigen Sie dabei die Konstruktion der Motorradbekleidung.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Motorrad-Denim ist nicht immer eine gewöhnliche Jeans","type":"text"}]},{"type":"paragraph","content":[{"text":"Motorradbekleidung kann elastische Fasern, Futter, Protektoren und verstärkte Bereiche enthalten. Klären Sie vor der Waschmittelempfehlung die Materialzusammensetzung und prüfen Sie, welche Teile herausgenommen werden können. Waschprogramm und Trocknung richten sich nach dem Pflegeetikett.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Pflege Schritt für Schritt","type":"text"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Prüfen Sie Pflegeetikett und Materialzusammensetzung.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Nehmen Sie die Protektoren heraus, wenn der Hersteller dies zulässt.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Wählen Sie Jeans Care für Denim und dosieren Sie es gemäß Etikett.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Wählen Sie das auf dem Pflegeetikett angegebene Programm.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Trocknen Sie die Bekleidung gemäß den Empfehlungen und vermeiden Sie übermäßige Wärme.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Wählen Sie das passende Produkt für das Kleidungsstück","type":"text"}]},{"type":"paragraph","content":[{"text":"Jeans Care ist kein Universalwaschmittel für jede Art von Bekleidung. Bei Hosen mit Membran oder einem hohen Anteil technischer Fasern richten Sie sich nach Materialzusammensetzung und Pflegeanleitung. Der 40-ml-Beutel ist ein kompaktes Format.","type":"text"}]}]},"product_bullets":["Wählen Sie Jeans Care für Denim, auch für Motorradbekleidung, sofern das Pflegeetikett dies zulässt.","Prüfen Sie Materialzusammensetzung, Beimischungen sowie Protektoren und Futter.","Wählen Sie Programm und Temperatur gemäß den Herstellerangaben.","Verwenden Sie ein Jeanswaschmittel nicht automatisch für Wolle oder Bekleidung mit Membran.","Der 40-ml-Beutel eignet sich als praktische Probier- oder Reisegröße."],"key_points_title":"Das Wichtigste","conversation_title":"Kundengespräch","conversation":[{"text":"Ich habe verstärkte Motorradjeans. Kann ich sie waschen?","speaker":"client"},{"text":"Ja. Jeans Care ist für Denim und Bekleidung mit Aramidfasern vorgesehen. Prüfen Sie das Pflegeetikett, drehen Sie die Hose auf links und wählen Sie einen Schonwaschgang, in der Regel bis 30 °C mit niedriger Schleuderdrehzahl. Lassen Sie sie an der Luft trocknen.","speaker":"seller"},{"text":"Kann ich sie im Wäschetrockner trocknen?","speaker":"client"},{"text":"Lassen Sie die Hose an der Luft trocknen und verwenden Sie keinen Wäschetrockner. Beachten Sie auch das Pflegeetikett.","speaker":"seller"},{"text":"Eignet sich Jeans Care für eine Jacke mit Membran?","speaker":"client"},{"text":"Wählen Sie es nicht für eine Jacke mit Membran. Nehmen Sie für technische Bekleidung Textile Care und beachten Sie das Pflegeetikett.","speaker":"seller"}]},{"lesson_id":311,"module_id":63,"module_sort_order":2,"sort_order":6,"title":"Verkaufssimulation – Pflege passend zur Bekleidungsart auswählen","summary":"Üben Sie die Auswahl des Waschmittels für verschiedene Bekleidungsarten und beantworten Sie die Frage nach Imprägnierung.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Drei Szenarien zum Üben","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Jacke mit Membran, Funktionsshirt und Jeans: Trennen Sie die Kleidungsstücke und wählen Sie für jedes Material ein geeignetes Produkt.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Der Kunde möchte die Jacke mit Fabric Protect „imprägnieren“: Erklären Sie den Unterschied und klären Sie, ob ein separates Imprägniermittel benötigt wird.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Der Kunde wäscht nur einen Merinopullover: Zeigen Sie Merino Care und beachten Sie die Pflegehinweise auf dem Etikett.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Empfehlungsschema","type":"text"}]},{"type":"paragraph","content":[{"text":"Fassen Sie den Bedarf des Kunden mit eigenen Worten zusammen, fragen Sie nach Material und Waschweise und empfehlen Sie dann ein Produkt. Erklären Sie dessen Einsatz und Grenzen. Bieten Sie nur dann ein weiteres Produkt an, wenn es einem anderen Bedarf entspricht.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Ziel der Übung","type":"text"}]},{"type":"paragraph","content":[{"text":"Nach jeder Szene sollte der Verkäufer die Empfehlung mit Material und Pflegeanleitung begründen können, statt allen Kunden dasselbe Waschmittel anzubieten.","type":"text"}]}]},"product_bullets":["Wählen Sie das Waschmittel passend zu Material, Zusammensetzung und Pflegehinweisen des Herstellers.","Textile Care eignet sich für technische Bekleidung, Active Care für synthetische Sportbekleidung.","Merino Care und Jeans Care sind für andere Faserarten vorgesehen.","Fabric Protect unterstützt die Frische beim Waschen, ist aber kein Imprägniermittel.","Verkaufen Sie kein komplettes Set, wenn der Kunde nur ein Produkt benötigt."],"key_points_title":"Das Wichtigste","conversation_title":"Kundengespräch","conversation":[{"text":"Ich habe eine Jacke mit Membran, ein Funktionsshirt und Jeans. Ich möchte ein Waschmittel für alles.","speaker":"client"},{"text":"Verstanden. Für diese drei Materialien wählen Sie separate Waschmittel: Textile Care für die Jacke, Active Care für die synthetische Schicht und Jeans Care für Denim – jeweils gemäß Pflegeetikett.","speaker":"seller"},{"text":"Imprägniert Fabric Protect die Jacke?","speaker":"client"},{"text":"Nein, der Zusatz unterstützt die Frische nach dem Waschen. Wenn die Jacke wasserabweisend sein soll, benötigt sie ein separates Imprägniermittel.","speaker":"seller"},{"text":"Ich wasche nur einen Merinopullover. Muss ich ein Set kaufen?","speaker":"client"},{"text":"Nein. Merino Care reicht aus, sofern das Pflegeetikett das Waschen erlaubt. Wählen Sie das vom Hersteller angegebene Programm.","speaker":"seller"}]},{"lesson_id":312,"module_id":64,"module_sort_order":3,"sort_order":0,"title":"Wie pflegt man Motorradhandschuhe?","summary":"Ermitteln Sie, ob das Problem das Handschuhinnere oder die Außenseite betrifft, und wählen Sie die passende Pflege.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Finden Sie zuerst die Ursache","type":"text"}]},{"type":"paragraph","content":[{"text":"Handschuhe bestehen oft aus Leder, Textilien, Protektoren und Nähten und haben schwer zugängliche Fingerbereiche. Fragen Sie, ob der Kunde außen Schmutz entfernen, das Innere auffrischen oder trockenes Leder pflegen möchte. Für diese Bedürfnisse gibt es unterschiedliche Lösungen.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Prüfen Sie die Pflegehinweise der Handschuhe","type":"text"}]},{"type":"paragraph","content":[{"text":"Nicht jedes Paar eignet sich für die Maschinenwäsche oder lässt sich auf links drehen. Bei Lederhandschuhen ist es besonders wichtig, die Empfehlungen des Herstellers zu prüfen. Weichen oder dehnen Sie die Handschuhe nicht, sofern die Anleitung dies nicht vorsieht.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Pflege passend auswählen","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Bei hartnäckigem Geruch im Inneren: Ziehen Sie Magiczne Rękawiczki gemäß der Anleitung in Betracht.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Bei Schmutz außen: Wählen Sie ein Mittel passend zum Handschuhmaterial und zu den Herstellerhinweisen.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Wenn sich ein Reißverschluss schwer bewegen lässt, aber nicht beschädigt ist: Ziehen Sie Zip Service in Betracht.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Bei Abrieb, gelösten Verklebungen oder gerissenen Nähten ersetzt ein Pflegeprodukt keine Reparatur.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Kurze Empfehlung","type":"text"}]},{"type":"paragraph","content":[{"text":"Erklären Sie beim Verkauf, wofür das Produkt gedacht ist und was es nicht leistet. Magiczne Rękawiczki frischen das Innere auf, ersetzen aber weder eine vollständige Wäsche noch die Reparatur des Handschuhs.","type":"text"}]}]},"product_bullets":["Handschuhe enthalten Nähte, Protektoren und unterschiedliche Materialien – prüfen Sie daher das Pflegeetikett.","Unterscheiden Sie zwischen äußerer Verschmutzung und Geruch oder Feuchtigkeit im Inneren.","Gehen Sie nicht davon aus, dass Handschuhe in der Maschine gewaschen oder auf links gedreht werden können.","Magiczne Rękawiczki helfen dabei, schwer zugängliche Innenbereiche aufzufrischen.","Bei Schäden, gelösten Nähten oder abgeriebenem Leder ist eine Reparatur erforderlich."],"key_points_title":"Das Wichtigste","conversation_title":"Kundengespräch","conversation":[{"text":"Die Handschuhe riechen, aber ich kann sie nicht auf links drehen.","speaker":"client"},{"text":"Verwenden Sie Magiczne Rękawiczki, um das schwer zugängliche Innere aufzufrischen. Ziehen Sie das getränkte Paar über Ihre Hände und reinigen Sie damit das Innenfutter gemäß Anleitung.","speaker":"seller"},{"text":"Kann ich sie einfach in die Waschmaschine geben?","speaker":"client"},{"text":"Nur, wenn der Handschuhhersteller Maschinenwäsche erlaubt. Prüfen Sie das Pflegeetikett – die Handschuhe können Leder, Protektoren und verklebte Teile enthalten.","speaker":"seller"},{"text":"Das Material ist abgerieben. Repariert das Mittel den Schaden?","speaker":"client"},{"text":"Nein. Ein Pflegeprodukt repariert weder Abrieb noch Nähte. Lassen Sie die Handschuhe von einem Servicebetrieb prüfen.","speaker":"seller"}]},{"lesson_id":313,"module_id":64,"module_sort_order":3,"sort_order":1,"title":"Magiczne Rękawiczki – Anwendung und Vorführung","summary":"Zeigen Sie dem Kunden, wie Magiczne Rękawiczki zum Auffrischen des Handschuhinneren richtig angewendet werden.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Wozu Magiczne Rękawiczki verwenden?","type":"text"}]},{"type":"paragraph","content":[{"text":"Das getränkte Paar erleichtert die Reinigung des schwer zugänglichen Handschuhinneren, wenn sich die Handschuhe nicht bequem auf links drehen lassen. Diese Lösung kann besonders bei Lederhandschuhen hilfreich sein, sofern deren Pflegehinweise diese Art der Auffrischung erlauben.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Vorführung","type":"text"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Öffnen Sie den Beutel und ziehen Sie das Einwegpaar über Ihre Hände.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Stecken Sie Ihre Hände in die Motorradhandschuhe.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Bewegen Sie die Finger und drücken Sie leicht, damit das Mittel das Innere erreicht.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Ziehen Sie nicht am Futter und drehen Sie die Handschuhe nicht mit Gewalt auf links.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Ziehen Sie das getränkte Paar nach der Anwendung aus und waschen Sie Ihre Hände gemäß Anleitung.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Was Sie nicht versprechen sollten","type":"text"}]},{"type":"paragraph","content":[{"text":"Es ist eine praktische Möglichkeit, das Innere aufzufrischen, ersetzt aber weder das Waschen des gesamten Handschuhs noch die Reparatur von Nähten oder die Entfernung jeder Art von Verschmutzung. Der Kunde sollte das Produkt gemäß Verpackungsanleitung verwenden.","type":"text"}]}]},"product_bullets":["Der Beutel enthält ein getränktes Einwegpaar Handschuhe.","Ziehen Sie sie über die Hände, stecken Sie diese in die Motorradhandschuhe und bewegen Sie die Finger.","Gehen Sie vorsichtig vor, damit Sie das Innere erreichen, ohne den Handschuh auf links zu drehen.","Es handelt sich um eine Auffrischung des Innenbereichs, nicht um eine vollständige Wäsche oder Reparatur.","Ziehen Sie das Produkt nach der Anwendung aus und waschen Sie Ihre Hände gemäß Anleitung."],"key_points_title":"Das Wichtigste","conversation_title":"Kundengespräch","conversation":[{"text":"Wie verwendet man Magiczne Rękawiczki?","speaker":"client"},{"text":"Ziehen Sie das getränkte Einwegpaar über Ihre Hände, stecken Sie sie in die Motorradhandschuhe und bewegen Sie die Finger, um das Innere zu reinigen.","speaker":"seller"},{"text":"Muss ich die Handschuhe auf links drehen?","speaker":"client"},{"text":"Nein. Genau deshalb stecken Sie die Hände mit den getränkten Handschuhen hinein. Ziehen Sie nicht am Futter.","speaker":"seller"},{"text":"Ersetzt das die vollständige Wäsche der Handschuhe?","speaker":"client"},{"text":"Nein, damit wird nur das Innere aufgefrischt. Ziehen Sie danach das Einwegpaar aus und befolgen Sie die Produktanleitung.","speaker":"seller"},{"text":"Kann ich sie für Lederhandschuhe verwenden?","speaker":"client"},{"text":"Prüfen Sie zuerst die Empfehlungen des Handschuhherstellers und die Produktanleitung und wenden Sie sie anschließend entsprechend an.","speaker":"seller"}]},{"lesson_id":314,"module_id":64,"module_sort_order":3,"sort_order":2,"title":"Zip Service – Reißverschlusspflege und Ergänzungsverkauf","summary":"Erklären Sie die Anwendung von Zip Service für Reißverschlüsse und unterscheiden Sie Pflege von der Reparatur eines Schadens.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Für einen intakten, aber klemmenden Reißverschluss","type":"text"}]},{"type":"paragraph","content":[{"text":"Zip Service pflegt Reißverschlüsse, die schwergängig, aber mechanisch intakt sind. Fragen Sie den Kunden, ob Reibung und Widerstand das Problem sind oder ob Zähne fehlen beziehungsweise der Schieber verbogen ist.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"So zeigen Sie die Anwendung","type":"text"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Entfernen Sie sichtbaren Schmutz vom Reißverschluss.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Geben Sie gemäß Etikett eine kleine Menge Zip Service auf die Zähne.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Bewegen Sie den Schieber mehrmals, damit sich das Mittel verteilt.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Wischen Sie überschüssiges Mittel mit einem sauberen, trockenen Tuch ab.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Prüfen Sie den Reißverschluss, ohne übermäßige Kraft anzuwenden.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Ein sinnvolles Zusatzprodukt","type":"text"}]},{"type":"paragraph","content":[{"text":"Wenn der Kunde ein Problem mit einem Reißverschluss hat, können Sie das Mittel als praktische Ergänzung zur Pflege von Bekleidung, Schuhen oder Taschen anbieten. Versprechen Sie nicht, dass es ausgebrochene Zähne, gerissenes Material oder einen beschädigten Schieber repariert.","type":"text"}]}]},"product_bullets":["Zip Service erleichtert das Öffnen und Schließen intakter Metall- und Kunststoffreißverschlüsse.","Geben Sie eine kleine Menge auf die Zähne und bewegen Sie den Schieber mehrmals.","Wischen Sie Überschüsse mit einem sauberen, trockenen Tuch ab.","Es kann für Reißverschlüsse an Bekleidung, Schuhen und Taschen nützlich sein.","Es repariert weder ausgebrochene Zähne noch einen beschädigten Schieber."],"key_points_title":"Das Wichtigste","conversation_title":"Kundengespräch","conversation":[{"text":"Der Reißverschluss meiner Jacke läuft schwer. Hilft Zip Service?","speaker":"client"},{"text":"Wenn Schieber und Zähne intakt sind, kann Zip Service den Reißverschluss pflegen. Geben Sie eine kleine Menge auf die Zähne, bewegen Sie den Schieber mehrmals und wischen Sie überschüssiges Mittel ab.","speaker":"seller"},{"text":"Wie viel Mittel soll ich auftragen?","speaker":"client"},{"text":"Eine kleine Menge gemäß Etikett. Wischen Sie nach dem Verteilen Rückstände mit einem sauberen, trockenen Tuch ab.","speaker":"seller"},{"text":"Ein Zahn ist ausgebrochen. Repariert das Mittel ihn?","speaker":"client"},{"text":"Nein. Zip Service pflegt intakte Reißverschlüsse, repariert aber weder beschädigte Zähne noch den Schieber.","speaker":"seller"}]},{"lesson_id":315,"module_id":65,"module_sort_order":4,"sort_order":0,"title":"Wo beginnt man mit der Motorradpflege?","summary":"Ermitteln Sie die Art der Verschmutzung und wählen Sie einen passenden, einfachen Pflegeablauf.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Beginnen Sie mit der Bedarfsermittlung","type":"text"}]},{"type":"paragraph","content":[{"text":"Ein Motorrad nach einer trockenen Fahrt erfordert eine andere Pflege als nach Regen oder einer schlammigen Tour. Fragen Sie nach Art und Stärke der Verschmutzung sowie nach dem Zugang zu Wasser, Hochdruckreiniger und Garage. So können Sie eine einfache Reihenfolge empfehlen, statt wahllos Produkte zusammenzustellen.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Schnelle Auffrischung","type":"text"}]},{"type":"paragraph","content":[{"text":"Bei leichtem Staub zwischen gründlichen Wäschen können Wash & Ride und ein sauberes, weiches Mikrofasertuch ausreichen. Reiben Sie mit dieser Methode keinen groben Sand kräftig ab, da er den Lack zerkratzen kann.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Gründliche Wäsche","type":"text"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Erwägen Sie bei eingetrockneten Insekten Bug Killer als Vorbehandlung.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Verwenden Sie für die Hauptwäsche Moto Wash oder eine vorbereitete Power-Powder-Lösung.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Wählen Sie für Ablagerungen auf den Felgen Wheelixir und das passende Zubehör.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Spülen und trocknen Sie das Motorrad gemäß den Produktanleitungen.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Auf einer sauberen, kühlen Oberfläche können Sie als Finish Ceramic Detailer verwenden.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Erklären Sie die Grenzen der Anwendung","type":"text"}]},{"type":"paragraph","content":[{"text":"Tragen Sie Mittel nicht auf heiße Teile auf und lassen Sie sie nicht antrocknen, sofern die Anleitung dies untersagt. Ceramic Detailer ersetzt weder die Wäsche noch eine professionelle, langanhaltende Beschichtung.","type":"text"}]}]},"product_bullets":["Ermitteln Sie, ob es sich um Staub, Insekten, Bremsstaub, Fett oder starken Schlamm handelt.","Fragen Sie nach dem Zugang zu Wasser und den Reinigungsbedingungen.","Wash & Ride eignet sich für leichten Staub zwischen gründlichen Wäschen.","Bug Killer, Moto Wash und Wheelixir sind für unterschiedliche Schritte und Verschmutzungen vorgesehen.","Verwenden Sie Ceramic Detailer nach der Wäsche auf einer sauberen, kühlen Oberfläche."],"key_points_title":"Das Wichtigste","conversation_title":"Kundengespräch","conversation":[{"text":"Mein Motorrad ist nur staubig und ich habe fünf Minuten. Was empfehlen Sie?","speaker":"client"},{"text":"Verwenden Sie bei leichtem Staub zwischen gründlichen Wäschen Wash & Ride und ein sauberes Mikrofasertuch. Bei viel Sand oder Schlamm sollten Sie das Motorrad zuerst abspülen und waschen.","speaker":"seller"},{"text":"Kann ich Insekten und Felgen mit einem einzigen Mittel reinigen?","speaker":"client"},{"text":"Wählen Sie Bug Killer für Insekten, Wheelixir für Ablagerungen auf den Felgen und Moto Wash für die Wäsche des gesamten Motorrads.","speaker":"seller"},{"text":"Kann ich anfangen, solange der Motor heiß ist?","speaker":"client"},{"text":"Warten Sie, bis das Motorrad abgekühlt ist. Tragen Sie Mittel nicht auf heiße Teile auf.","speaker":"seller"}]},{"lesson_id":316,"module_id":65,"module_sort_order":4,"sort_order":1,"title":"Wash & Ride – Motorradwäsche","summary":"Erklären Sie, wann Wash & Ride eine praktische Wahl ist und wie es bei leichter Verschmutzung sicher angewendet wird.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Schnelle Reinigung ohne Schlauch","type":"text"}]},{"type":"paragraph","content":[{"text":"Wash & Ride ist praktisch, wenn das Motorrad leicht aufgefrischt werden muss und kein Schlauch oder Eimer zur Verfügung steht. Es ergänzt die regelmäßige Wäsche, ersetzt sie aber nicht bei einer dicken Schicht aus Schlamm, Sand oder starken Ablagerungen.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Anwendung","type":"text"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Vergewissern Sie sich, dass die Oberfläche kühl ist.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Sprühen Sie das Produkt gemäß Etikett auf einen kleinen Bereich.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Nehmen Sie den Schmutz vorsichtig mit einem sauberen, weichen Mikrofasertuch auf und drücken Sie nicht fest auf.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Wechseln Sie die Tuchseite oder das Tuch, sobald sich Schmutz darauf sammelt.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Bei starker Verschmutzung unterbrechen Sie die Reinigung und planen Sie eine gründliche Wäsche.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Für wen?","type":"text"}]},{"type":"paragraph","content":[{"text":"Das Produkt eignet sich zwischen den Wäschen in der Garage, auf dem Parkplatz und unterwegs. Es frischt die Optik auf und hinterlässt gemäß Produktangaben eine leichte Schutzschicht.","type":"text"}]}]},"product_bullets":["Wash & Ride ist für Staub und leichte Verschmutzungen zwischen gründlichen Wäschen vorgesehen.","Verwenden Sie es auf einer kühlen Oberfläche und nehmen Sie den Schmutz vorsichtig mit einem sauberen Mikrofasertuch auf.","Es kann in der Garage, auf dem Parkplatz oder unterwegs nützlich sein.","Reiben Sie damit keine dicke Schicht aus Sand oder Schlamm kräftig ab.","Bei starker Verschmutzung sollten Sie abspülen und eine gründliche Wäsche durchführen."],"key_points_title":"Das Wichtigste","conversation_title":"Kundengespräch","conversation":[{"text":"Ich habe weder Schlauch noch Eimer. Wie kann ich das Motorrad auffrischen?","speaker":"client"},{"text":"Bei leichter Verschmutzung verwenden Sie Wash & Ride und ein sauberes, weiches Mikrofasertuch. Arbeiten Sie auf einer kühlen Oberfläche und nehmen Sie den Schmutz ohne starken Druck auf.","speaker":"seller"},{"text":"Reicht es nach einer schlammigen Tour aus?","speaker":"client"},{"text":"Verwenden Sie es nicht bei einer dicken Schicht aus Schlamm oder Sand. Spülen Sie den Schmutz zuerst ab und waschen Sie das Motorrad gründlich.","speaker":"seller"},{"text":"Kann ich es auf einem heißen Motor verwenden?","speaker":"client"},{"text":"Nein. Warten Sie, bis die Teile abgekühlt sind, und verwenden Sie das Produkt gemäß Etikett.","speaker":"seller"}]},{"lesson_id":317,"module_id":65,"module_sort_order":4,"sort_order":2,"title":"Power Powder – Zubereitung und Anwendung","summary":"Erklären Sie, wie die Power-Powder-Lösung zubereitet und passend eingesetzt wird.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Das Konzentrat wird vor der Anwendung zubereitet","type":"text"}]},{"type":"paragraph","content":[{"text":"Power Powder ist ein Pulver und muss gemäß der Anleitung der jeweiligen Variante in Wasser aufgelöst werden. Streuen Sie es nicht direkt auf das Motorrad und gehen Sie nicht davon aus, dass alle Beutel gleich angewendet werden.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Wählen Sie das passende Mittel für die Aufgabe","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Moto Wash ist für die Hauptwäsche vorgesehen.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Bug Killer hilft dabei, Insekten und organische Verschmutzungen vorzubehandeln.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Wheelixir ist für Felgen und Ablagerungen in deren Umgebung vorgesehen.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Eine Portion zubereiten","type":"text"}]},{"type":"paragraph","content":[{"text":"Ein Shaker mit 500 ml kann beim Abmessen des Wassers und Zubereiten einer Portion hilfreich sein. Beachten Sie die Dosierung auf der Verpackung, lösen Sie das Pulver in der entsprechenden Wassermenge auf und verwenden Sie die Lösung gemäß Herstellerangaben. Tauschen Sie die Produkte nicht untereinander aus.","type":"text"}]}]},"product_bullets":["Power Powder Moto Wash ist nach dem Auflösen für die gründliche Motorradwäsche vorgesehen.","Die Moto-Wash-Packung enthält drei Beutel; beachten Sie bei der Anwendung die Anleitung.","Bug Killer und Wheelixir sind separate Konzentrate für unterschiedliche Anwendungen.","Zum Zubereiten einer Portion kann der Shaker mit 500 ml verwendet werden.","Geben Sie nicht für alle Pulver dieselbe Verdünnung an."],"key_points_title":"Das Wichtigste","conversation_title":"Kundengespräch","conversation":[{"text":"Kann ich das Pulver direkt auf die Verkleidung streuen?","speaker":"client"},{"text":"Nein. Lösen Sie Power Powder zuerst gemäß Packungsanleitung in Wasser auf und verwenden Sie anschließend die zubereitete Lösung.","speaker":"seller"},{"text":"Werden alle Beutel gleich verdünnt?","speaker":"client"},{"text":"Nein. Moto Wash, Bug Killer und Wheelixir haben unterschiedliche Einsatzbereiche. Prüfen Sie für jedes Produkt die jeweilige Dosierung.","speaker":"seller"},{"text":"Wozu brauche ich den Shaker?","speaker":"client"},{"text":"Er erleichtert das Abmessen des Wassers und die Zubereitung einer Portion, sofern die Anleitung diese Anwendung vorsieht.","speaker":"seller"}]},{"lesson_id":318,"module_id":65,"module_sort_order":4,"sort_order":3,"title":"Bug Killer und Wheelixir – Verschmutzungen entfernen","summary":"Wählen Sie Bug Killer für organische Verschmutzungen und Wheelixir für Ablagerungen auf Felgen.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Zwei verschiedene Probleme, zwei Produkte","type":"text"}]},{"type":"paragraph","content":[{"text":"Bug Killer dient zur Vorbehandlung von Insekten, Vogelkot und anderen organischen Verschmutzungen. Wheelixir ist für Ablagerungen auf Felgen und in der Nähe der Bremssättel vorgesehen. Keines der beiden Produkte ersetzt die Wäsche des gesamten Motorrads.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Anwendung","type":"text"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Bereiten Sie das Power-Powder-Konzentrat gemäß Etikett zu.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Tragen Sie Bug Killer vor der Hauptwäsche auf die verschmutzte Stelle auf.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Lassen Sie es gemäß Anleitung einwirken und spülen Sie es ab oder fahren Sie mit der Wäsche fort.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Tragen Sie Wheelixir auf die Felge auf und verwenden Sie bei Bedarf eine geeignete Bürste.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Spülen Sie die Felge und die Ablagerungen gründlich ab.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Gehen Sie auf das Anliegen des Kunden ein","type":"text"}]},{"type":"paragraph","content":[{"text":"Befinden sich Insekten auf der Verkleidung, empfehlen Sie ein Mittel für organische Verschmutzungen. Bei dunklen Ablagerungen auf der Felge wählen Sie einen Felgenreiniger. Prüfen Sie die Materialverträglichkeit und arbeiten Sie auf einer kühlen Oberfläche.","type":"text"}]}]},"product_bullets":["Verwenden Sie Bug Killer zur Vorbehandlung von Insekten und organischen Verschmutzungen.","Wählen Sie Wheelixir für Felgen und Bremsstaub.","Lösen Sie die Power-Powder-Varianten vorher gemäß Etikett auf.","Lassen Sie Bug Killer gemäß Anleitung einwirken und nicht antrocknen.","Spülen Sie die Felgen nach der Anwendung von Wheelixir gründlich ab und wählen Sie eine passende Bürste."],"key_points_title":"Das Wichtigste","conversation_title":"Kundengespräch","conversation":[{"text":"Auf der Verkleidung sind Insekten eingetrocknet. Was soll ich verwenden?","speaker":"client"},{"text":"Tragen Sie vor der Wäsche Bug Killer auf die verschmutzte Stelle auf und lassen Sie es gemäß Etikett einwirken. Spülen Sie es anschließend ab und waschen Sie das Motorrad.","speaker":"seller"},{"text":"Wie entferne ich dunkle Ablagerungen von der Felge?","speaker":"client"},{"text":"Verwenden Sie Wheelixir für Ablagerungen auf Felgen. Wählen Sie bei Bedarf eine passende Felgenbürste und spülen Sie die Felge nach der Reinigung gründlich ab.","speaker":"seller"},{"text":"Kann ich Power Powder unverdünnt auftragen?","speaker":"client"},{"text":"Nein. Lösen Sie das Pulver zuerst im auf der Verpackung angegebenen Verhältnis in Wasser auf.","speaker":"seller"}]},{"lesson_id":319,"module_id":65,"module_sort_order":4,"sort_order":4,"title":"Ceramic Detailer – Finish und Schutz","summary":"Stellen Sie Ceramic Detailer als abschließende Pflege für ein sauberes Motorrad vor.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Der Schritt nach der Wäsche","type":"text"}]},{"type":"paragraph","content":[{"text":"Ceramic Detailer dient dem Finish eines sauberen Motorrads. Er kann Glanz und Farbe auffrischen und einen wasserabweisenden Effekt erzielen. Er ist weder für starke Verschmutzungen gedacht noch eine professionelle Keramikbeschichtung mit jahrelanger Haltbarkeit.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Vorführung","type":"text"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Arbeiten Sie auf einer kühlen Oberfläche und nicht in direkter Sonne.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Sprühen Sie eine kleine Menge auf ein Mikrofasertuch oder befolgen Sie die Angaben auf dem Etikett.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Verteilen Sie das Produkt abschnittsweise und tragen Sie nicht zu viel auf eine große Fläche auf.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Polieren Sie mit einer sauberen, trockenen Tuchseite oder einem zweiten Mikrofasertuch nach.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Prüfen Sie, ob Streifen zurückgeblieben sind, und wiederholen Sie die Anwendung nur gemäß Anleitung.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Realistische Erwartungen","type":"text"}]},{"type":"paragraph","content":[{"text":"Der Detailer kann die regelmäßige Pflege unterstützen und das Anhaften von Schmutz verringern. Das Motorrad muss weiterhin gewaschen werden; das Produkt ersetzt weder eine dauerhafte Beschichtung noch eine Lackaufbereitung.","type":"text"}]}]},"product_bullets":["Verwenden Sie Ceramic Detailer nach der Wäsche oder einer leichten Auffrischung auf einer sauberen Oberfläche.","Er hilft entsprechend dem vorgesehenen Einsatz, Glanz und einen wasserabweisenden Effekt zu erzielen.","Es ist ein Schnell-Detailer und keine professionelle Keramikbeschichtung mit jahrelanger Haltbarkeit.","Arbeiten Sie auf einer kühlen Oberfläche und nicht in direkter Sonne.","Verteilen Sie das Produkt mit einem Mikrofasertuch abschnittsweise und polieren Sie mit der trockenen Seite nach."],"key_points_title":"Das Wichtigste","conversation_title":"Kundengespräch","conversation":[{"text":"Ist Ceramic Detailer eine Beschichtung, die mehrere Jahre hält?","speaker":"client"},{"text":"Nein. Es ist ein Schnell-Detailer für das Finish und die regelmäßige Pflege, keine dauerhafte professionelle Keramikbeschichtung.","speaker":"seller"},{"text":"Kann ich ihn auf ein schmutziges Motorrad auftragen?","speaker":"client"},{"text":"Waschen und trocknen Sie das Motorrad zuerst. Tragen Sie den Detailer abschnittsweise auf eine saubere, kühle Oberfläche auf.","speaker":"seller"},{"text":"Muss ich das Motorrad nach der Anwendung nicht mehr waschen?","speaker":"client"},{"text":"Doch, es muss weiterhin gewaschen werden. Der Detailer pflegt die Oberfläche, ersetzt aber nicht die Wäsche.","speaker":"seller"}]},{"lesson_id":320,"module_id":65,"module_sort_order":4,"sort_order":5,"title":"Bürsten und Mikrofasertücher – passendes Zubehör auswählen","summary":"Wählen Sie Mikrofasertuch und Bürste passend zum jeweiligen Schritt und vermeiden Sie, Schmutz zwischen Oberflächen zu übertragen.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Das Zubehör passend zur Oberfläche wählen","type":"text"}]},{"type":"paragraph","content":[{"text":"Auch ein gutes Mittel ersetzt nicht das passende Werkzeug. Ein weiches Mikrofasertuch nimmt leichte Verschmutzungen auf und eignet sich für das Finish. Verwenden Sie für Felgen, Kette und schwer zugängliche Details separate Bürsten oder Pinsel.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Saubere und verschmutzte Bereiche trennen","type":"text"}]},{"type":"paragraph","content":[{"text":"Übertragen Sie kein Kettenfett auf Lack, Verkleidung oder Visier. Auch Felgenablagerungen können empfindliche Oberflächen zerkratzen. Sobald das Tuch Schmutz aufgenommen hat, wechseln Sie die Seite oder nehmen Sie ein sauberes Tuch.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Auswahl bei begrenztem Budget","type":"text"}]},{"type":"paragraph","content":[{"text":"Wenn der Kunde gerade erst anfängt, fragen Sie nach dem wichtigsten Problem. Ein sauberes, weiches Mikrofasertuch eignet sich für viele leichte Reinigungsaufgaben. Wählen Sie eine zusätzliche Bürste erst für einen bestimmten Bereich.","type":"text"}]}]},"product_bullets":["Verwenden Sie für leichte Reinigung und das Finish saubere, weiche Mikrofasertücher.","Verwenden Sie separate Tücher für unterschiedliche Schritte und Oberflächen.","Eine Kettenbürste ist nicht für Lack oder Visier geeignet.","Ein Detailing-Pinsel hilft dabei, schwer zugängliche Stellen zu erreichen.","Wählen Sie eine Bürste passend zu Felgen und Oberfläche, um den Lack nicht zu zerkratzen."],"key_points_title":"Das Wichtigste","conversation_title":"Kundengespräch","conversation":[{"text":"Reicht ein Mikrofasertuch für das ganze Motorrad?","speaker":"client"},{"text":"Verwenden Sie für die einzelnen Schritte separate, saubere Mikrofasertücher, damit kein Schmutz von Felgen und Antrieb auf den Lack gelangt.","speaker":"seller"},{"text":"Sind Detailing-Pinsel und Kettenbürste austauschbar?","speaker":"client"},{"text":"Nein. Die Kettenbürste ist für den Antrieb bestimmt, der Detailing-Pinsel für schwer zugängliche Details. Verwenden Sie die Kettenbürste nicht auf dem Lack.","speaker":"seller"},{"text":"Womit sollte ich bei kleinem Budget beginnen?","speaker":"client"},{"text":"Beginnen Sie mit einem sauberen, weichen Mikrofasertuch. Wählen Sie erst dann eine Bürste, wenn eine bestimmte Stelle schwer zu reinigen ist.","speaker":"seller"}]},{"lesson_id":321,"module_id":66,"module_sort_order":5,"sort_order":0,"title":"Welche Verschmutzungen entstehen beim Offroad-Fahren?","summary":"Erkennen Sie Offroad-Verschmutzungen und wählen Sie je nach Stärke Mud Breaker oder Dirt Finisher.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Warum Offroad-Pflege anders ist","type":"text"}]},{"type":"paragraph","content":[{"text":"Nach einer Offroad-Fahrt können Schlamm, Sand, Staub und Pfützenrückstände am Motorrad haften bleiben. Trockene Partikel wirken abrasiv. Wischen Sie deshalb nicht gleich das gesamte Fahrzeug mit einem Mikrofasertuch ab. Beurteilen Sie zuerst die Schmutzschicht und schaffen Sie geeignete Bedingungen für eine sichere Reinigung.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Wählen Sie einen von zwei Pflegewegen","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Dicker, angetrockneter Schlamm: Verwenden Sie Mud Breaker gemäß Anleitung und spülen Sie anschließend gründlich ab.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Leichter Staub nach einer trockenen Fahrt: Dirt Finisher und ein sauberes Mikrofasertuch können ausreichen.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Viel Sand: Entfernen Sie ihn sicher, bevor Sie die Oberfläche abwischen.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Fragen vor der Empfehlung","type":"text"}]},{"type":"paragraph","content":[{"text":"Fragen Sie, auf welchem Untergrund der Kunde fährt und ob Wasser zur Verfügung steht. Mud Breaker muss abgespült werden können. Versprechen Sie weder, dass das Mittel das Anhaften von neuem Schlamm verhindert, noch dass das Motorrad selbstreinigend wird.","type":"text"}]}]},"product_bullets":["Schlamm, Sand und Staub erfordern eine andere Behandlung als leichte Verschmutzungen von der Straße.","Wischen Sie eine dicke Sandschicht nicht trocken ab, da die Körner Kratzer verursachen können.","Mud Breaker weicht starke Verschmutzungen auf und muss gründlich abgespült werden.","Dirt Finisher hilft bei leichtem Staub und beim abschließenden Finish.","Fragen Sie, ob Wasser zur Verfügung steht, und arbeiten Sie auf einer kühlen Oberfläche."],"key_points_title":"Das Wichtigste","conversation_title":"Kundengespräch","conversation":[{"text":"Ich komme vom Motocross mit einer dicken Schlammschicht zurück. Kann ich das Motorrad gleich abwischen?","speaker":"client"},{"text":"Wischen Sie eine dicke Schicht aus Schlamm oder Sand nicht trocken ab. Weichen Sie die Verschmutzung mit Mud Breaker auf und spülen Sie gründlich nach.","speaker":"seller"},{"text":"Nach einer trockenen Fahrt ist nur Staub auf dem Motorrad. Muss ich es gründlich waschen?","speaker":"client"},{"text":"Bei leichtem Staub können Dirt Finisher und ein sauberes Mikrofasertuch ausreichen. Bei viel Sand entfernen Sie ihn zuerst auf sichere Weise.","speaker":"seller"},{"text":"Nach der Fahrt habe ich keinen Zugang zu Wasser.","speaker":"client"},{"text":"Mud Breaker muss abgespült werden. Verwenden Sie ihn deshalb erst an einem Ort mit Wasserzugang. Wählen Sie die Methode passend zu Verschmutzung und verfügbaren Bedingungen.","speaker":"seller"}]},{"lesson_id":322,"module_id":66,"module_sort_order":5,"sort_order":1,"title":"Mud Breaker – Schlamm entfernen","summary":"Lernen Sie, Mud Breaker bei starkem Schlamm sicher anzuwenden und Verschmutzungen gründlich abzuspülen.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Ein Produkt für starke Verschmutzungen","type":"text"}]},{"type":"paragraph","content":[{"text":"Mud Breaker weicht Schlamm, Sand und mineralischen Schmutz nach einer Offroad-Fahrt auf. Erklären Sie dem Kunden, dass das Produkt auf das Abspülen vorbereitet und keine fertige Reinigung ohne Wasser ermöglicht.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Anwendungsschritte","type":"text"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Warten Sie, bis das Motorrad abgekühlt ist.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Beurteilen Sie die Schlammschicht und sorgen Sie für Wasser zum Abspülen.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Tragen Sie das Mittel gemäß Etikett auf die verschmutzten Teile auf.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Lassen Sie es für die angegebene Zeit einwirken und nicht antrocknen.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Spülen Sie Schmutz und Mittel gründlich mit Wasser ab.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Bürste und weitere Pflege","type":"text"}]},{"type":"paragraph","content":[{"text":"Eine passende Bürste kann bei schwer zugänglichen Stellen helfen. Verwenden Sie sie vorsichtig und schrubben Sie nicht trocken. Nach dem Abspülen kann der Kunde entscheiden, ob er Dirt Finisher für das Finish benötigt.","type":"text"}]}]},"product_bullets":["Mud Breaker ist für starken Schlamm und mineralische Verschmutzungen vorgesehen.","Prüfen Sie, ob das Motorrad abgekühlt ist, und halten Sie Wasser zum Abspülen bereit.","Verwenden Sie es gemäß Etikett auf der verschmutzten Oberfläche.","Lassen Sie das Mittel nicht antrocknen; bürsten Sie nur bei Bedarf vorsichtig.","Spülen Sie das Fahrzeug nach der Einwirkzeit gründlich ab."],"key_points_title":"Das Wichtigste","conversation_title":"Kundengespräch","conversation":[{"text":"Entfernt Mud Breaker angetrockneten Schlamm von der Schwinge?","speaker":"client"},{"text":"Ja, er weicht den Schlamm auf, sodass er sich leichter abspülen lässt. Sprühen Sie die verschmutzte Oberfläche ein, lassen Sie das Mittel kurz einwirken und spülen Sie gründlich nach. Bei starken Ablagerungen können Sie vorsichtig eine Bürste verwenden.","speaker":"seller"},{"text":"Ich habe keinen Schlauch. Kann ich es auf dem Parkplatz verwenden?","speaker":"client"},{"text":"Nicht, wenn Sie nicht abspülen können. Verwenden Sie Mud Breaker an einem Waschplatz mit Wasser, da das Fahrzeug nach der Anwendung gründlich abgespült werden muss.","speaker":"seller"},{"text":"Kann ich das Mittel trocknen lassen?","speaker":"client"},{"text":"Nein. Spülen Sie es ab, bevor es antrocknet, und tragen Sie es nicht auf heiße Teile auf.","speaker":"seller"}]},{"lesson_id":323,"module_id":66,"module_sort_order":5,"sort_order":2,"title":"Dirt Finisher – Finish und Pflege","summary":"Erklären Sie die Anwendung von Dirt Finisher bei leichter Verschmutzung und als Schritt nach einer gründlicheren Wäsche.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Leichtere Pflege für Offroad-Motorräder","type":"text"}]},{"type":"paragraph","content":[{"text":"Dirt Finisher ist keine zweite Variante von Mud Breaker. Er hilft bei leichten Verschmutzungen und bei der abschließenden Pflege einer saubereren Oberfläche. Bei starkem Schlamm folgt er erst nach dem Aufweichen und Abspülen des Schmutzes.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Anwendung","type":"text"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Prüfen Sie, ob die Oberfläche kühl und frei von einer dicken Sandschicht ist.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Schütteln Sie die Verpackung gemäß Anleitung.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Sprühen Sie eine kleine Menge auf den ausgewählten Bereich.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Nehmen Sie leichte Verschmutzungen vorsichtig mit einem sauberen Mikrofasertuch auf.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Wechseln Sie das Tuch, sobald es Sand oder Schlamm aufgenommen hat.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"An den Verschmutzungsgrad anpassen","type":"text"}]},{"type":"paragraph","content":[{"text":"Bei leichtem Staub nach einer Schotterfahrt kann Dirt Finisher allein ausreichen. Bei einer dicken Lehmschicht verwenden Sie zuerst Mud Breaker und spülen Sie ab. Das Finish kann die spätere Pflege erleichtern, beseitigt Verschmutzungen aber nicht.","type":"text"}]}]},"product_bullets":["Dirt Finisher ist für die leichte Reinigung und das Finish vorgesehen.","Verwenden Sie bei starkem Schlamm zuerst Mud Breaker und spülen Sie gründlich ab.","Entfernen Sie vor der Anwendung groben Sand und prüfen Sie, ob die Oberfläche kühl ist.","Schütteln Sie die Verpackung und arbeiten Sie abschnittsweise.","Nehmen Sie den Schmutz mit einem sauberen Mikrofasertuch auf und wechseln Sie es, sobald es stark verschmutzt ist."],"key_points_title":"Das Wichtigste","conversation_title":"Kundengespräch","conversation":[{"text":"Muss ich Mud Breaker und Dirt Finisher zusammen kaufen?","speaker":"client"},{"text":"Nein. Bei leichtem Staub reicht Dirt Finisher. Nach starkem Schlamm verwenden Sie zuerst Mud Breaker und spülen ab; ergänzen Sie das Finish nur, wenn Sie es benötigen.","speaker":"seller"},{"text":"Kommt Dirt Finisher mit einer dicken Lehmschicht zurecht?","speaker":"client"},{"text":"Nein. Weichen Sie den Schlamm zuerst mit Mud Breaker auf und spülen Sie ihn ab. Dirt Finisher ist für die leichtere Reinigung und das Finish gedacht.","speaker":"seller"},{"text":"Kann ich damit viel Sand abwischen?","speaker":"client"},{"text":"Entfernen Sie zuerst groben Sand. Reiben Sie die Körner nicht mit einem Mikrofasertuch ein, da sie die Oberfläche zerkratzen können.","speaker":"seller"}]},{"lesson_id":324,"module_id":66,"module_sort_order":5,"sort_order":3,"title":"Wie wählt man das Off-Road Kit aus?","summary":"Wählen Sie die empfohlene Offroad-Pflege passend zum Fahrstil, Verschmutzungsgrad und Wasserzugang aus.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Fragen Sie nach, was mit „Set“ gemeint ist","type":"text"}]},{"type":"paragraph","content":[{"text":"Der Kunde kann eine fertige Packung oder eine Zusammenstellung von Pflegeprodukten meinen. Fragen Sie, welches Fahrzeug er fährt, welche Verschmutzungen am häufigsten auftreten und ob nach der Fahrt Wasser zur Verfügung steht. Bis ein bestimmtes Produkt bestätigt ist, stellen Sie die Lösung als ein System aus zwei Schritten vor.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Passend zum Einsatzprofil","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Motocross auf einer schlammigen Strecke: Mud Breaker, abspülen und bei Bedarf Dirt Finisher.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Enduro auf trockenem Schotter: Dirt Finisher bei leichtem Staub.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Quad oder MTB im tiefen Schlamm: Wählen Sie ein geeignetes Mittel und prüfen Sie die Hinweise für das Fahrzeug.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Kein Wasserzugang: Planen Sie die Reinigung an einem Ort, an dem gründliches Abspülen möglich ist.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Zubehör und sinnvolle Grundausstattung","type":"text"}]},{"type":"paragraph","content":[{"text":"Für das Finish ist ein sauberes, weiches Mikrofasertuch hilfreich, für schwer zugängliche Stellen eine passende Bürste. Fügen Sie nicht unnötig weitere Produkte hinzu. Empfehlen Sie zuerst die Mindestlösung, die das Problem behebt, und stellen Sie den zweiten Schritt als Option vor.","type":"text"}]}]},"product_bullets":["Fragen Sie, ob der Kunde Motocross, Enduro, Quad oder MTB fährt.","Empfehlen Sie bei starkem Schlamm Mud Breaker und stellen Sie sicher, dass abgespült werden kann.","Bei leichtem Staub kann der Kunde mit Dirt Finisher beginnen.","Wählen Sie ein weiteres Mikrofasertuch oder eine Bürste nur bei tatsächlichem Bedarf aus.","Stellen Sie Off-Road Kit ohne bestätigtes Produkt nicht als eine bestimmte fertige Box dar."],"key_points_title":"Das Wichtigste","conversation_title":"Kundengespräch","conversation":[{"text":"Ich möchte ein Set fürs Enduro und nicht fünf verschiedene Mittel kaufen. Was ist das Minimum?","speaker":"client"},{"text":"Wenn Sie meist mit starkem Schlamm zu tun haben und Wasser zum Abspülen verfügbar ist, beginnen Sie mit Mud Breaker. Ergänzen Sie Dirt Finisher nur, wenn Sie auch die saubere Oberfläche nachbehandeln möchten.","speaker":"seller"},{"text":"Ich fahre hauptsächlich auf trockenem Schotter. Brauche ich beide Produkte?","speaker":"client"},{"text":"Nein. Bei leichtem Staub beginnen Sie mit Dirt Finisher und einem sauberen Mikrofasertuch.","speaker":"seller"},{"text":"Ist Off-Road Kit eine fertige Box?","speaker":"client"},{"text":"Prüfen wir die derzeit verfügbare Produktvariante. Wenn Sie ein Pflegeset meinen, kann ich Mud Breaker und Dirt Finisher als zwei separate Schritte auswählen.","speaker":"seller"}]},{"lesson_id":325,"module_id":67,"module_sort_order":6,"sort_order":0,"title":"Wie erkennt man den Bedarf eines Kunden?","summary":"Stellen Sie Fragen, die den Bedarf des Kunden klären und zu einer einfachen Empfehlung führen.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Verkaufen beginnt mit Zuhören","type":"text"}]},{"type":"paragraph","content":[{"text":"Der Kunde kann sein Problem beschreiben, ohne die Produktnamen zu kennen: „Ich suche etwas für meinen Helm“ oder „Meine Jacke riecht unangenehm“. Ihre Aufgabe ist es, den Bedarf zu klären, statt sofort verfügbare Mittel aufzuzählen.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Fünf hilfreiche Fragen","type":"text"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Was möchten Sie reinigen oder schützen?","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Welches Problem ist am wichtigsten: Insekten, Staub, Schlamm, Schweiß oder Pflege?","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Aus welchem Material besteht die Bekleidung oder Oberfläche?","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Wo möchten Sie das Produkt verwenden, und haben Sie Zugang zu Wasser?","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Handelt es sich um einen einmaligen Bedarf oder um regelmäßige Pflege?","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Von der Antwort zur Empfehlung","type":"text"}]},{"type":"paragraph","content":[{"text":"Sie müssen nicht alle Fragen stellen. Wählen Sie diejenigen aus, die die Produktauswahl beeinflussen. Fassen Sie das Problem mit eigenen Worten zusammen, nennen Sie eine Lösung, erklären Sie deren Anwendung und weisen Sie auf eine wichtige Einschränkung hin. Bieten Sie eine Ergänzung erst an, wenn sie einen konkreten Pflegeschritt vervollständigt.","type":"text"}]}]},"product_bullets":["Fragen Sie, was der Kunde reinigen oder schützen möchte.","Ermitteln Sie das konkrete Problem: Insekten, Staub, Schlamm, Geruch oder Pflege.","Prüfen Sie Material, Einsatzbedingungen und Pflegehäufigkeit.","Fassen Sie das Problem mit eigenen Worten zusammen, bevor Sie ein Produkt empfehlen.","Zeigen Sie ein oder zwei passende Lösungen und erklären Sie deren Anwendung."],"key_points_title":"Das Wichtigste","conversation_title":"Kundengespräch","conversation":[{"text":"Ich brauche ein gutes Reinigungsmittel. Was empfehlen Sie?","speaker":"client"},{"text":"Lassen Sie uns zuerst klären, was Sie reinigen möchten: Helm, Bekleidung oder Motorrad. Welches Problem möchten Sie lösen – Insekten, Schmutz, Geruch oder Materialpflege?","speaker":"seller"},{"text":"Es geht um das Helmvisier und eingetrocknete Insekten.","speaker":"client"},{"text":"Dann beginnen Sie mit Helmet Gel, das die Insekten aufweicht. Anschließend können Sie das saubere Visier mit Helmet Detailer pflegen.","speaker":"seller"},{"text":"Der Kunde fragt sofort nur nach dem Preis. Was soll ich antworten?","speaker":"client"},{"text":"Nennen Sie den Preis, wenn Sie ihn kennen, und fragen Sie anschließend kurz nach dem Einsatzbereich. So können Sie eine passende Variante empfehlen, ohne zu einem unnötigen Produkt zu drängen.","speaker":"seller"}]},{"lesson_id":326,"module_id":67,"module_sort_order":6,"sort_order":1,"title":"Wie empfiehlt man Sets statt einzelner Produkte?","summary":"Erklären Sie den Nutzen eines Sets anhand der einzelnen Pflegeschritte und wählen Sie die Größe passend zur Nutzung.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Zeigen Sie den Ablauf, nicht nur den Preis","type":"text"}]},{"type":"paragraph","content":[{"text":"Ein Set ist leichter verständlich, wenn der Kunde weiß, welche Schritte es abdeckt. Bei Lederbekleidung kann es um Reinigung, Lederpflege und das Auffrischen des Innenfutters gehen. Beim Helm sind die Reinigung der Außenflächen und eine praktische Größe für zu Hause oder unterwegs entscheidend.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Wählen Sie das Set passend zur Situation","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Das Leather Care Kit eignet sich für Kunden, die mehrere Schritte zur Lederpflege benötigen.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Trip Kit ist praktisch für unterwegs.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"GIGA kann bei regelmäßiger Pflege zu Hause oder bei mehreren Helmen praktisch sein.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Wenn der Kunde Zubehör bereits besitzt, empfehlen Sie nur das noch fehlende Produkt.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Prüfen Sie den Bedarf","type":"text"}]},{"type":"paragraph","content":[{"text":"Ein Set ist nicht immer die beste Wahl. Fragen Sie, was der Kunde bereits besitzt, wie oft er seine Ausrüstung pflegt und wo er die Produkte verwenden wird. Der Mehrwert eines Sets liegt in der passenden Zusammenstellung und dem Komfort, nicht in der Anzahl der Teile.","type":"text"}]}]},"product_bullets":["Erklären Sie den Ablauf: Reinigung, Pflege oder Finish und bei Bedarf anschließend das Innenfutter.","Das Leather Care Kit kann die Pflege des Leders außen und das Auffrischen des Innenfutters kombinieren.","Trip Kit eignet sich für unterwegs, GIGA für die regelmäßige Helmpflege.","Wenn der Kunde bereits einige Produkte hat, kann er nur die fehlende Ergänzung kaufen.","Fragen Sie zum Abschluss nach der Art und Häufigkeit der Nutzung."],"key_points_title":"Das Wichtigste","conversation_title":"Kundengespräch","conversation":[{"text":"Wozu brauche ich ein Set, wenn ich nur ein Mittel benötige?","speaker":"client"},{"text":"Wenn Sie die übrigen Produkte und das Zubehör bereits besitzen, kaufen Sie nur das fehlende Mittel. Ein Set ist sinnvoll, wenn Sie alle Pflegeschritte durchführen möchten.","speaker":"seller"},{"text":"Ich brauche etwas für meinen Helm auf Reisen. Was soll ich wählen?","speaker":"client"},{"text":"Wählen Sie Trip Kit – die kompakten Verpackungen sind für unterwegs gedacht. Für die regelmäßige Reinigung zu Hause können Sie es mit GIGA vergleichen.","speaker":"seller"},{"text":"Funktioniert ein größeres Set besser?","speaker":"client"},{"text":"Nein, es unterscheidet sich in Größe und Umfang. Wählen Sie passend dazu, wie oft und wie viele Helme Sie reinigen.","speaker":"seller"}]},{"lesson_id":327,"module_id":67,"module_sort_order":6,"sort_order":2,"title":"Wie lässt sich der Verkauf mit ergänzenden Produkten steigern?","summary":"Ergänzen Sie den vom Kunden begonnenen Pflegeablauf höchstens um ein sinnvolles Zusatzprodukt.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Sinnvolle Ergänzungsangebote","type":"text"}]},{"type":"paragraph","content":[{"text":"Ein Zusatzprodukt ist dann sinnvoll, wenn es einen weiteren Pflegeschritt ergänzt. Wer einen Cleaner kauft, benötigt möglicherweise ein Mittel für die anschließende Pflege oder ein passendes Tuch. Besitzt der Kunde dieses Produkt bereits, gibt es keinen Grund, es erneut anzubieten.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Sinnvolle Produktkombinationen","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Helmet Gel → Helmet Detailer und ein passendes Tuch.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Leather Cleaner → Leather Milk nach der Reinigung und dem Trocknen des Leders.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Textile Care → Fabric Protect als Waschzusatz für mehr Frische, nicht zur Imprägnierung.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Moto Wash oder Bug Killer → Ceramic Detailer nach dem Waschen und Abspülen.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Mud Breaker → Dirt Finisher nach der gründlichen Wäsche, wenn der Kunde ein Finish wünscht.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Ohne Druck anbieten","type":"text"}]},{"type":"paragraph","content":[{"text":"Fragen Sie nach dem fehlenden Pflegeschritt und schlagen Sie höchstens eine passende Ergänzung vor. Zum Beispiel: „Der Cleaner entfernt den Schmutz vom Leder. Wenn Sie noch kein Pflegemittel für danach haben, kann ich Ihnen Leather Milk zeigen.“ Wenn der Kunde ablehnt, akzeptieren Sie die Entscheidung.","type":"text"}]}]},"product_bullets":["Ein Zusatzprodukt sollte einen weiteren Pflegeschritt abdecken und nicht einfach den Warenkorb vergrößern.","Helmet Gel lässt sich mit einem Detailer und einem geeigneten Tuch kombinieren.","Leather Milk ergänzt Leather Cleaner, sobald das Leder getrocknet ist.","Textile Care kann beim Waschen durch Fabric Protect ergänzt werden.","Akzeptieren Sie ein Nein und empfehlen Sie kein Produkt, das bereits vorhandene Ausstattung doppelt."],"key_points_title":"Das Wichtigste","conversation_title":"Kundengespräch","conversation":[{"text":"Warum schlagen Sie mir ein zweites Produkt vor?","speaker":"client"},{"text":"Ein Zusatzprodukt ist sinnvoll, wenn es einen notwendigen Pflegeschritt ergänzt: Leather Milk pflegt zum Beispiel das Leder nach der Reinigung. Wenn Sie dieses Produkt schon besitzen, müssen Sie kein weiteres kaufen.","speaker":"seller"},{"text":"Nein, danke. Ich habe das Produkt bereits.","speaker":"client"},{"text":"Verstanden. Dann bleiben wir bei dem, was Ihnen tatsächlich noch fehlt.","speaker":"seller"},{"text":"Was passt zu Leather Cleaner, wenn ich noch kein Lederpflegemittel habe?","speaker":"client"},{"text":"Nach der Reinigung und dem Trocknen des Leders können Sie Leather Milk als separaten Pflegeschritt verwenden.","speaker":"seller"}]},{"lesson_id":328,"module_id":67,"module_sort_order":6,"sort_order":3,"title":"Wie beantwortet man häufige Einwände von Kunden?","summary":"Gehen Sie auf Einwände ein, indem Sie die Bedenken verstehen, einen konkreten Fakt nennen und dem Kunden die Wahl lassen.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Ein Einwand liefert Informationen","type":"text"}]},{"type":"paragraph","content":[{"text":"„Das ist zu teuer“, „Ich habe schon etwas Ähnliches“ oder „Ist das sicher?“ zeigen, dass der Kunde weitere Informationen benötigt. Nehmen Sie den Einwand zuerst ernst, stellen Sie dann eine kurze Rückfrage, antworten Sie sachlich und überlassen Sie dem Kunden die Entscheidung.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Vier häufige Situationen","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Preis: Fragen Sie, ob das Produkt gelegentlich oder regelmäßig verwendet wird, und wählen Sie die passende Größe.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Normales Waschmittel: Vergleichen Sie den Einsatz mit dem Material und dem Pflegeetikett.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Sicherheit: Prüfen Sie Oberfläche, Finish und Pflegehinweise; testen Sie das Mittel bei Leder zuerst.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Wirkung: Erklären Sie die konkrete Funktion und die Grenzen des Produkts.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"In drei Sätzen antworten","type":"text"}]},{"type":"paragraph","content":[{"text":"Eine kurze Antwort kann Verständnis für die Bedenken, einen konkreten Fakt und einen Vorschlag für den nächsten Schritt enthalten. Drohen Sie nicht mit Schäden, versprechen Sie keine Wirkung „für alles“ und erfinden Sie keine Rückgabebedingungen. Wenn Sie die Antwort nicht kennen, prüfen Sie sie vor einer Empfehlung.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Übung","type":"text"}]},{"type":"paragraph","content":[{"text":"Üben Sie zu zweit den Umgang mit Einwänden: „zu teuer“, „ich habe schon normales Waschmittel“, „ist das sicher?“ und „funktioniert das?“. Wechseln Sie die Rollen und prüfen Sie, ob die Antwort im Rahmen des vorgesehenen Produkteinsatzes bleibt.","type":"text"}]}]},"product_bullets":["Nehmen Sie den Einwand ernst und stellen Sie eine klärende Rückfrage.","Wählen Sie Preis und Umfang passend zur Nutzungshäufigkeit.","Prüfen Sie bei Sicherheitsfragen Oberfläche, Pflegeetikett und Herstellerhinweise.","Erklären Sie den vorgesehenen Produkteinsatz, statt allgemeine Versprechen zu machen.","Machen Sie keine Angaben zu Rückgabe, Reparaturen oder Ergebnissen, die Sie nicht sicher kennen."],"key_points_title":"Das Wichtigste","conversation_title":"Kundengespräch","conversation":[{"text":"Das ist mir zu teuer.","speaker":"client"},{"text":"Das verstehe ich. Wenn Sie das Produkt nur gelegentlich verwenden, schauen wir uns eine kleinere Größe an oder kaufen nur den benötigten Pflegeschritt.","speaker":"seller"},{"text":"Ist dieses Mittel für jedes Material sicher?","speaker":"client"},{"text":"Es gibt kein Mittel für alles. Sagen Sie mir, für welches Material Sie es benötigen, dann wähle ich ein passendes Produkt und eine Anwendung gemäß Pflegeetikett aus.","speaker":"seller"},{"text":"Im Internet habe ich es günstiger gesehen.","speaker":"client"},{"text":"Vergleichen wir Gebindegröße, Variante und Setinhalt. Wenn es dasselbe Produkt ist, können Sie selbstverständlich das Angebot wählen, das Ihnen besser zusagt.","speaker":"seller"}]},{"lesson_id":329,"module_id":67,"module_sort_order":6,"sort_order":4,"title":"Verkaufsgespräche simulieren","summary":"Üben Sie vollständige Verkaufsgespräche – von der Bedarfsermittlung bis zur Auswahl einer passenden Lösung.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Szenario: Helm nach einer Fahrt","type":"text"}]},{"type":"paragraph","content":[{"text":"Der Kunde hat seinen ersten Helm gekauft und eingetrocknete Insekten auf dem Visier. Fragen Sie, ob er den Helm zu Hause oder unterwegs reinigt. Erklären Sie das Aufweichen der Verschmutzung und anschließend das Finish. Wenn er nach Pinlock fragt, unterscheiden Sie die Innenscheibe von der Visieraußenseite und beachten Sie die Herstelleranleitung.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Szenario: Kombi nach der Saison","type":"text"}]},{"type":"paragraph","content":[{"text":"Der Kunde hat verschmutztes Leder und Geruch im Innenfutter. Trennen Sie die Reinigung der Außenseite, die Pflege nach dem Trocknen und das Auffrischen des Innenfutters. Wenn der Kunde bereits einen Cleaner besitzt, empfehlen Sie nur den fehlenden Schritt. Verweisen Sie bei Materialabrieb an einen Servicebetrieb.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Szenario: Enduro nach einer Schlammtour","type":"text"}]},{"type":"paragraph","content":[{"text":"Der Kunde kommt von einer anspruchsvollen Offroad-Tour zurück und hat Zugang zu Wasser. Empfehlen Sie Mud Breaker und gründliches Abspülen; stellen Sie Dirt Finisher als optionale Nachbehandlung vor. Empfehlen Sie weder, Sand trocken abzuwischen, noch das Produkt auf heiße Teile aufzutragen.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Gespräch zusammenfassen","type":"text"}]},{"type":"paragraph","content":[{"text":"Nennen Sie in jeder Situation den Bedarf, wählen Sie ein passendes Produkt und erklären Sie Anwendung und Einschränkungen. Lassen Sie dem Kunden die Wahl. Wenn keine Ergänzung benötigt wird, belassen Sie es bei der Grundlösung.","type":"text"}]}]},"product_bullets":["Fragen Sie nach dem Einsatzbereich, bevor Sie ein Produkt zeigen.","Wählen Sie ein Produkt passend zum konkreten Problem und Material.","Erklären Sie die Anwendungsreihenfolge und eine wichtige Sicherheitsbedingung.","Schlagen Sie eine Ergänzung nur vor, wenn sie einen benötigten Schritt ergänzt.","Prüfen Sie bei Schäden oder Unsicherheit die Anleitung oder verweisen Sie den Kunden an einen Servicebetrieb."],"key_points_title":"Das Wichtigste","conversation_title":"Kundengespräch","conversation":[{"text":"Ich habe einen teuren Helm gekauft. Auf dem Visier sind eingetrocknete Insekten, und ich möchte nur ein Produkt.","speaker":"client"},{"text":"Beginnen Sie mit Helmet Gel, um die Insekten aufzuweichen, und nehmen Sie sie anschließend vorsichtig mit einem Mikrofasertuch ab. Wenn Sie möchten, können Sie das saubere Visier zum Schluss mit Helmet Detailer pflegen.","speaker":"seller"},{"text":"Kann ich Pinlock mit demselben Produkt reinigen?","speaker":"client"},{"text":"Nein. Produkte für die Visieraußenseite dürfen nicht auf die Innenscheibe gelangen. Reinigen Sie diese vorsichtig gemäß den Pflegehinweisen des Helmherstellers.","speaker":"seller"},{"text":"Ich habe eine Jacke mit Membran. Imprägniert Fabric Protect sie?","speaker":"client"},{"text":"Nein, Fabric Protect wird der Wäsche hinzugefügt und unterstützt die Frische. Wählen Sie für den Nässeschutz ein separates Imprägniermittel, das für die Jacke geeignet ist.","speaker":"seller"},{"text":"Ich komme mit stark verschlammtem Enduro zurück, möchte aber nur ein Mittel.","speaker":"client"},{"text":"Dann beginnen Sie mit Mud Breaker und spülen gründlich ab. Dirt Finisher können Sie später ergänzen, wenn Sie die saubere Oberfläche nachbehandeln möchten.","speaker":"seller"}]}]$de_lessons$::jsonb) AS translated(
  module_sort_order integer, sort_order integer, title text, summary text, content jsonb,
  product_bullets jsonb, key_points_title text, conversation_title text, conversation jsonb
)
WHERE course.slug = 'pielegnacja-i-sprzedaz-produktow-xzone' AND version.version_number = 9 AND version.status = 'published'
  AND module.sort_order = translated.module_sort_order
  AND lesson.sort_order = translated.sort_order
  AND 'de' = 'de'
ON CONFLICT (lesson_id, language_code) DO UPDATE SET
  title = EXCLUDED.title,
  summary = EXCLUDED.summary,
  content = EXCLUDED.content,
  product_bullets = EXCLUDED.product_bullets,
  key_points_title = EXCLUDED.key_points_title,
  conversation_title = EXCLUDED.conversation_title,
  conversation = EXCLUDED.conversation,
  youtube_video_id = COALESCE(lesson_translations.youtube_video_id, EXCLUDED.youtube_video_id),
  youtube_video_ids = CASE WHEN cardinality(lesson_translations.youtube_video_ids) > 0 THEN lesson_translations.youtube_video_ids ELSE EXCLUDED.youtube_video_ids END,
  image_path = COALESCE(lesson_translations.image_path, EXCLUDED.image_path),
  updated_at = now();

-- cs: course, module, and lesson text
INSERT INTO public.course_translations (course_version_id, language_code, title, description, image_path)
SELECT version.id,
       'cs', translated.title, COALESCE(translated.description, ''), source.image_path
FROM public.courses AS course
JOIN public.course_versions AS version ON version.id = course.published_version_id
JOIN public.course_translations AS source ON source.course_version_id = version.id AND source.language_code = 'pl'
CROSS JOIN LATERAL jsonb_to_record($cs_course${"course_id":3,"slug":"pielegnacja-i-sprzedaz-produktow-xzone","course_version_id":13,"language_code":"cs","title":"Péče o produkty Xzone a jejich prodej","description":"","image_path":null}$cs_course$::jsonb) AS translated(title text, description text)
WHERE course.slug = 'pielegnacja-i-sprzedaz-produktow-xzone' AND version.version_number = 9 AND version.status = 'published'
  AND translated.title IS NOT NULL AND 'cs' = 'cs'
ON CONFLICT (course_version_id, language_code) DO UPDATE SET
  title = EXCLUDED.title,
  description = EXCLUDED.description,
  image_path = COALESCE(course_translations.image_path, EXCLUDED.image_path),
  updated_at = now();

INSERT INTO public.module_translations (module_id, language_code, title, summary, image_path)
SELECT module.id,
       'cs', translated.title, COALESCE(translated.summary, ''), source.image_path
FROM public.courses AS course
JOIN public.course_versions AS version ON version.id = course.published_version_id
JOIN public.course_modules AS module ON module.course_version_id = version.id
JOIN public.module_translations AS source ON source.module_id = module.id AND source.language_code = 'pl'
CROSS JOIN LATERAL jsonb_to_recordset($cs_modules$[{"module_id":61,"module_sort_order":0,"title":"Péče o helmu","summary":"","image_path":null},{"module_id":62,"module_sort_order":1,"title":"Péče o kožené oblečení","summary":"","image_path":null},{"module_id":63,"module_sort_order":2,"title":"Péče o textilní oblečení","summary":"","image_path":null},{"module_id":64,"module_sort_order":3,"title":"Rukavice a příslušenství","summary":"","image_path":null},{"module_id":65,"module_sort_order":4,"title":"Detailing motocyklu","summary":"","image_path":null},{"module_id":66,"module_sort_order":5,"title":"Péče o terénní motocykl","summary":"","image_path":null},{"module_id":67,"module_sort_order":6,"title":"Efektivní prodej produktů Xzone","summary":"","image_path":null}]$cs_modules$::jsonb) AS translated(module_sort_order integer, title text, summary text)
WHERE course.slug = 'pielegnacja-i-sprzedaz-produktow-xzone' AND version.version_number = 9 AND version.status = 'published'
  AND module.sort_order = translated.module_sort_order
  AND 'cs' = 'cs'
ON CONFLICT (module_id, language_code) DO UPDATE SET
  title = EXCLUDED.title,
  summary = EXCLUDED.summary,
  image_path = COALESCE(module_translations.image_path, EXCLUDED.image_path),
  updated_at = now();

INSERT INTO public.lesson_translations (
  lesson_id, language_code, title, summary, youtube_video_id, content, product_bullets,
  key_points_title, conversation_title, conversation, youtube_video_ids, image_path
)
SELECT lesson.id,
       'cs', translated.title, COALESCE(translated.summary, ''), source.youtube_video_id,
       translated.content, COALESCE(translated.product_bullets, '[]'::jsonb),
       translated.key_points_title, translated.conversation_title,
       COALESCE(translated.conversation, '[]'::jsonb), source.youtube_video_ids, source.image_path
FROM public.courses AS course
JOIN public.course_versions AS version ON version.id = course.published_version_id
JOIN public.course_modules AS module ON module.course_version_id = version.id
JOIN public.course_lessons AS lesson ON lesson.module_id = module.id
JOIN public.lesson_translations AS source ON source.lesson_id = lesson.id AND source.language_code = 'pl'
CROSS JOIN LATERAL jsonb_to_recordset($cs_lessons$[{"lesson_id":294,"module_sort_order":0,"sort_order":0,"title":"Proč je třeba o helmu správně pečovat?","summary":"Rozpoznejte tři části helmy a pro každou zvolte správný způsob péče.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Proč si helma zaslouží pečlivou péči","type":"text"}]},{"type":"paragraph","content":[{"text":"Při jízdě se na helmě usazují hmyz, prach ze silnice a déšť, zatímco její vnitřek je vystaven potu a vlhkosti. Nečistoty na vnější straně hledí mohou zhoršit viditelnost a zanedbaná výstelka může snížit pohodlí při nošení. Při rozhovoru se zákazníkem nejprve zjistěte, která část helmy vyžaduje péči.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Tři části, tři způsoby péče","type":"text"}]},{"type":"heading","attrs":{"level":3},"content":[{"text":"Skořepina a vnější hledí","type":"text"}]},{"type":"paragraph","content":[{"text":"U zaschlého hmyzu nezačínejte třením suchého povrchu. Helmet Gel nečistoty změkčí, aby je bylo možné jemně setřít. Helmet Detailer se používá až poté k ošetření již čistého povrchu.","type":"text"}]},{"type":"heading","attrs":{"level":3},"content":[{"text":"Výstelka","type":"text"}]},{"type":"paragraph","content":[{"text":"Osvěžovač pomáhá udržet výstelku svěží mezi praním, ale neodstraní nečistoty tak jako praní. Před praním ověřte, zda lze výstelku vyjmout, a dodržujte pokyny k péči o helmu.","type":"text"}]},{"type":"heading","attrs":{"level":3},"content":[{"text":"Pinlock","type":"text"}]},{"type":"paragraph","content":[{"text":"Vložka Pinlock je choulostivá a vyžaduje samostatnou péči. Nepoužívejte na ni gel ani detailer a netřete ji. Opláchněte ji destilovanou vodou a nechte volně uschnout podle doporučení výrobce helmy.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Jak zahájit rozhovor","type":"text"}]},{"type":"paragraph","content":[{"text":"Zeptejte se, zda chce zákazník pečovat o hledí a skořepinu, vnitřek, nebo obojí. Poté doporučte vhodný přípravek. Nepředpokládejte, že každý potřebuje kompletní sadu nebo každodenní péči.","type":"text"}]}]},"product_bullets":["Skořepinu, vnější hledí a výstelku ošetřujte odděleně – každá část vyžaduje jiný postup.","Zaschlé zbytky hmyzu nejprve změkčete přípravkem Helmet Gel; neodírejte je nasucho.","Čistý povrch dočistěte přípravkem Helmet Detailer.","Osvěžovač vnitřku nenahrazuje praní znečištěné výstelky.","O vložku Pinlock pečujte samostatně a řiďte se pokyny výrobce helmy."],"key_points_title":"Klíčové body","conversation_title":"Rozhovor se zákazníkem","conversation":[{"text":"Mám novou helmu. Musím si hned koupit celou sadu přípravků na péči?","speaker":"client"},{"text":"Ne. Pokud chcete nyní pečovat o hledí a skořepinu, vyberte přípravky na vnější povrchy. Přípravek na vnitřek se hodí jen tehdy, když je třeba výstelku osvěžit nebo vyprat.","speaker":"seller"},{"text":"Mohu jedním přípravkem vyčistit hledí i vnitřek helmy?","speaker":"client"},{"text":"Je lepší postupovat ve dvou oddělených krocích. Na vnější stranu použijte přípravky určené na hledí a výstelku čistěte samostatným přípravkem podle pokynů k helmě.","speaker":"seller"},{"text":"Zatím mě trápí jen hmyz na hledí.","speaker":"client"},{"text":"V tom případě začněte přípravkem Helmet Gel a čistou mikrovláknovou utěrkou. Pokud chcete čisté hledí ještě dočistit, můžete přidat Detailer.","speaker":"seller"}],"youtube_video_id":null,"youtube_video_ids":[],"image_path":null},{"lesson_id":295,"module_sort_order":0,"sort_order":1,"title":"Helmet Gel a Helmet Detailer: rozdíl a způsob použití","summary":"Naučte se správné pořadí použití přípravků Helmet Gel a Helmet Detailer a vyberte utěrku i velikost balení podle potřeb zákazníka.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Dva přípravky, dvě různé funkce","type":"text"}]},{"type":"paragraph","content":[{"text":"Helmet Gel a Helmet Detailer se doplňují, ale jeden nenahrazuje druhý. Gel připraví znečištěný povrch, zatímco Detailer se používá až po jeho vyčištění.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Krok 1: Změkčení nečistot","type":"text"}]},{"type":"paragraph","content":[{"text":"Naneste Helmet Gel na znečištěné místo a nechte jej působit po dobu uvedenou na etiketě. U cestovního balení se uvádí přibližně pět minut; na přímém slunci dobu zkraťte. Nenechte přípravek zaschnout. Jakmile nečistoty změknou, setřete je čistou mikrovláknovou utěrkou bez silného tlaku.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Krok 2: Dočištění čistého povrchu","type":"text"}]},{"type":"paragraph","content":[{"text":"Helmet Detailer použijte až po odstranění nečistot. Uvolněné nečistoty dobře setřete silnější mikrovláknovou utěrkou; k závěrečnému dočištění použijte utěrku Evolon. Vždy začínejte s čistým příslušenstvím.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Vyberte velikost podle způsobu použití","type":"text"}]},{"type":"paragraph","content":[{"text":"Balení o objemu 30 ml se snadno vejde na cesty. Láhev o objemu 250 ml se hodí na pravidelné čištění helmy. Zeptejte se zákazníka, kde a jak často bude přípravky používat.","type":"text"}]}]},"product_bullets":["Helmet Gel je první krok: změkčí zaschlý hmyz a nečistoty, které pak lze šetrně odstranit.","Po nanesení vyčkejte podle pokynů; u cestovního balení je uvedeno přibližně 5 minut. Na přímém slunci čekání zkraťte.","Helmet Detailer je druhý krok: použijte jej na čistý povrch pro rovnoměrný výsledek a omezení šmouh.","Uvolněné nečistoty setřete čistou silnější mikrovláknovou utěrkou; na závěr použijte Evolon.","Přípravky jsou k dispozici v cestovním balení 30 ml a ve větším balení 250 ml. Zvolte velikost podle četnosti používání."],"key_points_title":"Klíčové body","conversation_title":"Rozhovor se zákazníkem","conversation":[{"text":"Stačí na zaschlý hmyz samotný Detailer?","speaker":"client"},{"text":"U zaschlého hmyzu začněte přípravkem Helmet Gel: změkčete nečistoty, jemně je setřete mikrovláknovou utěrkou a čisté hledí nakonec dočistěte Detailerem.","speaker":"seller"},{"text":"Mám matnou helmu. Způsobí Detailer lesklý povrch?","speaker":"client"},{"text":"Ano, lze jej použít i na matnou helmu – povrch zůstane matný. Naneste přípravek na čistou mikrovláknovou utěrku a dodržujte pokyny k helmě.","speaker":"seller"},{"text":"Jak dlouho mám po nanesení gelu čekat?","speaker":"client"},{"text":"Dodržujte dobu uvedenou na etiketě; u cestovního balení se uvádí přibližně 5 minut. Nenechte přípravek zaschnout a na přímém slunci dobu zkraťte.","speaker":"seller"},{"text":"Mohu použít papírovou utěrku?","speaker":"client"},{"text":"Použijte čistou měkkou mikrovláknovou utěrku. Papír může být hrubý a choulostivý povrch poškrábat.","speaker":"seller"}],"youtube_video_id":"rRsVUfSr9Sk","youtube_video_ids":["rRsVUfSr9Sk"],"image_path":null},{"lesson_id":296,"module_sort_order":0,"sort_order":2,"title":"Jak správně čistit hledí a Pinlock","summary":"Naučte se bezpečně čistit vnější stranu hledí a rozlišovat ji od choulostivé vložky Pinlock.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Nejprve určete, který povrch čistíte","type":"text"}]},{"type":"paragraph","content":[{"text":"Vnější hledí a vložka Pinlock vyžadují odlišnou péči. Před použitím přípravku si ověřte pokyny pro konkrétní helmu, hledí a jeho povrchovou úpravu.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Vnější hledí: šetrné čištění krok za krokem","type":"text"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Volné zrnka písku a další částice odstraňte bez tření. Nečistěte nasucho leštěním povrchu.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Na zaschlý hmyz naneste Helmet Gel a nechte jej působit podle pokynů na etiketě. Nenechte jej zaschnout.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Změklé nečistoty setřete čistou utěrkou bez silného tlaku.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Pokud to pokyny k hledí dovolují, použijte Helmet Detailer a čistou utěrku Evolon k závěrečnému dočištění.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Pinlock: samostatná choulostivá vložka","type":"text"}]},{"type":"paragraph","content":[{"text":"Na vložku nepoužívejte Helmet Gel ani Helmet Detailer. Neleštěte ji utěrkou. Opláchněte ji destilovanou vodou bez tření a nechte ji volně uschnout.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Co tyto přípravky nedělají","type":"text"}]},{"type":"paragraph","content":[{"text":"Tyto přípravky slouží k čištění a dočištění. Neodstraní škrábance ani neopraví poškozené hledí.","type":"text"}]}]},"product_bullets":["Před čištěním hledí odstraňte volný písek bez tření.","Na zaschlý hmyz na vnější straně hledí naneste gel a nečistoty setřete bez tlaku.","Čisté vnější hledí dočistěte Detailerem a utěrkou Evolon.","Na Pinlock nenanášejte gel ani Detailer a neleštěte jej mikrovláknovou utěrkou.","Pinlock opláchněte destilovanou vodou a nechte volně uschnout."],"key_points_title":"Klíčové body","conversation_title":"Rozhovor se zákazníkem","conversation":[{"text":"Mohu Pinlock čistit stejným přípravkem jako vnější hledí?","speaker":"client"},{"text":"Ne. Helmet Gel a Detailer používejte na vnější stranu hledí. Pinlock šetrně očistěte destilovanou vodou bez tření a dodržujte pokyny výrobce helmy.","speaker":"seller"},{"text":"Na hledí je písek. Mohu ho hned setřít mikrovláknovou utěrkou?","speaker":"client"},{"text":"Nejprve ho opláchněte nebo šetrně odstraňte volné částice. Pískem po hledí netřete, mohl by ho poškrábat.","speaker":"seller"},{"text":"Odstraní tyto přípravky škrábance?","speaker":"client"},{"text":"Ne. Slouží k čištění a dočištění, škrábance neopraví.","speaker":"seller"}],"youtube_video_id":"rRsVUfSr9Sk","youtube_video_ids":["rRsVUfSr9Sk","8z1Me4HeZAA"],"image_path":null},{"lesson_id":297,"module_sort_order":0,"sort_order":3,"title":"Jak pečovat o vnitřek helmy","summary":"Rozlišujte mezi osvěžením vnitřku helmy a praním znečištěné výstelky.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Nejprve zjistěte, co je potřeba","type":"text"}]},{"type":"paragraph","content":[{"text":"Zeptejte se, zda chce zákazník po jízdě osvěžit vnitřek, nebo zda je výstelka viditelně znečištěná. Osvěžovač a praní řeší různé problémy: přípravek pomáhá udržovat svěžest, zatímco znečištěná výstelka potřebuje řádné vyprání.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Osvěžení mezi praním","type":"text"}]},{"type":"paragraph","content":[{"text":"Osvěžovač Mint je určený pro vnitřek helmy. Nastříkejte jej ze vzdálenosti přibližně 15–20 cm a před nasazením nechte helmu zcela vyschnout. Přípravek není určený na pokožku ani tělo.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Praní výstelky","type":"text"}]},{"type":"paragraph","content":[{"text":"Nejprve ověřte, zda lze výstelku vyjmout, a prostudujte doporučení výrobce helmy. Pro ruční praní použijte specializovaný prací prostředek podle jeho etikety. Perte šetrně, důkladně vymáchejte a nechte volně uschnout. Materiál neždímejte ani nesušte u zdroje tepla.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Kdy se k tématu vrátit","type":"text"}]},{"type":"paragraph","content":[{"text":"Pokud zápach po osvěžení přetrvává, zkontrolujte stav výstelky a zvažte její vyprání. Osvěžovač představte jako doplněk péče mezi praním.","type":"text"}]}]},"product_bullets":["Zeptejte se, zda zákazníkovi vadí zápach, nebo zda je třeba vyprat znečištěnou výstelku.","Osvěžovač Mint pomáhá udržet helmu svěží mezi praním, ale praní nenahrazuje.","Nastříkejte přípravek dovnitř ze vzdálenosti přibližně 15–20 cm a počkejte, až zcela vyschne.","Vyjímatelnou výstelku perte ručně podle pokynů k helmě.","Důkladně vymáchejte a nechte volně uschnout; neždímejte ji ani nepoužívejte zdroj tepla."],"key_points_title":"Klíčové body","conversation_title":"Rozhovor se zákazníkem","conversation":[{"text":"Vnitřek helmy zapáchá potem. Co mám vybrat?","speaker":"client"},{"text":"Pro rychlé osvěžení helmy mezi praním zvolte Mint. Pokud je výstelka znečištěná, vyperte ji samostatným přípravkem podle pokynů k helmě.","speaker":"seller"},{"text":"Mohu přípravek nastříkat na hlavu?","speaker":"client"},{"text":"Ne. Používejte jej podle pokynů na etiketě uvnitř helmy, ne na pokožku.","speaker":"seller"},{"text":"Mohu si helmu nasadit hned po použití?","speaker":"client"},{"text":"Počkejte, až vnitřek zcela vyschne. Pokud se zápach vrátí, může být třeba výstelku vyprat.","speaker":"seller"}],"youtube_video_id":null,"youtube_video_ids":[],"image_path":null},{"lesson_id":298,"module_sort_order":0,"sort_order":4,"title":"Kterou sadu doporučit: GIGA, nebo Trip Kit?","summary":"Trip Kit nebo GIGA vybírejte podle toho, kde a jak často zákazník helmu čistí.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Vyberte sadu podle způsobu použití","type":"text"}]},{"type":"paragraph","content":[{"text":"Trip Kit a GIGA pokrývají kroky čištění vnější strany helmy: změkčení nečistot gelem a následné dočištění Detailerem. Liší se především velikostí lahví a snadností skladování.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Trip Kit: na cesty","type":"text"}]},{"type":"paragraph","content":[{"text":"Kompaktní lahvičky a cestovní pouzdro usnadňují vzít sadu na cestu, uložit ji do kufru nebo přihrádky a rychle ji použít během zastávky.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"GIGA: na pravidelnou péči","type":"text"}]},{"type":"paragraph","content":[{"text":"Větší lahve gelu a Detaileru o objemu 250 ml se hodí k častému čištění doma nebo v garáži, například při péči o více helem.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Otázky, které usnadní výběr","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Kde se bude helma obvykle čistit – během cesty, nebo doma?","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Jak často ji bude zákazník čistit?","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Jedna helma, nebo více?","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Je potřeba pouze odstranit hmyz, nebo také závěrečné dočištění?","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"Pokud zákazníkovi vadí zápach uvnitř helmy, proberte samostatný přípravek na vnitřek. Sada na čištění vnější strany nenahrazuje praní výstelky.","type":"text"}]}]},"product_bullets":["Trip Kit a GIGA slouží k dvoufázovému čištění vnější strany helmy.","Trip Kit má kompaktní lahvičky a pouzdro, takže se hodí na cesty.","GIGA obsahuje 250ml lahve a příslušenství pro pravidelné používání doma nebo v garáži.","Pro osvěžení vnitřku vyberte samostatný přípravek – sady na vnější povrch ho nenahrazují.","Zeptejte se, kde a jak často bude zákazník helmu čistit; nepředpokládejte, že větší sada je lepší."],"key_points_title":"Klíčové body","conversation_title":"Rozhovor se zákazníkem","conversation":[{"text":"Chci něco na čištění helmy na cestách. Kterou sadu mám zvolit?","speaker":"client"},{"text":"Trip Kit je kompaktní a navržený na cesty. Obsahuje přípravky na vnější stranu helmy i příslušenství.","speaker":"seller"},{"text":"Nebyl by Trip Kit lepší na pravidelné čištění dvou helem doma?","speaker":"client"},{"text":"Pro časté používání může být praktičtější GIGA s většími lahvemi. Velikost zvolte podle toho, jak často a kolik helem budete čistit.","speaker":"seller"},{"text":"Vyčistí sada také výstelku?","speaker":"client"},{"text":"Ne. Tato sada slouží k péči o vnější stranu helmy. V případě potřeby zvolte samostatný přípravek na vnitřek.","speaker":"seller"},{"text":"Došel mi gel. Musím znovu koupit celou sadu?","speaker":"client"},{"text":"Ne. Pokud je přípravek dostupný samostatně, můžete vyměnit pouze jej.","speaker":"seller"}],"youtube_video_id":null,"youtube_video_ids":[],"image_path":null},{"lesson_id":299,"module_sort_order":0,"sort_order":5,"title":"Prodejní scénka: zákazník si kupuje novou helmu","summary":"Procvičte si zjišťování potřeb a doporučování péče zákazníkovi, který si kupuje helmu.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Cíl cvičení","type":"text"}]},{"type":"paragraph","content":[{"text":"Nacvičte rozhovor, který zákazníkovi kupujícímu novou helmu pomůže vybrat přípravky na péči odpovídající jeho jízdním zvyklostem. Nezačínejte výčtem produktů. Zjistěte, kde a jak často bude helmu čistit a jaký problém chce vyřešit.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Na co se zaměřit","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Položte alespoň jednu otázku, která pomůže vybrat správnou velikost balení.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Ve dvou krátkých větách vysvětlete, k čemu slouží gel a Detailer.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Nedoporučujte doplněk, který zákazník nepotřebuje.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Neslibujte konkrétní výdrž bez ověřených údajů.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Samostatné procvičování","type":"text"}]},{"type":"paragraph","content":[{"text":"Po sehrání situací formulujte navrženou odpověď vlastními slovy. Na závěr položte jednu otázku: „Čistíte helmu častěji na cestách, nebo doma?“, „Máte jednu helmu, nebo více?“ nebo „Řešíte hlavně hmyz, nebo chcete osvěžit i vnitřek?“ Doporučení vysvětlete jednou větou.","type":"text"}]}]},"product_bullets":["Nejprve se zeptejte, kde a jak často se bude helma čistit a kolik helem vyžaduje péči.","Na péči na cestách zvolte Trip Kit, na pravidelné používání doma GIGA.","Stručně vysvětlete pořadí: gel změkčí nečistoty a Detailer dočistí čistý povrch.","Nedoporučujte osvěžovač vnitřku, pokud jej zákazník nepotřebuje.","Respektujte odmítnutí a neslibujte neověřenou výdrž."],"key_points_title":"Klíčové body","conversation_title":"Rozhovor se zákazníkem","conversation":[{"text":"Jedu na týdenní výlet a nechci mít na hledí hmyz. Co si mám vzít?","speaker":"client"},{"text":"Na čištění na cestách doporučuji Trip Kit. Gel změkčí hmyz a po jeho šetrném odstranění Detailer pomůže dočistit hledí.","speaker":"seller"},{"text":"Mohu stejnou sadou čistit Pinlock?","speaker":"client"},{"text":"Na vložku nepoužívejte přípravky určené na vnější hledí. Pinlock šetrně vyčistěte podle pokynů výrobce.","speaker":"seller"},{"text":"Na vnitřek nic nepotřebuji, helma je nová.","speaker":"client"},{"text":"To je v pořádku – nemusíte kupovat osvěžovač jen pro jistotu. Můžete se k němu vrátit, pokud se objeví zápach nebo nečistoty.","speaker":"seller"}],"youtube_video_id":null,"youtube_video_ids":[],"image_path":null},{"lesson_id":300,"module_sort_order":1,"sort_order":0,"title":"Proč je třeba pečovat o motocyklovou kůži?","summary":"Určete typ kůže a druh nečistot a potom zvolte samostatné přípravky na čištění a ošetření.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Nejprve zjistěte, s čím máte co do činění","type":"text"}]},{"type":"paragraph","content":[{"text":"Kombinéza může obsahovat různé druhy kůže, barvy, povrchové úpravy i textilní panely. Zeptejte se, co přesně vyžaduje péči, jak silné je znečištění a zda zákazník zná doporučení výrobce. Světlá nebo fluorescenční kůže vyžaduje zvláštní opatrnost.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Oddělte čištění od ošetření","type":"text"}]},{"type":"paragraph","content":[{"text":"Leather Cleaner odstraňuje nečistoty. Leather Milk se nanáší pouze na čistou a suchou kůži, aby ji ošetřil. Jeden přípravek automaticky nenahrazuje druhý a přípravky na péči neopraví fyzické poškození.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Předveďte bezpečný postup","type":"text"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Volný prach odstraňte bez silného tření.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Přípravek vyzkoušejte na skrytém místě a zkontrolujte výsledek.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Jemně čistěte vhodným čističem a měkkým kartáčkem.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Zbytky setřete čistou, lehce navlhčenou utěrkou a nechte volně uschnout.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Pokud kůže potřebuje ošetřit, naneste tenkou vrstvu Leather Milk podle pokynů na etiketě.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Nastavte realistická očekávání","type":"text"}]},{"type":"paragraph","content":[{"text":"Přípravek na péči může čistit a podpořit běžnou údržbu, neobnoví však opotřebenou povrchovou úpravu ani neopraví praskliny. V případě takového poškození doporučte nechat oděv posoudit opravnou nebo výrobcem.","type":"text"}]}]},"product_bullets":["Nejprve určete typ a barvu kůže a ověřte doporučení výrobce oděvu.","Leather Cleaner odstraňuje nečistoty; Leather Milk ošetřuje kůži po jejím vyschnutí.","Před použitím přípravek vyzkoušejte na nenápadném místě, zejména u světlé kůže.","K čištění použijte měkký kartáček a mírný tlak.","Přípravky na péči neopraví praskliny, oděrky ani poškození povrchové úpravy."],"key_points_title":"Klíčové body","conversation_title":"Rozhovor se zákazníkem","conversation":[{"text":"Mám koženou kombinézu s pestrobarevnými panely. Jak mám začít s čištěním?","speaker":"client"},{"text":"Na běžné nečistoty zvolte Leather Cleaner Normal. U fluorescenčních barev jej nejprve vyzkoušejte na nenápadném místě a čistěte měkkým kartáčkem.","speaker":"seller"},{"text":"Ošetří se kůže po použití čističe?","speaker":"client"},{"text":"Čistič odstraňuje nečistoty. Jakmile kůže zcela vyschne, můžete jako samostatný krok nanést Leather Milk.","speaker":"seller"},{"text":"U švu je prasklina. Opraví ji mléko?","speaker":"client"},{"text":"Ne. Přípravky na péči kůži ošetří, ale neopraví praskliny ani poškozené švy. S oděvem se obraťte na opravnu.","speaker":"seller"}],"youtube_video_id":null,"youtube_video_ids":[],"image_path":null},{"lesson_id":301,"module_sort_order":1,"sort_order":1,"title":"Jak čistit kůži: Leather Cleaner a kartáček","summary":"Vyberte variantu Leather Cleaner podle nečistot a barvy kůže a potom předveďte šetrnou techniku čištění.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Vyberte variantu podle kůže a nečistot","type":"text"}]},{"type":"paragraph","content":[{"text":"Automaticky nevybírejte nejsilnější čistič. Normal se hodí na běžné nečistoty a choulostivější barvy. Strong lze zvážit na silnější znečištění tradiční kůže, pokud to dovolují pokyny výrobce oděvu.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Ukázka krok za krokem","type":"text"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Láhev protřepejte a přípravek vyzkoušejte na nenápadném místě.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Pěnu naneste na měkký, lehce navlhčený kartáček, ne přímo na celý oděv.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Čistěte malou plochu klidnými, jemnými tahy.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Nečistoty setřete čistou, lehce navlhčenou utěrkou.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Než budete pokračovat v péči, nechte oděv volně uschnout.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Kdy změnit postup","type":"text"}]},{"type":"paragraph","content":[{"text":"Pokud má materiál neobvyklou povrchovou úpravu, výraznou barvu nebo známky poškození, ukázku přerušte a zkontrolujte pokyny k oděvu. Čistič odstraňuje nečistoty, ale neopravuje oděrky ani praskliny.","type":"text"}]}]},"product_bullets":["Normal je volba pro běžné nečistoty a choulostivější barvy.","Strong zvažte pro silnější znečištění tradiční kůže, nejprve jej však vyzkoušejte.","Láhev protřepejte a přípravek vyzkoušejte na skrytém místě.","Pěnu naneste na měkký, lehce navlhčený kartáček; nedrhněte silou.","Zbytky setřete a kůži nechte volně uschnout."],"key_points_title":"Klíčové body","conversation_title":"Rozhovor se zákazníkem","conversation":[{"text":"Mám bílou kombinézu s fluorescenčními panely. Mám zvolit Strong?","speaker":"client"},{"text":"U fluorescenčních barev zvolte Normal a nejprve jej vyzkoušejte na skrytém místě. Strong si nechte na silné nečistoty a používejte jej pouze určeným způsobem.","speaker":"seller"},{"text":"Mohu použít tvrdý kartáč na boty?","speaker":"client"},{"text":"Lepší je použít měkký kartáček. Pěnu naneste na lehce navlhčené štětiny a malou plochu jemně čistěte krouživými pohyby.","speaker":"seller"},{"text":"Kdy mám nanést Leather Milk?","speaker":"client"},{"text":"Po čištění setřete nečistoty čistou utěrkou a nechte kůži volně uschnout. Pokud potřebuje ošetřit, naneste mléko pouze na suchý povrch.","speaker":"seller"}],"youtube_video_id":"iyz1GD-lV2Y","youtube_video_ids":["iyz1GD-lV2Y","s4I4GwvoHuc"],"image_path":null},{"lesson_id":302,"module_sort_order":1,"sort_order":2,"title":"Jak ošetřit kůži: Leather Milk","summary":"Vysvětlete, že Leather Milk je krok ošetření po vyčištění a vysušení kůže.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Proč kůži ošetřovat","type":"text"}]},{"type":"paragraph","content":[{"text":"Po vyčištění a vysušení může kůže potřebovat samostatné ošetření. Leather Milk se používá po čističi; není to prací prostředek na znečištěný oděv. Před ukázkou aplikace zákazníkovi vysvětlete toto pořadí.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Nepřehánějte to s množstvím","type":"text"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Kůže musí být čistá a zcela suchá.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Vyzkoušejte přípravek na nenápadném místě, zejména u neobvyklé povrchové úpravy.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Naneste malé množství přípravku měkkou utěrkou.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Rozetřete jej v tenké rovnoměrné vrstvě podle pokynů na etiketě.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Nechte zaschnout a před případným dalším nanášením zkontrolujte výsledek.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Co dokáže a co ne","type":"text"}]},{"type":"paragraph","content":[{"text":"Mléko podporuje běžnou péči, ale neopraví praskliny, oděrky ani poškozenou povrchovou úpravu. Neslibujte voděodolnost, pokud výrobce přípravku výslovně neuvádí, že ji poskytuje. V případě pochybností se řiďte pokyny k oděvu.","type":"text"}]}]},"product_bullets":["Leather Milk nanášejte na čistou a suchou kůži.","Naneste tenkou rovnoměrnou vrstvu podle pokynů.","Před nanesením na celý oděv přípravek vyzkoušejte na skrytém místě.","Mléko nepoužívejte k odstranění nečistot.","Neslibujte, že opraví praskliny nebo obnoví původní ochrannou povrchovou úpravu."],"key_points_title":"Klíčové body","conversation_title":"Rozhovor se zákazníkem","conversation":[{"text":"Proč potřebuji Leather Milk, když už mám Leather Cleaner?","speaker":"client"},{"text":"Čistič odstraňuje nečistoty, zatímco Leather Milk ošetřuje kůži po vyčištění a vysušení. Pokud kůže právě ošetřit nepotřebuje, mléko přidávat nemusíte.","speaker":"seller"},{"text":"Mohu mléko nanést na špinavou bundu?","speaker":"client"},{"text":"Nejprve ji vyčistěte a nechte uschnout. Mléko čistič nenahrazuje.","speaker":"seller"},{"text":"Mám matnou kůži. Jak ověřím, zda je pro ni mléko vhodné?","speaker":"client"},{"text":"Vyzkoušejte jej na nenápadném místě a ověřte doporučení výrobce oděvu. Teprve potom naneste tenkou vrstvu podle pokynů na etiketě.","speaker":"seller"},{"text":"Opraví mléko praskliny?","speaker":"client"},{"text":"Ne. Praskliny a oděrky vyžadují opravu, ne přípravek na péči.","speaker":"seller"}],"youtube_video_id":null,"youtube_video_ids":[],"image_path":null},{"lesson_id":303,"module_sort_order":1,"sort_order":3,"title":"Jak používat Leather Care Kit","summary":"Proveďte zákazníka rutinou péče o kůži a ověřte, že každá položka skutečně odpovídá jeho potřebám.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Sada jako postup krok za krokem","type":"text"}]},{"type":"paragraph","content":[{"text":"Leather Care Kit může být praktická pro někoho, kdo chce pečovat o vnější stranu koženého oblečení a osvěžit jeho vnitřek. Sada obsahuje čistič, Leather Milk, osvěžovač vnitřku, kartáček a utěrku. Místo pouhého výčtu položek ukažte pořadí použití.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Pořadí použití","type":"text"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Vyberte variantu čističe podle nečistot a barvy a nejprve ji vyzkoušejte.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Kůži vyčistěte měkkým kartáčkem a setřete zbytky.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Nechte kůži volně uschnout.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Naneste tenkou vrstvu Leather Milk podle pokynů na etiketě.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Vnitřek osvěžte samostatně podle pokynů k danému přípravku.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Sadu doporučte jen tehdy, když se hodí","type":"text"}]},{"type":"paragraph","content":[{"text":"Zeptejte se, co už zákazník vlastní a zda potřebuje pečovat také o vnitřek. Pokud už má čistič a potřebuje jen kondicionér, doporučte pouze chybějící krok. Nepředstavujte sadu jako nezbytnou pro každého.","type":"text"}]}]},"product_bullets":["Leather Care Kit kombinuje čistič, ošetřující mléko, osvěžovač vnitřku a příslušenství.","Kůži nejprve vyčistěte a nechte uschnout, poté naneste Leather Milk.","Osvěžovač vnitřku řeší jinou potřebu než péče o vnější stranu.","Vyberte Normal nebo Strong podle barvy, nečistot a pokynů k oděvu.","Pokud už zákazník některé přípravky vlastní, doporučte pouze to, co mu chybí."],"key_points_title":"Klíčové body","conversation_title":"Rozhovor se zákazníkem","conversation":[{"text":"Mám oděv zvenku špinavý a uvnitř zapáchá. Vyřeší sada oba problémy?","speaker":"client"},{"text":"Leather Care Kit kombinuje čistič, ošetřující mléko, osvěžovač vnitřku a příslušenství. Kůži nejprve vyčistěte; po jejím vyschnutí ji ošetřete mlékem a vnitřek osvěžte samostatně.","speaker":"seller"},{"text":"Čistič už mám. Vyplatí se mi přesto koupit celou sadu?","speaker":"client"},{"text":"Pokud už ostatní položky máte, není to nutné. Vyberte pouze chybějící mléko nebo přípravek na vnitřek.","speaker":"seller"},{"text":"Kůže je popraskaná. Obnoví ji sada?","speaker":"client"},{"text":"Poškození neopraví. Pokud je kůže popraskaná, nejprve se obraťte na opravnu.","speaker":"seller"}],"youtube_video_id":null,"youtube_video_ids":[],"image_path":null},{"lesson_id":304,"module_sort_order":1,"sort_order":4,"title":"Prodejní scénka: zákazník si kupuje kožené oblečení","summary":"Procvičte si určení typu kůže, výběr nejjednoduššího vhodného řešení a reakci na potřeby zákazníka.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Začněte rozhovor zjištěním potřeb","type":"text"}]},{"type":"paragraph","content":[{"text":"Cílem scénky je vybrat řešení pro konkrétní kombinézu, ne prodat všechny přípravky v regálu. Zjistěte barvu a typ kůže, míru znečištění, její stav a to, co už zákazník vlastní. Teprve potom vysvětlete potřebné kroky.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Tři situace k procvičení","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Světlá kombinéza s fluorescenčními panely: pečlivě zvolte čistič a vyzkoušejte jej na skrytém místě.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Silně znečištěná černá kombinéza: zvolte čistič podle typu kůže, jemně čistěte a nechte uschnout.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Čistá bunda, která potřebuje běžnou péči: zvažte Leather Milk bez zbytečného přidávání čističe.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Společné zhodnocení","type":"text"}]},{"type":"paragraph","content":[{"text":"Po každém rozhovoru by měl prodavač vysvětlit, co si zákazník kupuje, v jakém pořadí přípravky použije a co jimi nelze opravit. Pokud už zákazník některé příslušenství vlastní, doporučení se může omezit na jediný chybějící přípravek.","type":"text"}]}]},"product_bullets":["Zeptejte se na typ, barvu a stav kůže i na doporučení výrobce oděvu.","Oddělte čištění vnějšího povrchu, jeho ošetření a osvěžení vnitřku.","Čistič vybírejte podle barvy a nečistot; u choulostivé kůže jej nejprve vyzkoušejte.","Leather Milk doporučte po vyschnutí kůže, pokud zákazník potřebuje ošetření.","Fyzické poškození přenechte opravně; neslibujte, že je přípravek na péči opraví."],"key_points_title":"Klíčové body","conversation_title":"Rozhovor se zákazníkem","conversation":[{"text":"Mám kombinézu s fluorescenčními panely a bojím se změny barvy.","speaker":"client"},{"text":"Na fluorescenční barvy zvolte Normal. Vyzkoušejte jej na nenápadném místě a potom měkkým kartáčkem vyčistěte malou plochu.","speaker":"seller"},{"text":"Čistič už mám. Co potřebuji pro péči po vyčištění?","speaker":"client"},{"text":"Pokud to kůže potřebuje, zvolte samotný Leather Milk. Nanášejte jej až po vyschnutí kůže po čištění.","speaker":"seller"},{"text":"Na rukávu je oděrka. Skryje ji přípravek na péči?","speaker":"client"},{"text":"Ne, přípravek na péči oděrku neopraví. Nechte kombinézu zkontrolovat, zda potřebuje odbornou opravu.","speaker":"seller"},{"text":"Uvnitř je cítit pot. Mám vyprat celou koženou kombinézu?","speaker":"client"},{"text":"Nezačínejte namáčením kombinézy. Zvolte samostatný přípravek na vnitřek a použijte jej podle pokynů k oděvu.","speaker":"seller"}],"youtube_video_id":null,"youtube_video_ids":[],"image_path":null},{"lesson_id":305,"module_sort_order":2,"sort_order":0,"title":"Jak pečovat o textilní oblečení","summary":"Určete materiál oděvu a pokyny k praní, poté zvolte přípravek pro konkrétní vlákno.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Než vyberete prací prostředek","type":"text"}]},{"type":"paragraph","content":[{"text":"Motocyklové oblečení může kombinovat membránu, podšívku, chrániče a různá vlákna. Zjistěte, co chce zákazník vyprat, zkontrolujte štítek s pokyny k péči a teprve potom doporučte přípravek. Pokyny k oděvu určují teplotu, program, dávkování i způsob sušení.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Vyberte přípravek podle materiálu","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Textile Care: na technické a membránové oblečení.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Active Care: na syntetické sportovní oblečení, funkční spodní vrstvy a mikrovlákno.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Merino Care: na merino vlnu a jemná přírodní vlákna.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Jeans Care: na denim, včetně motocyklového oblečení, pokud to dovoluje štítek s pokyny k péči.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Fabric Protect: přísada do praní, která pomáhá udržovat svěžest; nejde o impregnaci.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Neperte všechno stejně","type":"text"}]},{"type":"paragraph","content":[{"text":"Membránová bunda, funkční triko a merino vrstva mohou vyžadovat různé prací prostředky i programy. Nedoporučujte aviváž jako náhradu specializované péče. Pokud chce zákazník obnovit vodoodpudivost, zvolte samostatný přípravek určený k tomuto účelu a kompatibilní s pokyny k oděvu.","type":"text"}]}]},"product_bullets":["Vycházejte ze štítku: materiál, teplota, program, prací prostředek a sušení.","Na technické oblečení zvolte Textile Care, na sportovní oblečení Active Care.","Merino Care je určený na jemnou vlnu, zatímco Jeans Care na denim.","Fabric Protect pomáhá udržovat svěžest během praní a není přípravkem na vodoodpudivou úpravu.","Různé materiály perte odděleně, pokud vyžadují odlišné programy a přípravky."],"key_points_title":"Klíčové body","conversation_title":"Rozhovor se zákazníkem","conversation":[{"text":"Mám membránovou bundu, funkční triko a merino top. Mohu je vyprat dohromady?","speaker":"client"},{"text":"Je lepší je roztřídit podle štítků s pokyny k péči: jde o různé materiály, které mohou vyžadovat odlišné prací prostředky a programy. Na bundu zvolte Textile Care a na merino samostatný přípravek.","speaker":"seller"},{"text":"Zajistí Fabric Protect, že bude bunda voděodolná?","speaker":"client"},{"text":"Ne. Fabric Protect je přísada do praní, která pomáhá udržovat svěžest. Pro ochranu před vodou zvolte samostatnou impregnaci určenou pro daný oděv.","speaker":"seller"},{"text":"Nejsem si jistý, jaký program zvolit.","speaker":"client"},{"text":"Použijte program a teplotu uvedené na štítku oděvu a dávkování ověřte na etiketě pracího prostředku.","speaker":"seller"}],"youtube_video_id":null,"youtube_video_ids":[],"image_path":null},{"lesson_id":306,"module_sort_order":2,"sort_order":1,"title":"Textile Care: praní oblečení","summary":"Vysvětlete, k čemu slouží Textile Care, a ukažte, jak jej bezpečně vybrat pro technické oblečení.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"K čemu slouží Textile Care","type":"text"}]},{"type":"paragraph","content":[{"text":"Textile Care je určený na technické motocyklové oblečení, včetně oděvů s membránou. Neslibujte, že prací prostředek opraví opotřebovanou membránu nebo obnoví její vlastnosti po poškození. Cílem je oděv správně vyprat podle pokynů jeho výrobce.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Příprava na praní","type":"text"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Zkontrolujte štítek oděvu a vyjměte věci, které se musí prát zvlášť.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Zvolte povolený program a teplotu.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Prací prostředek odměřte podle pokynů na etiketě.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Nepřidávejte běžnou aviváž, pokud ji výrobce výslovně nedoporučuje.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Oděv sušte podle pokynů na štítku; pokud je to uvedeno, chraňte jej před nadměrným teplem.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Extra svěžest","type":"text"}]},{"type":"paragraph","content":[{"text":"Fabric Protect lze přidat do praní jako samostatnou přísadu. Jasně vysvětlete jeho funkci: pomáhá udržovat svěžest oblečení, ale nenahrazuje vodoodpudivou úpravu.","type":"text"}]}]},"product_bullets":["Textile Care je určený k praní technického a membránového motocyklového oblečení.","Program, teplotu a způsob sušení určuje štítek oděvu.","Běžnou aviváž automaticky nenahrazujte ani nepřidávejte.","Dávkujte podle etikety přípravku a pokynů k praní.","Fabric Protect lze zvážit jako samostatnou přísadu pro zachování svěžesti."],"key_points_title":"Klíčové body","conversation_title":"Rozhovor se zákazníkem","conversation":[{"text":"Je Textile Care vhodný na membránovou bundu?","speaker":"client"},{"text":"Ano. Jde o prací prostředek na technické a membránové oblečení. Program a teplotu zvolte podle štítku bundy.","speaker":"seller"},{"text":"Vždy používám aviváž. Mám v tom pokračovat?","speaker":"client"},{"text":"U technického oblečení ji nepoužívejte automaticky. Zkontrolujte štítek s pokyny k péči a použijte Textile Care podle návodu.","speaker":"seller"},{"text":"Co mohu přidat, aby oblečení po vyprání svěže vonělo?","speaker":"client"},{"text":"Do přihrádky na aviváž můžete místo běžné aviváže přidat Fabric Protect podle pokynů na etiketě.","speaker":"seller"}],"youtube_video_id":"UUXCozkqAZk","youtube_video_ids":["UUXCozkqAZk"],"image_path":null},{"lesson_id":307,"module_sort_order":2,"sort_order":2,"title":"Fabric Protect: péče a svěžest po praní","summary":"Ukažte, jak přidat Fabric Protect do praní, a odlište jej od impregnačního přípravku.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Přísada do praní, ne impregnace","type":"text"}]},{"type":"paragraph","content":[{"text":"Název může naznačovat ochranu před vodou, proto jasně vysvětlete funkci přípravku. Fabric Protect je přísada, která pomáhá udržovat svěžest oblečení během praní. Není to vodoodpudivá úprava a sama o sobě neobnovuje DWR vrstvu.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Jak jej používat","type":"text"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Zvolte prací prostředek podle materiálu a zkontrolujte štítek oděvu.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Pokud to návod uvádí, nalijte Fabric Protect do přihrádky na aviváž.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Použijte dávkování uvedené na etiketě.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Zvolte program odpovídající pokynům k oděvu.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Na impregnaci použijte samostatný přípravek, který je k tomu výslovně určený.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Jak vysvětlit přidanou hodnotu","type":"text"}]},{"type":"paragraph","content":[{"text":"Pokud zákazník pere technické oblečení a chce, aby po praní zůstalo svěží, můžete mu vedle Textile Care doporučit Fabric Protect. Pokud se ptá na ochranu proti dešti, jasně vysvětlete, že potřebuje samostatnou impregnaci.","type":"text"}]}]},"product_bullets":["Fabric Protect je přísada do praní, která pomáhá udržovat svěžest oblečení.","Může nahradit běžnou aviváž, pokud to uvádí etiketa.","Podle pokynů jej nalijte do přihrádky na aviváž.","Vyberte jej společně se správným pracím prostředkem pro daný materiál.","Neslibujte, že obnoví voděodolnost nebo DWR úpravu."],"key_points_title":"Klíčové body","conversation_title":"Rozhovor se zákazníkem","conversation":[{"text":"Zajistí Fabric Protect, že bude moje bunda znovu odpuzovat vodu?","speaker":"client"},{"text":"Ne – jde o přísadu do praní, která pomáhá zachovat svěžest oblečení, ne o vodoodpudivou úpravu. Na bundu zvolte samostatnou impregnaci.","speaker":"seller"},{"text":"Kam mám nalít Fabric Protect?","speaker":"client"},{"text":"Nalijte jej místo běžné aviváže do její přihrádky a oděv vyperte podle štítku s pokyny k péči.","speaker":"seller"},{"text":"Mohu jej použít společně s Textile Care?","speaker":"client"},{"text":"Ano. Textile Care vypere technické oblečení a Fabric Protect se jako samostatný krok přidává do přihrádky na máchání.","speaker":"seller"}],"youtube_video_id":null,"youtube_video_ids":[],"image_path":null},{"lesson_id":308,"module_sort_order":2,"sort_order":3,"title":"Active Care: péče o sportovní oblečení","summary":"Active Care vybírejte na syntetické sportovní oblečení a funkční spodní vrstvy podle způsobu jejich používání.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Kdy zvolit Active Care","type":"text"}]},{"type":"paragraph","content":[{"text":"Active Care se hodí na syntetické sportovní oblečení, funkční spodní vrstvy a mikrovlákno. Nejprve se zeptejte na aktivitu zákazníka a problém, který řeší, například zápach po tréninku nebo časté praní funkční vrstvy.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Vyberte podle materiálu","type":"text"}]},{"type":"paragraph","content":[{"text":"Pokud se zákazník ptá na membránovou bundu, zkontrolujte její štítek a zvažte Textile Care. Na merino vlnu zvolte přípravek určený na jemná přírodní vlákna. Active Care nevybírejte jen proto, že jde o sportovní oblečení.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Použití a velikost","type":"text"}]},{"type":"paragraph","content":[{"text":"Vždy zkontrolujte štítek oděvu, kde najdete program, teplotu a pokyny k sušení. Dávkování se řídí etiketou přípravku. Sáček o objemu 40 ml se hodí na vyzkoušení produktu nebo na cesty.","type":"text"}]}]},"product_bullets":["Active Care zvolte na syntetické sportovní oblečení a funkční spodní vrstvy.","Zeptejte se na materiál, zápach po cvičení a pokyny na štítku.","Nepředpokládejte, že jde o prací prostředek na všechny druhy oděvů.","Dodržujte dávkování a programy uvedené na etiketách přípravku i oděvu.","Sáček o objemu 40 ml umožní zákazníkovi produkt vyzkoušet před koupí většího balení."],"key_points_title":"Klíčové body","conversation_title":"Rozhovor se zákazníkem","conversation":[{"text":"Moje funkční triko pořád zapáchá potem. Co mám vybrat?","speaker":"client"},{"text":"Pokud jde o syntetické sportovní oblečení nebo funkční spodní vrstvu, zvolte Active Care. Vyperte ji podle štítku a dodržte dávkování uvedené na etiketě produktu.","speaker":"seller"},{"text":"Mám použít Active Care na membránovou bundu?","speaker":"client"},{"text":"Na membránovou bundu zvolte Textile Care. Active Care je určený na syntetické sportovní oblečení a funkční vrstvy.","speaker":"seller"},{"text":"Mohu si vzít menší balení na cesty?","speaker":"client"},{"text":"Ano, k dispozici je 40ml sáček. Hodí se na vyzkoušení produktu nebo na cesty.","speaker":"seller"}],"youtube_video_id":null,"youtube_video_ids":[],"image_path":null},{"lesson_id":309,"module_sort_order":2,"sort_order":4,"title":"Merino Care","summary":"Naučte se prát merino a jemná vlákna a vyhněte se příliš obecným doporučením.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Jemná vlákna vyžadují zvláštní péči","type":"text"}]},{"type":"paragraph","content":[{"text":"Merino vrstvy pomáhají regulovat pohodlí při jízdě a je třeba o ně pečovat podle štítků. Merino Care je určený na merino vlnu a další jemná vlákna uvedená výrobcem. Nepředpokládejte, že program vhodný pro syntetické spodní vrstvy je bezpečný i pro vlnu.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Praní a sušení","type":"text"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Zkontrolujte složení látky a symboly péče na štítku.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Pokud je to uvedeno, zvolte program na vlnu nebo ruční praní.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Prací prostředek dávkujte podle etikety; u malé dávky může být uvedeno 15–30 ml.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Nepoužívejte běžnou aviváž, pokud ji výrobce nedoporučuje.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Oděv nechte uschnout volně a nepokládejte jej na horký radiátor.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Rozhovor se zákazníkem","type":"text"}]},{"type":"paragraph","content":[{"text":"Zeptejte se, zda zákazník pere merino vrstvu samostatně, nebo oděv z různých materiálů. U směsových látek může být vhodnější oddělené praní než jeden prací prostředek na všechno.","type":"text"}]}]},"product_bullets":["Merino Care je určený na merino vlnu a jemná přírodní vlákna.","Teplotu a program určujte především podle štítku oděvu.","Prací prostředek dávkujte podle jeho etikety.","Nepřidávejte běžnou aviváž, pokud to není výslovně doporučeno.","Sušte volně podle pokynů a chraňte oděv před nadměrným teplem."],"key_points_title":"Klíčové body","conversation_title":"Rozhovor se zákazníkem","conversation":[{"text":"Mohu merino triko vyprat běžným pracím prostředkem?","speaker":"client"},{"text":"Na merino zvolte Merino Care a nejprve zkontrolujte štítek s pokyny k péči. Běžný prací prostředek nemusí být pro jemnou vlnu vhodný.","speaker":"seller"},{"text":"Jaký program a teplotu mám použít?","speaker":"client"},{"text":"Program na vlnu nebo ruční praní zvolte jen tehdy, pokud to dovoluje štítek s pokyny k péči, a dodržte uvedenou teplotu.","speaker":"seller"},{"text":"Mohu triko usušit na radiátoru?","speaker":"client"},{"text":"Nepokládejte je na horký radiátor. Nechte jej uschnout volně podle štítku s pokyny k péči.","speaker":"seller"}],"youtube_video_id":"Hs9QuFjKbRA","youtube_video_ids":["Hs9QuFjKbRA"],"image_path":null},{"lesson_id":310,"module_sort_order":2,"sort_order":5,"title":"Jeans Care","summary":"Jeans Care zvolte na denim a zohledněte konstrukci motocyklového oblečení.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Motocyklový denim nejsou vždy obyčejné džíny","type":"text"}]},{"type":"paragraph","content":[{"text":"Motocyklové oblečení může obsahovat elastická vlákna, podšívku, chrániče a zesílené panely. Před doporučením pracího prostředku ověřte složení materiálu a zjistěte, které části lze vyjmout. Štítek oděvu určuje program praní a způsob sušení.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Péče krok za krokem","type":"text"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Zkontrolujte štítek s pokyny k péči a složení materiálu.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Pokud to výrobce dovoluje, vyjměte chrániče.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Na denim zvolte Jeans Care a dávkujte podle pokynů na etiketě.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Zvolte program uvedený na štítku s pokyny k péči.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Oděv sušte podle pokynů a nevystavujte jej nadměrnému teplu.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Vyberte přípravek vhodný pro daný oděv","type":"text"}]},{"type":"paragraph","content":[{"text":"Jeans Care není univerzální přípravek na všechny druhy oblečení. Pokud má zákazník kalhoty s membránou nebo vysokým podílem technických vláken, řiďte se složením materiálu a pokyny k péči. Sáček o objemu 40 ml je kompaktní varianta.","type":"text"}]}]},"product_bullets":["Jeans Care zvolte na denim, včetně motocyklového oblečení, pokud to dovoluje štítek s pokyny k péči.","Zkontrolujte složení materiálu, směsová vlákna a to, zda má oděv chrániče nebo podšívku.","Program a teplotu nastavte podle symbolů péče od výrobce.","Prací prostředek na denim automaticky nepoužívejte na vlnu ani membránové oblečení.","Sáček o objemu 40 ml může posloužit jako vzorek nebo cestovní balení."],"key_points_title":"Klíčové body","conversation_title":"Rozhovor se zákazníkem","conversation":[{"text":"Mám zesílené motocyklové džíny. Mohu je prát?","speaker":"client"},{"text":"Ano – Jeans Care je určený na denim a oblečení s aramidovými vlákny. Zkontrolujte štítek, kalhoty obraťte naruby, zvolte šetrné praní, obvykle do 30 °C s nízkými otáčkami, a nechte je uschnout volně.","speaker":"seller"},{"text":"Mohu je sušit v sušičce?","speaker":"client"},{"text":"Nechte je uschnout volně a nepoužívejte sušičku. Zkontrolujte také štítek kalhot.","speaker":"seller"},{"text":"Je Jeans Care vhodný na membránovou bundu?","speaker":"client"},{"text":"Na membránovou bundu jej nevybírejte. Na technické oblečení zvolte Textile Care podle štítku s pokyny k péči.","speaker":"seller"}],"youtube_video_id":null,"youtube_video_ids":[],"image_path":null},{"lesson_id":311,"module_sort_order":2,"sort_order":6,"title":"Prodejní scénka: péče o různé druhy oblečení","summary":"Procvičte si výběr pracího prostředku pro různé druhy oblečení a reakci na požadavek na impregnaci.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Tři situace k procvičení","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Membránová bunda, funkční triko a džíny: rozdělte oblečení a pro každý materiál zvolte vhodný přípravek.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Zákazník chce bundu „naimpregnovat“ přípravkem Fabric Protect: vysvětlete rozdíl a ověřte, zda potřebuje samostatnou impregnaci.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Zákazník pere pouze merino top: ukažte Merino Care a příslušné pokyny na štítku oděvu.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Postup při doporučení","type":"text"}]},{"type":"paragraph","content":[{"text":"Vlastními slovy shrňte potřebu zákazníka, zeptejte se na složení materiálu a způsob praní a potom doporučte jeden přípravek. Vysvětlete, k čemu slouží a co nedokáže. Další přípravek doporučte pouze tehdy, když řeší samostatnou potřebu.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Cíl cvičení","type":"text"}]},{"type":"paragraph","content":[{"text":"Po každé situaci by měl prodavač umět vysvětlit doporučení podle materiálu a pokynů k péči, místo aby každému nabízel stejný prací prostředek.","type":"text"}]}]},"product_bullets":["Přípravek vybírejte podle materiálu, složení látky a pokynů výrobce oděvu.","Textile Care se hodí na technické oblečení; Active Care na syntetické sportovní oblečení a spodní vrstvy.","Merino Care a Jeans Care jsou určeny pro různé typy vláken.","Fabric Protect pomáhá udržovat svěžest při praní, ale není impregnací.","Neprodávejte celou sadu, pokud zákazník potřebuje jediný přípravek."],"key_points_title":"Klíčové body","conversation_title":"Rozhovor se zákazníkem","conversation":[{"text":"Mám membránovou bundu, funkční triko a džíny. Chci jeden prací prostředek na všechno.","speaker":"client"},{"text":"Rozumím. Pro tyto tři materiály zvolte samostatné prostředky: Textile Care na bundu, Active Care na syntetickou spodní vrstvu a Jeans Care na denim – vždy podle pokynů na štítku.","speaker":"seller"},{"text":"Zajistí Fabric Protect, že bude bunda voděodolná?","speaker":"client"},{"text":"Ne, tato přísada pomáhá po praní udržovat svěžest. Pokud chcete, aby bunda odpuzovala vodu, potřebuje samostatnou impregnaci.","speaker":"seller"},{"text":"Peru pouze merino top. Musím koupit sadu?","speaker":"client"},{"text":"Ne. Merino Care stačí, pokud štítek dovoluje praní; dodržujte program určený výrobcem.","speaker":"seller"}],"youtube_video_id":null,"youtube_video_ids":[],"image_path":null},{"lesson_id":312,"module_sort_order":3,"sort_order":0,"title":"Jak pečovat o motocyklové rukavice","summary":"Určete, zda se problém týká vnitřní, nebo vnější strany rukavic, a zvolte správný způsob péče.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Nejprve zjistěte, o jaký problém jde","type":"text"}]},{"type":"paragraph","content":[{"text":"Rukavice kombinují kůži, textil, chrániče, švy a špatně dostupné části prstů. Zeptejte se, zda chce zákazník odstranit nečistoty zvenku, osvěžit vnitřek, nebo ošetřit suchou kůži. Každá z těchto potřeb vyžaduje jiné řešení.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Zkontrolujte pokyny k rukavicím","type":"text"}]},{"type":"paragraph","content":[{"text":"Ne všechny rukavice lze prát v pračce nebo obrátit naruby. U kožených rukavic je obzvlášť důležité ověřit doporučení výrobce. Nenamáčejte je ani nenatahujte, pokud to pokyny nedovolují.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Zvolte správnou péči","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Zápach uvnitř, který se špatně odstraňuje: zvažte Magiczne Rękawiczki a dodržte jejich pokyny.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Nečistoty na vnější straně: podle materiálu rukavic a doporučení výrobce zvolte vhodný přípravek.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Zadrhávající, ale nepoškozený zip: zvažte Zip Service.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Oděrky, odlupování a roztržené švy: přípravek na péči nenahradí opravu.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Stručné doporučení","type":"text"}]},{"type":"paragraph","content":[{"text":"Při doporučování vysvětlete, k čemu přípravek slouží a co nedokáže. Magiczne Rękawiczki osvěžují vnitřek; rukavice kompletně nevyperou ani neopraví.","type":"text"}]}]},"product_bullets":["Rukavice mají švy, chrániče a různé materiály, proto zkontrolujte štítek s pokyny k péči.","Rozlišujte mezi nečistotami na vnější straně a zápachem či vlhkostí uvnitř.","Nepředpokládejte, že lze rukavice prát v pračce nebo obrátit naruby.","Magiczne Rękawiczki pomáhají osvěžit špatně dostupná místa uvnitř.","Poškozené nebo rozlepené švy a odřená kůže vyžadují odbornou opravu."],"key_points_title":"Klíčové body","conversation_title":"Rozhovor se zákazníkem","conversation":[{"text":"Rukavice zapáchají, ale nemohu je obrátit naruby.","speaker":"client"},{"text":"Použijte Magiczne Rękawiczki k osvěžení špatně dostupných míst uvnitř. Navlékněte si napuštěný pár na ruce a vyčistěte vnitřek podle pokynů.","speaker":"seller"},{"text":"Mohu je jednoduše dát do pračky?","speaker":"client"},{"text":"Pouze pokud výrobce rukavic povoluje praní v pračce. Zkontrolujte štítek – rukavice mohou obsahovat kůži, chrániče a lepené části.","speaker":"seller"},{"text":"Materiál je odřený. Opraví jej přípravek?","speaker":"client"},{"text":"Ne. Přípravek na péči neopraví oděrku ani šev; odneste rukavice do opravny.","speaker":"seller"}],"youtube_video_id":null,"youtube_video_ids":[],"image_path":null},{"lesson_id":313,"module_sort_order":3,"sort_order":1,"title":"Magiczne Rękawiczki: použití a ukázka","summary":"Ukažte zákazníkovi, jak použít Magiczne Rękawiczki k osvěžení vnitřku rukavic.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Proč používat Magiczne Rękawiczki","type":"text"}]},{"type":"paragraph","content":[{"text":"Napuštěný pár usnadňuje čištění špatně dostupných míst uvnitř rukavic, které nelze snadno obrátit naruby. Může se hodit zejména u kožených rukavic, pokud jejich pokyny tento způsob osvěžení dovolují.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Ukázka","type":"text"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Otevřete sáček a navlékněte si jednorázový pár na ruce.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Ruce vložte do motocyklových rukavic.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Pohybujte prsty a mírně zatlačte, aby se přípravek dostal dovnitř.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Netahejte za podšívku a nesnažte se rukavici násilím obrátit naruby.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Po dokončení napuštěný pár sundejte a umyjte si ruce podle pokynů.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Co neslibovat","type":"text"}]},{"type":"paragraph","content":[{"text":"Jde o praktický způsob osvěžení vnitřku, nikoli o náhradu praní celé rukavice, opravy švů nebo odstranění všech druhů nečistot. Zákazník má přípravek používat podle pokynů na obalu.","type":"text"}]}]},"product_bullets":["Sáček obsahuje jeden pár napuštěných jednorázových rukavic.","Navlékněte si je, vložte ruce do motocyklových rukavic a pohybujte prsty.","Jemně se dostaňte dovnitř, aniž byste rukavice obraceli naruby.","Jde o způsob osvěžení vnitřku, nikoli o úplné vyprání či opravu rukavic.","Po použití přípravek sundejte a umyjte si ruce podle pokynů."],"key_points_title":"Klíčové body","conversation_title":"Rozhovor se zákazníkem","conversation":[{"text":"Jak se používají Magiczne Rękawiczki?","speaker":"client"},{"text":"Nasaďte si napuštěný jednorázový pár, vložte ruce do motocyklových rukavic a pohybujte prsty, abyste vyčistili jejich vnitřek.","speaker":"seller"},{"text":"Musím rukavice obrátit naruby?","speaker":"client"},{"text":"Ne. Proto si napuštěné rukavice navléknete na ruce a vložíte je do motocyklových rukavic. Netahejte za podšívku.","speaker":"seller"},{"text":"Nahrazuje to vyprání celé rukavice?","speaker":"client"},{"text":"Ne, jde o způsob osvěžení vnitřku. Po použití jednorázový pár sundejte a řiďte se pokyny k produktu.","speaker":"seller"},{"text":"Mohu je použít u kožených rukavic?","speaker":"client"},{"text":"Nejprve zkontrolujte doporučení výrobce rukavic a pokyny k produktu a potom podle nich postupujte.","speaker":"seller"}],"youtube_video_id":null,"youtube_video_ids":[],"image_path":null},{"lesson_id":314,"module_sort_order":3,"sort_order":2,"title":"Zip Service: péče o zipy a doplňkový prodej","summary":"Vysvětlete, k čemu Zip Service slouží, a rozlišujte údržbu od opravy poškození.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Na funkční zip, který drhne","type":"text"}]},{"type":"paragraph","content":[{"text":"Zip Service je přípravek na údržbu zipů, které jdou ztuha, ale nejsou mechanicky poškozené. Zeptejte se, zda jde o tření a odpor, nebo zda chybějí zoubky či je jezdec ohnutý.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Jak předvést použití","type":"text"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Odstraňte ze zipu viditelné nečistoty.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Na zoubky naneste malé množství Zip Service podle pokynů na etiketě.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Několikrát posuňte jezdec tam a zpět, aby se přípravek rozprostřel.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Přebytek setřete čistou suchou utěrkou.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Vyzkoušejte chod zipu, ale nepoužívejte nadměrnou sílu.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Doplňkový produkt","type":"text"}]},{"type":"paragraph","content":[{"text":"Pokud zákazník zmíní problém se zipem, můžete přípravek doporučit jako praktický doplněk k oblečení, obuvi nebo tašce. Neslibujte opravu zlomených zoubků, roztržené látky ani poškozeného jezdce.","type":"text"}]}]},"product_bullets":["Zip Service pomáhá hladšímu chodu funkčních kovových i plastových zipů.","Naneste malé množství na zoubky a několikrát posuňte jezdec tam a zpět.","Přebytek setřete čistou suchou utěrkou.","Hodí se na zipy oblečení, obuvi i tašek.","Neopraví zlomené zoubky ani poškozený jezdec."],"key_points_title":"Klíčové body","conversation_title":"Rozhovor se zákazníkem","conversation":[{"text":"Zip na bundě jde ztuha. Pomůže Zip Service?","speaker":"client"},{"text":"Pokud jsou jezdec i zoubky nepoškozené, Zip Service může pomoci s údržbou zipu. Naneste malé množství na zoubky, několikrát posuňte jezdec tam a zpět a přebytek setřete.","speaker":"seller"},{"text":"Kolik mám nanést?","speaker":"client"},{"text":"Malé množství podle pokynů na etiketě. Po rozetření setřete zbytky čistou suchou utěrkou.","speaker":"seller"},{"text":"Jeden zoubek je zlomený. Opraví ho přípravek?","speaker":"client"},{"text":"Ne. Zip Service udržuje funkční zipy, ale neopraví poškozené zoubky ani jezdce.","speaker":"seller"}],"youtube_video_id":null,"youtube_video_ids":[],"image_path":null},{"lesson_id":315,"module_sort_order":4,"sort_order":0,"title":"Kde začít s péčí o motocykl","summary":"Určete typ nečistot a zvolte jednoduchý postup péče o motocykl.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Začněte posouzením","type":"text"}]},{"type":"paragraph","content":[{"text":"Motocykl po jízdě za sucha vyžaduje jiný postup než motocykl po jízdě v dešti nebo blátě. Zeptejte se, o jaké nečistoty jde, jak silné je znečištění a zda má zákazník přístup k vodě, tlakové myčce a garáži. Díky tomu doporučíte jednoduchý postup místo náhodného výběru přípravků.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Rychlé osvěžení","type":"text"}]},{"type":"paragraph","content":[{"text":"Na lehký prach mezi důkladnými mytími může stačit Wash & Ride a čistá měkká mikrovláknová utěrka. Nepoužívejte tento způsob k setření hrubého písku, který může poškrábat lak.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Důkladné mytí","type":"text"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Jako předmytí na zaschlý hmyz zvažte Bug Killer.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Na hlavní mytí použijte Moto Wash nebo připravený roztok Power Powder.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Na usazeniny na kolech zvolte Wheelixir a vhodné příslušenství.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Motocykl opláchněte a osušte podle pokynů k přípravku.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Jako závěrečný krok můžete na čistý a chladný povrch nanést Ceramic Detailer.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Vysvětlete omezení","type":"text"}]},{"type":"paragraph","content":[{"text":"Nenanášejte přípravky na horké části a nenechávejte je na povrchu zaschnout, pokud to pokyny zakazují. Ceramic Detailer nenahrazuje mytí ani profesionální dlouhotrvající ochrannou vrstvu.","type":"text"}]}]},"product_bullets":["Rozpoznejte prach, hmyz, brzdový prach, mastnotu nebo silné bláto.","Zeptejte se na přístup k vodě a podmínky čištění.","Wash & Ride je vhodný na lehký prach mezi důkladnými mytími.","Bug Killer, Moto Wash a Wheelixir slouží pro různé kroky a typy nečistot.","Ceramic Detailer použijte po umytí na čistý a chladný povrch."],"key_points_title":"Klíčové body","conversation_title":"Rozhovor se zákazníkem","conversation":[{"text":"Můj motocykl je jen zaprášený a mám pět minut. Co doporučujete?","speaker":"client"},{"text":"Na lehký prach mezi důkladnými mytími použijte Wash & Ride a čistou mikrovláknovou utěrku. Pokud je na motorce hodně písku nebo bláta, nejprve ji opláchněte a důkladně umyjte.","speaker":"seller"},{"text":"Mohu jedním přípravkem vyčistit hmyz i kola?","speaker":"client"},{"text":"Na hmyz zvolte Bug Killer, na usazeniny na kolech Wheelixir a na mytí celého motocyklu Moto Wash.","speaker":"seller"},{"text":"Mohu začít, když je motor horký?","speaker":"client"},{"text":"Počkejte, až motocykl vychladne. Přípravky nenanášejte na horké součásti.","speaker":"seller"}],"youtube_video_id":null,"youtube_video_ids":[],"image_path":null},{"lesson_id":316,"module_sort_order":4,"sort_order":1,"title":"Wash & Ride: čištění motocyklu","summary":"Ukažte, kdy se Wash & Ride hodí a jak jej bezpečně použít na lehké nečistoty.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Rychlé čištění bez hadice","type":"text"}]},{"type":"paragraph","content":[{"text":"Wash & Ride se hodí, když motocykl potřebuje lehce osvěžit a zákazník nemá přístup k hadici ani kbelíku. Doplňuje pravidelné mytí; nenahrazuje ho při silné vrstvě bláta, písku nebo odolných usazenin.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Jak jej používat","type":"text"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Ujistěte se, že je povrch chladný.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Nastříkejte přípravek na malou plochu podle pokynů na etiketě.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Nečistoty jemně setřete čistou měkkou mikrovláknovou utěrkou; netlačte silou.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Když se utěrka zašpiní, otočte ji na čistou stranu nebo ji vyměňte.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Při silném znečištění přestaňte a naplánujte důkladné mytí.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Pro koho je určený","type":"text"}]},{"type":"paragraph","content":[{"text":"Přípravek se hodí mezi mytími v garáži, na parkovišti i na cestách. Pomáhá osvěžit vzhled a podle výrobce zanechává lehkou ochrannou vrstvu.","type":"text"}]}]},"product_bullets":["Wash & Ride je určený na prach a lehké nečistoty mezi důkladnými mytími.","Používejte jej na chladném povrchu a nečistoty jemně setřete čistou mikrovláknovou utěrkou.","Hodí se v garáži, na parkovišti nebo na cestách.","Nepoužívejte jej k setření silné vrstvy písku nebo bláta.","Při silném znečištění motocykl opláchněte a důkladně umyjte."],"key_points_title":"Klíčové body","conversation_title":"Rozhovor se zákazníkem","conversation":[{"text":"Nemám hadici ani kbelík. Jak mohu motocykl osvěžit?","speaker":"client"},{"text":"Pokud jsou nečistoty lehké, použijte Wash & Ride a čistou měkkou mikrovláknovou utěrku. Pracujte na chladném povrchu a nečistoty setřete bez silného tlaku.","speaker":"seller"},{"text":"Bude fungovat po jízdě v blátě?","speaker":"client"},{"text":"Nepoužívejte jej na silnou vrstvu bláta nebo písku. Nečistoty nejprve opláchněte a motocykl důkladně umyjte.","speaker":"seller"},{"text":"Mohu jej použít na horký motor?","speaker":"client"},{"text":"Ne. Počkejte, až součásti vychladnou, a přípravek použijte podle pokynů na etiketě.","speaker":"seller"}],"youtube_video_id":"aqzUkc7BheU","youtube_video_ids":["aqzUkc7BheU"],"image_path":null},{"lesson_id":317,"module_sort_order":4,"sort_order":2,"title":"Power Powder: příprava a použití","summary":"Vysvětlete, jak připravit roztok Power Powder a jak zvolit správnou variantu pro daný úkol.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Koncentrát před použitím připravte","type":"text"}]},{"type":"paragraph","content":[{"text":"Power Powder je prášek, který se musí rozpustit ve vodě podle pokynů pro konkrétní variantu. Nesypte jej přímo na motocykl a nepředpokládejte, že všechny sáčky se používají stejně.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Vyberte přípravek podle úkolu","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Moto Wash slouží k hlavnímu mytí.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Bug Killer pomáhá jako předmytí odstranit hmyz a organické nečistoty.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Wheelixir je určený na kola a usazeniny v jejich okolí.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Příprava roztoku","type":"text"}]},{"type":"paragraph","content":[{"text":"Láhev Shaker 500 ml pomáhá odměřit vodu a připravit dávku. Přečtěte si dávkování na obalu, rozpusťte prášek ve správném množství vody a roztok používejte podle pokynů výrobce. Přípravky nezaměňujte.","type":"text"}]}]},"product_bullets":["Rozpuštěný Power Powder Moto Wash se používá k hlavnímu mytí motocyklu.","Balení Moto Wash obsahuje tři sáčky; dodržujte pokyny k použití.","Bug Killer a Wheelixir jsou samostatné koncentráty pro různé účely.","Láhev Shaker 500 ml lze použít k přípravě roztoku.","Neuvádějte jeden poměr ředění pro všechny prášky."],"key_points_title":"Klíčové body","conversation_title":"Rozhovor se zákazníkem","conversation":[{"text":"Mohu prášek nasypat přímo na kapotáž?","speaker":"client"},{"text":"Ne. Power Powder nejprve rozpusťte ve vodě podle pokynů na obalu a potom použijte připravený roztok.","speaker":"seller"},{"text":"Ředí se všechny sáčky stejně?","speaker":"client"},{"text":"Ne. Moto Wash, Bug Killer a Wheelixir mají různé použití; dávkování každého ověřte zvlášť.","speaker":"seller"},{"text":"K čemu potřebuji láhev Shaker?","speaker":"client"},{"text":"Usnadní odměření vody a přípravu dávky roztoku, pokud tento postup dovolují pokyny.","speaker":"seller"}],"youtube_video_id":null,"youtube_video_ids":[],"image_path":null},{"lesson_id":318,"module_sort_order":4,"sort_order":3,"title":"Bug Killer a Wheelixir: odstraňování nečistot","summary":"Na organické nečistoty zvolte Bug Killer a na usazeniny na kolech Wheelixir.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Dva různé problémy, dva přípravky","type":"text"}]},{"type":"paragraph","content":[{"text":"Bug Killer slouží k předčištění hmyzu, ptačího trusu a dalších organických nečistot. Wheelixir je určený na usazeniny na kolech a v okolí brzdových třmenů. Ani jeden nenahrazuje mytí celého motocyklu.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Jak je používat","type":"text"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Koncentrát Power Powder připravte podle pokynů na jeho etiketě.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Bug Killer naneste na nečistoty před hlavním mytím.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Vyčkejte po dobu uvedenou v pokynech, potom přípravek opláchněte nebo pokračujte v mytí.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Wheelixir naneste na kolo a v případě potřeby použijte vhodný kartáč.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Kolo a uvolněné nečistoty důkladně opláchněte.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Reagujte na problém zákazníka","type":"text"}]},{"type":"paragraph","content":[{"text":"Pokud je na kapotáži hmyz, doporučte přípravek na organické nečistoty. Na tmavé usazeniny na kole zvolte čistič kol. Ověřte kompatibilitu a pracujte na chladném povrchu.","type":"text"}]}]},"product_bullets":["Bug Killer používejte jako předmytí na hmyz a organické nečistoty.","Na kola a zbytky brzdového prachu zvolte Wheelixir.","Varianty Power Powder předem rozpusťte podle pokynů na etiketě.","Bug Killer nechte působit po dobu uvedenou v pokynech a nenechte jej zaschnout.","Po použití Wheelixir kola důkladně opláchněte; zvolte kartáč vhodný pro daný povrch."],"key_points_title":"Klíčové body","conversation_title":"Rozhovor se zákazníkem","conversation":[{"text":"Na kapotáži mám zaschlý hmyz. Co mám použít?","speaker":"client"},{"text":"Před mytím naneste na nečistoty Bug Killer a nechte jej působit po dobu uvedenou na etiketě. Potom jej opláchněte a motocykl umyjte.","speaker":"seller"},{"text":"A co mám použít na tmavé usazeniny na kole?","speaker":"client"},{"text":"Na usazeniny na kolech použijte Wheelixir. V případě potřeby zvolte vhodný kartáč na kola a po čištění vše důkladně opláchněte.","speaker":"seller"},{"text":"Mohu nasypat Power Powder bez ředění?","speaker":"client"},{"text":"Ne. Prášek nejprve rozpusťte ve vodě v poměru uvedeném na obalu.","speaker":"seller"}],"youtube_video_id":"WsgHV1M274Y","youtube_video_ids":["WsgHV1M274Y"],"image_path":null},{"lesson_id":319,"module_sort_order":4,"sort_order":4,"title":"Ceramic Detailer: dočištění a ochrana","summary":"Představte Ceramic Detailer jako závěrečné dočištění čistého motocyklu.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Závěrečný krok po umytí","type":"text"}]},{"type":"paragraph","content":[{"text":"Ceramic Detailer slouží k závěrečnému dočištění čistého motocyklu. Může zvýraznit lesk a barvu a dodat vodoodpudivý efekt. Nejde o silný čistič nečistot ani o profesionální keramický povlak s několikaletou výdrží.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Ukázka","type":"text"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Pracujte na chladném povrchu mimo přímé slunce.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Nastříkejte malé množství na mikrovláknovou utěrku nebo postupujte podle pokynů na etiketě.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Přípravek nanášejte po menších částech, ne na velkou plochu najednou.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Rozleštěte jej čistou suchou stranou utěrky nebo druhou mikrovláknovou utěrkou.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Zkontrolujte, zda nezůstaly šmouhy, a opakujte pouze podle pokynů.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Nastavte správná očekávání","type":"text"}]},{"type":"paragraph","content":[{"text":"Detailer podporuje běžnou péči a může pomoci omezit ulpívání nečistot. Motocykl je přesto třeba mýt a přípravek nenahrazuje odolnou ochrannou vrstvu ani renovaci laku.","type":"text"}]}]},"product_bullets":["Ceramic Detailer použijte na čistý povrch po umytí nebo lehkém osvěžení.","Při správném použití pomáhá dodat lesk a vodoodpudivý efekt.","Jde o rychlý detailer, nikoli o profesionální keramický povlak s několikaletou výdrží.","Pracujte na chladném povrchu mimo přímé slunce.","Nanáší se mikrovláknovou utěrkou po malých částech a leští suchou stranou."],"key_points_title":"Klíčové body","conversation_title":"Rozhovor se zákazníkem","conversation":[{"text":"Je Ceramic Detailer ochranná vrstva, která vydrží několik let?","speaker":"client"},{"text":"Ne. Jde o rychlý detailer na závěrečné dočištění a běžnou péči, nikoli o odolný profesionální keramický povlak.","speaker":"seller"},{"text":"Mohu jej nanést na špinavý motocykl?","speaker":"client"},{"text":"Motocykl nejprve umyjte a osušte. Detailer nanášejte na čistý a chladný povrch po menších částech.","speaker":"seller"},{"text":"Už po jeho použití nebudu muset motocykl mýt?","speaker":"client"},{"text":"Mytí bude stále potřeba. Detailer pomáhá dočistit povrch, ale mytí nenahrazuje.","speaker":"seller"}],"youtube_video_id":"mofx3RgqndY","youtube_video_ids":["mofx3RgqndY"],"image_path":null},{"lesson_id":320,"module_sort_order":4,"sort_order":5,"title":"Kartáče a mikrovláknové utěrky: výběr příslušenství","summary":"Vyberte pro každý krok mikrovláknovou utěrku a kartáč a zabraňte přenosu nečistot mezi povrchy.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Vyberte příslušenství podle povrchu","type":"text"}]},{"type":"paragraph","content":[{"text":"Ani dobrý přípravek nenahradí správný nástroj. Měkká mikrovláknová utěrka odstraňuje lehké nečistoty a používá se k dočištění. Na kola, řetěz a špatně dostupná místa zvolte samostatné kartáče.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Oddělujte čisté a špinavé plochy","type":"text"}]},{"type":"paragraph","content":[{"text":"Nepřenášejte mastnotu z řetězu na lak, kapotáž ani hledí. Usazeniny z kola mohou také poškrábat choulostivé povrchy. Jakmile se utěrka zašpiní, otočte ji na čistou stranu nebo použijte čistou utěrku.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Výběr příslušenství s omezeným rozpočtem","type":"text"}]},{"type":"paragraph","content":[{"text":"Pokud zákazník začíná od nuly, zeptejte se na jeho hlavní problém. Čistá měkká mikrovláknová utěrka je univerzální pro řadu lehkých úkonů. Další kartáč doporučte jen pro konkrétní místo.","type":"text"}]}]},"product_bullets":["K lehkému čištění a dočištění používejte čisté měkké mikrovláknové utěrky.","Na různé kroky a povrchy používejte samostatné utěrky.","Kartáč na řetěz nepoužívejte na lak ani hledí.","Detailingový kartáč pomáhá dostat se do špatně přístupných míst.","Vyberte kartáč na kola podle povrchu, abyste nepoškrábali lak."],"key_points_title":"Klíčové body","conversation_title":"Rozhovor se zákazníkem","conversation":[{"text":"Stačí mi na celý motocykl jedna mikrovláknová utěrka?","speaker":"client"},{"text":"Na každý krok používejte samostatné čisté mikrovláknové utěrky, aby se nečistoty z kol a pohonu nepřenesly na lak.","speaker":"seller"},{"text":"Mohu zaměňovat detailingový kartáč s kartáčem na řetěz?","speaker":"client"},{"text":"Ne. Kartáč na řetěz je určený pro pohon, detailingový kartáč na špatně dostupné detaily. Kartáč na řetěz nepoužívejte na lak.","speaker":"seller"},{"text":"Kde mám začít, když mám omezený rozpočet?","speaker":"client"},{"text":"Začněte čistou měkkou mikrovláknovou utěrkou. Kartáč přidejte jen pro konkrétní místo, které se špatně čistí.","speaker":"seller"}],"youtube_video_id":"xYSzhwsyZjs","youtube_video_ids":["xYSzhwsyZjs","sqLlcgn_lQA","FvYwpb_PqlA"],"image_path":null},{"lesson_id":321,"module_sort_order":5,"sort_order":0,"title":"Jaké nečistoty vznikají při jízdě v terénu?","summary":"Rozpoznejte nečistoty z jízdy v terénu a zvolte Mud Breaker nebo Dirt Finisher podle jejich závažnosti.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Proč jízda v terénu vyžaduje jiný postup","type":"text"}]},{"type":"paragraph","content":[{"text":"Motocykl se po jízdě v terénu může pokrývat blátem, pískem, prachem a usazeninami z kaluží. Suché částice jsou abrazivní, proto nezačínejte otíráním celého motocyklu mikrovláknovou utěrkou. Nejprve zhodnoťte míru znečištění a připravte se na bezpečné čištění.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Zvolte jeden ze dvou postupů","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Silná vrstva zaschlého bláta: použijte Mud Breaker podle návodu a potom důkladně opláchněte.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Lehký prach po jízdě za sucha: může stačit Dirt Finisher a čistá mikrovláknová utěrka.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Hodně písku: před otíráním jej bezpečně odstraňte.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Na co se zeptat před doporučením","type":"text"}]},{"type":"paragraph","content":[{"text":"Zeptejte se, v jakém terénu zákazník jezdí a zda má přístup k vodě. Mud Breaker se musí opláchnout. Neslibujte, že zabrání budoucímu ulpívání bláta nebo že se motocykl bude čistit sám.","type":"text"}]}]},"product_bullets":["Bláto, písek a prach vyžadují jiný postup než lehké silniční nečistoty.","Neotírejte silnou vrstvu suchého písku, protože částice mohou způsobit škrábance.","Mud Breaker změkčuje silné nečistoty a musí se důkladně opláchnout.","Dirt Finisher pomáhá s lehkým prachem a závěrečným dočištěním.","Zeptejte se, zda je k dispozici voda, a pracujte na chladném povrchu."],"key_points_title":"Klíčové body","conversation_title":"Rozhovor se zákazníkem","conversation":[{"text":"Vrátil jsem se z motokrosu se silnou vrstvou bláta. Mohu motorku hned otřít?","speaker":"client"},{"text":"Silnou vrstvu suchého bláta ani písku neotírejte. Nečistoty změkčete přípravkem Mud Breaker a důkladně je opláchněte.","speaker":"seller"},{"text":"Po jízdě za sucha je na motorce jen prach. Musím ji celou umýt?","speaker":"client"},{"text":"Na lehký prach může stačit Dirt Finisher a čistá mikrovláknová utěrka. Pokud je na motorce hodně písku, nejprve jej bezpečně odstraňte.","speaker":"seller"},{"text":"Po jízdě nemám přístup k vodě.","speaker":"client"},{"text":"Mud Breaker je třeba opláchnout, proto jej použijte tam, kde je voda k dispozici. Zvolte postup, který odpovídá nečistotám a podmínkám.","speaker":"seller"}],"youtube_video_id":null,"youtube_video_ids":[],"image_path":null},{"lesson_id":322,"module_sort_order":5,"sort_order":1,"title":"Mud Breaker: odstraňování bláta","summary":"Naučte se bezpečně používat Mud Breaker na silné znečištění blátem a správně oplachovat nečistoty.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Přípravek na silné znečištění","type":"text"}]},{"type":"paragraph","content":[{"text":"Mud Breaker pomáhá změkčit bláto, písek a minerální nečistoty po jízdě v terénu. Vysvětlete, že připraví nečistoty k opláchnutí; nejde o čištění bez vody.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Jak jej používat","type":"text"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Počkejte, až motocykl vychladne.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Zhodnoťte množství bláta a připravte vodu na oplach.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Na znečištěné součásti naneste přípravek podle pokynů na etiketě.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Nechte jej působit po uvedenou dobu, ale nenechte jej zaschnout.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Nečistoty i přípravek důkladně opláchněte vodou.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Kartáče a následná péče","type":"text"}]},{"type":"paragraph","content":[{"text":"Vhodný kartáč pomůže vyčistit špatně dostupná místa, ale používejte jej šetrně a nedrhněte nasucho. Po opláchnutí se zákazník může rozhodnout, zda potřebuje Dirt Finisher k závěrečnému dočištění.","type":"text"}]}]},"product_bullets":["Mud Breaker je určený na silné znečištění blátem a minerální nečistoty.","Před použitím nechte motocykl vychladnout a připravte vodu na oplach.","Použijte jej na znečištěný povrch podle pokynů na etiketě.","Nenechte přípravek zaschnout; v případě potřeby jemně použijte kartáč.","Po působení přípravku vozidlo důkladně opláchněte."],"key_points_title":"Klíčové body","conversation_title":"Rozhovor se zákazníkem","conversation":[{"text":"Odstraní Mud Breaker zaschlé bláto z kyvné vidlice?","speaker":"client"},{"text":"Ano, bláto změkčí, takže se snáze opláchne. Nastříkejte jej na znečištěný povrch, krátce počkejte a důkladně opláchněte; u silných nánosů v případě potřeby jemně použijte kartáč.","speaker":"seller"},{"text":"Nemám hadici. Mám ho použít na parkovišti?","speaker":"client"},{"text":"Pouze pokud jej můžete opláchnout. Mud Breaker používejte tam, kde je k dispozici voda, protože po působení je třeba vozidlo důkladně opláchnout.","speaker":"seller"},{"text":"Mohu nechat přípravek zaschnout?","speaker":"client"},{"text":"Ne. Opláchněte jej dříve, než zaschne, a nenanášejte jej na horké součásti.","speaker":"seller"}],"youtube_video_id":null,"youtube_video_ids":[],"image_path":null},{"lesson_id":323,"module_sort_order":5,"sort_order":2,"title":"Dirt Finisher: závěrečné dočištění a péče","summary":"Vysvětlete, jak se Dirt Finisher používá na lehké nečistoty a jako krok po důkladnějším mytí.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Šetrnější péče o terénní motocykly","type":"text"}]},{"type":"paragraph","content":[{"text":"Dirt Finisher není jinou verzí Mud Breaker. Pomáhá s lehkými nečistotami a dočištěním čistšího povrchu. U silného bláta slouží až jako následný krok, poté co nečistoty změkčíte a opláchnete.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Jak jej používat","type":"text"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Ověřte, že je povrch chladný a bez silné vrstvy písku.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Láhev protřepejte podle pokynů.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Nastříkejte malé množství na vybranou plochu.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Lehké nečistoty jemně setřete čistou mikrovláknovou utěrkou.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Jakmile utěrka zachytí písek nebo bláto, vyměňte ji.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Přizpůsobte postup míře znečištění","type":"text"}]},{"type":"paragraph","content":[{"text":"Dirt Finisher může sám stačit na lehký prach po jízdě po šotolině. U silné vrstvy jílu nejprve použijte Mud Breaker a opláchněte. Závěrečný krok může usnadnit následnou péči, ale neodstraní nečistoty navždy.","type":"text"}]}]},"product_bullets":["Dirt Finisher je určený na lehké čištění a dočištění.","U silného bláta nejprve použijte Mud Breaker a vše důkladně opláchněte.","Před použitím odstraňte hrubý písek a ověřte, že je povrch chladný.","Láhev protřepejte a pracujte po menších částech.","Nečistoty setřete čistou mikrovláknovou utěrkou; jakmile se silně zašpiní, vyměňte ji."],"key_points_title":"Klíčové body","conversation_title":"Rozhovor se zákazníkem","conversation":[{"text":"Musím koupit Mud Breaker a Dirt Finisher společně?","speaker":"client"},{"text":"Ne. Na lehký prach stačí Dirt Finisher. Na silné bláto nejprve použijte Mud Breaker a opláchněte; závěrečný přípravek přidejte jen v případě potřeby.","speaker":"seller"},{"text":"Zvládne Dirt Finisher silnou vrstvu jílu?","speaker":"client"},{"text":"Ne. Nejprve bláto změkčete přípravkem Mud Breaker a opláchněte. Dirt Finisher slouží k lehčímu čištění a dočištění.","speaker":"seller"},{"text":"Mohu jím setřít velké množství písku?","speaker":"client"},{"text":"Nejprve odstraňte hrubý písek. Neotírejte částice do povrchu mikrovláknovou utěrkou, mohly by jej poškrábat.","speaker":"seller"}],"youtube_video_id":null,"youtube_video_ids":[],"image_path":null},{"lesson_id":324,"module_sort_order":5,"sort_order":3,"title":"Jak vybrat Off-Road Kit","summary":"Vyberte sadu péče pro terénní jízdu podle stylu jízdy, množství nečistot a dostupnosti vody.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Zeptejte se, co zákazník myslí „sadou“","type":"text"}]},{"type":"paragraph","content":[{"text":"Zákazník může mít na mysli hotové balení nebo sestavu přípravků na péči. Zeptejte se, na čem jezdí, s jakými nečistotami se nejčastěji setkává a zda má po jízdě přístup k vodě. Než ověříte konkrétní produkt, představte řešení jako dvoufázový systém.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Přizpůsobte doporučení jezdci","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Motokros na blátivé trati: Mud Breaker, oplach a podle potřeby Dirt Finisher.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Enduro na suché šotolině: na lehký prach Dirt Finisher.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Čtyřkolka nebo horské kolo v silném blátě: vyberte přípravek a zkontrolujte pokyny k péči o vozidlo.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Bez přístupu k vodě: naplánujte čištění na místě, kde lze vozidlo řádně opláchnout.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Příslušenství a výběr nezbytných věcí","type":"text"}]},{"type":"paragraph","content":[{"text":"Čistá měkká mikrovláknová utěrka se hodí k dočištění a vhodný kartáč pomůže v úzkých místech. Nepřidávejte přípravky bez potřeby. Nejprve doporučte to nezbytné k vyřešení problému a další krok nabídněte jako volitelný.","type":"text"}]}]},"product_bullets":["Zjistěte, zda zákazník jezdí motokros, enduro, na čtyřkolce, nebo na horském kole.","Na silné bláto doporučte Mud Breaker a možnost opláchnutí vodou.","Na lehký prach může zákazník začít s Dirt Finisher.","Další mikrovláknovou utěrku nebo kartáč doporučte jen tehdy, pokud pro ně existuje konkrétní důvod.","Off-Road Kit nepředstavujte jako konkrétní hotový balíček, pokud jste si existenci produktu neověřili."],"key_points_title":"Klíčové body","conversation_title":"Rozhovor se zákazníkem","conversation":[{"text":"Chci jednu enduro sadu a nechci pět různých tekutin. Co je nezbytné?","speaker":"client"},{"text":"Pokud nejčastěji řešíte silné bláto a máte vodu na oplach, začněte s Mud Breaker. Dirt Finisher přidejte jen tehdy, pokud chcete také dočistit čistý povrch.","speaker":"seller"},{"text":"Jezdím hlavně po suché šotolině. Potřebuji oba přípravky?","speaker":"client"},{"text":"Ne. Na lehký prach začněte s Dirt Finisher a čistou mikrovláknovou utěrkou.","speaker":"seller"},{"text":"Je Off-Road Kit hotová sada v krabici?","speaker":"client"},{"text":"Podívejme se, jaká prodejní varianta je právě dostupná. Pokud myslíte sadu přípravků na péči, mohu doporučit Mud Breaker a Dirt Finisher jako dva samostatné kroky.","speaker":"seller"}],"youtube_video_id":null,"youtube_video_ids":[],"image_path":null},{"lesson_id":325,"module_sort_order":6,"sort_order":0,"title":"Jak rozpoznat potřeby zákazníka","summary":"Ptejte se tak, abyste zjistili potřeby zákazníka a mohli mu doporučit jednoduché řešení.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Prodej začíná nasloucháním","type":"text"}]},{"type":"paragraph","content":[{"text":"Zákazník může popsat problém, aniž by znal názvy produktů: „Hledám něco na helmu“ nebo „bunda nepříjemně zapáchá.“ Vaším úkolem je upřesnit, co potřebuje, ne hned vyjmenovávat dostupné přípravky.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Pět užitečných otázek","type":"text"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Co chcete vyčistit nebo ochránit?","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Co je hlavní problém: hmyz, prach, bláto, pot, nebo potřeba ošetření?","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Z jakého materiálu je oděv nebo povrch?","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Kde budete přípravek používat a budete mít přístup k vodě?","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Jde o jednorázovou potřebu, nebo o pravidelnou péči?","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Od odpovědí k doporučení","type":"text"}]},{"type":"paragraph","content":[{"text":"Nemusíte položit všechny otázky. Vyberte ty, které ovlivní vhodný přípravek. Vlastními slovy zopakujte problém, doporučte jedno řešení, vysvětlete jeho použití a zmiňte důležité omezení. Doplněk navrhněte jen tehdy, když vyřeší konkrétní chybějící krok.","type":"text"}]}]},"product_bullets":["Zeptejte se, co chce zákazník vyčistit nebo ochránit.","Určete konkrétní problém: hmyz, prach, bláto, zápach, nebo potřebu ošetření.","Ověřte materiál, podmínky použití a četnost péče.","Před doporučením přípravku shrňte problém vlastními slovy.","Představte jedno nebo dvě vhodná řešení a vysvětlete jejich použití."],"key_points_title":"Klíčové body","conversation_title":"Rozhovor se zákazníkem","conversation":[{"text":"Potřebuji dobrý čisticí přípravek. Co doporučíte?","speaker":"client"},{"text":"Nejprve zjistíme, co chcete čistit: helmu, oblečení, nebo motocykl. Jaký problém řešíte – hmyz, nečistoty, zápach, nebo péči o materiál?","speaker":"seller"},{"text":"Jde o hledí helmy a zaschlý hmyz.","speaker":"client"},{"text":"V tom případě začněte přípravkem Helmet Gel, který hmyz změkčí. Potom můžete čisté hledí dočistit přípravkem Helmet Detailer.","speaker":"seller"},{"text":"Zákazník se hned ptá jen na cenu. Co mám říct?","speaker":"client"},{"text":"Pokud cenu znáte, sdělte ji a pak se krátce zeptejte, k čemu produkt potřebuje. Pomůže vám to najít vhodnou možnost, aniž byste vnucovali zbytečný přípravek.","speaker":"seller"}],"youtube_video_id":null,"youtube_video_ids":[],"image_path":null},{"lesson_id":326,"module_sort_order":6,"sort_order":1,"title":"Jak doporučovat sady místo jednotlivých produktů","summary":"Ukažte hodnotu sady vysvětlením jednotlivých kroků péče a zvolte velikost podle způsobu použití.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Vysvětlete postup, ne pouze cenu","type":"text"}]},{"type":"paragraph","content":[{"text":"Sada dává smysl, když zákazník chápe, jaké kroky pokrývá. U koženého oblečení může jít o čištění, ošetření a osvěžení vnitřku. U helem zvažte čištění vnějších povrchů a velikost, která se hodí doma nebo na cestách.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Vyberte sadu podle situace","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Leather Care Kit zvažte pro zákazníka, který potřebuje několik kroků péče o kůži.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Trip Kit se hodí na cesty.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"GIGA může být praktická na pravidelnou péči doma nebo o více helem.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Pokud už zákazník nějaké příslušenství má, doporučte pouze chybějící přípravek.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Ověřte, co zákazník potřebuje","type":"text"}]},{"type":"paragraph","content":[{"text":"Sada není vždy nejlepší volba. Zeptejte se, co už zákazník vlastní, jak často o vybavení pečuje a kde bude přípravky používat. Hodnota sady spočívá v praktičnosti a vhodnosti, ne pouze v počtu položek.","type":"text"}]}]},"product_bullets":["Vysvětlete postup: čištění, ošetření nebo dočištění a případně také péči o vnitřek.","Leather Care Kit může spojit péči o vnější kůži s osvěžením vnitřku.","Trip Kit se hodí na cesty; GIGA na pravidelnou péči o helmu.","Zákazník, který už některé přípravky vlastní, si může koupit pouze to, co mu chybí.","Na závěr se zeptejte, jak a jak často bude přípravky používat."],"key_points_title":"Klíčové body","conversation_title":"Rozhovor se zákazníkem","conversation":[{"text":"Proč potřebuji sadu, když mi stačí jeden přípravek?","speaker":"client"},{"text":"Pokud už máte ostatní přípravky a příslušenství, kupte si pouze to, co vám chybí. Sada dává smysl, pokud chcete doplnit všechny kroky péče.","speaker":"seller"},{"text":"Potřebuji něco na helmu na cesty. Co mám vybrat?","speaker":"client"},{"text":"Zvolte Trip Kit – má kompaktní lahvičky, které se snadno vezou. Pro pravidelné čištění doma jej porovnejte s GIGA.","speaker":"seller"},{"text":"Je větší sada účinnější?","speaker":"client"},{"text":"Ne, sady se liší velikostí a obsahem. Vyberte podle toho, jak často čistíte a kolik máte helem.","speaker":"seller"}],"youtube_video_id":null,"youtube_video_ids":[],"image_path":null},{"lesson_id":327,"module_sort_order":6,"sort_order":2,"title":"Jak zvýšit prodej doplňkovými produkty","summary":"Doporučte nejvýše jeden vhodný doplňkový přípravek, který podpoří postup péče, který zákazník už začíná.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Smysluplný doplňkový prodej","type":"text"}]},{"type":"paragraph","content":[{"text":"Doplněk má hodnotu, když dokončuje další krok postupu. Zákazník, který kupuje čistič, může potřebovat také přípravek na následné ošetření nebo vhodnou utěrku. Pokud danou věc už má, není důvod ji doporučovat znovu.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Přirozené kombinace produktů","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Helmet Gel → Helmet Detailer a vhodná utěrka.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Leather Cleaner → Leather Milk po vyčištění a vyschnutí kůže.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Textile Care → Fabric Protect jako přísada pro svěžest, nikoli jako impregnace.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Moto Wash nebo Bug Killer → Ceramic Detailer po umytí a opláchnutí.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Mud Breaker → Dirt Finisher po důkladném umytí, pokud zákazník chce ještě dočišťovací krok.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Doporučujte bez nátlaku","type":"text"}]},{"type":"paragraph","content":[{"text":"Zeptejte se, který krok chybí, a nabídněte nejvýše jeden vhodný doplněk. Například: „Čistič odstraní nečistoty z kůže. Pokud nemáte přípravek na její ošetření po čištění, mohu vám ukázat Leather Milk.“ Když zákazník odmítne, respektujte jeho rozhodnutí.","type":"text"}]}]},"product_bullets":["Doplněk má podpořit další krok péče, ne jen zvýšit hodnotu nákupu.","Helmet Gel lze kombinovat s Detailerem a vhodnou utěrkou.","Leather Milk doplňuje Leather Cleaner poté, co kůže uschne.","Textile Care lze při praní doplnit přípravkem Fabric Protect.","Respektujte odmítnutí a nedoporučujte přípravek, který zdvojuje to, co už zákazník má."],"key_points_title":"Klíčové body","conversation_title":"Rozhovor se zákazníkem","conversation":[{"text":"Proč doporučujete druhý přípravek?","speaker":"client"},{"text":"Doplněk dává smysl, když doplňuje potřebný krok: například Leather Milk ošetřuje kůži po čištění. Pokud jej už máte, další kupovat nemusíte.","speaker":"seller"},{"text":"Ne, děkuji. Tento přípravek už mám.","speaker":"client"},{"text":"Samozřejmě. Zůstaneme u toho, co skutečně potřebujete.","speaker":"seller"},{"text":"Co mám přidat k Leather Cleaner, když nemám kondicionér na kůži?","speaker":"client"},{"text":"Po vyčištění a vyschnutí kůže můžete jako samostatný krok použít Leather Milk.","speaker":"seller"}],"youtube_video_id":null,"youtube_video_ids":[],"image_path":null},{"lesson_id":328,"module_sort_order":6,"sort_order":3,"title":"Jak reagovat na běžné námitky zákazníků","summary":"Reagujte na námitky tím, že zjistíte, čeho se zákazník obává, sdělíte relevantní fakt a necháte rozhodnutí na něm.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Námitka přináší informace","type":"text"}]},{"type":"paragraph","content":[{"text":"„Je to příliš drahé“, „Už mám něco podobného“ nebo „Je to bezpečné?“ jsou signály, že zákazník potřebuje upřesnění. Nejprve uznejte jeho obavu, položte krátkou otázku, odpovězte věcně a ponechte mu možnost volby.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Čtyři běžné situace","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Cena: zeptejte se, zda se bude přípravek používat občas, nebo pravidelně, a poté vyberte vhodnou velikost.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Běžný prací prostředek: porovnejte jeho určení s materiálem a štítkem oděvu.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Bezpečnost: zkontrolujte povrch, úpravu a pokyny; u kůže přípravek nejprve vyzkoušejte.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Účinnost: vysvětlete konkrétní funkci a omezení přípravku.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Odpověď ve třech větách","type":"text"}]},{"type":"paragraph","content":[{"text":"Stručná odpověď může uznat obavu, uvést konkrétní skutečnost a navrhnout další krok. Nestrašte zákazníka možným poškozením, neslibujte, že přípravek funguje „na všechno“, a nevymýšlejte podmínky vrácení. Pokud odpověď neznáte, před doporučením si ji ověřte.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Procvičení","type":"text"}]},{"type":"paragraph","content":[{"text":"Ve dvojicích si procvičte reakce na námitky: „Je to příliš drahé“, „Už mám běžný prací prostředek“, „Je to bezpečné?“ a „Bude to fungovat?“ Vyměňte si role a ověřte, že odpověď respektuje určený způsob použití přípravku.","type":"text"}]}]},"product_bullets":["Nejprve uznejte obavu a položte upřesňující otázku.","Při rozhovoru o ceně vyberte velikost a obsah podle četnosti použití.","Kvůli bezpečnosti zkontrolujte povrch, štítek s pokyny k péči a doporučení výrobce.","Vysvětlete, k čemu je přípravek určený, místo širokých slibů.","Nevymýšlejte si podmínky vrácení, opravy ani výsledky, které nemáte ověřené."],"key_points_title":"Klíčové body","conversation_title":"Rozhovor se zákazníkem","conversation":[{"text":"To je na mě příliš drahé.","speaker":"client"},{"text":"Rozumím. Pokud budete přípravek používat jen občas, podívejme se na menší balení nebo kupte jen to, co potřebujete pro tento krok.","speaker":"seller"},{"text":"Je tento přípravek bezpečný pro každý materiál?","speaker":"client"},{"text":"Jeden přípravek není vhodný na všechno. Řekněte mi, na jaký materiál jej potřebujete, a vyberu přípravek i postup podle štítku s pokyny k péči.","speaker":"seller"},{"text":"Na internetu jsem jej viděl levněji.","speaker":"client"},{"text":"Porovnejme velikost, variantu a obsah sady. Pokud jde o stejný produkt, můžete si vybrat nabídku, která vám vyhovuje více.","speaker":"seller"}],"youtube_video_id":null,"youtube_video_ids":[],"image_path":null},{"lesson_id":329,"module_sort_order":6,"sort_order":4,"title":"Prodejní scénky","summary":"Procvičte si celý prodejní rozhovor od zjištění potřeby až po výběr vhodného řešení.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Situace: helma po jízdě","type":"text"}]},{"type":"paragraph","content":[{"text":"Zákazník si koupil svou první helmu a na hledí má zaschlý hmyz. Zeptejte se, zda ji čistí doma, nebo na cestách. Vysvětlete, jak nečistoty změkčit a potom dočistit čistý povrch. Pokud se zeptá na Pinlock, odlište vložku od vnějšího hledí a dodržujte pokyny výrobce.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Situace: kombinéza po sezoně","type":"text"}]},{"type":"paragraph","content":[{"text":"Zákazník má znečištěnou koženou kombinézu a zápach uvnitř. Oddělte čištění vnější strany, její ošetření po vyschnutí a osvěžení vnitřku. Pokud už čistič vlastní, doporučte pouze chybějící krok. Oděrku v materiálu přenechte opravně.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Situace: enduro motocykl po jízdě v blátě","type":"text"}]},{"type":"paragraph","content":[{"text":"Zákazník se vrací z náročné jízdy v terénu a má přístup k vodě. Doporučte Mud Breaker a důkladné opláchnutí; Dirt Finisher nabídněte jako volitelný krok dočištění. Nedoporučujte otírání suchého písku ani nanášení přípravků na horké součásti.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Shrnutí rozhovoru","type":"text"}]},{"type":"paragraph","content":[{"text":"V každé situaci zjistěte potřebu, doporučte vhodný přípravek a vysvětlete jeho použití i omezení. Rozhodnutí ponechte na zákazníkovi; pokud další přípravek není potřeba, uzavřete rozhovor základním řešením.","type":"text"}]}]},"product_bullets":["Než přípravek nabídnete, zeptejte se, jak bude používán.","Vyberte přípravek pro konkrétní problém a materiál.","Vysvětlete pořadí použití a jednu důležitou bezpečnostní podmínku.","Doplněk doporučte jen tehdy, pokud pokrývá potřebný krok.","Pokud je něco poškozené nebo si nejste jisti, ověřte pokyny nebo zákazníka odkažte na opravnu."],"key_points_title":"Klíčové body","conversation_title":"Rozhovor se zákazníkem","conversation":[{"text":"Koupil jsem si drahou helmu. Na hledí mám zaschlý hmyz a chci jeden přípravek.","speaker":"client"},{"text":"Začněte přípravkem Helmet Gel, který hmyz změkčí, a potom jej jemně setřete mikrovláknovou utěrkou. Pokud chcete, čisté hledí dočistěte přípravkem Helmet Detailer.","speaker":"seller"},{"text":"Mohu Pinlock čistit stejným přípravkem?","speaker":"client"},{"text":"Ne. Přípravky na vnější hledí používejte pouze zvenku; vložku šetrně očistěte podle pokynů výrobce helmy.","speaker":"seller"},{"text":"Mám bundu s membránou. Udělá Fabric Protect bundu voděodolnou?","speaker":"client"},{"text":"Ne. Fabric Protect se přidává do praní, aby pomáhal udržovat svěžest. Zvolte samostatnou impregnaci vhodnou pro danou bundu.","speaker":"seller"},{"text":"Vrátil jsem se z endura v silném blátě, ale chci jen jeden přípravek.","speaker":"client"},{"text":"V tom případě začněte přípravkem Mud Breaker a důkladně jej opláchněte. Dirt Finisher můžete přidat později, pokud chcete čistý povrch dočistit.","speaker":"seller"}],"youtube_video_id":null,"youtube_video_ids":[],"image_path":null}]$cs_lessons$::jsonb) AS translated(
  module_sort_order integer, sort_order integer, title text, summary text, content jsonb,
  product_bullets jsonb, key_points_title text, conversation_title text, conversation jsonb
)
WHERE course.slug = 'pielegnacja-i-sprzedaz-produktow-xzone' AND version.version_number = 9 AND version.status = 'published'
  AND module.sort_order = translated.module_sort_order
  AND lesson.sort_order = translated.sort_order
  AND 'cs' = 'cs'
ON CONFLICT (lesson_id, language_code) DO UPDATE SET
  title = EXCLUDED.title,
  summary = EXCLUDED.summary,
  content = EXCLUDED.content,
  product_bullets = EXCLUDED.product_bullets,
  key_points_title = EXCLUDED.key_points_title,
  conversation_title = EXCLUDED.conversation_title,
  conversation = EXCLUDED.conversation,
  youtube_video_id = COALESCE(lesson_translations.youtube_video_id, EXCLUDED.youtube_video_id),
  youtube_video_ids = CASE WHEN cardinality(lesson_translations.youtube_video_ids) > 0 THEN lesson_translations.youtube_video_ids ELSE EXCLUDED.youtube_video_ids END,
  image_path = COALESCE(lesson_translations.image_path, EXCLUDED.image_path),
  updated_at = now();

-- fr: course, module, and lesson text
INSERT INTO public.course_translations (course_version_id, language_code, title, description, image_path)
SELECT version.id,
       'fr', translated.title, COALESCE(translated.description, ''), source.image_path
FROM public.courses AS course
JOIN public.course_versions AS version ON version.id = course.published_version_id
JOIN public.course_translations AS source ON source.course_version_id = version.id AND source.language_code = 'pl'
CROSS JOIN LATERAL jsonb_to_record($fr_course${"course_id":3,"slug":"pielegnacja-i-sprzedaz-produktow-xzone","course_version_id":13,"language_code":"fr","title":"Entretien et vente des produits Xzone","description":"","image_path":null}$fr_course$::jsonb) AS translated(title text, description text)
WHERE course.slug = 'pielegnacja-i-sprzedaz-produktow-xzone' AND version.version_number = 9 AND version.status = 'published'
  AND translated.title IS NOT NULL AND 'fr' = 'fr'
ON CONFLICT (course_version_id, language_code) DO UPDATE SET
  title = EXCLUDED.title,
  description = EXCLUDED.description,
  image_path = COALESCE(course_translations.image_path, EXCLUDED.image_path),
  updated_at = now();

INSERT INTO public.module_translations (module_id, language_code, title, summary, image_path)
SELECT module.id,
       'fr', translated.title, COALESCE(translated.summary, ''), source.image_path
FROM public.courses AS course
JOIN public.course_versions AS version ON version.id = course.published_version_id
JOIN public.course_modules AS module ON module.course_version_id = version.id
JOIN public.module_translations AS source ON source.module_id = module.id AND source.language_code = 'pl'
CROSS JOIN LATERAL jsonb_to_recordset($fr_modules$[{"module_id":61,"module_sort_order":0,"title":"Entretien des casques","summary":"","image_path":null},{"module_id":62,"module_sort_order":1,"title":"Entretien des vêtements en cuir","summary":"","image_path":null},{"module_id":63,"module_sort_order":2,"title":"Entretien des vêtements textiles","summary":"","image_path":null},{"module_id":64,"module_sort_order":3,"title":"Gants et accessoires","summary":"","image_path":null},{"module_id":65,"module_sort_order":4,"title":"Entretien et detailing de la moto","summary":"","image_path":null},{"module_id":66,"module_sort_order":5,"title":"Entretien des motos tout-terrain","summary":"","image_path":null},{"module_id":67,"module_sort_order":6,"title":"Vendre efficacement les produits Xzone","summary":"","image_path":null}]$fr_modules$::jsonb) AS translated(module_sort_order integer, title text, summary text)
WHERE course.slug = 'pielegnacja-i-sprzedaz-produktow-xzone' AND version.version_number = 9 AND version.status = 'published'
  AND module.sort_order = translated.module_sort_order
  AND 'fr' = 'fr'
ON CONFLICT (module_id, language_code) DO UPDATE SET
  title = EXCLUDED.title,
  summary = EXCLUDED.summary,
  image_path = COALESCE(module_translations.image_path, EXCLUDED.image_path),
  updated_at = now();

INSERT INTO public.lesson_translations (
  lesson_id, language_code, title, summary, youtube_video_id, content, product_bullets,
  key_points_title, conversation_title, conversation, youtube_video_ids, image_path
)
SELECT lesson.id,
       'fr', translated.title, COALESCE(translated.summary, ''), source.youtube_video_id,
       translated.content, COALESCE(translated.product_bullets, '[]'::jsonb),
       translated.key_points_title, translated.conversation_title,
       COALESCE(translated.conversation, '[]'::jsonb), source.youtube_video_ids, source.image_path
FROM public.courses AS course
JOIN public.course_versions AS version ON version.id = course.published_version_id
JOIN public.course_modules AS module ON module.course_version_id = version.id
JOIN public.course_lessons AS lesson ON lesson.module_id = module.id
JOIN public.lesson_translations AS source ON source.lesson_id = lesson.id AND source.language_code = 'pl'
CROSS JOIN LATERAL jsonb_to_recordset($fr_lessons$[{"lesson_id":294,"module_sort_order":0,"sort_order":0,"title":"Pourquoi un casque a-t-il besoin d’un entretien adapté ?","summary":"Repérez les trois zones du casque et choisissez la méthode d’entretien adaptée à chacune.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Pourquoi un casque nécessite un entretien attentif","type":"text"}]},{"type":"paragraph","content":[{"text":"En roulant, des insectes, de la poussière de la route et de la pluie se déposent sur le casque, tandis que l’intérieur est exposé à la transpiration et à l’humidité. Les salissures sur l’extérieur de l’écran peuvent réduire la visibilité, et une doublure négligée peut nuire au confort. Commencez par demander au client quelle partie du casque nécessite un entretien.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Trois zones, trois méthodes d’entretien","type":"text"}]},{"type":"heading","attrs":{"level":3},"content":[{"text":"Coque et face extérieure de l’écran","type":"text"}]},{"type":"paragraph","content":[{"text":"Pour les insectes séchés, ne commencez pas par frotter à sec. Helmet Gel ramollit les salissures afin de pouvoir les retirer en douceur. Utilisez ensuite Helmet Detailer pour la finition d’une surface déjà propre.","type":"text"}]},{"type":"heading","attrs":{"level":3},"content":[{"text":"Doublure intérieure","type":"text"}]},{"type":"paragraph","content":[{"text":"Un désodorisant aide à garder la doublure fraîche entre deux lavages, mais il n’élimine pas les salissures comme un lavage. Avant de laver la doublure, vérifiez si elle est amovible et suivez les instructions d’entretien du casque.","type":"text"}]},{"type":"heading","attrs":{"level":3},"content":[{"text":"Pinlock","type":"text"}]},{"type":"paragraph","content":[{"text":"La lentille Pinlock est fragile et doit être entretenue séparément. N’y appliquez ni gel ni detailer et ne la frottez pas. Rincez-la à l’eau distillée et laissez-la sécher à l’air libre, conformément aux recommandations du fabricant du casque.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Comment amorcer la discussion","type":"text"}]},{"type":"paragraph","content":[{"text":"Demandez au client s’il souhaite entretenir l’écran et la coque, l’intérieur du casque ou les deux. Recommandez ensuite un produit adapté. Ne partez pas du principe que tout le monde a besoin d’un kit complet ou d’un entretien quotidien.","type":"text"}]}]},"product_bullets":["Traitez séparément la coque, la face extérieure de l’écran et la doublure : chaque zone nécessite une méthode différente.","Ramollissez d’abord les insectes séchés avec Helmet Gel ; ne les frottez pas à sec.","Utilisez Helmet Detailer pour parfaire une surface propre.","Un désodorisant pour l’intérieur ne remplace pas le lavage d’une doublure sale.","Entretenez la lentille Pinlock séparément et suivez les instructions du fabricant du casque."],"key_points_title":"À retenir","conversation_title":"Échange avec le client","conversation":[{"text":"Je viens d’acheter un casque neuf. Dois-je tout de suite acheter le kit d’entretien complet ?","speaker":"client"},{"text":"Non. Si vous souhaitez entretenir l’écran et la coque dès maintenant, choisissez des produits pour les surfaces extérieures. Un produit pour l’intérieur ne sera utile que lorsque la doublure aura besoin d’être rafraîchie ou lavée.","speaker":"seller"},{"text":"Puis-je utiliser un seul produit liquide pour nettoyer l’écran et l’intérieur ?","speaker":"client"},{"text":"Mieux vaut procéder en deux étapes distinctes. Utilisez un produit conçu pour les écrans sur la face extérieure, et nettoyez la doublure avec un produit séparé, conformément aux instructions du casque.","speaker":"seller"},{"text":"Pour l’instant, je n’ai que des insectes sur l’écran.","speaker":"client"},{"text":"Dans ce cas, commencez avec Helmet Gel et un chiffon microfibre propre. Vous pouvez ajouter le Detailer si vous souhaitez aussi parfaire l’écran une fois propre.","speaker":"seller"}],"youtube_video_id":null,"youtube_video_ids":[],"image_path":null},{"lesson_id":295,"module_sort_order":0,"sort_order":1,"title":"Helmet Gel et Helmet Detailer : différences et utilisation","summary":"Apprenez dans quel ordre utiliser Helmet Gel et Helmet Detailer, puis choisissez le chiffon et le format adaptés aux besoins du client.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Deux produits, deux fonctions différentes","type":"text"}]},{"type":"paragraph","content":[{"text":"Helmet Gel et Helmet Detailer sont complémentaires, mais ne se remplacent pas. Le gel prépare la surface sale ; le Detailer s’utilise après le nettoyage.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Étape 1 : ramollir les salissures","type":"text"}]},{"type":"paragraph","content":[{"text":"Appliquez Helmet Gel sur la zone sale et laissez agir pendant la durée indiquée sur l’étiquette. Le format voyage recommande environ cinq minutes ; réduisez ce délai en plein soleil. Ne laissez pas le produit sécher. Une fois les salissures ramollies, essuyez-les sans appuyer avec un chiffon microfibre propre.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Étape 2 : parfaire la surface propre","type":"text"}]},{"type":"paragraph","content":[{"text":"N’utilisez Helmet Detailer qu’après avoir éliminé les salissures. Un chiffon microfibre épais convient pour retirer la saleté décollée ; utilisez un chiffon Evolon pour la finition. Commencez toujours avec des accessoires propres.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Choisissez le format adapté à l’utilisation","type":"text"}]},{"type":"paragraph","content":[{"text":"Le format 30 ml est facile à emporter en voyage. Le flacon de 250 ml est pratique pour un nettoyage régulier du casque. Demandez au client où et à quelle fréquence il compte utiliser les produits.","type":"text"}]}]},"product_bullets":["Helmet Gel est la première étape : il ramollit les insectes et les salissures séchés pour permettre de les retirer en douceur.","Après application, respectez le temps indiqué ; le format voyage recommande environ 5 minutes. Réduisez le temps de pose en plein soleil.","Helmet Detailer est la deuxième étape : appliquez-le sur une surface propre pour obtenir une finition uniforme et limiter les traces.","Retirez les salissures décollées avec un chiffon microfibre épais et propre ; utilisez Evolon pour la finition.","Les produits existent en format voyage de 30 ml et en grand format de 250 ml. Choisissez en fonction de la fréquence d’utilisation."],"key_points_title":"À retenir","conversation_title":"Échange avec le client","conversation":[{"text":"Le Detailer seul suffit-il pour les insectes séchés ?","speaker":"client"},{"text":"Pour les insectes séchés, commencez par Helmet Gel : ramollissez les salissures, retirez-les délicatement avec un chiffon microfibre, puis appliquez le Detailer sur l’écran propre.","speaker":"seller"},{"text":"J’ai un casque mat. Le Detailer va-t-il le faire briller ?","speaker":"client"},{"text":"Oui, il peut être utilisé sur un casque mat : la finition reste mate. Appliquez le produit sur un chiffon microfibre propre et suivez les instructions du casque.","speaker":"seller"},{"text":"Combien de temps dois-je attendre après avoir appliqué le gel ?","speaker":"client"},{"text":"Respectez le délai indiqué sur l’étiquette ; le format voyage recommande environ 5 minutes. Ne laissez pas le produit sécher et réduisez le temps de pose en plein soleil.","speaker":"seller"},{"text":"Puis-je utiliser de l’essuie-tout ?","speaker":"client"},{"text":"Utilisez un chiffon microfibre doux et propre. Le papier peut être rugueux et rayer une surface délicate.","speaker":"seller"}],"youtube_video_id":"rRsVUfSr9Sk","youtube_video_ids":["rRsVUfSr9Sk"],"image_path":null},{"lesson_id":296,"module_sort_order":0,"sort_order":2,"title":"Comment nettoyer correctement l’écran et le Pinlock","summary":"Apprenez à nettoyer sans risque la face extérieure de l’écran et à la distinguer de la lentille Pinlock, plus fragile.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Commencez par identifier la surface à nettoyer","type":"text"}]},{"type":"paragraph","content":[{"text":"L’écran extérieur et la lentille Pinlock nécessitent des soins différents. Avant d’utiliser un produit, consultez les consignes du casque, de l’écran et de son revêtement.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Écran extérieur : nettoyage en douceur, étape par étape","type":"text"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Retirez le sable et les autres particules libres sans frotter. Ne frottez pas les salissures sur une surface sèche.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Appliquez Helmet Gel sur les insectes séchés et laissez agir conformément à l’étiquette. Ne le laissez pas sécher.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Essuyez les salissures ramollies avec un chiffon propre, sans appuyer.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Si les consignes de l’écran l’autorisent, utilisez Helmet Detailer et un chiffon Evolon propre pour la finition.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Pinlock : une lentille distincte et fragile","type":"text"}]},{"type":"paragraph","content":[{"text":"N’utilisez ni Helmet Gel ni Helmet Detailer sur la lentille. Ne la polissez pas avec un chiffon. Rincez-la à l’eau distillée sans la frotter et laissez-la sécher à l’air libre.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Ce que ces produits ne font pas","type":"text"}]},{"type":"paragraph","content":[{"text":"Ces produits servent au nettoyage et à la finition. Ils n’éliminent pas les rayures et ne réparent pas un écran endommagé.","type":"text"}]}]},"product_bullets":["Retirez le sable libre sans frotter avant de commencer à nettoyer l’écran.","Appliquez le gel sur les insectes séchés sur l’extérieur de l’écran, puis retirez les salissures sans appuyer.","Parachevez l’écran extérieur propre avec le Detailer et un chiffon Evolon.","N’appliquez ni gel ni Detailer sur le Pinlock et ne le polissez pas avec un chiffon microfibre.","Rincez le Pinlock à l’eau distillée et laissez-le sécher à l’air libre."],"key_points_title":"À retenir","conversation_title":"Échange avec le client","conversation":[{"text":"Puis-je nettoyer le Pinlock avec le même produit que l’écran extérieur ?","speaker":"client"},{"text":"Non. Utilisez Helmet Gel et le Detailer sur l’extérieur de l’écran. Nettoyez délicatement le Pinlock à l’eau distillée, sans le frotter, et suivez les consignes du casque.","speaker":"seller"},{"text":"Il y a du sable sur l’écran. Puis-je le passer tout de suite au chiffon microfibre ?","speaker":"client"},{"text":"Rincez d’abord l’écran ou retirez délicatement les particules libres. Ne faites pas glisser le sable sur l’écran : il pourrait le rayer.","speaker":"seller"},{"text":"Ces produits éliminent-ils les rayures ?","speaker":"client"},{"text":"Non. Ils servent au nettoyage et à la finition, mais ne réparent pas les rayures.","speaker":"seller"}],"youtube_video_id":"rRsVUfSr9Sk","youtube_video_ids":["rRsVUfSr9Sk","8z1Me4HeZAA"],"image_path":null},{"lesson_id":297,"module_sort_order":0,"sort_order":3,"title":"Comment entretenir l’intérieur du casque","summary":"Faites la différence entre rafraîchir l’intérieur du casque et laver une doublure sale.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Commencez par identifier le besoin","type":"text"}]},{"type":"paragraph","content":[{"text":"Demandez au client s’il souhaite rafraîchir l’intérieur après une sortie ou si la doublure est visiblement sale. Le désodorisant et le lavage répondent à des besoins différents : le produit aide à maintenir la fraîcheur, tandis qu’une doublure sale doit être nettoyée correctement.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Rafraîchir entre deux lavages","type":"text"}]},{"type":"paragraph","content":[{"text":"Le désodorisant Mint est conçu pour l’intérieur du casque. Vaporisez-le à environ 15–20 cm de distance et laissez le casque sécher complètement avant de le porter. Le produit n’est pas destiné à la peau ni au corps.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Laver la doublure","type":"text"}]},{"type":"paragraph","content":[{"text":"Vérifiez d’abord si la doublure peut être retirée et consultez les recommandations du fabricant du casque. Pour un lavage à la main, utilisez un produit adapté conformément à son étiquette. Lavez délicatement, rincez soigneusement et laissez sécher à l’air libre. Ne tordez pas le tissu et ne le faites pas sécher près d’une source de chaleur.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Quand reprendre le sujet","type":"text"}]},{"type":"paragraph","content":[{"text":"Si l’odeur persiste après avoir rafraîchi l’intérieur, vérifiez l’état de la doublure et envisagez de la laver. Présentez le désodorisant comme un complément d’entretien entre les lavages.","type":"text"}]}]},"product_bullets":["Demandez au client s’il est gêné par une odeur ou si la doublure sale doit être lavée.","Le désodorisant Mint aide à garder le casque frais entre les lavages, mais ne remplace pas le lavage.","Vaporisez à l’intérieur à environ 15–20 cm de distance et attendez que le casque soit complètement sec.","Lavez à la main la doublure amovible conformément aux consignes du casque.","Rincez soigneusement et laissez sécher à l’air libre ; ne tordez pas le tissu et n’utilisez pas de source de chaleur."],"key_points_title":"À retenir","conversation_title":"Échange avec le client","conversation":[{"text":"L’intérieur du casque sent la transpiration. Que me conseillez-vous ?","speaker":"client"},{"text":"Choisissez Mint pour rafraîchir rapidement le casque entre les lavages. Si la doublure est sale, lavez-la avec un produit distinct conformément aux consignes du casque.","speaker":"seller"},{"text":"Puis-je vaporiser le produit sur ma tête ?","speaker":"client"},{"text":"Non. Utilisez-le à l’intérieur du casque conformément à l’étiquette, et non sur votre peau.","speaker":"seller"},{"text":"Puis-je remettre le casque juste après l’avoir utilisé ?","speaker":"client"},{"text":"Attendez que l’intérieur soit complètement sec. Si l’odeur revient, la doublure aura peut-être besoin d’être lavée.","speaker":"seller"}],"youtube_video_id":null,"youtube_video_ids":[],"image_path":null},{"lesson_id":298,"module_sort_order":0,"sort_order":4,"title":"Quel kit recommander : GIGA ou Trip Kit ?","summary":"Choisissez Trip Kit ou GIGA selon le lieu et la fréquence de nettoyage du casque par le client.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Choisissez le kit en fonction de son utilisation","type":"text"}]},{"type":"paragraph","content":[{"text":"Trip Kit et GIGA couvrent les étapes de nettoyage de l’extérieur du casque : ramollir les salissures avec le gel, puis terminer avec le Detailer. Ils diffèrent principalement par la taille des flacons et la facilité de rangement.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Trip Kit : pour les déplacements","type":"text"}]},{"type":"paragraph","content":[{"text":"Les flacons compacts et la pochette de transport permettent d’emporter facilement le kit, de le ranger dans un top-case ou un compartiment et de l’utiliser rapidement lors d’une pause.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"GIGA : pour l’entretien régulier","type":"text"}]},{"type":"paragraph","content":[{"text":"Les grands flacons de gel et de Detailer de 250 ml conviennent à un nettoyage fréquent à la maison ou au garage, par exemple pour entretenir plusieurs casques.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Des questions pour faciliter le choix","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Où le casque sera-t-il le plus souvent nettoyé : en voyage ou à la maison ?","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"À quelle fréquence le client le nettoiera-t-il ?","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Un seul casque ou plusieurs ?","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Le client a-t-il seulement besoin d’éliminer les insectes, ou souhaite-t-il aussi une finition ?","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"Si le client est gêné par une odeur à l’intérieur du casque, proposez un produit distinct pour l’intérieur. Un kit pour l’extérieur ne remplace pas le lavage de la doublure.","type":"text"}]}]},"product_bullets":["Trip Kit et GIGA servent à nettoyer l’extérieur du casque en deux étapes.","Trip Kit comprend des flacons compacts et une pochette : il est donc adapté aux déplacements.","GIGA comprend des flacons de 250 ml et des accessoires pour un usage régulier à la maison ou au garage.","Pour rafraîchir l’intérieur, choisissez un produit distinct : les kits pour les surfaces extérieures ne le remplacent pas.","Demandez où et à quelle fréquence le client nettoiera son casque ; ne supposez pas que le kit le plus grand est préférable."],"key_points_title":"À retenir","conversation_title":"Échange avec le client","conversation":[{"text":"Je cherche un produit pour nettoyer mon casque en voyage. Quel kit choisir ?","speaker":"client"},{"text":"Trip Kit est compact et conçu pour les déplacements. Il comprend des produits pour l’extérieur du casque ainsi que des accessoires.","speaker":"seller"},{"text":"Trip Kit conviendrait-il mieux pour nettoyer régulièrement deux casques à la maison ?","speaker":"client"},{"text":"Pour un usage fréquent, GIGA et ses grands flacons seront peut-être plus pratiques. Choisissez le format en fonction de la fréquence et du nombre de casques à nettoyer.","speaker":"seller"},{"text":"Le kit permet-il aussi de nettoyer la doublure ?","speaker":"client"},{"text":"Non. Ce kit est destiné à l’entretien de l’extérieur du casque. Si nécessaire, choisissez un produit distinct pour l’intérieur.","speaker":"seller"},{"text":"Je n’ai plus de gel. Dois-je racheter tout le kit ?","speaker":"client"},{"text":"Non. Vous pouvez racheter uniquement ce produit s’il est vendu séparément.","speaker":"seller"}],"youtube_video_id":null,"youtube_video_ids":[],"image_path":null},{"lesson_id":299,"module_sort_order":0,"sort_order":5,"title":"Mise en situation de vente : un client achète un casque neuf","summary":"Entraînez-vous à cerner les besoins et à recommander des produits d’entretien à un client qui achète un casque.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Objectif de l’exercice","type":"text"}]},{"type":"paragraph","content":[{"text":"Entraînez-vous à accompagner l’achat d’un casque neuf en recommandant des produits adaptés aux habitudes de conduite du client. Ne commencez pas par énumérer les produits. Demandez où et à quelle fréquence il nettoiera son casque, et quel problème il souhaite résoudre.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Points à observer","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Posez au moins une question pour choisir le bon format.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Expliquez en deux phrases simples le rôle du gel et du Detailer.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Ne proposez pas de produit complémentaire dont le client n’a pas besoin.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Ne promettez pas un rendement précis sans données vérifiées.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Exercice individuel","type":"text"}]},{"type":"paragraph","content":[{"text":"Après avoir joué les scènes, reformulez la réponse avec vos propres mots. Terminez par une question : « Nettoyez-vous plutôt votre casque en voyage ou à la maison ? », « Un casque ou plusieurs ? » ou « Le problème concerne surtout les insectes, ou souhaitez-vous aussi rafraîchir l’intérieur ? » Justifiez votre recommandation en une phrase.","type":"text"}]}]},"product_bullets":["Commencez par demander où et à quelle fréquence le casque sera nettoyé, et combien de casques sont concernés.","Choisissez Trip Kit pour l’entretien en déplacement et GIGA pour un usage régulier à la maison.","Expliquez brièvement l’ordre d’utilisation : le gel ramollit les salissures et le Detailer finit la surface propre.","Ne proposez pas de désodorisant pour l’intérieur si le client n’en a pas besoin.","Respectez un refus et ne promettez pas un rendement qui n’a pas été vérifié."],"key_points_title":"À retenir","conversation_title":"Échange avec le client","conversation":[{"text":"Je pars une semaine à moto et je ne veux pas avoir d’insectes sur mon écran. Que dois-je emporter ?","speaker":"client"},{"text":"Pour nettoyer le casque en voyage, je recommande Trip Kit. Le gel ramollit les insectes ; après les avoir retirés délicatement, le Detailer permet de parfaire l’écran propre.","speaker":"seller"},{"text":"Puis-je nettoyer le Pinlock avec le même kit ?","speaker":"client"},{"text":"N’utilisez pas les produits destinés à l’écran extérieur sur la lentille. Nettoyez délicatement le Pinlock conformément aux instructions du fabricant.","speaker":"seller"},{"text":"Je n’ai besoin de rien pour l’intérieur, le casque est neuf.","speaker":"client"},{"text":"Très bien, inutile d’acheter un désodorisant « au cas où ». Vous pourrez y revenir si une odeur ou des salissures deviennent gênantes.","speaker":"seller"}],"youtube_video_id":null,"youtube_video_ids":[],"image_path":null},{"lesson_id":300,"module_sort_order":1,"sort_order":0,"title":"Pourquoi le cuir de moto nécessite-t-il un entretien ?","summary":"Identifiez le type de cuir et les salissures, puis choisissez des produits distincts pour le nettoyage et l’entretien.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Commencez par identifier le cuir","type":"text"}]},{"type":"paragraph","content":[{"text":"Une combinaison en cuir peut associer différents types de cuir, couleurs, finitions et empiècements textiles. Demandez précisément quelle partie nécessite un entretien, l’importance des salissures et si le client connaît les recommandations du fabricant. Les cuirs clairs ou fluorescents nécessitent une attention particulière.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Distinguez nettoyage et entretien","type":"text"}]},{"type":"paragraph","content":[{"text":"Leather Cleaner élimine les salissures. Leather Milk s’applique uniquement sur du cuir propre et sec pour l’entretenir. Aucun de ces produits ne remplace l’autre, et les produits d’entretien ne réparent pas les dommages mécaniques.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Montrez l’ordre d’utilisation en toute sécurité","type":"text"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Retirez la poussière libre sans frotter fort.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Faites un essai sur une zone peu visible et vérifiez le résultat.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Nettoyez délicatement avec le nettoyant adapté et une brosse souple.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Essuyez les résidus avec un chiffon propre légèrement humide, puis laissez sécher à l’air libre.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Si le cuir nécessite un entretien, appliquez une fine couche de Leather Milk conformément à l’étiquette.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Fixez des attentes réalistes","type":"text"}]},{"type":"paragraph","content":[{"text":"Un produit d’entretien peut nettoyer et faciliter l’entretien courant, mais il ne restaurera pas une finition usée et ne réparera pas les craquelures. Pour ce type de dommage, conseillez de faire évaluer le vêtement par un atelier de réparation ou son fabricant.","type":"text"}]}]},"product_bullets":["Identifiez d’abord le type et la couleur du cuir, puis vérifiez les recommandations du fabricant du vêtement.","Leather Cleaner élimine les salissures ; Leather Milk entretient le cuir une fois sec.","Avant utilisation, testez le produit sur une zone discrète, en particulier sur un cuir clair.","Pour le nettoyage, utilisez une brosse souple et exercez une légère pression.","Les produits d’entretien ne réparent ni les craquelures, ni les éraflures, ni les dommages de finition."],"key_points_title":"À retenir","conversation_title":"Échange avec le client","conversation":[{"text":"J’ai une combinaison en cuir avec des empiècements de couleur vive. Comment commencer le nettoyage ?","speaker":"client"},{"text":"Pour les salissures courantes, choisissez Leather Cleaner Normal. Sur les couleurs fluorescentes, faites d’abord un essai sur une zone discrète et nettoyez avec une brosse souple.","speaker":"seller"},{"text":"Le cuir est-il entretenu après l’utilisation du nettoyant ?","speaker":"client"},{"text":"Le nettoyant élimine les salissures. Une fois le cuir complètement sec, vous pouvez appliquer Leather Milk comme étape d’entretien distincte.","speaker":"seller"},{"text":"Il y a une craquelure près de la couture. Le lait va-t-il la réparer ?","speaker":"client"},{"text":"Non. Les produits d’entretien nourrissent le cuir, mais ne réparent ni les craquelures ni les coutures endommagées. Pour cela, adressez-vous à un atelier de réparation.","speaker":"seller"}],"youtube_video_id":null,"youtube_video_ids":[],"image_path":null},{"lesson_id":301,"module_sort_order":1,"sort_order":1,"title":"Nettoyer le cuir : Leather Cleaner et une brosse","summary":"Choisissez la version de Leather Cleaner adaptée aux salissures et à la couleur du cuir, puis montrez une méthode de nettoyage douce.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Choisissez la version selon le cuir et les salissures","type":"text"}]},{"type":"paragraph","content":[{"text":"Ne choisissez pas automatiquement le nettoyant le plus puissant. Normal convient aux salissures courantes et aux couleurs plus délicates. Strong peut être envisagé pour les salissures tenaces sur un cuir classique, si les consignes du fabricant l’autorisent.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Démonstration étape par étape","type":"text"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Secouez le flacon et testez le produit sur une zone discrète.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Appliquez la mousse sur une brosse souple légèrement humide, et non directement sur tout le vêtement.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Nettoyez une petite zone par des gestes lents et doux.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Essuyez les salissures avec un chiffon propre légèrement humide.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Laissez le vêtement sécher à l’air libre avant de poursuivre l’entretien.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Quand changer de méthode","type":"text"}]},{"type":"paragraph","content":[{"text":"Si le matériau présente une finition inhabituelle, une couleur vive ou des signes de dommage, interrompez la démonstration et vérifiez les consignes du vêtement. Le nettoyant élimine les salissures, mais ne répare ni les éraflures ni les craquelures.","type":"text"}]}]},"product_bullets":["Normal est indiqué pour les salissures courantes et les couleurs plus délicates.","Envisagez Strong pour les salissures plus tenaces sur un cuir classique, après avoir effectué un essai.","Secouez le flacon et testez le produit sur une zone peu visible.","Appliquez la mousse sur une brosse souple légèrement humide ; ne frottez pas fort.","Essuyez les résidus et laissez le cuir sécher à l’air libre."],"key_points_title":"À retenir","conversation_title":"Échange avec le client","conversation":[{"text":"J’ai une combinaison blanche avec des empiècements fluorescents. Dois-je choisir Strong ?","speaker":"client"},{"text":"Pour les couleurs fluorescentes, choisissez Normal et faites d’abord un essai sur une zone peu visible. Réservez Strong aux salissures tenaces et utilisez-le uniquement conformément à sa destination.","speaker":"seller"},{"text":"Puis-je utiliser une brosse à chaussures dure ?","speaker":"client"},{"text":"Mieux vaut utiliser une brosse souple. Appliquez la mousse sur ses poils légèrement humides et nettoyez délicatement une petite zone par mouvements circulaires.","speaker":"seller"},{"text":"Quand dois-je appliquer Leather Milk ?","speaker":"client"},{"text":"Après le nettoyage, essuyez les salissures avec un chiffon propre et laissez le cuir sécher à l’air libre. Si le cuir nécessite un entretien, appliquez le lait uniquement sur la surface sèche.","speaker":"seller"}],"youtube_video_id":"iyz1GD-lV2Y","youtube_video_ids":["iyz1GD-lV2Y","s4I4GwvoHuc"],"image_path":null},{"lesson_id":302,"module_sort_order":1,"sort_order":2,"title":"Entretenir le cuir : Leather Milk","summary":"Présentez Leather Milk comme une étape d’entretien après le nettoyage et le séchage du cuir.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Pourquoi entretenir le cuir","type":"text"}]},{"type":"paragraph","content":[{"text":"Après le nettoyage et le séchage, le cuir peut nécessiter un soin distinct. Leather Milk s’utilise après le nettoyant ; ce n’est pas un détergent pour les vêtements sales. Expliquez cet ordre au client avant de montrer comment l’appliquer.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Appliquer sans excès","type":"text"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Assurez-vous que le cuir est propre et complètement sec.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Faites un essai sur une zone discrète, surtout si la finition est inhabituelle.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Appliquez une petite quantité de produit à l’aide d’un chiffon doux.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Étalez-le en couche fine et uniforme, conformément à l’étiquette.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Laissez sécher et vérifiez le résultat avant toute nouvelle application.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Ses possibilités et ses limites","type":"text"}]},{"type":"paragraph","content":[{"text":"Le lait contribue à l’entretien courant, mais ne répare ni les craquelures, ni les éraflures, ni une finition endommagée. Ne promettez pas d’imperméabilisation si le fabricant ne l’indique pas. En cas de doute, consultez les consignes du vêtement.","type":"text"}]}]},"product_bullets":["Appliquez Leather Milk sur du cuir propre et sec.","Appliquez une couche fine et uniforme conformément aux instructions.","Faites un essai sur une zone peu visible avant d’en appliquer sur tout le vêtement.","N’utilisez pas le lait pour éliminer les salissures.","Ne promettez pas qu’il réparera les craquelures ou rétablira la protection d’origine."],"key_points_title":"À retenir","conversation_title":"Échange avec le client","conversation":[{"text":"Pourquoi ai-je besoin de Leather Milk si j’ai déjà Leather Cleaner ?","speaker":"client"},{"text":"Le nettoyant élimine les salissures, tandis que Leather Milk entretient le cuir après son nettoyage et son séchage. Si le cuir n’a pas besoin d’un soin pour le moment, vous n’avez pas besoin d’ajouter le lait.","speaker":"seller"},{"text":"Puis-je appliquer le lait sur une veste sale ?","speaker":"client"},{"text":"Nettoyez et séchez d’abord la veste. Le lait ne remplace pas le nettoyant.","speaker":"seller"},{"text":"J’ai du cuir mat. Comment vérifier si le lait convient ?","speaker":"client"},{"text":"Faites un essai sur une zone discrète et consultez les recommandations du fabricant. Appliquez ensuite une fine couche conformément à l’étiquette.","speaker":"seller"},{"text":"Le lait réparera-t-il les craquelures ?","speaker":"client"},{"text":"Non. Les craquelures et les éraflures nécessitent une réparation, pas un produit d’entretien.","speaker":"seller"}],"youtube_video_id":null,"youtube_video_ids":[],"image_path":null},{"lesson_id":303,"module_sort_order":1,"sort_order":3,"title":"Comment utiliser le kit Leather Care","summary":"Présentez au client les étapes d’entretien du cuir et vérifiez que chaque élément répond à un besoin réel.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Le kit, une routine étape par étape","type":"text"}]},{"type":"paragraph","content":[{"text":"Leather Care Kit peut convenir à une personne qui souhaite entretenir l’extérieur d’un vêtement en cuir et rafraîchir son intérieur. Il comprend un nettoyant, Leather Milk, un désodorisant pour l’intérieur, une brosse et un chiffon. Montrez l’ordre d’utilisation au lieu de simplement énumérer les éléments.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Ordre d’utilisation","type":"text"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Choisissez la version du nettoyant adaptée aux salissures et à la couleur, puis faites un essai.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Nettoyez le cuir avec une brosse souple et essuyez les résidus.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Laissez le cuir sécher à l’air libre.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Appliquez une fine couche de Leather Milk conformément à l’étiquette.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Rafraîchissez l’intérieur séparément, conformément aux instructions du produit concerné.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Ne recommandez le kit que s’il est adapté","type":"text"}]},{"type":"paragraph","content":[{"text":"Demandez au client ce qu’il possède déjà et s’il souhaite également entretenir l’intérieur. S’il a déjà un nettoyant et n’a besoin que d’un soin, recommandez uniquement l’étape manquante. Ne présentez pas le kit comme indispensable à tout le monde.","type":"text"}]}]},"product_bullets":["Leather Care Kit réunit un nettoyant, un lait d’entretien, un désodorisant pour l’intérieur et des accessoires.","Nettoyez d’abord le cuir, laissez-le sécher, puis appliquez Leather Milk.","Un désodorisant pour l’intérieur répond à un besoin différent de l’entretien de la face extérieure.","Choisissez Normal ou Strong selon la couleur, les salissures et les consignes du vêtement.","Si le client possède déjà certains produits, recommandez uniquement ce qui lui manque."],"key_points_title":"À retenir","conversation_title":"Échange avec le client","conversation":[{"text":"Ma combinaison est sale à l’extérieur et sent mauvais à l’intérieur. Le kit répondra-t-il aux deux problèmes ?","speaker":"client"},{"text":"Leather Care Kit réunit un nettoyant, un lait d’entretien, un désodorisant pour l’intérieur et des accessoires. Nettoyez d’abord le cuir ; une fois sec, entretenez-le avec le lait et rafraîchissez l’intérieur séparément.","speaker":"seller"},{"text":"J’ai déjà un nettoyant. Est-ce quand même intéressant de prendre tout le kit ?","speaker":"client"},{"text":"Ce n’est pas nécessaire si vous avez déjà les autres éléments. Choisissez uniquement le lait d’entretien ou le produit pour l’intérieur qui vous manque.","speaker":"seller"},{"text":"Le cuir est craquelé. Le kit va-t-il le restaurer ?","speaker":"client"},{"text":"Il ne réparera pas les dommages. Si le cuir est craquelé, consultez d’abord un atelier de réparation.","speaker":"seller"}],"youtube_video_id":null,"youtube_video_ids":[],"image_path":null},{"lesson_id":304,"module_sort_order":1,"sort_order":4,"title":"Mise en situation de vente : un client achète un vêtement en cuir","summary":"Entraînez-vous à identifier le type de cuir, à choisir la solution adaptée la plus simple et à répondre aux besoins du client.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Commencez par évaluer le besoin","type":"text"}]},{"type":"paragraph","content":[{"text":"L’objectif de cette mise en situation est de choisir une solution adaptée à une combinaison précise, et non de vendre tous les produits du rayon. Demandez la couleur et le type de cuir, le degré de salissure, l’état du vêtement et ce que le client possède déjà. Expliquez ensuite les étapes nécessaires.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Trois situations à mettre en pratique","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Combinaison claire avec des empiècements fluorescents : choisissez soigneusement le nettoyant et testez-le sur une zone peu visible.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Combinaison noire très sale : choisissez un nettoyant adapté au type de cuir, nettoyez délicatement et laissez sécher.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Veste propre nécessitant un entretien courant : envisagez Leather Milk sans ajouter inutilement un nettoyant.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Faites le point ensemble","type":"text"}]},{"type":"paragraph","content":[{"text":"Après chaque échange, le vendeur doit pouvoir expliquer ce qui est acheté, dans quel ordre les produits seront utilisés et ce qu’ils ne peuvent pas réparer. Si le client possède déjà certains accessoires, la recommandation peut se limiter à un seul produit manquant.","type":"text"}]}]},"product_bullets":["Demandez le type, la couleur et l’état du cuir, ainsi que les recommandations du fabricant du vêtement.","Distinguez le nettoyage de la surface extérieure, son entretien et le rafraîchissement de l’intérieur.","Choisissez un nettoyant adapté à la couleur et aux salissures ; faites d’abord un essai sur un cuir délicat.","Si le client souhaite entretenir le cuir, recommandez Leather Milk une fois celui-ci sec.","Pour les dommages mécaniques, orientez le client vers un atelier ; ne promettez pas qu’un produit d’entretien pourra les réparer."],"key_points_title":"À retenir","conversation_title":"Échange avec le client","conversation":[{"text":"Ma combinaison a des empiècements fluorescents et j’ai peur qu’ils se décolorent.","speaker":"client"},{"text":"Pour les couleurs fluorescentes, choisissez Normal. Faites un essai sur une zone discrète, puis nettoyez une petite partie avec une brosse souple.","speaker":"seller"},{"text":"J’ai déjà le nettoyant. Que me faut-il pour l’entretien après le nettoyage ?","speaker":"client"},{"text":"Si le cuir en a besoin, choisissez uniquement Leather Milk. Appliquez-le lorsque le cuir a séché après le nettoyage.","speaker":"seller"},{"text":"La manche est éraflée. Un produit d’entretien peut-il masquer l’éraflure ?","speaker":"client"},{"text":"Non, un produit d’entretien ne réparera pas une éraflure. Faites vérifier la combinaison afin de savoir si elle nécessite une réparation professionnelle.","speaker":"seller"},{"text":"L’intérieur sent la transpiration. Dois-je laver toute la combinaison en cuir ?","speaker":"client"},{"text":"Ne commencez pas par tremper la combinaison. Choisissez un produit distinct pour l’intérieur et utilisez-le conformément aux consignes du vêtement.","speaker":"seller"}],"youtube_video_id":null,"youtube_video_ids":[],"image_path":null},{"lesson_id":305,"module_sort_order":2,"sort_order":0,"title":"Comment entretenir les vêtements textiles","summary":"Identifiez la matière du vêtement et les consignes de lavage, puis choisissez le produit adapté à la fibre.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Avant de choisir une lessive","type":"text"}]},{"type":"paragraph","content":[{"text":"Les vêtements de moto peuvent associer membrane, doublure, protections et différentes fibres. Demandez au client ce qu’il souhaite laver, vérifiez l’étiquette d’entretien, puis recommandez un produit. Les consignes du vêtement déterminent la température, le programme, le dosage et le séchage.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Choisissez le produit adapté à la matière","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Textile Care : vêtements techniques classiques et vêtements avec membrane.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Active Care : vêtements de sport synthétiques, sous-vêtements thermiques et microfibre.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Merino Care : laine mérinos et fibres naturelles délicates.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Jeans Care : denim, y compris les vêtements de moto si leur étiquette d’entretien l’autorise.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Fabric Protect : un additif de lavage qui contribue à la fraîcheur, et non un traitement imperméabilisant.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Ne lavez pas tout de la même façon","type":"text"}]},{"type":"paragraph","content":[{"text":"Une veste à membrane, un haut thermique et une couche en mérinos peuvent nécessiter des lessives et programmes différents. Ne recommandez pas l’assouplissant comme substitut à un produit d’entretien adapté. Si le client souhaite restaurer le déperlance, choisissez un produit distinct compatible avec les consignes du vêtement.","type":"text"}]}]},"product_bullets":["Commencez par lire l’étiquette : matière, température, programme, lessive et séchage.","Choisissez Textile Care pour les vêtements techniques et Active Care pour les vêtements de sport.","Merino Care est conçu pour la laine délicate, tandis que Jeans Care convient au denim.","Fabric Protect contribue à la fraîcheur pendant le lavage et n’est pas un traitement déperlant.","Lavez séparément les matières différentes si elles nécessitent des programmes et produits distincts."],"key_points_title":"À retenir","conversation_title":"Échange avec le client","conversation":[{"text":"J’ai une veste à membrane, un haut thermique et un pull en mérinos. Puis-je tout laver ensemble ?","speaker":"client"},{"text":"Mieux vaut les séparer en suivant leurs étiquettes : ces matières différentes peuvent nécessiter des lessives et programmes distincts. Choisissez Textile Care pour la veste et un produit séparé pour le mérinos.","speaker":"seller"},{"text":"Fabric Protect va-t-il imperméabiliser ma veste ?","speaker":"client"},{"text":"Non. Fabric Protect est un additif de lavage qui contribue à la fraîcheur. Pour protéger le vêtement de l’eau, choisissez un traitement imperméabilisant distinct adapté à cette veste.","speaker":"seller"},{"text":"Je ne sais pas quel programme choisir.","speaker":"client"},{"text":"Utilisez le programme et la température indiqués sur l’étiquette du vêtement, puis vérifiez le dosage sur l’étiquette de la lessive.","speaker":"seller"}],"youtube_video_id":null,"youtube_video_ids":[],"image_path":null},{"lesson_id":306,"module_sort_order":2,"sort_order":1,"title":"Textile Care : nettoyer les vêtements","summary":"Expliquez à quoi sert Textile Care et montrez comment le choisir en toute sécurité pour les vêtements techniques.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"À quoi sert Textile Care","type":"text"}]},{"type":"paragraph","content":[{"text":"Textile Care est conçu pour les vêtements de moto techniques, y compris ceux avec membrane. Ne promettez pas que cette lessive réparera une membrane usée ou rétablira ses propriétés après un dommage. L’objectif est de laver correctement le vêtement en suivant les consignes de son fabricant.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Préparer le lavage","type":"text"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Vérifiez l’étiquette du vêtement et retirez les éléments à laver séparément.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Sélectionnez un programme et une température autorisés.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Dosez la lessive conformément à son étiquette.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"N’ajoutez pas d’assouplissant classique, sauf recommandation explicite du fabricant.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Séchez le vêtement conformément à l’étiquette et à l’écart d’une chaleur excessive, si cela est indiqué.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Fraîcheur supplémentaire","type":"text"}]},{"type":"paragraph","content":[{"text":"Fabric Protect peut être ajouté au lavage comme additif distinct. Expliquez clairement son rôle : il contribue à garder les vêtements frais, mais ne remplace pas un traitement déperlant.","type":"text"}]}]},"product_bullets":["Textile Care est conçu pour laver les vêtements de moto techniques et ceux avec membrane.","L’étiquette du vêtement indique le programme, la température et le mode de séchage.","Ne remplacez pas automatiquement le produit par un assouplissant classique.","Respectez le dosage indiqué sur l’étiquette du produit et les consignes de lavage.","Fabric Protect peut être utilisé comme additif distinct pour contribuer à la fraîcheur."],"key_points_title":"À retenir","conversation_title":"Échange avec le client","conversation":[{"text":"Textile Care convient-il à une veste à membrane ?","speaker":"client"},{"text":"Oui. C’est une lessive pour les vêtements techniques et à membrane. Choisissez le programme et la température conformément à l’étiquette de la veste.","speaker":"seller"},{"text":"J’ajoute toujours de l’assouplissant. Dois-je continuer ?","speaker":"client"},{"text":"N’en ajoutez pas automatiquement pour les vêtements techniques. Vérifiez l’étiquette et utilisez Textile Care conformément aux instructions.","speaker":"seller"},{"text":"Que puis-je ajouter si je veux que mes vêtements restent frais après le lavage ?","speaker":"client"},{"text":"Vous pouvez verser Fabric Protect dans le compartiment de l’assouplissant à la place d’un assouplissant classique, conformément à son étiquette.","speaker":"seller"}],"youtube_video_id":"UUXCozkqAZk","youtube_video_ids":["UUXCozkqAZk"],"image_path":null},{"lesson_id":307,"module_sort_order":2,"sort_order":2,"title":"Fabric Protect : entretien et fraîcheur après le lavage","summary":"Montrez comment ajouter Fabric Protect au lavage et expliquez en quoi il diffère d’un traitement imperméabilisant.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Un additif de lavage, pas un imperméabilisant","type":"text"}]},{"type":"paragraph","content":[{"text":"Son nom peut évoquer une protection contre l’eau : expliquez donc clairement son rôle. Fabric Protect est un additif qui contribue à la fraîcheur du vêtement pendant le lavage. Ce n’est pas un traitement déperlant et il ne restaure pas à lui seul le revêtement DWR.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Comment l’utiliser","type":"text"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Choisissez une lessive adaptée à la matière et vérifiez l’étiquette du vêtement.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Versez Fabric Protect dans le compartiment de l’assouplissant si les instructions le précisent.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Respectez le dosage indiqué sur l’étiquette.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Choisissez un programme conforme aux consignes du vêtement.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Utilisez un produit distinct spécialement conçu pour l’imperméabilisation.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Comment présenter l’avantage supplémentaire","type":"text"}]},{"type":"paragraph","content":[{"text":"Si le client lave des vêtements techniques et souhaite qu’ils restent frais après lavage, vous pouvez proposer Fabric Protect en complément de Textile Care. S’il demande une protection contre la pluie, expliquez clairement qu’il lui faut un traitement imperméabilisant distinct.","type":"text"}]}]},"product_bullets":["Fabric Protect est un additif de lavage qui contribue à la fraîcheur des vêtements.","Il peut remplacer l’assouplissant classique si l’étiquette le précise.","Versez-le dans le compartiment de l’assouplissant conformément aux instructions.","Associez-le à la lessive adaptée à la matière.","Ne promettez pas qu’il rétablira l’imperméabilité ou la finition DWR."],"key_points_title":"À retenir","conversation_title":"Échange avec le client","conversation":[{"text":"Fabric Protect va-t-il rendre ma veste déperlante ?","speaker":"client"},{"text":"Non : c’est un additif de lavage qui contribue à garder les vêtements frais, pas un traitement déperlant. Choisissez un traitement imperméabilisant distinct pour la veste.","speaker":"seller"},{"text":"Où dois-je verser Fabric Protect ?","speaker":"client"},{"text":"Versez-le dans le compartiment de l’assouplissant à la place de l’assouplissant classique, puis lavez le vêtement selon son étiquette.","speaker":"seller"},{"text":"Puis-je l’utiliser avec Textile Care ?","speaker":"client"},{"text":"Oui. Textile Care lave les vêtements techniques, et Fabric Protect s’ajoute séparément dans le compartiment de rinçage.","speaker":"seller"}],"youtube_video_id":null,"youtube_video_ids":[],"image_path":null},{"lesson_id":308,"module_sort_order":2,"sort_order":3,"title":"Active Care : entretien des vêtements de sport","summary":"Choisissez Active Care pour les vêtements de sport synthétiques et les sous-vêtements thermiques, selon leur utilisation.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Quand envisager Active Care","type":"text"}]},{"type":"paragraph","content":[{"text":"Active Care convient aux vêtements de sport synthétiques, aux sous-vêtements thermiques et à la microfibre. Commencez par demander au client quelle activité il pratique et quel problème il veut résoudre, par exemple une odeur après l’entraînement ou le lavage fréquent d’une première couche.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Adaptez-le à la matière","type":"text"}]},{"type":"paragraph","content":[{"text":"Si le client demande conseil pour une veste à membrane, vérifiez son étiquette et envisagez Textile Care. Pour la laine mérinos, choisissez un produit destiné aux fibres naturelles délicates. Ne choisissez pas Active Care uniquement parce qu’il s’agit d’un vêtement de sport.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Utilisation et format","type":"text"}]},{"type":"paragraph","content":[{"text":"Vérifiez toujours sur l’étiquette du vêtement le programme, la température et les consignes de séchage. Respectez le dosage indiqué sur l’étiquette du produit. Le sachet de 40 ml est pratique pour essayer le produit ou l’emporter en voyage.","type":"text"}]}]},"product_bullets":["Choisissez Active Care pour les vêtements de sport synthétiques et les sous-vêtements thermiques.","Demandez la matière, les odeurs après l’effort et les consignes de l’étiquette.","Ne partez pas du principe que cette lessive convient à tous les vêtements.","Respectez le dosage et le programme indiqués sur les étiquettes du produit et du vêtement.","Le sachet de 40 ml permet au client d’essayer le produit avant d’acheter un format plus grand."],"key_points_title":"À retenir","conversation_title":"Échange avec le client","conversation":[{"text":"Mon haut thermique garde une odeur de transpiration. Que me conseillez-vous ?","speaker":"client"},{"text":"S’il s’agit d’un vêtement de sport synthétique ou d’une première couche thermique, choisissez Active Care. Lavez-le conformément à son étiquette et respectez le dosage indiqué sur celle du produit.","speaker":"seller"},{"text":"Dois-je utiliser Active Care pour une veste à membrane ?","speaker":"client"},{"text":"Choisissez Textile Care pour une veste à membrane. Active Care est destiné aux vêtements de sport synthétiques et aux premières couches.","speaker":"seller"},{"text":"Puis-je emporter un plus petit format en voyage ?","speaker":"client"},{"text":"Oui, un sachet de 40 ml est disponible. C’est un format pratique pour essayer le produit ou l’emporter en voyage.","speaker":"seller"}],"youtube_video_id":null,"youtube_video_ids":[],"image_path":null},{"lesson_id":309,"module_sort_order":2,"sort_order":4,"title":"Merino Care","summary":"Apprenez à laver la laine mérinos et les fibres délicates, et évitez les recommandations trop générales.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Les fibres délicates nécessitent un soin particulier","type":"text"}]},{"type":"paragraph","content":[{"text":"Les couches en mérinos contribuent au confort pendant la conduite et doivent être entretenues conformément à leur étiquette. Merino Care est conçu pour la laine mérinos et les autres fibres délicates indiquées par le fabricant. Ne supposez pas qu’un programme adapté aux premières couches synthétiques convient aussi à la laine.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Lavage et séchage","type":"text"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Vérifiez la composition et les symboles d’entretien sur l’étiquette.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Choisissez un programme laine ou un lavage à la main si cela est indiqué.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Dosez la lessive selon son étiquette ; pour une petite charge, celle-ci peut indiquer 15 à 30 ml.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Évitez l’assouplissant classique, sauf recommandation contraire du fabricant.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Laissez sécher le vêtement à l’air libre et ne le posez pas sur un radiateur chaud.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Échange avec le client","type":"text"}]},{"type":"paragraph","content":[{"text":"Demandez au client s’il lave une couche en mérinos seule ou un vêtement composé de plusieurs matières. Pour les textiles mixtes, des lavages séparés peuvent être préférables à une seule lessive pour tout.","type":"text"}]}]},"product_bullets":["Merino Care est conçu pour la laine mérinos et les fibres naturelles délicates.","Choisissez la température et le programme en priorité selon l’étiquette du vêtement.","Respectez le dosage de lessive indiqué sur son étiquette.","N’ajoutez pas d’assouplissant classique, sauf recommandation explicite.","Laissez sécher à l’air libre conformément aux consignes, à l’écart d’une chaleur excessive."],"key_points_title":"À retenir","conversation_title":"Échange avec le client","conversation":[{"text":"Puis-je laver un haut en mérinos avec une lessive classique ?","speaker":"client"},{"text":"Choisissez Merino Care pour le mérinos et vérifiez d’abord l’étiquette. Une lessive classique peut ne pas convenir à la laine délicate.","speaker":"seller"},{"text":"Quel programme et quelle température dois-je utiliser ?","speaker":"client"},{"text":"Utilisez un programme laine ou lavez à la main uniquement si l’étiquette l’autorise, et respectez la température indiquée.","speaker":"seller"},{"text":"Puis-je faire sécher le haut sur un radiateur ?","speaker":"client"},{"text":"Ne le posez pas sur un radiateur chaud. Laissez-le sécher à l’air libre conformément à l’étiquette.","speaker":"seller"}],"youtube_video_id":"Hs9QuFjKbRA","youtube_video_ids":["Hs9QuFjKbRA"],"image_path":null},{"lesson_id":310,"module_sort_order":2,"sort_order":5,"title":"Jeans Care","summary":"Choisissez Jeans Care pour le denim, en tenant compte de la conception du vêtement de moto.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Le denim de moto n’est pas toujours un jean classique","type":"text"}]},{"type":"paragraph","content":[{"text":"Les vêtements de moto peuvent contenir des fibres extensibles, une doublure, des protections et des zones renforcées. Avant de recommander une lessive, vérifiez la composition et les éléments amovibles. L’étiquette du vêtement précise le programme de lavage et le mode de séchage.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Entretien étape par étape","type":"text"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Vérifiez l’étiquette d’entretien et la composition du tissu.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Retirez les protections si le fabricant l’autorise.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Choisissez Jeans Care pour le denim et respectez le dosage indiqué sur l’étiquette.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Sélectionnez le programme indiqué sur l’étiquette d’entretien.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Séchez le vêtement conformément aux consignes, sans chaleur excessive.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Choisissez un produit adapté au vêtement","type":"text"}]},{"type":"paragraph","content":[{"text":"Jeans Care ne convient pas à tous les types de vêtements. Si le client a un pantalon avec membrane ou une forte proportion de fibres techniques, tenez compte de sa composition et de ses consignes d’entretien. Le sachet de 40 ml constitue un format compact.","type":"text"}]}]},"product_bullets":["Choisissez Jeans Care pour le denim, y compris les vêtements de moto si leur étiquette l’autorise.","Vérifiez la composition, les mélanges de fibres et la présence de protections ou d’une doublure.","Choisissez le programme et la température selon les symboles d’entretien du fabricant.","N’utilisez pas automatiquement une lessive pour denim sur des vêtements en laine ou à membrane.","Le sachet de 40 ml constitue un format pratique à essayer ou à emporter en voyage."],"key_points_title":"À retenir","conversation_title":"Échange avec le client","conversation":[{"text":"J’ai un jean de moto renforcé. Puis-je le laver ?","speaker":"client"},{"text":"Oui, Jeans Care est conçu pour le denim et les vêtements contenant des fibres aramides. Vérifiez l’étiquette, retournez le pantalon et choisissez un cycle délicat, généralement jusqu’à 30 °C avec un essorage doux ; laissez sécher à l’air libre.","speaker":"seller"},{"text":"Puis-je le mettre au sèche-linge ?","speaker":"client"},{"text":"Laissez-le sécher à l’air libre et n’utilisez pas de sèche-linge. Vérifiez également l’étiquette du pantalon.","speaker":"seller"},{"text":"Jeans Care convient-il à une veste à membrane ?","speaker":"client"},{"text":"Ne le choisissez pas pour une veste à membrane. Pour les vêtements techniques, choisissez Textile Care en suivant l’étiquette d’entretien.","speaker":"seller"}],"youtube_video_id":null,"youtube_video_ids":[],"image_path":null},{"lesson_id":311,"module_sort_order":2,"sort_order":6,"title":"Mise en situation de vente : choisir l’entretien adapté à chaque vêtement","summary":"Entraînez-vous à choisir une lessive pour plusieurs types de vêtements et à répondre à une demande d’imperméabilisation.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Trois situations à mettre en pratique","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Veste à membrane, haut thermique et jean : séparez les vêtements et choisissez un produit adapté à chaque matière.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Le client souhaite « imperméabiliser » une veste avec Fabric Protect : expliquez la différence et vérifiez s’il lui faut un produit imperméabilisant distinct.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Le client ne lave qu’un haut en mérinos : présentez Merino Care et les consignes d’entretien correspondantes.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Méthode de recommandation","type":"text"}]},{"type":"paragraph","content":[{"text":"Reformulez le besoin du client avec vos propres mots, demandez la composition et la méthode de lavage, puis recommandez un produit. Expliquez son usage et ses limites. Ne proposez un produit complémentaire que s’il répond à un besoin distinct.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Objectif de l’exercice","type":"text"}]},{"type":"paragraph","content":[{"text":"À la fin de chaque situation, le vendeur doit pouvoir justifier sa recommandation par la matière et ses consignes d’entretien, plutôt que de proposer la même lessive à tous les clients.","type":"text"}]}]},"product_bullets":["Choisissez le produit selon la matière, la composition du tissu et les consignes du fabricant du vêtement.","Textile Care convient aux vêtements techniques ; Active Care aux vêtements de sport synthétiques et aux premières couches.","Merino Care et Jeans Care conviennent à différents types de fibres.","Fabric Protect contribue à la fraîcheur pendant le lavage, mais n’est pas un traitement imperméabilisant.","Ne vendez pas un kit complet si le client n’a besoin que d’un seul produit."],"key_points_title":"À retenir","conversation_title":"Échange avec le client","conversation":[{"text":"J’ai une veste à membrane, un haut thermique et un jean. Je veux une seule lessive pour tout.","speaker":"client"},{"text":"Je comprends. Choisissez une lessive différente pour chaque matière : Textile Care pour la veste, Active Care pour la première couche synthétique et Jeans Care pour le denim, en suivant chaque étiquette.","speaker":"seller"},{"text":"Fabric Protect va-t-il imperméabiliser la veste ?","speaker":"client"},{"text":"Non, cet additif contribue à la fraîcheur après lavage. Pour rendre la veste déperlante, il faut un traitement imperméabilisant distinct.","speaker":"seller"},{"text":"Je ne lave qu’un haut en mérinos. Dois-je acheter un kit ?","speaker":"client"},{"text":"Non. Merino Care suffit si l’étiquette autorise le lavage ; suivez le programme indiqué par le fabricant.","speaker":"seller"}],"youtube_video_id":null,"youtube_video_ids":[],"image_path":null},{"lesson_id":312,"module_sort_order":3,"sort_order":0,"title":"Comment entretenir des gants de moto","summary":"Déterminez si le problème concerne l’intérieur ou l’extérieur du gant, puis choisissez la méthode d’entretien adaptée.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Commencez par identifier le problème","type":"text"}]},{"type":"paragraph","content":[{"text":"Les gants associent cuir, textiles, protections, coutures et doigts difficiles d’accès. Demandez au client s’il souhaite enlever les salissures extérieures, rafraîchir l’intérieur ou entretenir du cuir sec. Ces besoins nécessitent des solutions différentes.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Vérifiez les consignes des gants","type":"text"}]},{"type":"paragraph","content":[{"text":"Tous les gants ne peuvent pas être lavés en machine ni retournés. Il est particulièrement important de vérifier les recommandations du fabricant pour les gants en cuir. Ne les faites pas tremper et ne les étirez pas si les consignes ne le prévoient pas.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Choisissez l’entretien adapté","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Odeur tenace à l’intérieur : envisagez Magiczne Rękawiczki et suivez leurs instructions.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Salissures à l’extérieur : choisissez un produit adapté à la matière du gant et aux recommandations du fabricant.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Fermeture éclair difficile à manipuler mais intacte : envisagez Zip Service.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Éraflures, décollement ou coutures décousues : un produit d’entretien ne remplace pas une réparation.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Une recommandation concise","type":"text"}]},{"type":"paragraph","content":[{"text":"Lorsque vous recommandez un produit, expliquez son usage et ses limites. Magiczne Rękawiczki rafraîchit l’intérieur ; cela ne lave pas entièrement les gants et ne les répare pas.","type":"text"}]}]},"product_bullets":["Les gants comportent des coutures, des protections et différentes matières : vérifiez leur étiquette d’entretien.","Distinguez les salissures extérieures des odeurs ou de l’humidité à l’intérieur.","Ne supposez pas que les gants peuvent être lavés en machine ou retournés.","Magiczne Rękawiczki aide à rafraîchir les zones difficiles d’accès à l’intérieur.","Les coutures endommagées ou décollées et le cuir éraflé nécessitent une réparation professionnelle."],"key_points_title":"À retenir","conversation_title":"Échange avec le client","conversation":[{"text":"Mes gants sentent mauvais, mais je ne peux pas les retourner.","speaker":"client"},{"text":"Utilisez Magiczne Rękawiczki pour rafraîchir les zones difficiles d’accès à l’intérieur. Enfilez la paire imprégnée sur vos mains et nettoyez l’intérieur en suivant les instructions.","speaker":"seller"},{"text":"Puis-je simplement les mettre en machine ?","speaker":"client"},{"text":"Uniquement si le fabricant des gants autorise le lavage en machine. Vérifiez l’étiquette : les gants peuvent comporter du cuir, des protections et des éléments collés.","speaker":"seller"},{"text":"La matière est éraflée. Le produit va-t-il la réparer ?","speaker":"client"},{"text":"Non. Un produit d’entretien ne réparera ni une éraflure ni une couture ; faites examiner les gants par un atelier.","speaker":"seller"}],"youtube_video_id":null,"youtube_video_ids":[],"image_path":null},{"lesson_id":313,"module_sort_order":3,"sort_order":1,"title":"Magiczne Rękawiczki : utilisation et démonstration","summary":"Montrez au client comment utiliser Magiczne Rękawiczki pour rafraîchir l’intérieur de ses gants.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Pourquoi utiliser Magiczne Rękawiczki","type":"text"}]},{"type":"paragraph","content":[{"text":"La paire imprégnée facilite le nettoyage des zones difficiles d’accès à l’intérieur de gants qu’il est difficile de retourner. Cette solution peut être particulièrement utile pour les gants en cuir si leurs consignes autorisent cette méthode de rafraîchissement.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Démonstration","type":"text"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Ouvrez le sachet et enfilez la paire à usage unique sur vos mains.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Glissez vos mains dans les gants de moto.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Bougez les doigts et exercez une légère pression afin que le produit atteigne l’intérieur.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Ne tirez pas sur la doublure et ne forcez pas pour retourner les gants.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Une fois l’opération terminée, retirez la paire imprégnée et lavez-vous les mains conformément aux consignes.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Ce qu’il ne faut pas promettre","type":"text"}]},{"type":"paragraph","content":[{"text":"C’est une solution pratique pour rafraîchir l’intérieur, mais elle ne remplace ni le lavage complet des gants, ni la réparation des coutures, ni l’élimination de toutes les salissures. Le client doit utiliser le produit conformément à l’emballage.","type":"text"}]}]},"product_bullets":["Le sachet contient une paire de gants imprégnés à usage unique.","Enfilez-les, glissez vos mains dans les gants de moto et bougez les doigts.","Procédez délicatement pour atteindre l’intérieur sans retourner les gants.","Cette méthode sert à rafraîchir l’intérieur ; elle ne lave pas entièrement les gants et ne les répare pas.","Après utilisation, retirez le produit et lavez-vous les mains conformément aux consignes."],"key_points_title":"À retenir","conversation_title":"Échange avec le client","conversation":[{"text":"Comment utiliser Magiczne Rękawiczki ?","speaker":"client"},{"text":"Enfilez la paire imprégnée à usage unique, glissez vos mains dans les gants de moto et bougez les doigts pour nettoyer l’intérieur.","speaker":"seller"},{"text":"Dois-je retourner les gants ?","speaker":"client"},{"text":"Non. C’est justement pour cela que vous glissez vos mains, gantées de la paire imprégnée, à l’intérieur. Ne tirez pas sur la doublure.","speaker":"seller"},{"text":"Cela remplace-t-il le lavage complet des gants ?","speaker":"client"},{"text":"Non, cette méthode sert à rafraîchir l’intérieur. Après utilisation, retirez la paire à usage unique et suivez les consignes du produit.","speaker":"seller"},{"text":"Puis-je l’utiliser avec des gants en cuir ?","speaker":"client"},{"text":"Vérifiez d’abord les recommandations du fabricant des gants et les instructions du produit, puis utilisez-le en conséquence.","speaker":"seller"}],"youtube_video_id":null,"youtube_video_ids":[],"image_path":null},{"lesson_id":314,"module_sort_order":3,"sort_order":2,"title":"Zip Service : entretien des fermetures éclair et vente complémentaire","summary":"Expliquez l’utilité de Zip Service pour les fermetures éclair et distinguez l’entretien de la réparation.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Pour une fermeture éclair fonctionnelle mais qui coince","type":"text"}]},{"type":"paragraph","content":[{"text":"Zip Service est un produit d’entretien pour les fermetures éclair qui coulissent difficilement mais ne sont pas endommagées mécaniquement. Demandez si le problème vient du frottement ou si des dents manquent ou si le curseur est tordu.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Comment montrer son utilisation","type":"text"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Nettoyez les salissures visibles sur la fermeture éclair.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Appliquez une petite quantité de Zip Service sur les dents, conformément à l’étiquette.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Faites coulisser plusieurs fois le curseur pour répartir le produit.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Essuyez l’excédent avec un chiffon propre et sec.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Vérifiez le coulissement sans forcer.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Un produit complémentaire","type":"text"}]},{"type":"paragraph","content":[{"text":"Vous pouvez le proposer en complément pour un vêtement, des chaussures ou un sac si le client signale un problème de fermeture éclair. Ne promettez pas qu’il réparera des dents cassées, un tissu déchiré ou un curseur endommagé.","type":"text"}]}]},"product_bullets":["Zip Service facilite le coulissement des fermetures éclair métalliques et plastiques en bon état.","Appliquez-en une petite quantité sur les dents et faites coulisser plusieurs fois le curseur.","Essuyez l’excédent avec un chiffon propre et sec.","Il peut être utile pour les fermetures éclair de vêtements, chaussures et sacs.","Il ne réparera ni les dents cassées ni un curseur endommagé."],"key_points_title":"À retenir","conversation_title":"Échange avec le client","conversation":[{"text":"La fermeture éclair de ma veste est difficile à ouvrir. Zip Service peut-il aider ?","speaker":"client"},{"text":"Si le curseur et les dents sont intacts, Zip Service peut contribuer à l’entretien de la fermeture éclair. Appliquez-en une petite quantité sur les dents, faites coulisser plusieurs fois le curseur, puis essuyez l’excédent.","speaker":"seller"},{"text":"Quelle quantité dois-je appliquer ?","speaker":"client"},{"text":"Une petite quantité, conformément à l’étiquette. Après l’avoir répartie, essuyez les résidus avec un chiffon propre et sec.","speaker":"seller"},{"text":"Une dent est cassée. Le produit peut-il la réparer ?","speaker":"client"},{"text":"Non. Zip Service entretient les fermetures éclair fonctionnelles, mais ne répare ni les dents ni les curseurs endommagés.","speaker":"seller"}],"youtube_video_id":null,"youtube_video_ids":[],"image_path":null},{"lesson_id":315,"module_sort_order":4,"sort_order":0,"title":"Par où commencer l’entretien de la moto","summary":"Identifiez le type de salissures et choisissez une routine d’entretien simple pour la moto.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Commencez par évaluer la situation","type":"text"}]},{"type":"paragraph","content":[{"text":"Une moto qui revient d’une sortie par temps sec ne s’entretient pas comme une moto qui a roulé sous la pluie ou dans la boue. Demandez le type et l’importance des salissures, ainsi que l’accès à l’eau, à un nettoyeur haute pression et à un garage. Vous pourrez ainsi recommander un ordre d’utilisation simple plutôt qu’un assortiment de produits au hasard.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Rafraîchissement rapide","type":"text"}]},{"type":"paragraph","content":[{"text":"Pour éliminer une fine poussière entre deux lavages complets, Wash & Ride et un chiffon microfibre doux et propre peuvent suffire. Ne frottez pas avec cette méthode une épaisse couche de sable, qui pourrait rayer la peinture.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Lavage complet","type":"text"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Pour les insectes séchés, envisagez Bug Killer comme étape de prélavage.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Pour le lavage principal, utilisez Moto Wash ou une solution Power Powder préparée.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Pour les dépôts sur les jantes, choisissez Wheelixir et l’accessoire adapté.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Rincez et séchez la moto conformément aux instructions des produits.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Sur une surface propre et froide, vous pouvez appliquer Ceramic Detailer en finition.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Expliquez les limites","type":"text"}]},{"type":"paragraph","content":[{"text":"N’appliquez pas les produits sur des éléments chauds et ne les laissez pas sécher sur la surface si les consignes l’interdisent. Ceramic Detailer ne remplace ni le lavage ni un traitement professionnel durable.","type":"text"}]}]},"product_bullets":["Identifiez la poussière, les insectes, les résidus de frein, la graisse ou la boue épaisse.","Demandez si le client a accès à l’eau et dans quelles conditions il nettoiera la moto.","Wash & Ride convient pour éliminer une fine poussière entre deux lavages complets.","Bug Killer, Moto Wash et Wheelixir répondent à des étapes et des types de salissures différents.","Utilisez Ceramic Detailer après le lavage, sur une surface propre et froide."],"key_points_title":"À retenir","conversation_title":"Échange avec le client","conversation":[{"text":"Ma moto est juste poussiéreuse et je n’ai que cinq minutes. Que me conseillez-vous ?","speaker":"client"},{"text":"Pour une fine poussière entre deux lavages complets, utilisez Wash & Ride et un chiffon microfibre propre. S’il y a beaucoup de sable ou de boue, rincez et lavez d’abord la moto.","speaker":"seller"},{"text":"Puis-je utiliser un seul produit pour nettoyer les insectes et les jantes ?","speaker":"client"},{"text":"Choisissez Bug Killer pour les insectes, Wheelixir pour les dépôts sur les jantes et Moto Wash pour laver toute la moto.","speaker":"seller"},{"text":"Puis-je commencer alors que le moteur est chaud ?","speaker":"client"},{"text":"Attendez que la moto refroidisse. N’appliquez pas de produits sur des éléments chauds.","speaker":"seller"}],"youtube_video_id":null,"youtube_video_ids":[],"image_path":null},{"lesson_id":316,"module_sort_order":4,"sort_order":1,"title":"Wash & Ride : nettoyage de la moto","summary":"Montrez quand Wash & Ride est une solution pratique et comment l’utiliser sans risque sur des salissures légères.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Nettoyage rapide sans tuyau","type":"text"}]},{"type":"paragraph","content":[{"text":"Wash & Ride est pratique lorsque la moto a besoin d’un léger rafraîchissement et que le client n’a ni tuyau ni seau à disposition. Il complète les lavages réguliers, mais ne les remplace pas en présence d’une épaisse couche de boue, de sable ou de dépôts importants.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Comment l’utiliser","type":"text"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Assurez-vous que la surface est froide.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Vaporisez le produit sur une petite zone conformément à l’étiquette.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Retirez délicatement les salissures avec un chiffon microfibre doux et propre, sans appuyer.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Retournez le chiffon ou remplacez-le dès qu’il est sale.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"En cas de salissures importantes, interrompez le nettoyage et prévoyez un lavage complet.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Pour qui ?","type":"text"}]},{"type":"paragraph","content":[{"text":"Ce produit est utile entre deux lavages, au garage, sur un parking ou en déplacement. Il aide à rafraîchir l’aspect de la moto et laisse une légère couche protectrice, conformément aux indications du fabricant.","type":"text"}]}]},"product_bullets":["Wash & Ride est conçu pour la poussière et les salissures légères entre deux lavages complets.","Utilisez-le sur une surface froide et retirez délicatement les salissures avec un chiffon microfibre propre.","Il peut être utile au garage, sur un parking ou en voyage.","Ne l’utilisez pas pour frotter une épaisse couche de sable ou de boue.","En cas de salissures importantes, rincez la moto et procédez à un lavage complet."],"key_points_title":"À retenir","conversation_title":"Échange avec le client","conversation":[{"text":"Je n’ai ni tuyau ni seau. Comment rafraîchir ma moto ?","speaker":"client"},{"text":"Si les salissures sont légères, utilisez Wash & Ride et un chiffon microfibre doux et propre. Travaillez sur une surface froide et essuyez sans appuyer.","speaker":"seller"},{"text":"Est-ce que cela convient après une sortie dans la boue ?","speaker":"client"},{"text":"Ne l’utilisez pas sur une épaisse couche de boue ou de sable. Rincez d’abord les salissures et effectuez un lavage complet.","speaker":"seller"},{"text":"Puis-je l’utiliser sur un moteur chaud ?","speaker":"client"},{"text":"Non. Attendez que les éléments refroidissent et utilisez le produit conformément à l’étiquette.","speaker":"seller"}],"youtube_video_id":"aqzUkc7BheU","youtube_video_ids":["aqzUkc7BheU"],"image_path":null},{"lesson_id":317,"module_sort_order":4,"sort_order":2,"title":"Power Powder : préparation et utilisation","summary":"Expliquez comment préparer une solution Power Powder et choisir la version adaptée à l’utilisation.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Préparez le concentré avant utilisation","type":"text"}]},{"type":"paragraph","content":[{"text":"Power Powder est une poudre à dissoudre dans l’eau conformément aux instructions de la version concernée. Ne la saupoudrez pas directement sur la moto et ne supposez pas que tous les sachets s’utilisent de la même manière.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Choisissez le produit adapté","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Moto Wash est destiné au lavage principal.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Bug Killer aide à éliminer les insectes et les salissures organiques lors du prélavage.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Wheelixir est conçu pour les jantes et les dépôts qui les entourent.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Préparer une solution","type":"text"}]},{"type":"paragraph","content":[{"text":"Le Shaker de 500 ml facilite le dosage de l’eau et la préparation d’une portion. Lisez le dosage sur l’emballage, dissolvez la poudre dans la quantité d’eau indiquée et utilisez la solution conformément aux instructions du fabricant. Ne considérez pas les produits comme interchangeables.","type":"text"}]}]},"product_bullets":["Une fois dissous, Power Powder Moto Wash s’utilise pour le lavage principal de la moto.","Le conditionnement de Moto Wash contient trois sachets ; respectez les consignes d’utilisation.","Bug Killer et Wheelixir sont des concentrés distincts destinés à des usages différents.","Le Shaker de 500 ml peut servir à préparer une solution.","N’indiquez pas un même dosage de dilution pour toutes les poudres."],"key_points_title":"À retenir","conversation_title":"Échange avec le client","conversation":[{"text":"Puis-je saupoudrer la poudre directement sur le carénage ?","speaker":"client"},{"text":"Non. Dissolvez d’abord Power Powder dans l’eau conformément aux instructions de l’emballage, puis utilisez la solution préparée.","speaker":"seller"},{"text":"Tous les sachets se diluent-ils de la même manière ?","speaker":"client"},{"text":"Non. Moto Wash, Bug Killer et Wheelixir ont des usages différents ; vérifiez séparément le dosage de chacun.","speaker":"seller"},{"text":"À quoi sert la bouteille Shaker ?","speaker":"client"},{"text":"Elle permet de mesurer plus facilement l’eau et de préparer une portion de solution, si ce mode d’utilisation est autorisé par les consignes.","speaker":"seller"}],"youtube_video_id":null,"youtube_video_ids":[],"image_path":null},{"lesson_id":318,"module_sort_order":4,"sort_order":3,"title":"Bug Killer et Wheelixir : éliminer les salissures","summary":"Choisissez Bug Killer pour les salissures organiques et Wheelixir pour les dépôts sur les jantes.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Deux problèmes différents, deux produits","type":"text"}]},{"type":"paragraph","content":[{"text":"Bug Killer sert au prétraitement des insectes, des fientes d’oiseaux et d’autres salissures organiques. Wheelixir cible les dépôts sur les jantes et autour des étriers de frein. Aucun des deux ne remplace le lavage complet de la moto.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Comment les utiliser","type":"text"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Préparez le concentré Power Powder conformément à son étiquette.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Appliquez Bug Killer sur les salissures avant le lavage principal.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Respectez le temps de pose indiqué, puis rincez ou poursuivez le lavage.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Appliquez Wheelixir sur la jante et utilisez une brosse adaptée si nécessaire.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Rincez soigneusement la jante et les salissures décollées.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Répondez au besoin du client","type":"text"}]},{"type":"paragraph","content":[{"text":"Si le carénage est couvert d’insectes, recommandez un produit pour les salissures organiques. Si des dépôts sombres se trouvent sur la jante, choisissez un nettoyant pour jantes. Vérifiez la compatibilité et travaillez sur une surface froide.","type":"text"}]}]},"product_bullets":["Utilisez Bug Killer en prélavage contre les insectes et les salissures organiques.","Choisissez Wheelixir pour les jantes et les résidus de frein.","Dissolvez au préalable les versions Power Powder conformément à leur étiquette.","Laissez agir Bug Killer pendant la durée indiquée et ne le laissez pas sécher.","Après l’utilisation de Wheelixir, rincez soigneusement les jantes et choisissez une brosse adaptée à leur surface."],"key_points_title":"À retenir","conversation_title":"Échange avec le client","conversation":[{"text":"Des insectes ont séché sur mon carénage. Que dois-je utiliser ?","speaker":"client"},{"text":"Avant le lavage, appliquez Bug Killer sur les salissures et laissez agir le temps indiqué sur l’étiquette. Rincez ensuite et lavez la moto.","speaker":"seller"},{"text":"Et que dois-je utiliser pour éliminer les dépôts sombres sur la jante ?","speaker":"client"},{"text":"Utilisez Wheelixir pour les dépôts sur les jantes. Si nécessaire, choisissez une brosse adaptée et rincez soigneusement après le nettoyage.","speaker":"seller"},{"text":"Puis-je utiliser Power Powder sans le diluer ?","speaker":"client"},{"text":"Non. Dissolvez d’abord la poudre dans l’eau selon le dosage indiqué sur l’emballage.","speaker":"seller"}],"youtube_video_id":"WsgHV1M274Y","youtube_video_ids":["WsgHV1M274Y"],"image_path":null},{"lesson_id":319,"module_sort_order":4,"sort_order":4,"title":"Ceramic Detailer : finition et protection","summary":"Présentez Ceramic Detailer comme la touche de finition d’une moto propre.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"L’étape de finition après le lavage","type":"text"}]},{"type":"paragraph","content":[{"text":"Ceramic Detailer sert à parfaire une moto propre. Il peut rehausser la brillance et la couleur, et produire un effet déperlant. Ce n’est ni un nettoyant pour salissures tenaces ni un traitement céramique professionnel durant plusieurs années.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Démonstration","type":"text"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Travaillez sur une surface froide, à l’abri du soleil direct.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Vaporisez une petite quantité sur un chiffon microfibre, ou suivez les instructions de l’étiquette.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Appliquez le produit par petites zones plutôt que d’imbiber une grande surface.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Lustrez avec une face propre et sèche du chiffon ou avec un second chiffon microfibre.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Vérifiez l’absence de traces et ne recommencez que conformément aux instructions.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Fixez des attentes claires","type":"text"}]},{"type":"paragraph","content":[{"text":"Le Detailer contribue à l’entretien courant et peut limiter l’adhérence des salissures. La moto doit toujours être lavée ; le produit ne remplace ni un revêtement durable ni une rénovation de la peinture.","type":"text"}]}]},"product_bullets":["Utilisez Ceramic Detailer sur une surface propre, après le lavage ou un léger rafraîchissement.","Utilisé conformément à sa destination, il contribue à la brillance et à l’effet déperlant.","C’est un detailer rapide, et non un traitement céramique professionnel durant plusieurs années.","Travaillez sur une surface froide, à l’abri du soleil direct.","Appliquez-le avec un chiffon microfibre par petites zones, puis lustrez avec une face sèche."],"key_points_title":"À retenir","conversation_title":"Échange avec le client","conversation":[{"text":"Ceramic Detailer est-il un revêtement qui dure plusieurs années ?","speaker":"client"},{"text":"Non. C’est un detailer rapide destiné à la finition et à l’entretien courant, pas un revêtement céramique professionnel durable.","speaker":"seller"},{"text":"Puis-je l’appliquer sur une moto sale ?","speaker":"client"},{"text":"Lavez et séchez d’abord la moto. Appliquez le Detailer sur une surface propre et froide, par petites zones.","speaker":"seller"},{"text":"N’aurai-je plus besoin de laver la moto après l’avoir utilisé ?","speaker":"client"},{"text":"Vous devrez toujours laver la moto. Le Detailer aide à parfaire la surface, mais ne remplace pas le lavage.","speaker":"seller"}],"youtube_video_id":"mofx3RgqndY","youtube_video_ids":["mofx3RgqndY"],"image_path":null},{"lesson_id":320,"module_sort_order":4,"sort_order":5,"title":"Brosses et chiffons microfibre : choisir les accessoires","summary":"Choisissez un chiffon microfibre et une brosse adaptés à chaque étape, et évitez de transférer les salissures d’une surface à l’autre.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Choisissez les accessoires selon la surface","type":"text"}]},{"type":"paragraph","content":[{"text":"Même un bon produit ne remplace pas l’outil adapté. Un chiffon microfibre doux enlève les salissures légères et sert à la finition. Utilisez des brosses différentes pour les jantes, la chaîne et les détails difficiles d’accès.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Séparez les zones propres et sales","type":"text"}]},{"type":"paragraph","content":[{"text":"Ne transférez pas la graisse de la chaîne sur la peinture, les carénages ou l’écran. Les dépôts des jantes peuvent également rayer les surfaces délicates. Lorsque le chiffon ramasse des salissures, utilisez une face propre ou changez de chiffon.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Choisir des accessoires avec un budget limité","type":"text"}]},{"type":"paragraph","content":[{"text":"Si le client commence de zéro, demandez-lui quel est son principal besoin. Un chiffon microfibre doux et propre est polyvalent pour de nombreuses tâches légères. Ne recommandez une brosse supplémentaire que pour une zone précise.","type":"text"}]}]},"product_bullets":["Utilisez des chiffons microfibre propres et doux pour le nettoyage léger et la finition.","Utilisez des chiffons distincts pour les différentes étapes et surfaces.","N’utilisez pas une brosse pour chaîne sur la peinture ou l’écran.","Un pinceau de detailing permet d’atteindre les zones difficiles d’accès.","Choisissez une brosse pour jantes adaptée à la surface afin d’éviter de rayer la peinture."],"key_points_title":"À retenir","conversation_title":"Échange avec le client","conversation":[{"text":"Un seul chiffon microfibre suffit-il pour toute la moto ?","speaker":"client"},{"text":"Utilisez des chiffons microfibre propres et distincts pour chaque étape afin de ne pas transférer sur la peinture les salissures des jantes et de la transmission.","speaker":"seller"},{"text":"Puis-je utiliser indifféremment un pinceau de detailing et une brosse pour chaîne ?","speaker":"client"},{"text":"Non. La brosse pour chaîne est destinée à la transmission ; le pinceau de detailing sert aux détails difficiles d’accès. N’utilisez pas la brosse pour chaîne sur la peinture.","speaker":"seller"},{"text":"Par quoi commencer si mon budget est limité ?","speaker":"client"},{"text":"Commencez par un chiffon microfibre doux et propre. Ajoutez une brosse uniquement pour une zone précise difficile à nettoyer.","speaker":"seller"}],"youtube_video_id":"xYSzhwsyZjs","youtube_video_ids":["xYSzhwsyZjs","sqLlcgn_lQA","FvYwpb_PqlA"],"image_path":null},{"lesson_id":321,"module_sort_order":5,"sort_order":0,"title":"Quelles salissures apparaissent lors d’une sortie tout-terrain ?","summary":"Identifiez les salissures tout-terrain et choisissez Mud Breaker ou Dirt Finisher selon leur importance.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Pourquoi le tout-terrain nécessite une approche différente","type":"text"}]},{"type":"paragraph","content":[{"text":"Après une sortie tout-terrain, la moto peut être couverte de boue, de sable, de poussière et de résidus de flaques. Les particules sèches sont abrasives : ne commencez pas par essuyer toute la moto avec un chiffon microfibre. Évaluez d’abord la quantité de salissures et préparez un nettoyage sans risque.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Choisissez l’une des deux méthodes","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Boue épaisse et séchée : utilisez Mud Breaker conformément aux consignes, puis rincez soigneusement.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Poussière légère après une sortie par temps sec : Dirt Finisher et un chiffon microfibre propre peuvent suffire.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Sable abondant : retirez-le sans risque avant d’essuyer la surface.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Questions à poser avant de recommander","type":"text"}]},{"type":"paragraph","content":[{"text":"Demandez au client sur quel type de terrain il roule et s’il a accès à de l’eau. Mud Breaker doit être rincé. Ne promettez pas qu’il empêchera la boue de se déposer à l’avenir ou rendra la moto autonettoyante.","type":"text"}]}]},"product_bullets":["La boue, le sable et la poussière nécessitent une méthode différente des salissures légères de la route.","N’essuyez pas une épaisse couche de sable sec : les particules peuvent rayer la surface.","Mud Breaker ramollit les salissures importantes et doit être rincé soigneusement.","Dirt Finisher convient à la poussière légère et à la finition.","Demandez si de l’eau est disponible et travaillez sur une surface froide."],"key_points_title":"À retenir","conversation_title":"Échange avec le client","conversation":[{"text":"Je rentre du motocross avec une épaisse couche de boue. Puis-je essuyer la moto tout de suite ?","speaker":"client"},{"text":"N’essuyez pas à sec une épaisse couche de boue ou de sable. Ramollissez les salissures avec Mud Breaker et rincez soigneusement.","speaker":"seller"},{"text":"Après une sortie par temps sec, il n’y a que de la poussière. Dois-je faire un lavage complet ?","speaker":"client"},{"text":"Dirt Finisher et un chiffon microfibre propre peuvent suffire pour une poussière légère. S’il y a beaucoup de sable, retirez-le d’abord sans risque.","speaker":"seller"},{"text":"Je n’ai pas accès à de l’eau après ma sortie.","speaker":"client"},{"text":"Mud Breaker doit être rincé : utilisez-le donc dans un endroit où vous disposez d’eau. Choisissez une méthode adaptée aux salissures et aux conditions.","speaker":"seller"}],"youtube_video_id":null,"youtube_video_ids":[],"image_path":null},{"lesson_id":322,"module_sort_order":5,"sort_order":1,"title":"Mud Breaker : éliminer la boue","summary":"Apprenez à utiliser Mud Breaker sans risque sur les salissures importantes et à bien rincer les résidus.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Un produit pour les salissures importantes","type":"text"}]},{"type":"paragraph","content":[{"text":"Mud Breaker aide à ramollir la boue, le sable et les salissures minérales après une sortie tout-terrain. Expliquez qu’il prépare les salissures au rinçage : ce n’est pas une méthode de nettoyage sans eau.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Comment l’utiliser","type":"text"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Attendez que la moto refroidisse.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Évaluez la quantité de boue et assurez-vous de disposer d’eau.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Appliquez le produit sur les éléments sales conformément à l’étiquette.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Laissez agir pendant la durée indiquée, sans le laisser sécher.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Rincez soigneusement les salissures et le produit à l’eau.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Brosses et entretien complémentaire","type":"text"}]},{"type":"paragraph","content":[{"text":"Une brosse adaptée peut aider à atteindre les zones difficiles, mais utilisez-la délicatement et ne frottez pas à sec. Après le rinçage, le client peut déterminer s’il souhaite appliquer Dirt Finisher en finition.","type":"text"}]}]},"product_bullets":["Mud Breaker est conçu pour les boues épaisses et les salissures minérales.","Assurez-vous que la moto a refroidi et préparez de l’eau pour le rinçage.","Utilisez-le sur une surface sale conformément à l’étiquette.","Ne laissez pas sécher le produit ; si nécessaire, brossez délicatement.","Après le temps d’action, rincez soigneusement le véhicule."],"key_points_title":"À retenir","conversation_title":"Échange avec le client","conversation":[{"text":"Mud Breaker éliminera-t-il la boue séchée du bras oscillant ?","speaker":"client"},{"text":"Oui, il ramollit la boue pour faciliter son rinçage. Vaporisez sur la surface sale, laissez agir un court instant et rincez soigneusement ; pour les dépôts importants, utilisez délicatement une brosse si nécessaire.","speaker":"seller"},{"text":"Je n’ai pas de tuyau. Puis-je l’utiliser sur le parking ?","speaker":"client"},{"text":"Non, sauf si vous pouvez le rincer. Utilisez Mud Breaker dans un endroit où vous disposez d’eau, car le véhicule doit être rincé soigneusement après le temps d’action.","speaker":"seller"},{"text":"Puis-je laisser le produit sécher ?","speaker":"client"},{"text":"Non. Rincez-le avant qu’il ne sèche et ne l’appliquez pas sur des éléments chauds.","speaker":"seller"}],"youtube_video_id":null,"youtube_video_ids":[],"image_path":null},{"lesson_id":323,"module_sort_order":5,"sort_order":2,"title":"Dirt Finisher : finition et entretien","summary":"Expliquez comment utiliser Dirt Finisher pour les salissures légères et après un lavage plus intensif.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Entretien léger des motos tout-terrain","type":"text"}]},{"type":"paragraph","content":[{"text":"Dirt Finisher n’est pas une autre version de Mud Breaker. Il aide à éliminer les salissures légères et à parfaire une surface déjà propre. En cas de boue épaisse, utilisez-le uniquement après avoir ramolli puis rincé les salissures.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Comment l’utiliser","type":"text"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Vérifiez que la surface est froide et qu’elle ne présente pas une épaisse couche de sable.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Agitez le flacon conformément aux consignes.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Vaporisez une petite quantité sur la zone choisie.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Retirez délicatement les salissures légères avec un chiffon microfibre propre.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Changez de chiffon dès qu’il ramasse du sable ou de la boue.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Adaptez le produit à l’importance des salissures","type":"text"}]},{"type":"paragraph","content":[{"text":"Dirt Finisher peut suffire à lui seul pour une fine poussière après une sortie sur gravier. En présence d’une épaisse couche d’argile, utilisez d’abord Mud Breaker et rincez. La finition peut faciliter l’entretien ultérieur, mais elle n’élimine pas les salissures.","type":"text"}]}]},"product_bullets":["Dirt Finisher est destiné au nettoyage léger et à la finition.","En présence de boue épaisse, utilisez d’abord Mud Breaker et rincez soigneusement.","Avant l’utilisation, retirez le sable grossier et vérifiez que la surface est froide.","Agitez le flacon et travaillez par petites zones.","Retirez les salissures avec un chiffon microfibre propre et remplacez-le lorsqu’il est très sale."],"key_points_title":"À retenir","conversation_title":"Échange avec le client","conversation":[{"text":"Dois-je acheter Mud Breaker et Dirt Finisher ensemble ?","speaker":"client"},{"text":"Non. Dirt Finisher suffit pour une poussière légère. En cas de boue épaisse, utilisez d’abord Mud Breaker et rincez ; ajoutez le produit de finition uniquement si nécessaire.","speaker":"seller"},{"text":"Dirt Finisher peut-il éliminer une épaisse couche d’argile ?","speaker":"client"},{"text":"Non. Ramollissez d’abord la boue avec Mud Breaker et rincez-la. Dirt Finisher est conçu pour un nettoyage plus léger et la finition.","speaker":"seller"},{"text":"Puis-je l’utiliser pour essuyer une grande quantité de sable ?","speaker":"client"},{"text":"Retirez d’abord le sable grossier. Ne frottez pas les particules sur la surface avec un chiffon microfibre : elles pourraient la rayer.","speaker":"seller"}],"youtube_video_id":null,"youtube_video_ids":[],"image_path":null},{"lesson_id":324,"module_sort_order":5,"sort_order":3,"title":"Comment choisir un Off-Road Kit","summary":"Choisissez un kit d’entretien tout-terrain adapté au style de conduite, à l’importance des salissures et à l’accès à l’eau.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Demandez au client ce qu’il entend par « kit »","type":"text"}]},{"type":"paragraph","content":[{"text":"Le client peut parler d’un coffret prêt à l’emploi ou d’un ensemble de produits d’entretien. Demandez quel véhicule il utilise, quelles salissures il rencontre le plus souvent et s’il a accès à de l’eau après sa sortie. Tant que le produit précis n’est pas confirmé, présentez la solution comme un système en deux étapes.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Adaptez la recommandation au pilote","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Motocross sur une piste boueuse : Mud Breaker, rinçage et Dirt Finisher si nécessaire.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Enduro sur gravier sec : Dirt Finisher pour une poussière légère.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Quad ou VTT dans une boue épaisse : choisissez le produit adapté et vérifiez les consignes d’entretien du véhicule.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Pas d’accès à l’eau : prévoyez le nettoyage dans un endroit où vous pourrez rincer correctement le véhicule.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Accessoires et choix des essentiels","type":"text"}]},{"type":"paragraph","content":[{"text":"Un chiffon microfibre doux et propre est utile pour la finition ; une brosse adaptée permet d’atteindre les zones difficiles. N’ajoutez pas de produits sans nécessité. Recommandez d’abord le minimum qui répond au besoin, puis présentez la deuxième étape comme une option.","type":"text"}]}]},"product_bullets":["Demandez au client s’il pratique le motocross, l’enduro, le quad ou le VTT.","Pour la boue épaisse, recommandez Mud Breaker et un accès à l’eau pour le rinçage.","Pour une poussière légère, le client peut commencer par Dirt Finisher.","Ne recommandez un chiffon microfibre ou une brosse supplémentaire qu’en cas de besoin réel.","Ne présentez pas Off-Road Kit comme un coffret précis prêt à l’emploi sans avoir vérifié le produit."],"key_points_title":"À retenir","conversation_title":"Échange avec le client","conversation":[{"text":"Je veux un kit pour l’enduro sans acheter cinq produits différents. De quoi ai-je besoin au minimum ?","speaker":"client"},{"text":"Si vous rencontrez surtout de la boue épaisse et disposez d’eau pour rincer, commencez par Mud Breaker. Ajoutez Dirt Finisher uniquement si vous souhaitez aussi parfaire la surface propre.","speaker":"seller"},{"text":"Je roule surtout sur du gravier sec. Ai-je besoin des deux produits ?","speaker":"client"},{"text":"Non. Pour une poussière légère, commencez par Dirt Finisher et un chiffon microfibre propre.","speaker":"seller"},{"text":"Off-Road Kit est-il un coffret prêt à l’emploi ?","speaker":"client"},{"text":"Vérifions d’abord les options actuellement disponibles à la vente. Si vous parlez d’un kit d’entretien, je peux vous recommander Mud Breaker et Dirt Finisher comme deux étapes distinctes.","speaker":"seller"}],"youtube_video_id":null,"youtube_video_ids":[],"image_path":null},{"lesson_id":325,"module_sort_order":6,"sort_order":0,"title":"Comment cerner les besoins du client","summary":"Posez des questions qui révèlent les besoins du client et permettent de formuler une recommandation simple.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"La vente commence par l’écoute","type":"text"}]},{"type":"paragraph","content":[{"text":"Un client peut décrire son problème sans connaître le nom des produits : « Je cherche quelque chose pour mon casque » ou « Ma veste sent mauvais ». Votre rôle consiste à préciser son besoin, et non à énumérer immédiatement les produits disponibles.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Cinq questions utiles","type":"text"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Que souhaitez-vous nettoyer ou protéger ?","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Quel est le principal problème : insectes, poussière, boue, transpiration ou entretien ?","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"De quelle matière est fait le vêtement ou la surface ?","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Où utiliserez-vous le produit et aurez-vous accès à de l’eau ?","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"S’agit-il d’un besoin ponctuel ou d’un entretien régulier ?","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Des réponses à la recommandation","type":"text"}]},{"type":"paragraph","content":[{"text":"Vous n’avez pas besoin de poser toutes les questions. Choisissez celles qui influencent le choix du produit. Reformulez le problème avec vos propres mots, proposez une solution, expliquez son utilisation et mentionnez une limite importante. Ne suggérez un produit complémentaire que s’il répond à un besoin précis dans le processus.","type":"text"}]}]},"product_bullets":["Demandez au client ce qu’il souhaite nettoyer ou protéger.","Identifiez le problème précis : insectes, poussière, boue, odeur ou entretien.","Vérifiez la matière, les conditions d’utilisation et la fréquence d’entretien.","Résumez le problème avec vos propres mots avant de recommander un produit.","Présentez une ou deux solutions adaptées et expliquez leur utilisation."],"key_points_title":"À retenir","conversation_title":"Échange avec le client","conversation":[{"text":"Je cherche un bon produit de nettoyage. Que me conseillez-vous ?","speaker":"client"},{"text":"Commençons par préciser ce que vous souhaitez nettoyer : un casque, un vêtement ou une moto. Quel problème voulez-vous résoudre : des insectes, des salissures, une odeur ou l’entretien d’une matière ?","speaker":"seller"},{"text":"C’est l’écran du casque, avec des insectes séchés.","speaker":"client"},{"text":"Dans ce cas, commencez par Helmet Gel pour ramollir les insectes. Vous pourrez ensuite parfaire l’écran propre avec Helmet Detailer.","speaker":"seller"},{"text":"Le client demande tout de suite uniquement le prix. Que dois-je répondre ?","speaker":"client"},{"text":"Indiquez le prix si vous le connaissez, puis demandez brièvement à quoi le produit servira. Vous pourrez ainsi trouver la bonne option sans pousser un achat inutile.","speaker":"seller"}],"youtube_video_id":null,"youtube_video_ids":[],"image_path":null},{"lesson_id":326,"module_sort_order":6,"sort_order":1,"title":"Comment recommander des kits plutôt que des produits à l’unité","summary":"Présentez l’intérêt du kit en expliquant les étapes d’entretien qu’il comprend, et choisissez un format adapté à son utilisation.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Présentez le processus, pas seulement le prix","type":"text"}]},{"type":"paragraph","content":[{"text":"Un kit est plus facile à comprendre lorsque le client sait quelles étapes il couvre. Pour les vêtements en cuir, il peut s’agir du nettoyage, de l’entretien du cuir et du rafraîchissement de l’intérieur. Pour un casque, tenez compte du nettoyage des surfaces extérieures et choisissez un format pratique à la maison ou en déplacement.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Choisissez un kit adapté à la situation","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Envisagez Leather Care Kit pour une personne qui a besoin de plusieurs étapes d’entretien du cuir.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Trip Kit est pratique en voyage.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"GIGA peut être pratique pour un entretien régulier à la maison ou pour plusieurs casques.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Si le client possède déjà des accessoires, recommandez uniquement le produit qui lui manque.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Vérifiez le besoin du client","type":"text"}]},{"type":"paragraph","content":[{"text":"Un kit n’est pas toujours le meilleur choix. Demandez au client ce qu’il possède déjà, à quelle fréquence il entretient son équipement et où il l’utilisera. La valeur d’un kit tient à sa praticité et à son adéquation au besoin, pas simplement au nombre d’articles.","type":"text"}]}]},"product_bullets":["Expliquez les étapes : nettoyage, entretien ou finition, puis entretien de l’intérieur le cas échéant.","Leather Care Kit peut réunir l’entretien du cuir extérieur et le rafraîchissement de l’intérieur.","Trip Kit est adapté aux déplacements ; GIGA convient à l’entretien régulier du casque.","Un client qui possède déjà certains produits peut acheter uniquement ce qui lui manque.","Terminez en demandant comment et à quelle fréquence les produits seront utilisés."],"key_points_title":"À retenir","conversation_title":"Échange avec le client","conversation":[{"text":"Pourquoi aurais-je besoin d’un kit si je n’ai besoin que d’un seul produit ?","speaker":"client"},{"text":"Si vous possédez déjà les autres produits et accessoires, achetez uniquement celui qui vous manque. Le kit est intéressant lorsque vous souhaitez suivre toutes les étapes d’entretien.","speaker":"seller"},{"text":"Je cherche quelque chose pour entretenir mon casque en voyage. Que choisir ?","speaker":"client"},{"text":"Choisissez Trip Kit, qui comprend des flacons compacts faciles à emporter. Pour un nettoyage régulier à la maison, comparez-le avec GIGA.","speaker":"seller"},{"text":"Le kit plus grand est-il plus efficace ?","speaker":"client"},{"text":"Non, les kits diffèrent par leur format et leur contenu. Choisissez selon la fréquence de nettoyage et le nombre de casques.","speaker":"seller"}],"youtube_video_id":null,"youtube_video_ids":[],"image_path":null},{"lesson_id":327,"module_sort_order":6,"sort_order":2,"title":"Comment développer les ventes grâce aux produits complémentaires","summary":"Proposez au maximum un produit complémentaire pertinent pour accompagner la démarche d’entretien déjà engagée par le client.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Une vente complémentaire pertinente","type":"text"}]},{"type":"paragraph","content":[{"text":"Un produit complémentaire est utile lorsqu’il complète une autre étape du processus. Un client qui achète un nettoyant peut aussi avoir besoin d’un soin à appliquer ensuite ou d’un chiffon adapté. S’il possède déjà cet article, inutile de le lui proposer à nouveau.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Des associations naturelles","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Helmet Gel → Helmet Detailer et un chiffon adapté.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Leather Cleaner → Leather Milk après le nettoyage et le séchage du cuir.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Textile Care → Fabric Protect comme additif pour la fraîcheur, et non pour l’imperméabilisation.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Moto Wash ou Bug Killer → Ceramic Detailer après le lavage et le rinçage.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Mud Breaker → Dirt Finisher après un lavage intensif si le client souhaite une étape de finition.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Proposez sans insister","type":"text"}]},{"type":"paragraph","content":[{"text":"Demandez quelle étape manque et proposez au maximum un complément pertinent. Par exemple : « Le nettoyant éliminera les salissures du cuir. Si vous n’avez pas de produit pour l’entretenir après le nettoyage, je peux vous présenter Leather Milk. » Si le client refuse, respectez sa décision.","type":"text"}]}]},"product_bullets":["Un complément doit répondre à l’étape d’entretien suivante, et non simplement augmenter le panier.","Helmet Gel peut être associé au Detailer et à un chiffon adapté.","Leather Milk complète Leather Cleaner une fois le cuir sec.","Textile Care peut être associé à Fabric Protect comme additif de lavage.","Respectez le refus du client et ne proposez pas un produit qu’il possède déjà."],"key_points_title":"À retenir","conversation_title":"Échange avec le client","conversation":[{"text":"Pourquoi me recommandez-vous un deuxième produit ?","speaker":"client"},{"text":"Un complément est pertinent s’il répond à une étape nécessaire : par exemple, Leather Milk entretient le cuir après le nettoyage. Si vous en possédez déjà, inutile d’en acheter un autre.","speaker":"seller"},{"text":"Non merci, j’ai déjà ce produit.","speaker":"client"},{"text":"Bien sûr. Restons-en à ce dont vous avez réellement besoin.","speaker":"seller"},{"text":"Que puis-je ajouter à Leather Cleaner si je n’ai pas de produit d’entretien du cuir ?","speaker":"client"},{"text":"Après avoir nettoyé et séché le cuir, vous pouvez utiliser Leather Milk comme étape distincte.","speaker":"seller"}],"youtube_video_id":null,"youtube_video_ids":[],"image_path":null},{"lesson_id":328,"module_sort_order":6,"sort_order":3,"title":"Comment répondre aux objections courantes des clients","summary":"Répondez aux objections en comprenant la préoccupation, en donnant un fait pertinent et en laissant le client décider.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Une objection apporte des informations","type":"text"}]},{"type":"paragraph","content":[{"text":"« C’est trop cher », « J’ai déjà quelque chose de similaire » ou « Est-ce sans risque ? » indiquent que le client a besoin d’informations complémentaires. Reconnaissez d’abord sa préoccupation, posez une question brève, donnez une réponse factuelle et laissez-lui le choix.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Quatre situations courantes","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Prix : demandez si le produit sera utilisé ponctuellement ou régulièrement, puis choisissez le bon format.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Lessive classique : comparez son usage prévu à la matière et à l’étiquette du vêtement.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Sécurité : vérifiez la surface, la finition et les consignes ; faites d’abord un essai sur le cuir.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Efficacité : expliquez la fonction précise et les limites du produit.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Répondez en trois phrases","type":"text"}]},{"type":"paragraph","content":[{"text":"Une réponse brève peut reconnaître la préoccupation, présenter un fait précis et proposer une étape suivante. N’effrayez pas le client avec des risques de dommages, ne promettez pas qu’un produit « fait tout » et n’inventez pas de politique de retour. Si vous ne connaissez pas la réponse, vérifiez-la avant de faire une recommandation.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Exercice pratique","type":"text"}]},{"type":"paragraph","content":[{"text":"Par deux, entraînez-vous à répondre aux objections suivantes : « C’est trop cher », « J’ai déjà une lessive classique », « Est-ce sans risque ? » et « Est-ce que ça va fonctionner ? » Échangez les rôles et vérifiez que vos réponses respectent l’usage prévu du produit.","type":"text"}]}]},"product_bullets":["Commencez par reconnaître la préoccupation et poser une question de clarification.","Pour parler du prix, choisissez un format et un contenu adaptés à la fréquence d’utilisation.","Pour la sécurité, vérifiez la surface, l’étiquette d’entretien et les recommandations du fabricant.","Expliquez la fonction du produit plutôt que de faire des promesses générales.","Ne faites pas de déclarations sur les retours, les réparations ou les résultats que vous ne pouvez pas vérifier."],"key_points_title":"À retenir","conversation_title":"Échange avec le client","conversation":[{"text":"C’est trop cher pour moi.","speaker":"client"},{"text":"Je comprends. Si vous l’utilisez ponctuellement, regardons un format plus petit ou achetons uniquement le produit nécessaire pour cette étape.","speaker":"seller"},{"text":"Ce produit est-il sans risque pour toutes les matières ?","speaker":"client"},{"text":"Il n’existe pas de produit universel. Indiquez-moi la matière concernée et je choisirai un produit et une méthode conformes à son étiquette d’entretien.","speaker":"seller"},{"text":"Je l’ai vu moins cher sur Internet.","speaker":"client"},{"text":"Comparons le format, la version et le contenu du kit. S’il s’agit du même produit, vous pouvez choisir l’offre qui vous convient le mieux.","speaker":"seller"}],"youtube_video_id":null,"youtube_video_ids":[],"image_path":null},{"lesson_id":329,"module_sort_order":6,"sort_order":4,"title":"Mises en situation de vente","summary":"Entraînez-vous à mener une conversation de vente complète, de l’identification du besoin au choix d’une solution adaptée.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Scénario : un casque après une sortie","type":"text"}]},{"type":"paragraph","content":[{"text":"Le client vient d’acheter son premier casque et a des insectes séchés sur l’écran. Demandez-lui s’il le nettoie à la maison ou en déplacement. Expliquez comment ramollir les salissures, puis comment parfaire la surface propre. S’il pose une question sur le Pinlock, distinguez la lentille de l’écran extérieur et suivez les instructions du fabricant.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Scénario : une combinaison après la saison","type":"text"}]},{"type":"paragraph","content":[{"text":"Le client a du cuir sale et une odeur à l’intérieur de la combinaison. Distinguez le nettoyage extérieur, l’entretien du cuir une fois sec et le rafraîchissement de l’intérieur. S’il possède déjà un nettoyant, recommandez uniquement l’étape manquante. Pour une éraflure du matériau, orientez-le vers un atelier.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Scénario : une moto d’enduro après une sortie dans la boue","type":"text"}]},{"type":"paragraph","content":[{"text":"Le client revient d’une sortie tout-terrain exigeante et a accès à de l’eau. Recommandez Mud Breaker suivi d’un rinçage soigneux ; présentez Dirt Finisher comme une finition facultative. Ne conseillez pas d’essuyer du sable sec ni d’appliquer des produits sur des éléments chauds.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Récapitulatif de l’échange","type":"text"}]},{"type":"paragraph","content":[{"text":"Dans chaque situation, identifiez le besoin, recommandez un produit adapté et expliquez son utilisation et ses limites. Laissez le client décider et, si aucun complément n’est nécessaire, arrêtez-vous à la solution de base.","type":"text"}]}]},"product_bullets":["Demandez comment le produit sera utilisé avant de le présenter.","Choisissez un produit adapté au problème précis et à la matière.","Expliquez l’ordre d’utilisation et une consigne de sécurité importante.","Ne proposez un complément que s’il répond à une étape nécessaire.","En cas de dommage ou de doute, vérifiez les consignes ou orientez le client vers un atelier."],"key_points_title":"À retenir","conversation_title":"Échange avec le client","conversation":[{"text":"J’ai acheté un casque coûteux. Des insectes ont séché sur l’écran et je ne veux qu’un seul produit.","speaker":"client"},{"text":"Commencez par Helmet Gel pour ramollir les insectes, puis retirez-les délicatement avec un chiffon microfibre. Si vous le souhaitez, appliquez ensuite Helmet Detailer sur l’écran propre.","speaker":"seller"},{"text":"Puis-je nettoyer le Pinlock avec le même produit ?","speaker":"client"},{"text":"Non. Utilisez les produits pour l’écran extérieur uniquement sur sa face externe ; nettoyez délicatement la lentille conformément aux instructions du fabricant du casque.","speaker":"seller"},{"text":"J’ai une veste à membrane. Fabric Protect va-t-il l’imperméabiliser ?","speaker":"client"},{"text":"Non. Fabric Protect s’ajoute au lavage pour contribuer à la fraîcheur. Choisissez un traitement imperméabilisant distinct adapté à la veste.","speaker":"seller"},{"text":"Je rentre d’une sortie d’enduro dans la boue et je ne veux qu’un seul produit.","speaker":"client"},{"text":"Dans ce cas, commencez par Mud Breaker et rincez soigneusement. Vous pourrez ajouter Dirt Finisher plus tard si vous souhaitez parfaire la surface propre.","speaker":"seller"}],"youtube_video_id":null,"youtube_video_ids":[],"image_path":null}]$fr_lessons$::jsonb) AS translated(
  module_sort_order integer, sort_order integer, title text, summary text, content jsonb,
  product_bullets jsonb, key_points_title text, conversation_title text, conversation jsonb
)
WHERE course.slug = 'pielegnacja-i-sprzedaz-produktow-xzone' AND version.version_number = 9 AND version.status = 'published'
  AND module.sort_order = translated.module_sort_order
  AND lesson.sort_order = translated.sort_order
  AND 'fr' = 'fr'
ON CONFLICT (lesson_id, language_code) DO UPDATE SET
  title = EXCLUDED.title,
  summary = EXCLUDED.summary,
  content = EXCLUDED.content,
  product_bullets = EXCLUDED.product_bullets,
  key_points_title = EXCLUDED.key_points_title,
  conversation_title = EXCLUDED.conversation_title,
  conversation = EXCLUDED.conversation,
  youtube_video_id = COALESCE(lesson_translations.youtube_video_id, EXCLUDED.youtube_video_id),
  youtube_video_ids = CASE WHEN cardinality(lesson_translations.youtube_video_ids) > 0 THEN lesson_translations.youtube_video_ids ELSE EXCLUDED.youtube_video_ids END,
  image_path = COALESCE(lesson_translations.image_path, EXCLUDED.image_path),
  updated_at = now();

-- it: course, module, and lesson text
INSERT INTO public.course_translations (course_version_id, language_code, title, description, image_path)
SELECT version.id,
       'it', translated.title, COALESCE(translated.description, ''), source.image_path
FROM public.courses AS course
JOIN public.course_versions AS version ON version.id = course.published_version_id
JOIN public.course_translations AS source ON source.course_version_id = version.id AND source.language_code = 'pl'
CROSS JOIN LATERAL jsonb_to_record($it_course${"course_version_id":13,"language_code":"it","title":"Cura e vendita dei prodotti Xzone","description":"","image_path":null}$it_course$::jsonb) AS translated(title text, description text)
WHERE course.slug = 'pielegnacja-i-sprzedaz-produktow-xzone' AND version.version_number = 9 AND version.status = 'published'
  AND translated.title IS NOT NULL AND 'it' = 'it'
ON CONFLICT (course_version_id, language_code) DO UPDATE SET
  title = EXCLUDED.title,
  description = EXCLUDED.description,
  image_path = COALESCE(course_translations.image_path, EXCLUDED.image_path),
  updated_at = now();

INSERT INTO public.module_translations (module_id, language_code, title, summary, image_path)
SELECT module.id,
       'it', translated.title, COALESCE(translated.summary, ''), source.image_path
FROM public.courses AS course
JOIN public.course_versions AS version ON version.id = course.published_version_id
JOIN public.course_modules AS module ON module.course_version_id = version.id
JOIN public.module_translations AS source ON source.module_id = module.id AND source.language_code = 'pl'
CROSS JOIN LATERAL jsonb_to_recordset($it_modules$[{"module_id":61,"module_sort_order":0,"title":"Cura del casco","summary":"","image_path":null},{"module_id":62,"module_sort_order":1,"title":"Cura dell’abbigliamento in pelle","summary":"","image_path":null},{"module_id":63,"module_sort_order":2,"title":"Cura dell’abbigliamento in tessuto","summary":"","image_path":null},{"module_id":64,"module_sort_order":3,"title":"Guanti e accessori","summary":"","image_path":null},{"module_id":65,"module_sort_order":4,"title":"Detailing della moto","summary":"","image_path":null},{"module_id":66,"module_sort_order":5,"title":"Cura delle moto off-road","summary":"","image_path":null},{"module_id":67,"module_sort_order":6,"title":"Vendita efficace dei prodotti Xzone","summary":"","image_path":null}]$it_modules$::jsonb) AS translated(module_sort_order integer, title text, summary text)
WHERE course.slug = 'pielegnacja-i-sprzedaz-produktow-xzone' AND version.version_number = 9 AND version.status = 'published'
  AND module.sort_order = translated.module_sort_order
  AND 'it' = 'it'
ON CONFLICT (module_id, language_code) DO UPDATE SET
  title = EXCLUDED.title,
  summary = EXCLUDED.summary,
  image_path = COALESCE(module_translations.image_path, EXCLUDED.image_path),
  updated_at = now();

INSERT INTO public.lesson_translations (
  lesson_id, language_code, title, summary, youtube_video_id, content, product_bullets,
  key_points_title, conversation_title, conversation, youtube_video_ids, image_path
)
SELECT lesson.id,
       'it', translated.title, COALESCE(translated.summary, ''), source.youtube_video_id,
       translated.content, COALESCE(translated.product_bullets, '[]'::jsonb),
       translated.key_points_title, translated.conversation_title,
       COALESCE(translated.conversation, '[]'::jsonb), source.youtube_video_ids, source.image_path
FROM public.courses AS course
JOIN public.course_versions AS version ON version.id = course.published_version_id
JOIN public.course_modules AS module ON module.course_version_id = version.id
JOIN public.course_lessons AS lesson ON lesson.module_id = module.id
JOIN public.lesson_translations AS source ON source.lesson_id = lesson.id AND source.language_code = 'pl'
CROSS JOIN LATERAL jsonb_to_recordset($it_lessons$[{"lesson_id":294,"module_sort_order":0,"sort_order":0,"title":"Perché un casco richiede una cura adeguata?","summary":"Riconosci le tre zone del casco e scegli il metodo di cura più adatto per ciascuna.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Perché il casco richiede una cura attenta","type":"text"}]},{"type":"paragraph","content":[{"text":"Durante la guida il casco entra in contatto con insetti, polvere della strada e pioggia, mentre l’interno è esposto a sudore e umidità. Lo sporco sulla visiera esterna può ridurre la visibilità, mentre una fodera trascurata compromette il comfort. Nel dialogo con il cliente, chiedi prima quale parte del casco richiede attenzione.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Tre zone, tre metodi","type":"text"}]},{"type":"heading","attrs":{"level":3},"content":[{"text":"Calotta e visiera esterna","type":"text"}]},{"type":"paragraph","content":[{"text":"In presenza di insetti secchi, non iniziare strofinando a secco. Helmet Gel ammorbidisce lo sporco, così puoi rimuoverlo delicatamente. In seguito, Helmet Detailer serve per rifinire la superficie già pulita.","type":"text"}]},{"type":"heading","attrs":{"level":3},"content":[{"text":"Fodera","type":"text"}]},{"type":"paragraph","content":[{"text":"Il deodorante aiuta a mantenere la freschezza tra un lavaggio e l’altro, ma non rimuove lo sporco come un lavaggio. Prima di lavare la fodera, verifica se è rimovibile e come pulirla secondo le istruzioni del casco.","type":"text"}]},{"type":"heading","attrs":{"level":3},"content":[{"text":"Pinlock","type":"text"}]},{"type":"paragraph","content":[{"text":"L’inserto Pinlock è delicato e richiede un trattamento specifico. Non applicare gel o detailer e non strofinarlo. Risciacqualo con acqua distillata e lascialo asciugare naturalmente, seguendo le indicazioni del produttore del casco.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Come iniziare la conversazione","type":"text"}]},{"type":"paragraph","content":[{"text":"Chiedi al cliente se vuole prendersi cura della visiera e della calotta, dell’interno o di entrambe le aree. Solo dopo scegli il prodotto. Non dare per scontato che tutti abbiano bisogno di un kit completo o di una cura quotidiana.","type":"text"}]}]},"product_bullets":["Separa calotta, visiera esterna e fodera: ciascuna zona richiede un trattamento diverso.","Per prima cosa ammorbidisci gli insetti secchi con Helmet Gel; non strofinarli a secco.","Usa Helmet Detailer per rifinire una superficie già pulita.","Il deodorante per l’interno non sostituisce il lavaggio di una fodera sporca.","Tratta Pinlock separatamente e segui le istruzioni del produttore del casco."],"key_points_title":"Da ricordare","conversation_title":"Dialogo con il cliente","conversation":[{"text":"Ho un casco nuovo. Devo comprare subito un kit completo per la cura?","speaker":"client"},{"text":"No. Se vuoi occuparti subito della visiera e della calotta, scegli i prodotti per le superfici esterne. Un prodotto per l’interno servirà solo quando la fodera avrà bisogno di essere rinfrescata o lavata.","speaker":"seller"},{"text":"Posso pulire visiera e interno con lo stesso prodotto?","speaker":"client"},{"text":"È meglio separare le due fasi. Per la visiera esterna usa prodotti specifici per visiere e pulisci la fodera con un prodotto distinto, seguendo le istruzioni del casco.","speaker":"seller"},{"text":"Per ora mi danno fastidio solo gli insetti sulla visiera.","speaker":"client"},{"text":"In tal caso, inizia con Helmet Gel e un panno in microfibra pulito. Puoi aggiungere il detailer se vuoi rifinire anche la visiera pulita.","speaker":"seller"}],"youtube_video_id":null,"youtube_video_ids":[],"image_path":null},{"lesson_id":295,"module_sort_order":0,"sort_order":1,"title":"Helmet Gel e Helmet Detailer: differenze e utilizzo","summary":"Scopri la sequenza d’uso di Helmet Gel e Helmet Detailer e scegli il panno e il formato più adatti alle esigenze del cliente.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Due prodotti, due funzioni diverse","type":"text"}]},{"type":"paragraph","content":[{"text":"Helmet Gel e Helmet Detailer si completano, ma non si sostituiscono a vicenda. Il gel aiuta a preparare la superficie sporca, mentre il detailer si usa dopo averla pulita.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Fase 1: ammorbidire lo sporco","type":"text"}]},{"type":"paragraph","content":[{"text":"Applica Helmet Gel sulla zona sporca e lascialo agire per il tempo indicato sull’etichetta. Per il formato da viaggio sono indicati circa cinque minuti; in caso di forte esposizione al sole, riduci il tempo. Non aspettare che il prodotto si asciughi. Quando lo sporco si è ammorbidito, rimuovilo con una microfibra pulita senza premere troppo.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Fase 2: rifinire la superficie pulita","type":"text"}]},{"type":"paragraph","content":[{"text":"Solo dopo aver rimosso lo sporco, usa Helmet Detailer. Per raccogliere lo sporco disciolto è adatta una microfibra più spessa; per la finitura finale usa un panno Evolon. Inizia sempre con accessori puliti.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Scegli il formato in base all’utilizzo","type":"text"}]},{"type":"paragraph","content":[{"text":"Il formato da 30 ml è facile da portare in viaggio. La confezione da 250 ml è pratica se il casco viene pulito regolarmente. Chiedi al cliente dove e con quale frequenza intende usare i prodotti.","type":"text"}]}]},"product_bullets":["Helmet Gel è la fase 1: ammorbidisce insetti secchi e sporco prima che vengano rimossi delicatamente.","Dopo l’applicazione, attendi secondo le istruzioni: per il formato da viaggio sono indicati circa 5 minuti. Riduci il tempo se lavori al sole.","Helmet Detailer è la fase 2: usalo su una superficie pulita per uniformare la finitura e aiutare a evitare aloni.","Rimuovi lo sporco disciolto con una microfibra pulita e più spessa; per la finitura usa Evolon.","I prodotti sono disponibili nel formato da viaggio da 30 ml e in quello più grande da 250 ml. Scegli il formato in base alla frequenza d’uso."],"key_points_title":"Da ricordare","conversation_title":"Dialogo con il cliente","conversation":[{"text":"Il solo detailer basta per gli insetti secchi?","speaker":"client"},{"text":"Con gli insetti secchi, inizia con Helmet Gel: ammorbidisci lo sporco, rimuovilo delicatamente con una microfibra e rifinisci la visiera pulita con il detailer.","speaker":"seller"},{"text":"Ho un casco opaco. Il detailer renderà lucida la superficie?","speaker":"client"},{"text":"Sì, puoi usarlo anche su un casco opaco: la finitura rimane opaca. Applica il prodotto su una microfibra pulita e segui le istruzioni del casco.","speaker":"seller"},{"text":"Quanto tempo devo aspettare dopo aver applicato il gel?","speaker":"client"},{"text":"Segui i tempi indicati sull’etichetta; per il formato da viaggio sono indicati circa 5 minuti. Non lasciare che il prodotto si asciughi e riduci il tempo se lavori al sole.","speaker":"seller"},{"text":"Posso usare un tovagliolo di carta?","speaker":"client"},{"text":"Usa una microfibra morbida e pulita. La carta può essere ruvida e graffiare una superficie delicata.","speaker":"seller"}],"youtube_video_id":"rRsVUfSr9Sk","youtube_video_ids":["rRsVUfSr9Sk"],"image_path":null},{"lesson_id":296,"module_sort_order":0,"sort_order":2,"title":"Come pulire correttamente la visiera e Pinlock?","summary":"Impara a pulire in sicurezza la visiera esterna e a distinguerla dal delicato inserto Pinlock.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Per prima cosa, identifica la superficie da pulire","type":"text"}]},{"type":"paragraph","content":[{"text":"La visiera esterna e l’inserto Pinlock richiedono trattamenti diversi. Prima di usare qualsiasi prodotto, verifica le istruzioni del produttore per il casco, la visiera e il relativo rivestimento.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Visiera esterna: pulizia delicata, passo dopo passo","type":"text"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Rimuovi la sabbia e le altre particelle senza strofinare. Non lucidare lo sporco a secco.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Per gli insetti secchi, applica Helmet Gel e lascialo agire secondo le istruzioni. Non lasciare che si asciughi.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Rimuovi lo sporco ammorbidito con un panno pulito, senza premere troppo.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Se le istruzioni della visiera lo consentono, usa Helmet Detailer e un panno Evolon pulito per la finitura.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Pinlock: un inserto separato e delicato","type":"text"}]},{"type":"paragraph","content":[{"text":"Non applicare Helmet Gel o Helmet Detailer sull’inserto. Non lucidarlo con un panno. Risciacqualo con acqua distillata senza strofinare e lascialo asciugare naturalmente.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Cosa non fanno questi prodotti","type":"text"}]},{"type":"paragraph","content":[{"text":"Questi prodotti servono per la pulizia e la finitura. Non rimuovono i graffi e non riparano una visiera danneggiata.","type":"text"}]}]},"product_bullets":["Rimuovi la sabbia e le particelle senza strofinare prima di iniziare a pulire la visiera.","Per gli insetti secchi sulla visiera esterna, applica il gel e rimuovi lo sporco senza premere.","Puoi rifinire la visiera esterna pulita con il detailer e un panno Evolon.","Non applicare gel o detailer su Pinlock e non lucidarlo con una microfibra.","Risciacqua Pinlock con acqua distillata e lascialo asciugare naturalmente."],"key_points_title":"Da ricordare","conversation_title":"Dialogo con il cliente","conversation":[{"text":"Posso pulire Pinlock con lo stesso prodotto della visiera esterna?","speaker":"client"},{"text":"No. Usa Helmet Gel e il detailer sulla parte esterna della visiera. Pulisci Pinlock delicatamente con acqua distillata, senza strofinare e seguendo le istruzioni del casco.","speaker":"seller"},{"text":"C’è della sabbia sulla visiera. Posso passarci subito la microfibra?","speaker":"client"},{"text":"Prima risciacqua o rimuovi delicatamente le particelle. Non strofinare la sabbia sulla visiera perché potrebbe graffiarla.","speaker":"seller"},{"text":"Questi prodotti rimuovono i graffi?","speaker":"client"},{"text":"No, servono per la pulizia e la finitura. Non riparano i graffi.","speaker":"seller"}],"youtube_video_id":"rRsVUfSr9Sk","youtube_video_ids":["rRsVUfSr9Sk","8z1Me4HeZAA"],"image_path":null},{"lesson_id":297,"module_sort_order":0,"sort_order":3,"title":"Come prendersi cura dell’interno del casco?","summary":"Distingui il rinfresco dell’interno del casco dal lavaggio di una fodera sporca.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Per prima cosa, individua l’esigenza","type":"text"}]},{"type":"paragraph","content":[{"text":"Chiedi al cliente se vuole rinfrescare l’interno dopo un giro o se la fodera è visibilmente sporca. Deodorante e lavaggio risolvono problemi diversi: il prodotto aiuta a mantenere la freschezza, mentre una fodera sporca va pulita correttamente.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Rinfrescare tra un lavaggio e l’altro","type":"text"}]},{"type":"paragraph","content":[{"text":"Mint è un deodorante per l’interno del casco. Spruzzalo da una distanza di circa 15–20 cm e lascia asciugare completamente il casco prima di indossarlo. Il prodotto non è destinato all’uso sulla pelle o sul corpo.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Lavaggio della fodera","type":"text"}]},{"type":"paragraph","content":[{"text":"Per prima cosa, verifica se la fodera è rimovibile e quali istruzioni fornisce il produttore del casco. Per il lavaggio a mano, usa un detergente specifico seguendo l’etichetta. Lava delicatamente, risciacqua a fondo e lascia asciugare naturalmente. Non strizzare il materiale e non asciugarlo vicino a una fonte di calore.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Quando riprendere l’argomento","type":"text"}]},{"type":"paragraph","content":[{"text":"Se l’odore persiste dopo aver rinfrescato l’interno, controlla le condizioni della fodera e valuta di lavarla. Presenta il deodorante come un complemento alla cura tra un lavaggio e l’altro.","type":"text"}]}]},"product_bullets":["Chiedi se il cliente è infastidito dall’odore o se la fodera sporca ha bisogno di essere lavata.","Mint aiuta a mantenere la freschezza tra una pulizia e l’altra, ma non sostituisce il lavaggio.","Spruzza l’interno da una distanza di circa 15–20 cm e attendi che sia completamente asciutto.","Lava a mano la fodera rimovibile seguendo le istruzioni del casco.","Risciacqua a fondo e lascia asciugare naturalmente; non strizzare e non usare fonti di calore."],"key_points_title":"Da ricordare","conversation_title":"Dialogo con il cliente","conversation":[{"text":"L’interno del casco odora di sudore. Cosa scelgo?","speaker":"client"},{"text":"Per rinfrescarlo rapidamente tra un lavaggio e l’altro, scegli Mint. Se la fodera è sporca, lavala con un prodotto separato seguendo le istruzioni del casco.","speaker":"seller"},{"text":"Posso spruzzare il prodotto sulla testa?","speaker":"client"},{"text":"No. Usalo all’interno del casco secondo l’etichetta, non sulla pelle.","speaker":"seller"},{"text":"Posso indossare subito il casco dopo l’uso?","speaker":"client"},{"text":"Aspetta che l’interno sia completamente asciutto. Se l’odore torna, potrebbe essere necessario lavare la fodera.","speaker":"seller"}],"youtube_video_id":null,"youtube_video_ids":[],"image_path":null},{"lesson_id":298,"module_sort_order":0,"sort_order":4,"title":"Quale kit consigliare al cliente: GIGA o Trip Kit?","summary":"Scegli Trip Kit o GIGA in base a dove e con quale frequenza il cliente pulisce il casco.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Scegli il kit in base all’utilizzo","type":"text"}]},{"type":"paragraph","content":[{"text":"Trip Kit e GIGA coprono le fasi di pulizia della parte esterna del casco: ammorbidire lo sporco con il gel e poi rifinire con il detailer. Si distinguono soprattutto per la dimensione delle confezioni e la praticità di trasporto.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Trip Kit: per i viaggi","type":"text"}]},{"type":"paragraph","content":[{"text":"Le confezioni compatte e il sacchetto da viaggio facilitano il trasporto del kit, che può essere riposto nel bauletto o nel vano e usato rapidamente durante una sosta.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"GIGA: per la cura regolare","type":"text"}]},{"type":"paragraph","content":[{"text":"Le confezioni più grandi da 250 ml di gel e detailer sono adatte alla pulizia frequente a casa o in garage, ad esempio quando si curano più caschi.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Domande che aiutano a scegliere","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Dove verrà pulito più spesso il casco: in viaggio o a casa?","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Con quale frequenza lo pulirà il cliente?","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Un casco o più di uno?","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Serve solo la fase di rimozione degli insetti o anche la finitura finale?","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"Se l’odore all’interno del casco dà fastidio al cliente, parla di un prodotto specifico per l’interno. Il kit per la pulizia esterna non sostituisce il lavaggio della fodera.","type":"text"}]}]},"product_bullets":["Trip Kit e GIGA servono per la pulizia in due fasi della parte esterna del casco.","Trip Kit ha confezioni compatte e un sacchetto, quindi è adatto ai viaggi.","GIGA contiene confezioni da 250 ml e accessori per l’uso regolare a casa o in garage.","Per rinfrescare l’interno scegli un prodotto separato: i kit per l’esterno non lo sostituiscono.","Chiedi dove e quanto spesso il cliente pulirà il casco; non dare per scontato che il kit più grande sia migliore."],"key_points_title":"Da ricordare","conversation_title":"Dialogo con il cliente","conversation":[{"text":"Cerco qualcosa per pulire il casco in viaggio. Quale kit scelgo?","speaker":"client"},{"text":"Trip Kit è compatto ed è pensato per essere portato in viaggio. Include le fasi di cura della parte esterna del casco e gli accessori.","speaker":"seller"},{"text":"Per pulire regolarmente due caschi a casa, è meglio Trip Kit?","speaker":"client"},{"text":"Per un uso frequente, GIGA con le confezioni più grandi potrebbe essere più pratico. Scegli il formato in base alla frequenza e al numero di caschi.","speaker":"seller"},{"text":"Il kit pulisce anche la fodera?","speaker":"client"},{"text":"No. È un kit per la cura esterna del casco. Se serve, scegli un prodotto separato per l’interno.","speaker":"seller"},{"text":"Ho finito il gel. Devo ricomprare tutto il kit?","speaker":"client"},{"text":"No. Puoi ricomprare solo il prodotto, se è disponibile separatamente.","speaker":"seller"}],"youtube_video_id":null,"youtube_video_ids":[],"image_path":null},{"lesson_id":299,"module_sort_order":0,"sort_order":5,"title":"Simulazione di vendita: il cliente acquista un casco nuovo","summary":"Esercitati a individuare le esigenze e a scegliere la cura più adatta alla situazione di chi acquista un casco.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Obiettivo dell’esercizio","type":"text"}]},{"type":"paragraph","content":[{"text":"Esercitati in una conversazione che aiuti chi acquista un casco nuovo a scegliere la cura più adatta al suo stile di guida. Non iniziare elencando i prodotti. Scopri dove e quanto spesso pulirà il casco e quale problema vuole risolvere.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"A cosa prestare attenzione","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Fai almeno una domanda che aiuti a scegliere il formato.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Spiega in due frasi brevi la funzione del gel e del detailer.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Non proporre un prodotto aggiuntivo se il cliente non ne ha bisogno.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Non promettere una resa specifica senza dati verificati.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Esercitazione individuale","type":"text"}]},{"type":"paragraph","content":[{"text":"Dopo aver recitato le scene, riformula la risposta con parole tue. Infine, fai una domanda: «Pulisce più spesso il casco in viaggio o a casa?», «Ha un casco o più di uno?» oppure «Il problema principale sono gli insetti o vuole anche rinfrescare l’interno?». Motiva la raccomandazione in una frase.","type":"text"}]}]},"product_bullets":["Inizia chiedendo dove e quanto spesso pulisce il casco e quanti caschi possiede.","Consiglia Trip Kit per la cura in viaggio e GIGA per l’uso regolare a casa.","Spiega brevemente la sequenza: il gel ammorbidisce lo sporco, il detailer rifinisce la superficie pulita.","Non proporre il deodorante per l’interno se il cliente non ne ha bisogno.","Rispetta un rifiuto e non promettere una resa che non è confermata dai dati."],"key_points_title":"Da ricordare","conversation_title":"Dialogo con il cliente","conversation":[{"text":"Parto per un viaggio di una settimana e non voglio guidare con insetti sulla visiera. Cosa porto?","speaker":"client"},{"text":"Per la pulizia in viaggio consiglio Trip Kit. Il gel ammorbidisce gli insetti e, dopo averli rimossi delicatamente, il detailer aiuta a rifinire la visiera pulita.","speaker":"seller"},{"text":"Con lo stesso kit posso pulire Pinlock?","speaker":"client"},{"text":"Non usare i prodotti per la visiera esterna sull’inserto. Pulisci Pinlock delicatamente seguendo le istruzioni del produttore.","speaker":"seller"},{"text":"Non mi serve nulla per l’interno, il casco è nuovo.","speaker":"client"},{"text":"Va bene: non c’è bisogno di comprare un deodorante in anticipo. Potrai pensarci se si presenta un problema di odore o di sporco.","speaker":"seller"}],"youtube_video_id":null,"youtube_video_ids":[],"image_path":null},{"lesson_id":300,"module_sort_order":1,"sort_order":0,"title":"Perché l’abbigliamento da moto in pelle richiede cura?","summary":"Riconosci il tipo di pelle e lo sporco, poi scegli separatamente la pulizia e la cura.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Per prima cosa, individua di che cosa si tratta","type":"text"}]},{"type":"paragraph","content":[{"text":"Una tuta in pelle può combinare diversi tipi e colori di pelle, finiture e inserti in tessuto. Chiedi quale parte richiede attenzione, quanto è sporca e se il cliente conosce le indicazioni del produttore. La pelle chiara o fluorescente richiede particolare cautela.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Separa la pulizia dalla cura","type":"text"}]},{"type":"paragraph","content":[{"text":"Leather Cleaner serve a rimuovere lo sporco. Leather Milk si applica solo sulla pelle pulita e asciutta per prendersene cura. Un prodotto non sostituisce automaticamente l’altro e i prodotti per la cura non riparano i danni meccanici.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Mostra la sequenza sicura","type":"text"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Rimuovi la polvere superficiale senza strofinare con forza.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Fai una prova su una zona non visibile e attendi di vedere il risultato.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Pulisci delicatamente con il cleaner adatto e una spazzola morbida.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Raccogli i residui con un panno pulito e leggermente umido e lascia asciugare naturalmente.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Se la pelle ne ha bisogno, applica uno strato sottile di Leather Milk seguendo l’etichetta.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Definisci aspettative realistiche","type":"text"}]},{"type":"paragraph","content":[{"text":"Un prodotto per la cura può pulire e aiutare nella manutenzione, ma non ripristina un rivestimento usurato né ripara le crepe. In presenza di danni simili, suggerisci di far valutare il capo da un servizio di assistenza o dal produttore.","type":"text"}]}]},"product_bullets":["Per prima cosa, verifica il tipo e il colore della pelle e le indicazioni del produttore del capo.","Leather Cleaner rimuove lo sporco; Leather Milk si prende cura della pelle dopo l’asciugatura.","Prima dell’uso, fai una prova in una zona poco visibile, soprattutto sulla pelle chiara.","Per pulire, usa una spazzola morbida e una pressione leggera.","I prodotti per la cura non riparano crepe, abrasioni o danni al rivestimento."],"key_points_title":"Da ricordare","conversation_title":"Dialogo con il cliente","conversation":[{"text":"Ho una tuta in pelle con inserti vivaci. Come inizio a pulirla?","speaker":"client"},{"text":"Per lo sporco normale, scegli Leather Cleaner Normal. Sui colori fluo, fai prima una prova in una zona poco visibile e pulisci con una spazzola morbida.","speaker":"seller"},{"text":"Dopo il cleaner, la pelle è già trattata?","speaker":"client"},{"text":"Il cleaner rimuove lo sporco. Quando la pelle è completamente asciutta, puoi applicare Leather Milk come fase di cura separata.","speaker":"seller"},{"text":"Ho una crepa vicino alla cucitura. Il latte la riparerà?","speaker":"client"},{"text":"No. I prodotti per la cura trattano la pelle, ma non riparano crepe o cuciture danneggiate; fai valutare quella zona da un servizio di assistenza.","speaker":"seller"}],"youtube_video_id":null,"youtube_video_ids":[],"image_path":null},{"lesson_id":301,"module_sort_order":1,"sort_order":1,"title":"Come pulire la pelle: Leather Cleaner e spazzola","summary":"Scegli la variante di Leather Cleaner in base allo sporco e al colore della pelle, poi mostra una tecnica di pulizia delicata.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Scegli la variante in base alla pelle e allo sporco","type":"text"}]},{"type":"paragraph","content":[{"text":"Non scegliere automaticamente il prodotto più potente. Normal è adatto allo sporco comune e ai colori più delicati. Puoi valutare Strong per lo sporco intenso sulla pelle tradizionale, se le istruzioni del produttore del capo lo consentono.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Dimostrazione passo dopo passo","type":"text"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Agita la confezione e fai una prova in una zona poco visibile.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Applica la schiuma su una spazzola morbida e leggermente inumidita, non direttamente su tutto il capo.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Pulisci una piccola zona con movimenti lenti e delicati.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Raccogli lo sporco con un panno pulito e leggermente umido.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Lascia asciugare il capo naturalmente prima di procedere con la cura.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Quando cambiare approccio","type":"text"}]},{"type":"paragraph","content":[{"text":"Se il materiale ha un rivestimento particolare, un colore intenso o segni di danni, interrompi la dimostrazione e controlla le istruzioni del capo. Il cleaner rimuove lo sporco, ma non ripara abrasioni o crepe.","type":"text"}]}]},"product_bullets":["Normal è indicato per lo sporco normale e i colori più delicati.","Valuta Strong per lo sporco intenso sulla pelle tradizionale, dopo una prova.","Agita la confezione e prova il prodotto su una zona nascosta.","Applica la schiuma su una spazzola morbida e appena umida; non strofinare con forza.","Rimuovi i residui e lascia asciugare la pelle naturalmente."],"key_points_title":"Da ricordare","conversation_title":"Dialogo con il cliente","conversation":[{"text":"Ho una tuta bianca con pannelli fluorescenti. Scelgo Strong?","speaker":"client"},{"text":"Sui colori fluo scegli Normal e provalo prima su una zona nascosta. Riserva Strong allo sporco intenso e usalo secondo la destinazione d’uso del prodotto.","speaker":"seller"},{"text":"Posso usare una spazzola rigida da scarpe?","speaker":"client"},{"text":"È meglio una spazzola morbida. Applica la schiuma sulle setole appena inumidite e pulisci una piccola zona con delicati movimenti circolari.","speaker":"seller"},{"text":"Quando applico Leather Milk?","speaker":"client"},{"text":"Dopo la pulizia, rimuovi lo sporco con un panno pulito e lascia asciugare la pelle naturalmente. Applica Leather Milk solo sulla superficie asciutta, se ha bisogno di cura.","speaker":"seller"}],"youtube_video_id":"iyz1GD-lV2Y","youtube_video_ids":["iyz1GD-lV2Y","s4I4GwvoHuc"],"image_path":null},{"lesson_id":302,"module_sort_order":1,"sort_order":2,"title":"Come prendersi cura della pelle: Leather Milk","summary":"Mostra il ruolo di Leather Milk come fase di cura dopo aver pulito e asciugato la pelle.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Perché prendersi cura della pelle","type":"text"}]},{"type":"paragraph","content":[{"text":"Dopo la pulizia e l’asciugatura, la pelle può aver bisogno di un trattamento specifico. Leather Milk si usa dopo il cleaner, non è un detergente per capi sporchi. Spiega questa sequenza al cliente prima di mostrare come applicarlo.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Applicazione senza eccessi","type":"text"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Assicurati che la pelle sia pulita e completamente asciutta.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Fai una prova su una zona non visibile, soprattutto se la finitura è particolare.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Applica una piccola quantità di prodotto con un panno morbido.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Distribuiscilo in modo uniforme e sottile, seguendo l’etichetta.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Lascia asciugare e controlla il risultato prima di applicare altro prodotto.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Limiti del prodotto","type":"text"}]},{"type":"paragraph","content":[{"text":"Il latte aiuta nella cura ordinaria, ma non ripara crepe, abrasioni o rivestimenti danneggiati. Non promettere l’impermeabilità se il produttore del prodotto non la dichiara. In caso di dubbi, fai riferimento alle istruzioni del capo.","type":"text"}]}]},"product_bullets":["Applica Leather Milk sulla pelle pulita e asciutta.","Applica uno strato sottile e uniforme seguendo le istruzioni.","Prima di trattare tutto il capo, fai una prova su una zona nascosta.","Non usare il latte per rimuovere lo sporco.","Non promettere che ripari le crepe o ripristini la protezione originale."],"key_points_title":"Da ricordare","conversation_title":"Dialogo con il cliente","conversation":[{"text":"Perché Leather Milk, se ho già Leather Cleaner?","speaker":"client"},{"text":"Il cleaner rimuove lo sporco; Leather Milk si prende cura della pelle dopo la pulizia e l’asciugatura. Se in questo momento la pelle non ha bisogno di essere trattata, non è necessario aggiungere il latte.","speaker":"seller"},{"text":"Posso applicare il latte su una giacca sporca?","speaker":"client"},{"text":"Prima puliscila e lasciala asciugare. Il latte non sostituisce il cleaner.","speaker":"seller"},{"text":"Ho la pelle opaca. Come verifico che il latte sia adatto?","speaker":"client"},{"text":"Fai una prova su una zona non visibile e controlla le indicazioni del produttore del capo. Solo dopo applica uno strato sottile seguendo l’etichetta.","speaker":"seller"},{"text":"Il latte riparerà le crepe?","speaker":"client"},{"text":"No. Le crepe e le abrasioni richiedono una riparazione, non un prodotto cosmetico.","speaker":"seller"}],"youtube_video_id":null,"youtube_video_ids":[],"image_path":null},{"lesson_id":303,"module_sort_order":1,"sort_order":3,"title":"Come usare il Leather Care Kit?","summary":"Guida il cliente attraverso il trattamento della pelle con il kit e verifica che ogni componente risponda a una sua esigenza.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Il kit come sequenza di cura","type":"text"}]},{"type":"paragraph","content":[{"text":"Leather Care Kit può essere pratico per chi vuole trattare la pelle esterna e rinfrescare l’interno del capo. Include cleaner, Leather Milk, deodorante per l’interno, spazzola e panno. Mostra l’ordine delle fasi invece di elencare soltanto i componenti.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Ordine di utilizzo","type":"text"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Scegli la variante di cleaner in base allo sporco e al colore, poi fai una prova.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Pulisci la pelle con una spazzola morbida e rimuovi i residui.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Lascia asciugare la pelle naturalmente.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Applica uno strato sottile di Leather Milk seguendo l’etichetta.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Rinfresca separatamente l’interno, seguendo le istruzioni del relativo prodotto.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Scegli il kit solo se è adatto","type":"text"}]},{"type":"paragraph","content":[{"text":"Chiedi che cosa possiede già il cliente e se vuole trattare anche l’interno. Se ha il cleaner e gli manca solo un prodotto per la manutenzione, proponi la fase mancante. Non presentare il kit come indispensabile per tutti.","type":"text"}]}]},"product_bullets":["Leather Care Kit combina cleaner, latte, deodorante per l’interno e accessori.","Prima pulisci la pelle, poi attendi che asciughi e applica Leather Milk.","Il deodorante per l’interno risponde a un’esigenza diversa dalla cura della pelle esterna.","Scegli Normal o Strong in base al colore, allo sporco e alle indicazioni del capo.","Se il cliente possiede già alcuni prodotti, proponi solo quelli che gli mancano."],"key_points_title":"Da ricordare","conversation_title":"Dialogo con il cliente","conversation":[{"text":"La tuta è sporca all’esterno e ha cattivo odore all’interno. Il kit risolve entrambi i problemi?","speaker":"client"},{"text":"Leather Care Kit combina cleaner, latte, deodorante per l’interno e accessori. Prima pulisci la pelle, poi la tratti con il latte dopo l’asciugatura e rinfreschi separatamente l’interno.","speaker":"seller"},{"text":"Ho già il cleaner. Mi conviene comunque acquistare tutto il kit?","speaker":"client"},{"text":"Non è necessario se possiedi già gli altri componenti. Scegli solo il latte o il prodotto per l’interno che ti manca.","speaker":"seller"},{"text":"La pelle è screpolata. Il kit la ripristina?","speaker":"client"},{"text":"No, non ripara i danni. Se la pelle è screpolata, fai prima valutare la tuta da un servizio di assistenza.","speaker":"seller"}],"youtube_video_id":null,"youtube_video_ids":[],"image_path":null},{"lesson_id":304,"module_sort_order":1,"sort_order":4,"title":"Simulazione di vendita: il cliente acquista abbigliamento in pelle","summary":"Esercitati a valutare il tipo di pelle, scegliere una soluzione essenziale e rispondere alle esigenze del cliente.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"La conversazione inizia dalla valutazione","type":"text"}]},{"type":"paragraph","content":[{"text":"L’obiettivo della simulazione è trovare una soluzione adatta a una tuta specifica, non vendere tutti i prodotti disponibili. Verifica il colore e il tipo di pelle, il livello di sporco, le condizioni del capo e ciò che il cliente possiede già. Solo dopo spiega quali fasi servono.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Tre situazioni da esercitare","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Tuta chiara con pannelli fluorescenti: scegli il cleaner con cautela e provalo in una zona nascosta.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Capo nero molto sporco: scegli il cleaner in base al tipo di pelle, pulisci delicatamente e lascia asciugare.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Giacca pulita che richiede manutenzione: valuta Leather Milk senza aggiungere un cleaner non necessario.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Riepilogo condiviso","type":"text"}]},{"type":"paragraph","content":[{"text":"Dopo ogni conversazione, il venditore dovrebbe saper spiegare che cosa si acquista, in quale ordine si usano i prodotti e quali danni non possono riparare. Se il cliente possiede già alcuni accessori, la raccomandazione può limitarsi a un solo prodotto mancante.","type":"text"}]}]},"product_bullets":["Chiedi il tipo, il colore e le condizioni della pelle e le indicazioni del produttore del capo.","Separa la pulizia della superficie esterna, la cura della pelle e il rinfresco dell’interno.","Scegli il cleaner in base al colore e allo sporco; fai una prova sulla pelle delicata.","Consiglia Leather Milk dopo l’asciugatura della pelle, se il cliente ha bisogno di trattarla.","Per i danni meccanici, indirizza il cliente a un servizio di assistenza; non promettere che un prodotto cosmetico li ripari."],"key_points_title":"Da ricordare","conversation_title":"Dialogo con il cliente","conversation":[{"text":"Ho una tuta con inserti fluorescenti e temo che scoloriscano.","speaker":"client"},{"text":"Per i colori fluo scegli Normal. Provalo in una zona non visibile e poi pulisci una piccola area con una spazzola morbida.","speaker":"seller"},{"text":"Ho già il cleaner. Che cosa mi serve per prendermi cura della pelle dopo la pulizia?","speaker":"client"},{"text":"Se la pelle ne ha bisogno, scegli soltanto Leather Milk. Applicalo dopo che la pelle si è asciugata in seguito alla pulizia.","speaker":"seller"},{"text":"Ho un’abrasione sulla manica. Il prodotto la nasconde?","speaker":"client"},{"text":"No, il prodotto non ripara l’abrasione. È consigliabile verificare se la tuta richiede una riparazione da parte di un servizio di assistenza.","speaker":"seller"},{"text":"All’interno sento odore di sudore. Devo lavare tutta la pelle?","speaker":"client"},{"text":"Non iniziare bagnando la tuta. Scegli un prodotto separato per l’interno e usalo seguendo le istruzioni del capo.","speaker":"seller"}],"youtube_video_id":null,"youtube_video_ids":[],"image_path":null},{"lesson_id":305,"module_sort_order":2,"sort_order":0,"title":"Come prendersi cura dell’abbigliamento in tessuto?","summary":"Riconosci il materiale del capo, le istruzioni di lavaggio e scegli il prodotto adatto alla fibra.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Prima di scegliere il detergente","type":"text"}]},{"type":"paragraph","content":[{"text":"L’abbigliamento da moto può combinare membrana, fodera, protezioni e fibre diverse. Chiedi al cliente che cosa vuole lavare, controlla l’etichetta e solo allora consiglia un prodotto. Temperatura, programma, dosaggio e asciugatura dipendono soprattutto dalle istruzioni del capo.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Scegli il prodotto in base al materiale","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Textile Care: abbigliamento tecnico classico e capi con membrana.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Active Care: abbigliamento sportivo sintetico, capi termici e microfibra.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Merino Care: lana merino e fibre naturali delicate.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Jeans Care: denim, compreso l’abbigliamento da moto se l’etichetta lo consente.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Fabric Protect: additivo per il lavaggio che aiuta a mantenere la freschezza; non è un impermeabilizzante.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Non lavare tutto allo stesso modo","type":"text"}]},{"type":"paragraph","content":[{"text":"Una giacca con membrana, una maglia termica e uno strato in merino possono richiedere detergenti e programmi diversi. Non consigliare l’ammorbidente come sostituto di un trattamento specifico. Se il cliente vuole ripristinare l’idrorepellenza, scegli un prodotto separato compatibile con le istruzioni del capo.","type":"text"}]}]},"product_bullets":["Inizia dall’etichetta: materiale, temperatura, programma, detergente e asciugatura.","Scegli Textile Care per l’abbigliamento tecnico e Active Care per quello sportivo.","Merino Care è per la lana delicata, mentre Jeans Care è per il denim.","Fabric Protect aiuta a mantenere la freschezza durante il lavaggio e non è un impermeabilizzante idrorepellente.","Lava separatamente i diversi materiali se richiedono programmi o prodotti diversi."],"key_points_title":"Da ricordare","conversation_title":"Dialogo con il cliente","conversation":[{"text":"Ho una giacca con membrana, una maglia termica e una felpa in merino. Posso lavarle insieme?","speaker":"client"},{"text":"È meglio separarle seguendo le rispettive etichette: sono materiali diversi e possono richiedere detergenti e programmi differenti. Scegli Textile Care per la giacca e un prodotto specifico per il merino.","speaker":"seller"},{"text":"Fabric Protect impermeabilizza la giacca?","speaker":"client"},{"text":"No, Fabric Protect è un additivo per il lavaggio che aiuta a mantenere la freschezza. Per proteggere il capo dall’acqua scegli un impermeabilizzante separato adatto all’indumento.","speaker":"seller"},{"text":"Non so quale programma impostare.","speaker":"client"},{"text":"Imposta programma e temperatura indicati sull’etichetta del capo e controlla il dosaggio del detergente sulla sua etichetta.","speaker":"seller"}],"youtube_video_id":null,"youtube_video_ids":[],"image_path":null},{"lesson_id":306,"module_sort_order":2,"sort_order":1,"title":"Textile Care: lavaggio dell’abbigliamento","summary":"Spiega a cosa serve Textile Care e mostra come sceglierlo in sicurezza per l’abbigliamento tecnico.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Il ruolo di Textile Care","type":"text"}]},{"type":"paragraph","content":[{"text":"Scegli Textile Care per l’abbigliamento tecnico da moto, compresi i capi con membrana. Durante la conversazione non promettere che il detergente ripari una membrana usurata o ne ripristini le proprietà dopo un danno. L’obiettivo è lavare il capo correttamente, secondo le istruzioni del produttore.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Come preparare il lavaggio","type":"text"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Controlla l’etichetta del capo e rimuovi gli elementi che vanno lavati separatamente.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Imposta un programma e una temperatura consentiti.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Misura il detergente seguendo l’etichetta.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Non aggiungere il normale ammorbidente, a meno che il produttore lo indichi esplicitamente.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Asciuga seguendo l’etichetta e, se indicato, lontano da fonti di calore eccessivo.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Freschezza aggiuntiva","type":"text"}]},{"type":"paragraph","content":[{"text":"Fabric Protect può essere aggiunto al lavaggio come prodotto separato. Spiega chiaramente il suo ruolo: aiuta a mantenere la freschezza del capo, ma non sostituisce un trattamento idrorepellente.","type":"text"}]}]},"product_bullets":["Textile Care è indicato per lavare l’abbigliamento tecnico da moto e i capi con membrana.","Programma, temperatura e metodo di asciugatura dipendono dall’etichetta del capo.","Non usare automaticamente il normale ammorbidente come alternativa.","Segui il dosaggio indicato sull’etichetta del prodotto e le istruzioni di lavaggio.","Puoi valutare Fabric Protect come additivo separato per aiutare a mantenere la freschezza."],"key_points_title":"Da ricordare","conversation_title":"Dialogo con il cliente","conversation":[{"text":"Textile Care è adatto a una giacca con membrana?","speaker":"client"},{"text":"Sì, è un detergente per abbigliamento tecnico e capi con membrana. Scegli programma e temperatura in base all’etichetta della giacca.","speaker":"seller"},{"text":"Aggiungo sempre l’ammorbidente. Devo continuare?","speaker":"client"},{"text":"Non aggiungerlo automaticamente ai capi tecnici. Controlla l’etichetta e usa Textile Care seguendo le istruzioni.","speaker":"seller"},{"text":"Che cosa posso aggiungere se voglio mantenere la freschezza dopo il lavaggio?","speaker":"client"},{"text":"Puoi aggiungere Fabric Protect nella vaschetta dell’ammorbidente al posto del normale ammorbidente, seguendo l’etichetta del prodotto.","speaker":"seller"}],"youtube_video_id":"UUXCozkqAZk","youtube_video_ids":["UUXCozkqAZk"],"image_path":null},{"lesson_id":307,"module_sort_order":2,"sort_order":2,"title":"Fabric Protect: cura e freschezza dopo il lavaggio","summary":"Mostra come aggiungere Fabric Protect al bucato e distinguilo da un impermeabilizzante.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Un additivo per il bucato, non un impermeabilizzante","type":"text"}]},{"type":"paragraph","content":[{"text":"Il nome può far pensare a una protezione dall’acqua, quindi spiega con chiarezza la funzione del prodotto. Fabric Protect è un additivo per il lavaggio che aiuta a mantenere la freschezza dei capi. Non è un impermeabilizzante idrorepellente e non ripristina da solo il trattamento DWR.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Come si usa","type":"text"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Scegli il detergente adatto al materiale e controlla l’etichetta del capo.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Versa Fabric Protect nella vaschetta dell’ammorbidente, se indicato nelle istruzioni.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Usa il dosaggio indicato sull’etichetta.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Avvia un programma conforme alle istruzioni del capo.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Per impermeabilizzare, usa un prodotto separato destinato a questo scopo.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Come presentare il vantaggio aggiuntivo","type":"text"}]},{"type":"paragraph","content":[{"text":"Se il cliente lava abbigliamento tecnico e vuole mantenerlo fresco dopo il lavaggio, puoi proporre Fabric Protect in abbinamento a Textile Care. Se chiede della pioggia, spiega chiaramente che serve un impermeabilizzante separato.","type":"text"}]}]},"product_bullets":["Fabric Protect è un additivo per il lavaggio che aiuta a mantenere la freschezza dei capi.","Può sostituire il normale ammorbidente se lo indica l’etichetta.","Versalo nella vaschetta dell’ammorbidente seguendo le istruzioni.","È preferibile abbinarlo al detergente adatto al materiale.","Non promettere di ripristinare l’impermeabilità o il trattamento DWR."],"key_points_title":"Da ricordare","conversation_title":"Dialogo con il cliente","conversation":[{"text":"Fabric Protect farà sì che la giacca torni a respingere l’acqua?","speaker":"client"},{"text":"No: è un additivo per il lavaggio che aiuta a mantenere la freschezza del capo; non è un impermeabilizzante idrorepellente. Per proteggerla dall’acqua scegli un impermeabilizzante specifico per la giacca.","speaker":"seller"},{"text":"Dove si versa Fabric Protect?","speaker":"client"},{"text":"Versalo nella vaschetta dell’ammorbidente al posto del normale ammorbidente e avvia un lavaggio conforme all’etichetta.","speaker":"seller"},{"text":"Posso abbinarlo a Textile Care?","speaker":"client"},{"text":"Sì. Textile Care lava l’abbigliamento tecnico, mentre Fabric Protect si aggiunge nella vaschetta del risciacquo come fase separata.","speaker":"seller"}],"youtube_video_id":null,"youtube_video_ids":[],"image_path":null},{"lesson_id":308,"module_sort_order":2,"sort_order":3,"title":"Active Care: cura dell’abbigliamento sportivo","summary":"Scegli Active Care per l’abbigliamento sportivo sintetico e termico, tenendo conto dell’uso che ne fa il cliente.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Quando valutare Active Care","type":"text"}]},{"type":"paragraph","content":[{"text":"Active Care è adatto all’abbigliamento sportivo sintetico, agli strati termici e alla microfibra. Inizia chiedendo quale attività pratica il cliente e qual è il problema, ad esempio l’odore dopo l’allenamento o i lavaggi frequenti dello strato base.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Scegli in base al materiale","type":"text"}]},{"type":"paragraph","content":[{"text":"Se il cliente chiede di una giacca con membrana, controlla l’etichetta e valuta Textile Care. Per la lana merino, scegli un prodotto adatto alle fibre naturali delicate. Non scegliere Active Care solo perché il capo è sportivo.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Uso e formato","type":"text"}]},{"type":"paragraph","content":[{"text":"Controlla sempre sull’etichetta del capo le indicazioni per programma, temperatura e asciugatura. Leggi il dosaggio sull’etichetta del prodotto. La bustina da 40 ml può essere pratica per provare il prodotto o portarlo in viaggio.","type":"text"}]}]},"product_bullets":["Scegli Active Care per gli strati sportivi sintetici e termici.","Chiedi il materiale, se resta odore dopo l’allenamento e che cosa indica l’etichetta.","Non dare per scontato che sia un detergente adatto a ogni tipo di capo.","Segui il dosaggio e il programma indicati sulla confezione e sull’etichetta del capo.","La bustina da 40 ml può essere utile per provare il prodotto prima di acquistare un formato più grande."],"key_points_title":"Da ricordare","conversation_title":"Dialogo con il cliente","conversation":[{"text":"La maglia termica continua a odorare di sudore. Cosa scelgo?","speaker":"client"},{"text":"Se è un capo sportivo sintetico o termico, scegli Active Care. Lavalo seguendo l’etichetta e dosa il prodotto secondo le istruzioni.","speaker":"seller"},{"text":"Posso usare Active Care per una giacca con membrana?","speaker":"client"},{"text":"Per una giacca con membrana scegli Textile Care. Usa Active Care per gli strati sportivi sintetici.","speaker":"seller"},{"text":"Posso prendere una confezione più piccola da portare in viaggio?","speaker":"client"},{"text":"Sì, è disponibile la bustina da 40 ml, un formato pratico da provare o portare in viaggio.","speaker":"seller"}],"youtube_video_id":null,"youtube_video_ids":[],"image_path":null},{"lesson_id":309,"module_sort_order":2,"sort_order":4,"title":"Merino Care","summary":"Impara a lavare il merino e le fibre delicate ed evita consigli troppo generici.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Le fibre delicate richiedono un trattamento specifico","type":"text"}]},{"type":"paragraph","content":[{"text":"Gli strati in merino aiutano a mantenere il comfort durante la guida e vanno trattati seguendo l’etichetta. Scegli Merino Care per la lana merino e per le altre fibre delicate indicate dal produttore. Non dare per scontato che un programma adatto alla biancheria sintetica sia sicuro per la lana.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Lavaggio e asciugatura","type":"text"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Controlla la composizione e i simboli sull’etichetta.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Scegli un programma per lana o il lavaggio a mano, se indicato.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Misura il detergente seguendo l’etichetta; per un carico piccolo può essere indicata una dose di 15–30 ml.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Evita il normale ammorbidente, salvo diversa indicazione del produttore.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Lascia asciugare naturalmente e non appoggiare il capo su un termosifone caldo.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Dialogo di vendita","type":"text"}]},{"type":"paragraph","content":[{"text":"Chiedi se il cliente lava solo lo strato in merino o un capo composto da materiali misti. In caso di fibre miste, è preferibile separarli invece di usare un unico detergente per tutto.","type":"text"}]}]},"product_bullets":["Merino Care è destinato alla lana merino e alle fibre naturali delicate.","Scegli temperatura e programma soprattutto in base all’etichetta del capo.","Usa la dose di detergente indicata sull’etichetta.","Non aggiungere il normale ammorbidente senza un’indicazione esplicita.","Lascia asciugare naturalmente seguendo le istruzioni e lontano dal calore eccessivo."],"key_points_title":"Da ricordare","conversation_title":"Dialogo con il cliente","conversation":[{"text":"Posso lavare la maglia in merino con un normale detersivo?","speaker":"client"},{"text":"Per il merino scegli Merino Care e controlla prima l’etichetta. Un detergente normale potrebbe non essere adatto alla lana delicata.","speaker":"seller"},{"text":"Che programma e temperatura devo impostare?","speaker":"client"},{"text":"Imposta un programma per lana o scegli il lavaggio a mano solo se l’etichetta lo consente; rispetta la temperatura indicata.","speaker":"seller"},{"text":"Posso asciugare la maglia sul termosifone?","speaker":"client"},{"text":"Non appoggiarla su un termosifone caldo. Lasciala asciugare naturalmente seguendo l’etichetta.","speaker":"seller"}],"youtube_video_id":"Hs9QuFjKbRA","youtube_video_ids":["Hs9QuFjKbRA"],"image_path":null},{"lesson_id":310,"module_sort_order":2,"sort_order":5,"title":"Jeans Care","summary":"Scegli Jeans Care per il denim e considera la struttura dell’abbigliamento da moto.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Il denim da moto non è sempre un semplice paio di jeans","type":"text"}]},{"type":"paragraph","content":[{"text":"L’abbigliamento da moto può contenere fibre elastiche, fodere, protezioni e rinforzi. Prima di consigliare un detergente, verifica la composizione e quali elementi si possono rimuovere. L’etichetta del capo indica il programma e il metodo di asciugatura.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Cura passo dopo passo","type":"text"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Controlla l’etichetta e la composizione del materiale.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Rimuovi le protezioni se il produttore consente di farlo.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Scegli Jeans Care per il denim e dosa il prodotto seguendo l’etichetta.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Imposta il programma indicato sull’etichetta.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Asciuga il capo seguendo le istruzioni e senza calore eccessivo.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Scegli il prodotto in base al capo","type":"text"}]},{"type":"paragraph","content":[{"text":"Jeans Care non è un prodotto universale per ogni tipo di abbigliamento. Se il cliente ha pantaloni con membrana o con un’alta percentuale di fibre tecniche, basati sulla composizione e sulle istruzioni. La bustina da 40 ml è un formato compatto e pratico.","type":"text"}]}]},"product_bullets":["Scegli Jeans Care per il denim, compreso l’abbigliamento da moto se l’etichetta lo consente.","Controlla la composizione, le fibre miste e la presenza di protezioni o fodera.","Imposta programma e temperatura secondo le indicazioni del produttore.","Non usare automaticamente il detergente per jeans su capi in lana o con membrana.","La bustina da 40 ml può essere pratica per una prova o per un viaggio."],"key_points_title":"Da ricordare","conversation_title":"Dialogo con il cliente","conversation":[{"text":"Ho dei jeans da moto rinforzati. Posso lavarli?","speaker":"client"},{"text":"Sì: Jeans Care è indicato per il denim e i capi con fibre aramidiche. Controlla l’etichetta, gira i pantaloni al rovescio e scegli un lavaggio delicato, di solito fino a 30 °C e con una centrifuga a bassa velocità; lasciali asciugare naturalmente.","speaker":"seller"},{"text":"Posso asciugarli nell’asciugatrice?","speaker":"client"},{"text":"Lasciali asciugare naturalmente e non usare l’asciugatrice. Controlla anche l’etichetta dei pantaloni.","speaker":"seller"},{"text":"Jeans Care è adatto a una giacca con membrana?","speaker":"client"},{"text":"Non scegliere Jeans Care per una giacca con membrana. Per l’abbigliamento tecnico usa Textile Care, seguendo l’etichetta.","speaker":"seller"}],"youtube_video_id":null,"youtube_video_ids":[],"image_path":null},{"lesson_id":311,"module_sort_order":2,"sort_order":6,"title":"Simulazione di vendita: scegliere la cura in base al tipo di capo","summary":"Esercitati a scegliere il detergente per diversi tipi di abbigliamento e a rispondere a una richiesta di impermeabilizzazione.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Tre scenari da esercitare","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Giacca con membrana, maglia termica e jeans: separa i capi e scegli un prodotto per ciascun materiale.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Il cliente vuole «impermeabilizzare» la giacca con Fabric Protect: spiega la differenza e verifica se serve un impermeabilizzante separato.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Il cliente lava solo una felpa in merino: presenta Merino Care e le istruzioni corrette riportate sull’etichetta.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Schema per la raccomandazione","type":"text"}]},{"type":"paragraph","content":[{"text":"Ripeti con parole tue l’esigenza del cliente, chiedi la composizione e le modalità di lavaggio, poi indica un prodotto. Spiegane l’uso e i limiti. Proponi un prodotto aggiuntivo solo se risponde a un’esigenza diversa.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Obiettivo dell’esercizio","type":"text"}]},{"type":"paragraph","content":[{"text":"Dopo ogni scena, il venditore dovrebbe saper motivare la scelta in base al materiale e alle istruzioni, invece di proporre lo stesso detergente a tutti.","type":"text"}]}]},"product_bullets":["Scegli il prodotto in base al materiale, alla composizione e alle indicazioni del produttore.","Textile Care è adatto all’abbigliamento tecnico; Active Care agli strati sportivi sintetici.","Merino Care e Jeans Care sono adatti a tipi di fibre diversi.","Fabric Protect aiuta a mantenere la freschezza durante il lavaggio, ma non è un impermeabilizzante.","Non vendere un kit completo se il cliente ha bisogno di un solo prodotto."],"key_points_title":"Da ricordare","conversation_title":"Dialogo con il cliente","conversation":[{"text":"Ho una giacca con membrana, una maglia termica e dei jeans. Vorrei un solo detersivo per tutto.","speaker":"client"},{"text":"Capisco. Per questi tre materiali scegli detergenti separati: Textile Care per la giacca, Active Care per lo strato sintetico e Jeans Care per il denim, seguendo le rispettive etichette.","speaker":"seller"},{"text":"Fabric Protect impermeabilizza la giacca?","speaker":"client"},{"text":"No, l’additivo aiuta a mantenere la freschezza dopo il lavaggio. Se vuoi che la giacca respinga l’acqua, serve un impermeabilizzante separato.","speaker":"seller"},{"text":"Lavo solo una felpa in merino. Devo comprare un kit?","speaker":"client"},{"text":"No. È sufficiente Merino Care, se l’etichetta consente il lavaggio, e il programma indicato dal produttore.","speaker":"seller"}],"youtube_video_id":null,"youtube_video_ids":[],"image_path":null},{"lesson_id":312,"module_sort_order":3,"sort_order":0,"title":"Come prendersi cura dei guanti da moto?","summary":"Individua se il problema riguarda l’interno o l’esterno del guanto e scegli il trattamento adatto.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Per prima cosa, individua l’origine del problema","type":"text"}]},{"type":"paragraph","content":[{"text":"I guanti combinano pelle, tessuto, protezioni, cuciture e dita difficili da raggiungere. Chiedi se il cliente vuole rimuovere lo sporco all’esterno, rinfrescare l’interno o trattare la pelle asciutta. Sono esigenze che richiedono soluzioni diverse.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Controlla le istruzioni dei guanti","type":"text"}]},{"type":"paragraph","content":[{"text":"Non tutti i guanti si possono lavare in lavatrice o rivoltare. Per i guanti in pelle è particolarmente importante controllare le indicazioni del produttore. Non bagnarli né allungarli, a meno che le istruzioni lo prevedano.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Scegli il trattamento adatto","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Odore persistente all’interno difficile da eliminare: valuta Magiczne Rękawiczki seguendo le istruzioni.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Sporco all’esterno: scegli un prodotto adatto al materiale del guanto e alle indicazioni del produttore.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"La zip scorre con difficoltà ma non è danneggiata: valuta Zip Service.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Abrasioni, parti scollate o cuciture aperte: un prodotto per la cura non sostituisce una riparazione.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Una raccomandazione breve","type":"text"}]},{"type":"paragraph","content":[{"text":"Al momento dell’acquisto, spiega a cosa serve il prodotto e che cosa non fa. Magiczne Rękawiczki rinfresca l’interno, ma non sostituisce il lavaggio completo o la riparazione del guanto.","type":"text"}]}]},"product_bullets":["I guanti hanno cuciture, protezioni e materiali diversi: controlla l’etichetta.","Separa lo sporco esterno dall’odore o dall’umidità all’interno.","Non dare per scontato che i guanti si possano lavare in lavatrice o rivoltare.","Magiczne Rękawiczki aiutano a rinfrescare le parti interne difficili da raggiungere.","Per danni, cuciture scollate o pelle consumata, serve un servizio di riparazione."],"key_points_title":"Da ricordare","conversation_title":"Dialogo con il cliente","conversation":[{"text":"I guanti hanno cattivo odore, ma non riesco a rivoltarli.","speaker":"client"},{"text":"Per rinfrescare l’interno difficile da raggiungere, usa Magiczne Rękawiczki. Indossa il paio imbevuto sulle mani e pulisci l’interno seguendo le istruzioni.","speaker":"seller"},{"text":"Posso semplicemente metterli in lavatrice?","speaker":"client"},{"text":"Solo se il produttore dei guanti consente il lavaggio in lavatrice. Controlla l’etichetta: potrebbero avere parti in pelle, protezioni e componenti incollati.","speaker":"seller"},{"text":"Il materiale è consumato. Il prodotto lo riparerà?","speaker":"client"},{"text":"No. Un prodotto per la cura non ripara abrasioni o cuciture; porta i guanti a un servizio di assistenza.","speaker":"seller"}],"youtube_video_id":null,"youtube_video_ids":[],"image_path":null},{"lesson_id":313,"module_sort_order":3,"sort_order":1,"title":"Magiczne Rękawiczki: uso e dimostrazione","summary":"Mostra al cliente come usare correttamente Magiczne Rękawiczki per rinfrescare l’interno dei guanti.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Perché usare Magiczne Rękawiczki","type":"text"}]},{"type":"paragraph","content":[{"text":"Il paio imbevuto facilita la pulizia delle parti interne difficili da raggiungere quando non è possibile rivoltare comodamente i guanti. Può essere particolarmente utile con guanti in pelle, se le istruzioni consentono questo metodo per rinfrescarli.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Dimostrazione","type":"text"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Apri la bustina e indossa il paio monouso sulle mani.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Infila le mani nei guanti da moto.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Muovi le dita e premi delicatamente per far arrivare il prodotto all’interno.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Non tirare la fodera e non rivoltare il guanto con forza.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Al termine, togli il paio imbevuto e lavati le mani seguendo le istruzioni.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Che cosa non promettere","type":"text"}]},{"type":"paragraph","content":[{"text":"È un metodo pratico per rinfrescare l’interno, non sostituisce il lavaggio completo dei guanti, la riparazione delle cuciture o la rimozione di ogni tipo di sporco. Il cliente deve usare il prodotto seguendo le istruzioni sulla confezione.","type":"text"}]}]},"product_bullets":["La bustina contiene un paio di guanti monouso imbevuti.","Indossali, infila le mani nei guanti da moto e muovi le dita.","Procedi delicatamente per raggiungere l’interno senza rivoltare il guanto.","È un metodo per rinfrescare l’interno, non per lavare o riparare completamente il guanto.","Dopo l’uso, togli il prodotto e lavati le mani secondo le istruzioni."],"key_points_title":"Da ricordare","conversation_title":"Dialogo con il cliente","conversation":[{"text":"Come si usano Magiczne Rękawiczki?","speaker":"client"},{"text":"Indossa sulle mani il paio monouso imbevuto, infila le mani nei guanti da moto e muovi le dita per pulirne l’interno.","speaker":"seller"},{"text":"Devo rivoltare i guanti?","speaker":"client"},{"text":"No. È proprio per questo che infili all’interno le mani con i guanti imbevuti. Non tirare la fodera.","speaker":"seller"},{"text":"Sostituiscono il lavaggio completo dei guanti?","speaker":"client"},{"text":"No, servono a rinfrescare l’interno. Dopo l’uso, togli il paio monouso e segui le istruzioni del prodotto.","speaker":"seller"},{"text":"Posso usarli con i guanti in pelle?","speaker":"client"},{"text":"Prima controlla le indicazioni del produttore dei guanti e le istruzioni del prodotto, poi usali di conseguenza.","speaker":"seller"}],"youtube_video_id":null,"youtube_video_ids":[],"image_path":null},{"lesson_id":314,"module_sort_order":3,"sort_order":2,"title":"Zip Service: cura delle cerniere e accessori complementari","summary":"Spiega l’utilizzo di Zip Service per le cerniere e distingui la manutenzione dalla riparazione di un danno.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Per una cerniera integra che si inceppa","type":"text"}]},{"type":"paragraph","content":[{"text":"Zip Service è un prodotto per la cura delle cerniere che scorrono con difficoltà ma non sono danneggiate meccanicamente. Chiedi se il problema è l’attrito o se mancano denti oppure il cursore è piegato.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Come mostrare l’utilizzo","type":"text"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Rimuovi lo sporco visibile dalla cerniera.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Applica una piccola quantità di Zip Service sui denti, seguendo l’etichetta.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Fai scorrere più volte il cursore per distribuire il prodotto.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Rimuovi l’eccesso con un panno pulito e asciutto.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Verifica il funzionamento della cerniera senza forzare.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Un prodotto complementare","type":"text"}]},{"type":"paragraph","content":[{"text":"Puoi proporlo come accessorio pratico per la cura di abbigliamento, scarpe o borse se il cliente segnala un problema con la cerniera. Non promettere che ripari denti rotti, strappi nel tessuto o un cursore danneggiato.","type":"text"}]}]},"product_bullets":["Zip Service aiuta le cerniere integre in metallo o plastica a scorrere meglio.","Applica una piccola quantità sui denti e fai scorrere più volte il cursore.","Rimuovi l’eccesso con un panno pulito e asciutto.","Può essere utile per cerniere su abbigliamento, scarpe e borse.","Non ripara denti rotti o un cursore danneggiato."],"key_points_title":"Da ricordare","conversation_title":"Dialogo con il cliente","conversation":[{"text":"La cerniera della giacca scorre con difficoltà. Zip Service può aiutare?","speaker":"client"},{"text":"Se cursore e denti sono integri, Zip Service può aiutare a mantenere la cerniera. Applicane una piccola quantità sui denti, fai scorrere il cursore alcune volte e rimuovi l’eccesso.","speaker":"seller"},{"text":"Quanto prodotto devo applicare?","speaker":"client"},{"text":"Una piccola quantità, seguendo l’etichetta. Dopo averlo distribuito, rimuovi i residui con un panno pulito e asciutto.","speaker":"seller"},{"text":"Si è rotto un dente. Può ripararlo?","speaker":"client"},{"text":"No. Zip Service si prende cura delle cerniere integre, ma non ripara denti o cursori danneggiati.","speaker":"seller"}],"youtube_video_id":null,"youtube_video_ids":[],"image_path":null},{"lesson_id":315,"module_sort_order":4,"sort_order":0,"title":"Da dove iniziare a prendersi cura della moto?","summary":"Individua il tipo di sporco e scegli un percorso semplice per la cura della moto.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Inizia dalla valutazione","type":"text"}]},{"type":"paragraph","content":[{"text":"Una moto dopo un giro su strade asciutte richiede un trattamento diverso da una moto usata sotto la pioggia o nel fango. Chiedi quale sporco c’è, quanto è intenso e se il cliente ha accesso ad acqua, idropulitrice e garage. Così potrai suggerire una sequenza semplice invece di un insieme casuale di prodotti.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Un rapido rinfresco","type":"text"}]},{"type":"paragraph","content":[{"text":"Per la polvere leggera tra un lavaggio completo e l’altro, possono bastare Wash & Ride e una microfibra morbida e pulita. Non usare questo metodo per strofinare con forza la sabbia grossolana, che può graffiare la vernice.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Lavaggio completo","type":"text"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Per gli insetti secchi, valuta Bug Killer come fase preliminare.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Per il lavaggio principale usa Moto Wash o una soluzione preparata con Power Powder.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Per i residui sui cerchi scegli Wheelixir e l’accessorio adatto.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Risciacqua e asciuga la moto seguendo le istruzioni dei prodotti.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Su una superficie pulita e fredda, puoi usare Ceramic Detailer come finitura.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Spiega i limiti del prodotto","type":"text"}]},{"type":"paragraph","content":[{"text":"Non applicare i prodotti su parti calde e non lasciarli asciugare se le istruzioni lo vietano. Ceramic Detailer non sostituisce il lavaggio né un rivestimento professionale di lunga durata.","type":"text"}]}]},"product_bullets":["Individua se si tratta di polvere, insetti, polvere dei freni, grasso o fango pesante.","Chiedi se il cliente ha accesso all’acqua e quali sono le condizioni di pulizia.","Wash & Ride è adatto alla polvere leggera tra i lavaggi completi.","Bug Killer, Moto Wash e Wheelixir servono per fasi e tipi di sporco diversi.","Usa Ceramic Detailer dopo il lavaggio, su una superficie pulita e fredda."],"key_points_title":"Da ricordare","conversation_title":"Dialogo con il cliente","conversation":[{"text":"La moto è solo impolverata e ho cinque minuti. Cosa mi consigli?","speaker":"client"},{"text":"Per la polvere leggera tra un lavaggio completo e l’altro, usa Wash & Ride e una microfibra pulita. Se c’è molta sabbia o fango, prima risciacqua e lava la moto.","speaker":"seller"},{"text":"Posso usare un solo prodotto per pulire gli insetti e i cerchi?","speaker":"client"},{"text":"Per gli insetti scegli Bug Killer, per i residui sui cerchi Wheelixir e per lavare tutta la moto Moto Wash.","speaker":"seller"},{"text":"Posso iniziare quando il motore è caldo?","speaker":"client"},{"text":"Aspetta che la moto si raffreddi. Non applicare i prodotti sulle parti calde.","speaker":"seller"}],"youtube_video_id":null,"youtube_video_ids":[],"image_path":null},{"lesson_id":316,"module_sort_order":4,"sort_order":1,"title":"Wash & Ride: lavaggio della moto","summary":"Mostra quando Wash & Ride è una scelta pratica e come usarlo in sicurezza con lo sporco leggero.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Pulizia rapida senza tubo","type":"text"}]},{"type":"paragraph","content":[{"text":"Wash & Ride è pratico quando la moto ha bisogno di un leggero rinfresco e il cliente non ha accesso a un tubo o a un secchio. Integra i lavaggi regolari, ma non li sostituisce quando c’è uno spesso strato di fango, sabbia o sporco ostinato.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Modalità d’uso","type":"text"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Assicurati che la superficie sia fredda.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Spruzza il prodotto su una piccola zona seguendo l’etichetta.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Raccogli delicatamente lo sporco con una microfibra morbida e pulita; non premere troppo.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Quando il panno si sporca, cambia lato o prendine uno pulito.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"In caso di sporco intenso, fermati e programma un lavaggio completo.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"A chi è adatto","type":"text"}]},{"type":"paragraph","content":[{"text":"Il prodotto è utile tra un lavaggio e l’altro in garage, al parcheggio o in viaggio. Aiuta a rinfrescare l’aspetto e, secondo quanto dichiarato, lascia un leggero strato protettivo.","type":"text"}]}]},"product_bullets":["Wash & Ride serve per la polvere e lo sporco leggero tra i lavaggi completi.","Usalo su una superficie fredda e raccogli delicatamente lo sporco con una microfibra pulita.","Può essere utile in garage, al parcheggio o durante un viaggio.","Non usarlo per strofinare con forza uno spesso strato di sabbia o fango.","Con lo sporco pesante, risciacqua e procedi con un lavaggio completo."],"key_points_title":"Da ricordare","conversation_title":"Dialogo con il cliente","conversation":[{"text":"Non ho un tubo né un secchio. Come posso rinfrescare la moto?","speaker":"client"},{"text":"Se lo sporco è leggero, usa Wash & Ride e una microfibra morbida e pulita. Lavora su una superficie fredda e raccogli lo sporco senza premere troppo.","speaker":"seller"},{"text":"È adatto dopo un giro nel fango?","speaker":"client"},{"text":"Non usarlo su uno spesso strato di fango o sabbia. Prima risciacqua lo sporco e fai un lavaggio completo.","speaker":"seller"},{"text":"Posso usarlo sul motore caldo?","speaker":"client"},{"text":"No. Aspetta che le parti si raffreddino e usa il prodotto seguendo l’etichetta.","speaker":"seller"}],"youtube_video_id":"aqzUkc7BheU","youtube_video_ids":["aqzUkc7BheU"],"image_path":null},{"lesson_id":317,"module_sort_order":4,"sort_order":2,"title":"Power Powder: preparazione e utilizzo","summary":"Spiega come preparare la soluzione Power Powder e scegliere il prodotto per l’uso corretto.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Il concentrato va preparato prima dell’uso","type":"text"}]},{"type":"paragraph","content":[{"text":"Power Powder è una polvere da sciogliere in acqua seguendo le istruzioni della variante specifica. Non versarla direttamente sulla moto e non dare per scontato che tutte le bustine si usino allo stesso modo.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Scegli il prodotto in base all’operazione","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Moto Wash serve per il lavaggio principale.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Bug Killer aiuta a rimuovere in via preliminare insetti e sporco organico.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Wheelixir è pensato per i cerchi e i residui nelle zone circostanti.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Preparazione della dose","type":"text"}]},{"type":"paragraph","content":[{"text":"Lo Shaker da 500 ml può essere utile per misurare l’acqua e preparare una dose. Leggi il dosaggio sulla confezione, sciogli la polvere nella quantità d’acqua indicata e usa la soluzione nel modo consentito dal produttore. Non scambiare i prodotti tra loro.","type":"text"}]}]},"product_bullets":["Una volta sciolto, Power Powder Moto Wash serve per il lavaggio principale della moto.","La confezione di Moto Wash contiene tre bustine; usale seguendo le istruzioni.","Bug Killer e Wheelixir sono concentrati separati per usi diversi.","Per preparare una dose può essere utile la bottiglia Shaker da 500 ml.","Non indicare una sola diluizione per tutte le polveri."],"key_points_title":"Da ricordare","conversation_title":"Dialogo con il cliente","conversation":[{"text":"Posso versare la polvere direttamente sulla carena?","speaker":"client"},{"text":"No. Prima sciogli Power Powder in acqua seguendo le istruzioni sulla confezione, poi usa la soluzione preparata.","speaker":"seller"},{"text":"Tutte le bustine si diluiscono allo stesso modo?","speaker":"client"},{"text":"No. Moto Wash, Bug Killer e Wheelixir hanno usi diversi; controlla il dosaggio specifico per ciascuno.","speaker":"seller"},{"text":"A cosa serve la bottiglia Shaker?","speaker":"client"},{"text":"Aiuta a misurare l’acqua e preparare una dose della soluzione, se questo metodo d’uso è consentito dalle istruzioni.","speaker":"seller"}],"youtube_video_id":null,"youtube_video_ids":[],"image_path":null},{"lesson_id":318,"module_sort_order":4,"sort_order":3,"title":"Bug Killer e Wheelixir: rimozione dello sporco","summary":"Scegli Bug Killer per lo sporco organico e Wheelixir per i residui sui cerchi.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Due problemi diversi, due prodotti","type":"text"}]},{"type":"paragraph","content":[{"text":"Bug Killer serve per trattare in via preliminare insetti, escrementi di uccelli e altro sporco organico. Wheelixir è adatto ai residui sui cerchi e vicino alle pinze dei freni. Nessuno dei due sostituisce il lavaggio completo della moto.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Utilizzo","type":"text"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Prepara il concentrato Power Powder seguendo l’etichetta.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Applica Bug Killer sullo sporco prima del lavaggio principale.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Attendi il tempo indicato nelle istruzioni, poi risciacqua o procedi con il lavaggio.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Applica Wheelixir sul cerchio e, se necessario, usa la spazzola adatta.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Risciacqua a fondo il cerchio e i residui.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Rispondi all’esigenza del cliente","type":"text"}]},{"type":"paragraph","content":[{"text":"Se ci sono insetti sulla carena, scegli un prodotto per lo sporco organico. Se i residui scuri sono sul cerchio, scegli un prodotto specifico. Verifica la compatibilità e lavora su una superficie fredda.","type":"text"}]}]},"product_bullets":["Usa Bug Killer come fase preliminare contro insetti e sporco organico.","Scegli Wheelixir per i cerchi e i residui dei freni.","Sciogli prima le varianti Power Powder seguendo l’etichetta.","Lascia agire Bug Killer per il tempo indicato nelle istruzioni e non farlo asciugare.","Dopo aver usato Wheelixir, risciacqua bene i cerchi; scegli una spazzola adatta alla superficie."],"key_points_title":"Da ricordare","conversation_title":"Dialogo con il cliente","conversation":[{"text":"Si sono seccati degli insetti sulla carena. Cosa posso usare?","speaker":"client"},{"text":"Prima del lavaggio, applica Bug Killer sullo sporco e attendi il tempo indicato sull’etichetta. Poi risciacqua e lava la moto.","speaker":"seller"},{"text":"E per rimuovere i residui scuri dal cerchio?","speaker":"client"},{"text":"Usa Wheelixir per i residui sui cerchi. Se serve, scegli una spazzola adatta e risciacqua bene il cerchio dopo la pulizia.","speaker":"seller"},{"text":"Posso versare Power Powder senza diluirlo?","speaker":"client"},{"text":"No. Prima sciogli la polvere nell’acqua nella proporzione indicata sulla confezione.","speaker":"seller"}],"youtube_video_id":"WsgHV1M274Y","youtube_video_ids":["WsgHV1M274Y"],"image_path":null},{"lesson_id":319,"module_sort_order":4,"sort_order":4,"title":"Ceramic Detailer: finitura e protezione","summary":"Mostra Ceramic Detailer come fase finale per rifinire una moto pulita.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Dopo il lavaggio","type":"text"}]},{"type":"paragraph","content":[{"text":"Ceramic Detailer serve per rifinire una moto pulita. Può aiutare a ravvivare brillantezza e colore e a ottenere un effetto idrorepellente. Non rimuove lo sporco pesante e non è un rivestimento ceramico professionale pluriennale.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Dimostrazione","type":"text"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Lavora su una superficie fredda e lontano dal sole diretto.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Spruzza una piccola quantità sulla microfibra o come indicato sull’etichetta.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Distribuisci il prodotto su piccole zone senza coprire una superficie troppo ampia.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Lucida con il lato pulito e asciutto del panno o con una seconda microfibra.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Controlla che non siano rimasti aloni e ripeti solo se le istruzioni lo consentono.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Aspettative chiare","type":"text"}]},{"type":"paragraph","content":[{"text":"Il detailer può aiutare nella cura regolare e ridurre l’adesione dello sporco. La moto va comunque lavata e il prodotto non sostituisce un rivestimento duraturo o il ripristino della vernice.","type":"text"}]}]},"product_bullets":["Usa Ceramic Detailer su una superficie pulita dopo il lavaggio o un leggero rinfresco.","Aiuta a ottenere brillantezza ed effetto idrorepellente, secondo la funzione dichiarata del prodotto.","È un detailer rapido, non un rivestimento ceramico professionale di lunga durata.","Lavora su una superficie fredda e lontano dal sole diretto.","Distribuiscilo con una microfibra su piccole zone e lucida con il lato asciutto."],"key_points_title":"Da ricordare","conversation_title":"Dialogo con il cliente","conversation":[{"text":"Ceramic Detailer è un rivestimento che dura diversi anni?","speaker":"client"},{"text":"No. È un detailer rapido per la finitura e la cura regolare, non un rivestimento ceramico professionale e permanente.","speaker":"seller"},{"text":"Posso applicarlo su una moto sporca?","speaker":"client"},{"text":"Prima lava e asciuga la moto. Applica il detailer su una superficie pulita e fredda, lavorando su piccole zone.","speaker":"seller"},{"text":"Dopo averlo usato non dovrò più lavare la moto?","speaker":"client"},{"text":"La moto va comunque lavata. Il detailer aiuta a rifinire la superficie, ma non sostituisce il lavaggio.","speaker":"seller"}],"youtube_video_id":"mofx3RgqndY","youtube_video_ids":["mofx3RgqndY"],"image_path":null},{"lesson_id":320,"module_sort_order":4,"sort_order":5,"title":"Spazzole e microfibre: come scegliere gli accessori?","summary":"Scegli la microfibra e la spazzola per la fase specifica, evitando di trasferire lo sporco da una superficie all’altra.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Scegli l’accessorio in base alla superficie","type":"text"}]},{"type":"paragraph","content":[{"text":"Nemmeno un buon prodotto sostituisce l’attrezzo giusto. Una microfibra morbida raccoglie lo sporco leggero e serve per la finitura. Per cerchi, catena e dettagli difficili da raggiungere, scegli spazzole o pennelli separati.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Separa le zone pulite da quelle sporche","type":"text"}]},{"type":"paragraph","content":[{"text":"Non trasferire il grasso della catena sulla vernice, sulle carene o sulla visiera. Anche i residui dei cerchi possono graffiare le superfici delicate. Quando il panno si sporca, cambia lato o prendine uno pulito.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Scelta con un budget limitato","type":"text"}]},{"type":"paragraph","content":[{"text":"Se il cliente parte da zero, chiedi qual è il problema principale. Una microfibra morbida e pulita è utile per molte operazioni leggere. Scegli una spazzola aggiuntiva solo quando sai quale zona deve raggiungere.","type":"text"}]}]},"product_bullets":["Per la pulizia leggera e la finitura, usa microfibre morbide e pulite.","Usa panni diversi per le varie fasi e superfici.","La spazzola per la catena non va usata sulla vernice o sulla visiera.","Un pennello da detailing aiuta a raggiungere i punti difficili.","Scegli una spazzola adatta ai cerchi e alla superficie per non graffiare la vernice."],"key_points_title":"Da ricordare","conversation_title":"Dialogo con il cliente","conversation":[{"text":"Una sola microfibra basta per tutta la moto?","speaker":"client"},{"text":"Usa microfibre pulite separate per le diverse fasi, così non trasferisci sporco dai cerchi e dalla trasmissione alla vernice.","speaker":"seller"},{"text":"Il pennello da detailing e la spazzola per la catena sono intercambiabili?","speaker":"client"},{"text":"No. La spazzola per la catena serve alla trasmissione; il pennello da detailing aiuta a raggiungere i dettagli difficili. Non usare la spazzola della catena sulla vernice.","speaker":"seller"},{"text":"Da dove inizio se ho un budget limitato?","speaker":"client"},{"text":"Inizia con una microfibra morbida e pulita. Scegli una spazzola solo per una zona specifica che è difficile da pulire.","speaker":"seller"}],"youtube_video_id":"xYSzhwsyZjs","youtube_video_ids":["xYSzhwsyZjs","sqLlcgn_lQA","FvYwpb_PqlA"],"image_path":null},{"lesson_id":321,"module_sort_order":5,"sort_order":0,"title":"Quali tipi di sporco si accumulano durante la guida off-road?","summary":"Individua lo sporco tipico del fuoristrada e scegli Mud Breaker o Dirt Finisher in base alla sua intensità.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Perché il fuoristrada richiede un approccio diverso","type":"text"}]},{"type":"paragraph","content":[{"text":"Dopo un’uscita off-road, sulla moto possono restare fango, sabbia, polvere e residui delle pozzanghere. Le particelle secche sono abrasive, quindi non iniziare passando la microfibra su tutto il veicolo. Valuta prima lo strato di sporco e prepara le condizioni per pulire in sicurezza.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Scegli uno dei due metodi","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Fango spesso e secco: usa Mud Breaker seguendo le istruzioni, poi risciacqua a fondo.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Polvere leggera dopo un giro su strada asciutta: Dirt Finisher e una microfibra pulita possono bastare.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Molta sabbia: rimuovila in sicurezza prima di strofinare la superficie.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Domande prima di consigliare","type":"text"}]},{"type":"paragraph","content":[{"text":"Scopri su quale terreno guida il cliente e se ha accesso all’acqua. Mud Breaker richiede la possibilità di risciacquare. Non promettere che impedirà al fango di attaccarsi in futuro o che renderà la moto autopulente.","type":"text"}]}]},"product_bullets":["Fango, sabbia e polvere richiedono un metodo diverso dallo sporco leggero della strada.","Non strofinare a secco uno spesso strato di sabbia: le particelle potrebbero graffiare.","Mud Breaker ammorbidisce lo sporco pesante e richiede un risciacquo accurato.","Dirt Finisher è utile per la polvere leggera e la finitura finale.","Chiedi se è disponibile l’acqua e lavora su una superficie fredda."],"key_points_title":"Da ricordare","conversation_title":"Dialogo con il cliente","conversation":[{"text":"Torno da un giro di motocross con molto fango sulla moto. Posso pulirla subito con un panno?","speaker":"client"},{"text":"Non strofinare a secco uno spesso strato di fango o sabbia. Ammorbidisci lo sporco con Mud Breaker e risciacqua a fondo.","speaker":"seller"},{"text":"Dopo un giro su strada asciutta c’è solo polvere. Devo lavarla completamente?","speaker":"client"},{"text":"Per la polvere leggera possono bastare Dirt Finisher e una microfibra pulita. Se c’è molta sabbia, prima rimuovila in sicurezza.","speaker":"seller"},{"text":"Dopo il giro non ho accesso all’acqua.","speaker":"client"},{"text":"Mud Breaker richiede il risciacquo: usalo solo in un posto dove c’è acqua. Scegli il metodo in base allo sporco e alle condizioni disponibili.","speaker":"seller"}],"youtube_video_id":null,"youtube_video_ids":[],"image_path":null},{"lesson_id":322,"module_sort_order":5,"sort_order":1,"title":"Mud Breaker: rimozione del fango","summary":"Impara a usare Mud Breaker in sicurezza sul fango pesante e a risciacquare correttamente lo sporco.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Un prodotto per lo sporco pesante","type":"text"}]},{"type":"paragraph","content":[{"text":"Mud Breaker aiuta ad ammorbidire fango, sabbia e sporco minerale dopo la guida off-road. Spiega al cliente che prepara lo sporco al risciacquo e non è un metodo di pulizia completo senza acqua.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Fasi di utilizzo","type":"text"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Aspetta che la moto si raffreddi.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Valuta la quantità di fango e prepara l’accesso all’acqua.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Applica il prodotto sulle parti sporche seguendo l’etichetta.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Lascialo agire per il tempo indicato senza farlo asciugare.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Risciacqua a fondo con acqua lo sporco e il prodotto.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Spazzola e cura successiva","type":"text"}]},{"type":"paragraph","content":[{"text":"Per i punti difficili può essere utile una spazzola adatta, ma usala con delicatezza e non strofinare a secco. Dopo il risciacquo, il cliente può decidere se gli serve Dirt Finisher per la finitura.","type":"text"}]}]},"product_bullets":["Mud Breaker è destinato al fango pesante e allo sporco minerale.","Controlla che la moto si sia raffreddata e prepara l’acqua per il risciacquo.","Usalo sulla superficie sporca seguendo l’etichetta.","Non lasciare asciugare il prodotto; spazzola delicatamente solo se necessario.","Dopo averlo lasciato agire, risciacqua accuratamente il veicolo."],"key_points_title":"Da ricordare","conversation_title":"Dialogo con il cliente","conversation":[{"text":"Mud Breaker rimuove il fango secco dal forcellone?","speaker":"client"},{"text":"Sì, ammorbidisce il fango per facilitare il risciacquo. Spruzza sulla superficie sporca, attendi qualche istante e risciacqua a fondo; per i depositi più resistenti, aiutati delicatamente con una spazzola.","speaker":"seller"},{"text":"Non ho un tubo. Posso usarlo al parcheggio?","speaker":"client"},{"text":"Non usarlo se non puoi risciacquare. Applica Mud Breaker in un posto dove è possibile lavare con acqua, perché dopo l’uso il veicolo va risciacquato accuratamente.","speaker":"seller"},{"text":"Posso lasciare asciugare il prodotto?","speaker":"client"},{"text":"No. Risciacqualo prima che si asciughi e non applicarlo sulle parti calde.","speaker":"seller"}],"youtube_video_id":null,"youtube_video_ids":[],"image_path":null},{"lesson_id":323,"module_sort_order":5,"sort_order":2,"title":"Dirt Finisher: finitura e cura","summary":"Spiega come usare Dirt Finisher per lo sporco leggero e come fase successiva a un lavaggio più impegnativo.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Cura più leggera della moto da fuoristrada","type":"text"}]},{"type":"paragraph","content":[{"text":"Dirt Finisher non è una seconda variante di Mud Breaker. Aiuta con lo sporco leggero e nella finitura di una superficie più pulita. In caso di fango pesante, si usa solo dopo aver ammorbidito lo sporco e aver risciacquato.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Modalità d’uso","type":"text"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Verifica che la superficie sia fredda e priva di uno spesso strato di sabbia.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Agita la confezione seguendo le istruzioni.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Spruzza una piccola quantità sulla zona scelta.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Raccogli delicatamente lo sporco leggero con una microfibra pulita.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Cambia il panno quando raccoglie sabbia o fango.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Scegli in base alla quantità di sporco","type":"text"}]},{"type":"paragraph","content":[{"text":"Con la polvere leggera dopo uno sterrato, Dirt Finisher può bastare da solo. Per uno spesso strato di fango argilloso, usa prima Mud Breaker e risciacqua. La finitura può facilitare la cura successiva, ma non elimina lo sporco.","type":"text"}]}]},"product_bullets":["Dirt Finisher è pensato per la pulizia leggera e la finitura.","Con il fango pesante, usa prima Mud Breaker e risciacqua accuratamente.","Prima dell’uso rimuovi la sabbia più grossolana e verifica che la superficie sia fredda.","Agita la confezione e lavora su piccole zone.","Raccogli lo sporco con una microfibra pulita e cambiala quando è molto sporca."],"key_points_title":"Da ricordare","conversation_title":"Dialogo con il cliente","conversation":[{"text":"Devo acquistare insieme Mud Breaker e Dirt Finisher?","speaker":"client"},{"text":"No. Per la polvere leggera basta Dirt Finisher; dopo il fango pesante, usa prima Mud Breaker e risciacqua. Aggiungi la fase di finitura solo se ti serve.","speaker":"seller"},{"text":"Dirt Finisher può rimuovere uno spesso strato di fango argilloso?","speaker":"client"},{"text":"No. Prima ammorbidisci il fango con Mud Breaker e risciacqua. Dirt Finisher serve per una pulizia più leggera e per la finitura.","speaker":"seller"},{"text":"Posso usarlo per strofinare via molta sabbia?","speaker":"client"},{"text":"Prima rimuovi la sabbia grossolana. Non strofinare le particelle con la microfibra: potrebbero graffiare la superficie.","speaker":"seller"}],"youtube_video_id":null,"youtube_video_ids":[],"image_path":null},{"lesson_id":324,"module_sort_order":5,"sort_order":3,"title":"Come scegliere il kit Off-Road?","summary":"Scegli il kit off-road in base allo stile di guida, alla quantità di sporco e all’accesso all’acqua.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Chiedi che cosa intende per «kit»","type":"text"}]},{"type":"paragraph","content":[{"text":"Il cliente può intendere una confezione già pronta o un insieme di prodotti per la cura. Chiedi che veicolo usa, quale sporco incontra più spesso e se dopo il giro ha accesso all’acqua. Finché non confermi un prodotto specifico, presenta la soluzione come un sistema in due fasi.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Scegli in base al profilo","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Motocross su pista fangosa: Mud Breaker, risciacquo e, se serve, Dirt Finisher.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Enduro su sterrato asciutto: Dirt Finisher per la polvere leggera.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Quad o MTB nel fango pesante: scegli il prodotto e controlla le indicazioni per il veicolo.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Se non c’è accesso all’acqua, programma la pulizia in un luogo dove sia possibile risciacquare bene.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Accessori e scelta essenziale","type":"text"}]},{"type":"paragraph","content":[{"text":"Per la finitura serve una microfibra morbida e pulita; per i punti difficili, una spazzola adatta. Non aggiungere prodotti senza motivo. Per prima cosa indica il minimo necessario per risolvere il problema e presenta la seconda fase come facoltativa.","type":"text"}]}]},"product_bullets":["Chiedi se il cliente guida una moto da cross, enduro, quad o MTB.","Con il fango pesante, consiglia Mud Breaker e assicurati che sia possibile risciacquare.","Per la polvere leggera, il cliente può iniziare con Dirt Finisher.","Scegli una microfibra o una spazzola aggiuntiva solo se serve davvero.","Non presentare Off-Road Kit come una confezione specifica senza averne verificato il prodotto."],"key_points_title":"Da ricordare","conversation_title":"Dialogo con il cliente","conversation":[{"text":"Voglio un kit per l’enduro, ma non voglio cinque detergenti. Qual è il minimo che mi serve?","speaker":"client"},{"text":"Se trovi spesso fango pesante e hai acqua per risciacquare, inizia con Mud Breaker. Aggiungi Dirt Finisher solo se vuoi rifinire anche la superficie pulita.","speaker":"seller"},{"text":"Guido soprattutto su strade sterrate asciutte. Mi servono entrambi i prodotti?","speaker":"client"},{"text":"No. Per la polvere leggera inizia con Dirt Finisher e una microfibra pulita.","speaker":"seller"},{"text":"Off-Road Kit è una confezione già pronta?","speaker":"client"},{"text":"Verifichiamo la variante attualmente disponibile. Se cerchi un kit per la cura, posso consigliarti Mud Breaker e Dirt Finisher come due fasi separate.","speaker":"seller"}],"youtube_video_id":null,"youtube_video_ids":[],"image_path":null},{"lesson_id":325,"module_sort_order":6,"sort_order":0,"title":"Come riconoscere le esigenze del cliente?","summary":"Fai domande che aiutino a individuare l’esigenza del cliente e portino a una raccomandazione semplice.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"La vendita inizia dall’ascolto","type":"text"}]},{"type":"paragraph","content":[{"text":"Il cliente può descrivere un problema senza conoscere i nomi dei prodotti: «Cerco qualcosa per il casco» oppure «La giacca ha un cattivo odore». Il tuo compito è capire meglio l’esigenza, non elencare subito i prodotti disponibili.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Cinque domande utili","type":"text"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Che cosa vuole pulire o proteggere?","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Qual è il problema principale: insetti, polvere, fango, sudore o manutenzione?","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Di che materiale è fatto il capo o la superficie?","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Dove userà il prodotto e avrà accesso all’acqua?","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"È un’esigenza occasionale o una cura regolare?","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Dalle risposte alla raccomandazione","type":"text"}]},{"type":"paragraph","content":[{"text":"Non è necessario fare tutte le domande. Scegli quelle che influenzano la scelta del prodotto. Riassumi il problema con parole tue, indica una soluzione, spiega come si usa e menziona un limite importante. Proponi un prodotto aggiuntivo solo quando completa una fase specifica.","type":"text"}]}]},"product_bullets":["Chiedi che cosa vuole pulire o proteggere il cliente.","Individua il problema preciso: insetti, polvere, fango, odore o manutenzione.","Verifica il materiale, le condizioni d’uso e la frequenza della manutenzione.","Riassumi il problema con parole tue prima di consigliare un prodotto.","Presenta una o due soluzioni adatte e spiega come usarle."],"key_points_title":"Da ricordare","conversation_title":"Dialogo con il cliente","conversation":[{"text":"Cerco un buon prodotto liquido. Che cosa mi consigli?","speaker":"client"},{"text":"Per prima cosa, capiamo che cosa vuoi pulire: il casco, l’abbigliamento o la moto. Quale problema vuoi risolvere: insetti, sporco, odore o cura del materiale?","speaker":"seller"},{"text":"Mi riferisco alla visiera del casco e agli insetti secchi.","speaker":"client"},{"text":"In tal caso, inizia con Helmet Gel, che ammorbidisce gli insetti. Poi puoi rifinire la visiera pulita con Helmet Detailer.","speaker":"seller"},{"text":"Il cliente chiede subito solo il prezzo. Che cosa rispondo?","speaker":"client"},{"text":"Indica il prezzo, se lo conosci, e poi chiedi brevemente a cosa serve il prodotto. Così puoi consigliare la variante adatta senza proporre un acquisto non necessario.","speaker":"seller"}],"youtube_video_id":null,"youtube_video_ids":[],"image_path":null},{"lesson_id":326,"module_sort_order":6,"sort_order":1,"title":"Come proporre kit pronti invece di singoli prodotti?","summary":"Mostra il valore del kit attraverso le diverse fasi di cura e scegli il formato in base all’uso.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Mostra il processo, non solo il prezzo","type":"text"}]},{"type":"paragraph","content":[{"text":"Il kit è facile da capire quando il cliente vede quali fasi include. Per un capo in pelle può trattarsi di pulizia, cura della pelle e rinfresco dell’interno. Per il casco conta la pulizia delle superfici esterne e un formato pratico a casa o in viaggio.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Scegli il kit in base alla situazione","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Valuta Leather Care Kit per chi ha bisogno di più fasi per la cura della pelle.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Trip Kit è pratico da portare in viaggio.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"GIGA può essere comodo per la cura regolare a casa o di più caschi.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Se il cliente possiede già gli accessori, indica solo il prodotto che gli manca.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Verifica l’esigenza","type":"text"}]},{"type":"paragraph","content":[{"text":"Un kit non è sempre la scelta migliore. Chiedi che cosa possiede già il cliente, quanto spesso si prende cura dell’attrezzatura e dove la usa. Il valore del kit sta nella comodità e nell’adeguatezza, non nel numero di componenti.","type":"text"}]}]},"product_bullets":["Spiega le fasi: pulizia, cura o finitura e, se serve, trattamento dell’interno.","Leather Care Kit può combinare la cura della pelle esterna e il rinfresco dell’interno.","Trip Kit è adatto ai viaggi; GIGA alla cura regolare del casco.","Chi possiede già alcuni prodotti può acquistare solo ciò che gli manca.","Concludi chiedendo come e quanto spesso userà il prodotto."],"key_points_title":"Da ricordare","conversation_title":"Dialogo con il cliente","conversation":[{"text":"Perché dovrei comprare un kit se mi serve solo un prodotto liquido?","speaker":"client"},{"text":"Se possiedi già gli altri prodotti e accessori, acquista solo quello che ti manca. Il kit ha senso se vuoi eseguire tutte le fasi di cura.","speaker":"seller"},{"text":"Cerco qualcosa da portare in viaggio per il casco. Che cosa scelgo?","speaker":"client"},{"text":"Scegli Trip Kit: ha confezioni compatte da portare in viaggio. Per la pulizia regolare a casa, confrontalo con GIGA.","speaker":"seller"},{"text":"Il kit più grande funziona meglio?","speaker":"client"},{"text":"No, cambiano formato e contenuto. Sceglilo in base a quanto spesso e quanti caschi pulisci.","speaker":"seller"}],"youtube_video_id":null,"youtube_video_ids":[],"image_path":null},{"lesson_id":327,"module_sort_order":6,"sort_order":2,"title":"Come aumentare le vendite con prodotti complementari?","summary":"Abbina al massimo un prodotto complementare utile alla procedura che il cliente ha già iniziato.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Una vendita complementare utile","type":"text"}]},{"type":"paragraph","content":[{"text":"Un prodotto complementare è utile quando completa una fase distinta. Chi acquista un cleaner potrebbe aver bisogno di un prodotto per la cura successiva o del panno adatto. Se possiede già quell’accessorio, non serve proporlo di nuovo.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Abbinamenti naturali","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Helmet Gel → Helmet Detailer e il panno adatto.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Leather Cleaner → Leather Milk dopo aver pulito e asciugato la pelle.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Textile Care → Fabric Protect come additivo che aiuta a mantenere la freschezza, non come impermeabilizzante.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Moto Wash o Bug Killer → Ceramic Detailer dopo il lavaggio e il risciacquo.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Mud Breaker → Dirt Finisher dopo il lavaggio intenso, se il cliente vuole una finitura.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Una proposta senza pressione","type":"text"}]},{"type":"paragraph","content":[{"text":"Chiedi quale fase manca e proponi al massimo un prodotto complementare adatto. Per esempio: «Il cleaner rimuove lo sporco dalla pelle. Se non ha un prodotto per trattarla dopo la pulizia, posso mostrarle Leather Milk». Se il cliente rifiuta, rispetta la sua scelta.","type":"text"}]}]},"product_bullets":["Il prodotto complementare dovrebbe completare la fase successiva, non aumentare l’acquisto a caso.","Abbina Helmet Gel al detailer e al panno adatto.","Leather Cleaner si completa con Leather Milk dopo l’asciugatura della pelle.","Textile Care si può abbinare a Fabric Protect come additivo per il bucato.","Rispetta il rifiuto e non proporre un prodotto che il cliente possiede già."],"key_points_title":"Da ricordare","conversation_title":"Dialogo con il cliente","conversation":[{"text":"Perché mi propone un secondo prodotto?","speaker":"client"},{"text":"Un prodotto complementare è utile se completa una fase necessaria: per esempio, Leather Milk tratta la pelle dopo la pulizia. Se possiedi già il prodotto, non serve acquistarne un altro.","speaker":"seller"},{"text":"No, grazie. Ho già un prodotto del genere.","speaker":"client"},{"text":"Va bene. Restiamo su ciò che ti manca davvero.","speaker":"seller"},{"text":"Che cosa posso abbinare a Leather Cleaner se non ho un prodotto per la cura della pelle?","speaker":"client"},{"text":"Dopo aver pulito e asciugato la pelle, puoi usare Leather Milk come fase separata.","speaker":"seller"}],"youtube_video_id":null,"youtube_video_ids":[],"image_path":null},{"lesson_id":328,"module_sort_order":6,"sort_order":3,"title":"Come rispondere alle obiezioni più comuni dei clienti?","summary":"Rispondi alle obiezioni comprendendo il dubbio, fornendo un fatto concreto e lasciando al cliente la libertà di scegliere.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Un’obiezione fornisce informazioni","type":"text"}]},{"type":"paragraph","content":[{"text":"«Costa troppo», «Ho già qualcosa di simile» oppure «È sicuro?» sono segnali che il cliente ha bisogno di chiarimenti. Prima riconosci il suo dubbio, poi fai una breve domanda, rispondi in modo concreto e lascia la scelta al cliente.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Quattro situazioni frequenti","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Prezzo: chiedi se il prodotto verrà usato occasionalmente o regolarmente e scegli il formato adatto.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Detergente comune: confronta l’uso previsto con il materiale e l’etichetta del capo.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Sicurezza: verifica la superficie, la finitura e le istruzioni; sulla pelle fai prima una prova.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Efficacia: spiega la funzione specifica e i limiti del prodotto.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Rispondi in tre frasi","type":"text"}]},{"type":"paragraph","content":[{"text":"Una risposta breve può riconoscere il dubbio, presentare un fatto concreto e proporre il passo successivo. Non allarmare il cliente parlando di danni, non promettere un prodotto «buono per tutto» e non inventare una politica di reso. Se non conosci la risposta, verificala prima di consigliare.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Esercizio","type":"text"}]},{"type":"paragraph","content":[{"text":"A coppie, esercitatevi a rispondere a queste obiezioni: «Costa troppo», «Uso già un detergente normale», «È sicuro?» e «Funziona davvero?». Scambiatevi i ruoli e verificate che la risposta rispetti la destinazione d’uso del prodotto.","type":"text"}]}]},"product_bullets":["Per prima cosa, riconosci il dubbio e fai una domanda per chiarirlo.","In caso di dubbi sul prezzo, scegli il formato e la quantità in base alla frequenza d’uso.","Per la sicurezza, controlla la superficie, l’etichetta e le istruzioni del produttore.","Spiega a cosa serve il prodotto invece di fare promesse generiche.","Non dichiarare condizioni di reso, riparazioni o risultati che non conosci."],"key_points_title":"Da ricordare","conversation_title":"Dialogo con il cliente","conversation":[{"text":"Per me costa troppo.","speaker":"client"},{"text":"Capisco. Se userai il prodotto solo ogni tanto, possiamo valutare un formato più piccolo o acquistare solo la fase necessaria.","speaker":"seller"},{"text":"Questo prodotto è sicuro su tutti i materiali?","speaker":"client"},{"text":"Non esiste un unico prodotto adatto a tutto. Dimmi su quale materiale vuoi usarlo e sceglierò il prodotto e il metodo indicati sull’etichetta.","speaker":"seller"},{"text":"L’ho visto a un prezzo inferiore su internet.","speaker":"client"},{"text":"Confrontiamo quantità, variante e contenuto del kit. Se è lo stesso prodotto, puoi tranquillamente scegliere l’offerta che preferisci.","speaker":"seller"}],"youtube_video_id":null,"youtube_video_ids":[],"image_path":null},{"lesson_id":329,"module_sort_order":6,"sort_order":4,"title":"Simulazioni di conversazioni di vendita","summary":"Esercitati in conversazioni di vendita complete: dall’individuazione dell’esigenza alla scelta di una soluzione adatta.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Scenario: casco dopo un giro","type":"text"}]},{"type":"paragraph","content":[{"text":"Il cliente ha appena acquistato il suo primo casco e la visiera ha insetti secchi. Chiedi se lo pulisce a casa o in viaggio. Spiega la fase di ammorbidimento dello sporco e poi la finitura. Se chiede di Pinlock, distingui l’inserto dalla visiera esterna e segui le istruzioni del produttore.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Scenario: tuta a fine stagione","type":"text"}]},{"type":"paragraph","content":[{"text":"Il cliente ha la pelle sporca e cattivo odore all’interno. Separa la pulizia esterna, la cura dopo l’asciugatura e il rinfresco dell’interno. Se ha già il cleaner, proponi solo la fase mancante. Per un’abrasione del materiale, indirizzalo a un servizio di assistenza.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Scenario: enduro nel fango","type":"text"}]},{"type":"paragraph","content":[{"text":"Il cliente torna da un’uscita off-road impegnativa e ha accesso all’acqua. Consiglia Mud Breaker e un risciacquo accurato; presenta Dirt Finisher come opzione per la finitura. Non consigliare di strofinare la sabbia a secco o di applicare il prodotto su una parte calda.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Riepilogo della conversazione","type":"text"}]},{"type":"paragraph","content":[{"text":"In ogni scena, individua l’esigenza, indica il prodotto adatto e spiega come usarlo e quali sono i suoi limiti. Lascia scegliere il cliente; se un prodotto aggiuntivo non serve, fermati alla soluzione essenziale.","type":"text"}]}]},"product_bullets":["Chiedi a cosa serve il prodotto prima di mostrarlo.","Scegli il prodotto in base al problema specifico e al materiale.","Spiega l’ordine d’uso e una condizione importante per la sicurezza.","Proponi un prodotto complementare solo se completa una fase necessaria.","In caso di danni o dubbi, controlla le istruzioni o indirizza il cliente a un servizio di assistenza."],"key_points_title":"Da ricordare","conversation_title":"Dialogo con il cliente","conversation":[{"text":"Ho comprato un casco costoso. Ci sono insetti secchi sulla visiera e voglio un solo prodotto.","speaker":"client"},{"text":"Inizia con Helmet Gel per ammorbidire gli insetti; poi rimuovili delicatamente con una microfibra. Se vuoi, alla fine puoi rifinire la visiera pulita con Helmet Detailer.","speaker":"seller"},{"text":"Posso usare lo stesso prodotto per pulire Pinlock?","speaker":"client"},{"text":"No. Usa i prodotti per la visiera esterna solo all’esterno; pulisci delicatamente l’inserto seguendo le istruzioni del produttore del casco.","speaker":"seller"},{"text":"Ho una giacca con membrana. Fabric Protect la impermeabilizza?","speaker":"client"},{"text":"No, Fabric Protect si aggiunge al bucato per aiutare a mantenere la freschezza. Per proteggere la giacca dall’acqua scegli un impermeabilizzante specifico e compatibile.","speaker":"seller"},{"text":"Torno da un giro di enduro nel fango pesante, ma voglio un solo prodotto.","speaker":"client"},{"text":"In tal caso, inizia con Mud Breaker e risciacqua a fondo. Puoi acquistare Dirt Finisher più avanti, se vorrai rifinire la superficie pulita.","speaker":"seller"}],"youtube_video_id":null,"youtube_video_ids":[],"image_path":null}]$it_lessons$::jsonb) AS translated(
  module_sort_order integer, sort_order integer, title text, summary text, content jsonb,
  product_bullets jsonb, key_points_title text, conversation_title text, conversation jsonb
)
WHERE course.slug = 'pielegnacja-i-sprzedaz-produktow-xzone' AND version.version_number = 9 AND version.status = 'published'
  AND module.sort_order = translated.module_sort_order
  AND lesson.sort_order = translated.sort_order
  AND 'it' = 'it'
ON CONFLICT (lesson_id, language_code) DO UPDATE SET
  title = EXCLUDED.title,
  summary = EXCLUDED.summary,
  content = EXCLUDED.content,
  product_bullets = EXCLUDED.product_bullets,
  key_points_title = EXCLUDED.key_points_title,
  conversation_title = EXCLUDED.conversation_title,
  conversation = EXCLUDED.conversation,
  youtube_video_id = COALESCE(lesson_translations.youtube_video_id, EXCLUDED.youtube_video_id),
  youtube_video_ids = CASE WHEN cardinality(lesson_translations.youtube_video_ids) > 0 THEN lesson_translations.youtube_video_ids ELSE EXCLUDED.youtube_video_ids END,
  image_path = COALESCE(lesson_translations.image_path, EXCLUDED.image_path),
  updated_at = now();

DO $verify$
DECLARE
  target_language_code text;
  course_count integer;
  module_count integer;
  lesson_count integer;
BEGIN
  FOREACH target_language_code IN ARRAY ARRAY['en', 'de', 'cs', 'fr', 'it'] LOOP
    SELECT count(*) INTO course_count
    FROM public.course_translations AS translation
    JOIN public.course_versions AS version ON version.id = translation.course_version_id
    JOIN public.courses AS course ON course.published_version_id = version.id
    WHERE course.slug = 'pielegnacja-i-sprzedaz-produktow-xzone' AND version.version_number = 9 AND translation.language_code = target_language_code;
    SELECT count(*) INTO module_count
    FROM public.module_translations AS translation
    JOIN public.course_modules AS module ON module.id = translation.module_id
    JOIN public.course_versions AS version ON version.id = module.course_version_id
    JOIN public.courses AS course ON course.published_version_id = version.id
    WHERE course.slug = 'pielegnacja-i-sprzedaz-produktow-xzone' AND version.version_number = 9 AND translation.language_code = target_language_code;
    SELECT count(*) INTO lesson_count
    FROM public.lesson_translations AS translation
    JOIN public.course_lessons AS lesson ON lesson.id = translation.lesson_id
    JOIN public.course_modules AS module ON module.id = lesson.module_id
    JOIN public.course_versions AS version ON version.id = module.course_version_id
    JOIN public.courses AS course ON course.published_version_id = version.id
    WHERE course.slug = 'pielegnacja-i-sprzedaz-produktow-xzone' AND version.version_number = 9 AND translation.language_code = target_language_code;
    IF course_count <> 1 OR module_count <> 7 OR lesson_count <> 36 THEN
      RAISE EXCEPTION 'Incomplete % translation (courses %, modules %, lessons %)', target_language_code, course_count, module_count, lesson_count;
    END IF;
  END LOOP;
END
$verify$;

COMMIT;
